BOOL CCRCForceCtrl::Is_Reciprocal(unsigned int iAnalType, unsigned int iLcaseKey)
{
	T_LCRS_D LcrsD;
	LcrsD.Initialize();
	if (!m_pAttrCtrl->GetLcrs(LcrsD))	return FALSE;
	int nLcrsSize = LcrsD.aCase.GetSize();
	for (int i = 0; i < nLcrsSize; ++i)
	{
		T_LCRS_BASE &LcrsBase = LcrsD.aCase.GetAt(i);
		BOOL bAnalTypeOK = (LcrsBase.AnalType == iAnalType);
		BOOL bLcaseKeyOK = (LcrsBase.LoadCaseKey == iLcaseKey);
		if (bAnalTypeOK && bLcaseKeyOK)	return TRUE;
	}
	return FALSE;
}

BOOL CCRCForceCtrl::GetErectionLoadType(CString strErName, T_STCT_D &rStct, CString &strLCType)
{
	strLCType = _T("");
	for (INT_PTR i = 0; i < rStct.aErection.GetSize(); ++i)
	{
		const T_STCT_EREC &ErecD = rStct.aErection[i];
		if (strErName.CompareNoCase(ErecD.strErection) == 0)
		{
			if (ErecD.nNumStctCase > 0) // 혹시라도 strErName에 erection이 아닌 load case인데 strErection과 이름이 같을 수 있기 때문에 
			{
				strLCType = ErecD.LoadCaseType;
				return TRUE;
			}
		}
	}
	return FALSE;
}

BOOL CCRCForceCtrl::IsBeforeLoadSgld(CString strLoadCaseName, T_STCT_D &rStct)
{
	BOOL bBeforeLoad = FALSE;
	CString strErLoadType = _T("");
	if (strLoadCaseName == _LS(IDS_DB_SGLD_DL))
	{
		bBeforeLoad = TRUE;
	}
	else if (strLoadCaseName == _LS(IDS_DB_SGLD_CS) ||
		     strLoadCaseName == _LS(IDS_DB_SGLD_SS) )
	{
		bBeforeLoad = TRUE;
	}
	else if (GetErectionLoadType(strLoadCaseName, rStct, strErLoadType))
	{
		if (CDBLib::IsStldDL(strErLoadType)) bBeforeLoad = TRUE;

	}

	return bBeforeLoad;
}

BOOL CCRCForceCtrl::IsTranferLoad(CString strLoadCaseName, T_STCT_D &rStct)
{
	BOOL bTransferLoad = FALSE;
	CString strErLoadType = _T("");
	if (strLoadCaseName == _LS(IDS_DB_SGLD_DL) ||
		strLoadCaseName == _LS(IDS_DB_SGLD_TP) ||
		strLoadCaseName == _LS(IDS_DB_SGLD_TS) ||
		strLoadCaseName == _LS(IDS_DB_SGLD_CP) ||
		strLoadCaseName == _LS(IDS_DB_SGLD_CS) ||
		strLoadCaseName == _LS(IDS_DB_SGLD_SP) ||
		strLoadCaseName == _LS(IDS_DB_SGLD_SS) ||
		strLoadCaseName == _LS(IDS_DB_SGLD_SUM) ||
		strLoadCaseName == _LS(IDS_DB_SGLD_LL))
	{
		bTransferLoad = TRUE;
	}
	else if (GetErectionLoadType(strLoadCaseName, rStct, strErLoadType))
	{
		// 요구사항 있을 때 조건을 달자.
		bTransferLoad = TRUE;
		//if ( CDBLib::IsStldDL(strErLoadType) ) bTransferLoad = TRUE;
	}

	return bTransferLoad;
}

BOOL CCRCForceCtrl::GetErectionCSMaxFactor(T_STCT_D &rStct, T_CSLF_CPT &rCslf)
{
	int nLcomSize = Get_LcomDataCount();
	int nChkLcomCount = 0;

	//CArray<double,double&> aErMaxFactor;
	CArray<int, int&> aErCount;

	INT_PTR nErSize = rStct.aErection.GetSize();
	if (nErSize > 0)
	{
		rCslf.aFacEr.SetSize(nErSize);
		//aErMaxFactor.SetSize(nErSize);
		aErCount.SetSize(nErSize);
		for (INT_PTR i = 0; i < nErSize; ++i) rCslf.aFacEr[i].dFactor = 1.0;
	}

	for (int i = 0; i < nLcomSize; ++i)
	{
		int nDgnLcomNo = i + 1;
		_DGN_LCOM DgnLcom;
		if (Get_DgnLcomData(nDgnLcomNo, DgnLcom))
		{
			BOOL bULSLcom = Is_LcomForStrn(nDgnLcomNo);
			if (bULSLcom == FALSE) continue;
			for (INT_PTR j = 0; j < DgnLcom.LcomUlData.Combination.GetSize(); ++j)
			{
				T_LCOM_BASE &LCase = DgnLcom.LcomUlData.Combination[j];
				if (LCase.AnalType == D_LCOM_STAGE)
				{
					T_SGLD_D SgldD;
					m_pStageInfo->GetSgldPost(LCase.LoadCaseKey, SgldD);

					for (INT_PTR k = 0; k < nErSize; ++k)
					{
						if (SgldD.LoadCaseName.CompareNoCase(rStct.aErection[k].strErection) == 0)
						{
							T_CSLF_BASE &CslfB = rCslf.aFacEr[k];
							if (aErCount[k] == 0)
							{
								CslfB.nErIdx = k;
								CslfB.dFactor = LCase.Factor;
							}
							else
							{
								if (rCslf.aFacEr[k].dFactor < LCase.Factor)
								{
									CslfB.nErIdx = k;
									CslfB.dFactor = LCase.Factor;
								}
							}
							aErCount[k]++;
						}
					}
				}
			}
		}
	}// i                        

	return TRUE;
}

BOOL CCRCForceCtrl::IsSgldScfpKey(T_SGLD_K SgldK, T_STCT_D &StctD)
{
	T_SGLD_D SgldD;
	if (m_pStageInfo->GetSgldPost(SgldK, SgldD))
	{
		// 더 추가 할 CS load case가 있으면 추가..
		if      (SgldK == D_SGLD_CS_CVL)return TRUE; //if     (SgldD.LoadCaseName.CompareNoCase(_LS(IDS_DB_SGLD_CS))) return TRUE;
		else if (SgldK == D_SGLD_SS_CVL)return TRUE; //else if(SgldD.LoadCaseName.CompareNoCase(_LS(IDS_DB_SGLD_SS))) return TRUE;
		else
		{
			for (int i = 0; i < StctD.aErection.GetSize(); i++)
			{
				if (SgldD.LoadCaseName.CompareNoCase(StctD.aErection[i].strErection) == 0)
				{
					return IsErectionScfp(i, StctD);
				}
			}
		}
	}
	return FALSE;
}

BOOL CCRCForceCtrl::IsErectionScfp(int nType, T_STCT_D &StctD)
{
	if (nType > (StctD.aErection.GetSize() - 1)) return FALSE;

	int nNumStctCase = StctD.aErection[nType].nNumStctCase;

	for (int i = 0; i < nNumStctCase; ++i)
	{
		T_STLD_K StldK;
		T_STLD_D StldD; StldD.Initialize();

		StldK = StctD.aErection[nType].LoadCaseKey[i];

		if (m_pAttrCtrl->GetStld(StldK, StldD))
		{
			// 하나라도 온도가 아니면 FALSE
			// 조건은 다시 협의가 필요하고 온도만 할것인가 아니면 Creep, Shrinkage 고려할 것인가 협의 필요
			if (CDBLib::IsStldTL(StldD.LoadCaseType) == FALSE) return FALSE;
		}
	}
	return TRUE;
}
