BOOL CCRCForceCtrl::Get_Sepc(ElemPairK ElemK, unsigned int iLcaseKey, int nForType, BOOL bCalcStss, int iLcaseType, _DGN_FORC_CRC& ForceLcase, _DGN_STRS_CRC& StressLcase, _DGN_SHRS_ADD& StssLcase,
	_DGN_FORC_CRC& ForcePart1, _DGN_STRS_CRC& StressPart1, _DGN_FORC_CRC& ForcePart2, _DGN_STRS_CRC& StressPart2)
{
	if (!(iLcaseType == D_LOADCASE_SPECTRUM || iLcaseType == D_LOADCASE_ECCENSPEC))	return FALSE;

	_DGN_STRBFORC_LCASE      DgnStrb;
	_DGN_STRBFORC_PART_LCASE DgnStrbPart;
	GetStrb4Elem(ElemK, nForType, iLcaseType, iLcaseKey, DgnStrb, DgnStrbPart);

	ForceLcase = DgnStrb.Force;
	StressLcase = DgnStrb.Stress;
	if (bCalcStss == TRUE) StssLcase = DgnStrb.Stss;

	if (nForType > 0)
	{
		ForcePart1 = DgnStrbPart.ForceP1;
		ForcePart2 = DgnStrbPart.ForceP2;
		StressPart1 = DgnStrb.Stress;
		StressPart2 = DgnStrbPart.StressP2;
	}

	// Set Force Type (D,L,W,...).
	if (iLcaseType == D_LOADCASE_SPECTRUM)				ForceLcase.strType = StressLcase.strType = _T("RSP");
	else if (iLcaseType == D_LOADCASE_ECCENSPEC)	ForceLcase.strType = StressLcase.strType = _T("ESP");
	else	ASSERT(0);

	return TRUE;
}

BOOL CCRCForceCtrl::Get_This(ElemPairK ElemK, T_THIS_K ThisK, int nForType, BOOL bCalcStss, _DGN_FORC_CRC& ForceLcase, _DGN_STRS_CRC& StressLcase, _DGN_SHRS_ADD& StssLcase,
	_DGN_FORC_CRC& ForcePart1, _DGN_STRS_CRC& StressPart1, _DGN_FORC_CRC& ForcePart2, _DGN_STRS_CRC& StressPart2)
{

	int nLcaseType = D_LOADCASE_HISTORY;

	_DGN_STRBFORC_LCASE      DgnStrb;
	_DGN_STRBFORC_PART_LCASE DgnStrbPart;
	GetStrb4Elem(ElemK, nForType, nLcaseType, ThisK, DgnStrb, DgnStrbPart);

	ForceLcase = DgnStrb.Force;
	StressLcase = DgnStrb.Stress;
	if (bCalcStss == TRUE) StssLcase = DgnStrb.Stss;

	if (nForType > 0)
	{
		ForcePart1 = DgnStrbPart.ForceP1;
		ForcePart2 = DgnStrbPart.ForceP2;
		StressPart1 = DgnStrb.Stress;
		StressPart2 = DgnStrbPart.StressP2;
	}

	// Set Force Type.
	ForceLcase.strType = StressLcase.strType = _T("TH");

	return TRUE;
}

BOOL CCRCForceCtrl::Get_Sgld(ElemPairK ElemK, T_SGLD_K SgldK, int nForType, BOOL bCalcStss, int iStepNo, _DGN_FORC_CRC& ForceLcase, _DGN_STRS_CRC& StressLcase, _DGN_SHRS_ADD& StssLcase,
	_DGN_FORC_CRC& ForcePart1, _DGN_STRS_CRC& StressPart1, _DGN_FORC_CRC& ForcePart2, _DGN_STRS_CRC& StressPart2)
{
	T_SGLD_D SgldD;
	SgldD.Initialize();
	return Get_Sgld(ElemK, SgldK, nForType, bCalcStss, SgldD, iStepNo, ForceLcase, StressLcase, StssLcase, ForcePart1, StressPart1, ForcePart2, StressPart2);
}

BOOL CCRCForceCtrl::Get_Sgld(ElemPairK ElemK, T_SGLD_K SgldK, int nForType, BOOL bCalcStss, T_SGLD_D& SgldD, int iStepNo, _DGN_FORC_CRC& ForceLcase, _DGN_STRS_CRC& StressLcase, _DGN_SHRS_ADD& StssLcase,
	_DGN_FORC_CRC& ForcePart1, _DGN_STRS_CRC& StressPart1, _DGN_FORC_CRC& ForcePart2, _DGN_STRS_CRC& StressPart2, int Lcase/*Default=0*/)
{

	int nLcaseType = D_LOADCASE_STAGE;

	_DGN_STRBFORC_LCASE      DgnStrb;
	_DGN_STRBFORC_PART_LCASE DgnStrbPart;
	GetStrb4Elem(ElemK, nForType, nLcaseType, SgldK, DgnStrb, DgnStrbPart);

	ForceLcase = DgnStrb.Force;
	StressLcase = DgnStrb.Stress;
	if (bCalcStss == TRUE) StssLcase = DgnStrb.Stss;

	if (nForType > 0)
	{
		ForcePart1 = DgnStrbPart.ForceP1;
		ForcePart2 = DgnStrbPart.ForceP2;
		StressPart1 = DgnStrb.Stress;
		StressPart2 = DgnStrbPart.StressP2;
	}


	T_STCT_D StctD; StctD.Initialize();
	m_pAttrCtrl->GetStct(StctD);

	if (iStepNo > 0)
	{
		ASSERT(0);
	}

	// Get Load Case Name(DL,LL,EL,TP,TS,CP,CS,SP,SS,SUM).
	if (SgldD.LoadCaseId == 0 && SgldD.LoadCaseName.IsEmpty())
	{
		//++++++++++++++++++++++++++++++++++++++++++++++++++
		// 반드시 함수를 호출하는 곳에서 Stage를 설정한 후에 사용해야 한다.
		SgldD.Initialize();
		if (!m_pStageInfo->GetSgldPost(SgldK, SgldD))	return FALSE;
		//++++++++++++++++++++++++++++++++++++++++++++++++++
	}

	CString strCSLCType = _T("");
	CString strLCSubType = _T("");
	GetStageLoadDgnType(SgldD.LoadCaseName, StctD, strCSLCType, strLCSubType);
	ForceLcase.strType = StressLcase.strType = strCSLCType;
	ForceLcase.strLCSubType = StressLcase.strLCSubType = strLCSubType;

	return TRUE;
}

BOOL CCRCForceCtrl::Get_Sgld_Expo(ElemPairK ElemK, T_SGLD_K SgldK, T_SGLD_D& SgldD, int iStepNo, _DGN_FORC_CRC& ForceLcase, _DGN_STRS_CRC& StressLcase, _DGN_SHRS_ADD& StssLcase)
{
	ForceLcase.Initialize();
	StressLcase.Initialize();
	StssLcase.Initialize();

	int iLcaseType = D_LOADCASE_STAGE;
	T_STRB_D StrMaxData; StrMaxData.Initialize();
	// Principle.
	T_STSS_D StssMaxData; StssMaxData.Initialize();
	T_STCT_D StctD; StctD.Initialize();
	m_pAttrCtrl->GetStct(StctD);

	T_LCOM_D LcasD;
	LcasD.Initialize();
	if (!m_pPostCtrl->MakeLoadComb(D_LOADCASE_STAGE, SgldK, LcasD)) { ASSERT(0); return FALSE; }
	if (iStepNo > 0)	m_pPostCtrl->SelectLoadCombNew(LcasD, iStepNo, 2);	// 0=Nonlinear, 1=Pushover, 2=Construction.
	else			m_pPostCtrl->SelectLoadCombNew(LcasD);
	// Strb
	m_pPostCtrl->GetStrbNew(ElemK.first, &StrMaxData, 0, 0, TRUE, NULL, ElemK.second);
	// Stss
	m_pPostCtrl->GetStssNew(ElemK.first, &StssMaxData, 0, 0, TRUE);

	// Get Load Case Name(DL,LL,EL,TP,TS,CP,CS,SP,SS,SUM).
	if (SgldD.LoadCaseId == 0 && SgldD.LoadCaseName.IsEmpty())
	{
		//++++++++++++++++++++++++++++++++++++++++++++++++++
		// 반드시 함수를 호출하는 곳에서 Stage를 설정한 후에 사용해야 한다.
		SgldD.Initialize();
		if (!m_pStageInfo->GetSgldPost(SgldK, SgldD))	return FALSE;
		//++++++++++++++++++++++++++++++++++++++++++++++++++
	}

	CString strCSLCType = _T("");
	CString strLCSubType = _T("");
	GetStageLoadDgnType(SgldD.LoadCaseName, StctD, strCSLCType, strLCSubType);
	ForceLcase.strType = StressLcase.strType = strCSLCType;
	ForceLcase.strLCSubType = StressLcase.strLCSubType = strLCSubType;

	// Set Forces.
	Get_StrbToForce(StrMaxData, ForceLcase);
	// Normal Stress
	Get_LoadCaseStress(ElemK, StrMaxData, StressLcase);
	// Principle 
	Get_LoadCaseStss(StssMaxData, StssLcase);

	return TRUE;
}

