	_DGN_SBCFFORC_LCASE      DgnSbcf;
	_DGN_SBCFFORC_PART_LCASE DgnSbcfPart;
	GetSbcf4Elem(ElemK, nForType, iLcaseType, iLcaseKey, DgnSbcf, DgnSbcfPart, bSpc);  // Civil v891 US - BS Assessment - CS454 Special Moving Load Case (CIVIL-1069) 

