BOOL CCRCForceCtrl::Get_Stld_EX(ElemPairK ElemK, T_STLD_K StldK, int nForType, BOOL bCalcStss, _DGN_FORC_CRC_EX& ForceLcase,
	_DGN_STRS_ADD_EX& StressAdd, _DGN_STRS_CRC_EX& StressLcase, _DGN_SHRS_ADD_EX& StssLcase,
	_DGN_FORC_CRC_EX& ForcePart1, _DGN_STRS_CRC_EX& StressPart1, _DGN_FORC_CRC_EX& ForcePart2,
	_DGN_STRS_CRC_EX& StressPart2)
{
	//PROFILING(_T("CCRCForceCtrl::Get_Stld"));

	// Get Member Force by Element.
	int nLcaseType = D_LOADCASE_STATIC;

	//
	_DGN_STRBFORC_LCASE_EX      DgnStrb;
	_DGN_STRBFORC_PART_LCASE_EX DgnStrbPart;
	GetStld4Elem_EX(ElemK, nForType, nLcaseType, StldK, DgnStrb, DgnStrbPart);

	ForceLcase = DgnStrb.Force;
	StressLcase = DgnStrb.Stress;
	if (bCalcStss == TRUE) StssLcase = DgnStrb.Stss;

	if (nForType > 0)
	{
		ForcePart1 = DgnStrbPart.ForceP1;
		ForcePart2 = DgnStrbPart.ForceP2;
		StressPart1 = DgnStrb.Stress;
		StressPart2 = DgnStrbPart.StressP2;
	}

	// Set Force Type (D,L,W,...).
	T_STLD_D StldD;
	StldD.Initialize();
	if (!m_pPostCtrl->GetStld(StldK, StldD))	return FALSE;
	ForceLcase.strType = StressLcase.strType = StldD.LoadCaseType;
	ForcePart1.strType = StressPart1.strType = StldD.LoadCaseType;
	ForcePart2.strType = StressPart2.strType = StldD.LoadCaseType;

	return TRUE;
}

