BOOL CCRCForceCtrl::Get_Sbcf_EX(ElemPairK ElemK, unsigned int iLcaseKey, int nForType, BOOL bCalcStss, int iLcaseType,
	ADGNFORCE_EX& aForceLcase, ADGNSTRESS_EX& aStressLcase, ADGNSHRSADD_EX& aStssLcase,
	ADGNFORCE_EX& aForceP1, ADGNSTRESS_EX& aStressP1, ADGNFORCE_EX &aForceP2,
	ADGNSTRESS_EX &aStressP2)
{
	aForceLcase.RemoveAll();
	aStressLcase.RemoveAll();
	aStssLcase.RemoveAll();

	aForceLcase.SetSize(cFORC_CON);
	aStressLcase.SetSize(cFORC_CON);
	aStssLcase.SetSize(cFORC_CON);
	aForceP1.SetSize(cFORC_CON);
	aForceP2.SetSize(cFORC_CON);
	aStressP1.SetSize(cFORC_CON);
	aStressP2.SetSize(cFORC_CON);

	if (!(iLcaseType == D_LOADCASE_MOVING || iLcaseType == D_LOADCASE_SETTLE))	return FALSE;

	_DGN_SBCFFORC_LCASE_EX      DgnSbcf;
	_DGN_SBCFFORC_PART_LCASE_EX DgnSbcfPart;
	GetSbcf4Elem_EX(ElemK, nForType, iLcaseType, iLcaseKey, DgnSbcf, DgnSbcfPart);

	for (int i = 0; i < cFORC_CON; ++i)
	{
		BOOL bMax = (i % 2 == 0 ? TRUE : FALSE);
		// Set Force Type.
		CString strForType = GetConCurrForceType(i);
		DgnSbcf.Force[i].strType = strForType;
		// Set Forces.
		aForceLcase.SetAt(i, DgnSbcf.Force[i]);

		aStressLcase.SetAt(i, DgnSbcf.Stress[i]);

		if (bCalcStss == TRUE) aStssLcase.SetAt(i, DgnSbcf.Stss[i]);

		// Part별 Concurrent force는 없음. 해석에서 계산되면 적용 
		if (nForType > 0)
		{
			//       DgnSbcfPart.ForceP1[i].strType = strForType;
			//       aForceP1.SetAt(i, DgnSbcfPart.ForceP1[i]);
			//       DgnSbcfPart.ForceP2[i].strType = strForType;
			//       aForceP2.SetAt(i, DgnSbcfPart.ForceP2[i]);
			//
			aStressP1.SetAt(i, DgnSbcf.Stress[i]);
			aStressP2.SetAt(i, DgnSbcfPart.StressP2[i]);
		}
	}

	return TRUE;
}

