	_DGN_SBCFFORC_LCASE_EX      DgnSbcf;
	_DGN_SBCFFORC_PART_LCASE_EX DgnSbcfPart;
	GetSbcf4Elem_EX(ElemK, nForType, iLcaseType, iLcaseKey, DgnSbcf, DgnSbcfPart, bSpc);

	int i = iMaxMinType - 1;
