BOOL CCRCForceCtrl::Get_Sbcf_EX(ElemPairK ElemK, unsigned int iLcaseKey, int nForType, BOOL bCalcStss, int iLcaseType,
	ADGNFORCE_EX& aForceLcase, BOOL bElemAll)
{
	aForceLcase.RemoveAll();

	if (!bElemAll) ASSERT(0);

	if (!(iLcaseType == D_LOADCASE_MOVING || iLcaseType == D_LOADCASE_SETTLE))	return FALSE;

	aForceLcase.SetSize(cFORC_CON);

	// Get Force Data by Load Case.
	T_LCOM_D LcasD;
	LcasD.Initialize();
	if (!m_pPostCtrl->MakeLoadComb(iLcaseType, iLcaseKey, LcasD)) { ASSERT(0); return FALSE; }
	m_pPostCtrl->SelectLoadCombNew(LcasD);

	// Concurrent Forces.
	T_SBCF_D StrMaxData; StrMaxData.Initialize();
	T_SBCF_D StrMinData; StrMinData.Initialize();
	m_pPostCtrl->GetSbcfNew(ElemK.first, &StrMaxData, &StrMinData, NULL, TRUE, FALSE, ElemK.second);

	for (int i = 0; i < cFORC_CON; ++i)
	{
		_DGN_FORC_CRC_EX ForceLcase;
		BOOL bMax = (i % 2 == 0 ? TRUE : FALSE);
		// Set Force Type.
		ForceLcase.strType = GetConCurrForceType(i);
		// Set Forces.
		Get_SbcfToForce_EX(bMax, i, StrMaxData, StrMinData, ForceLcase);
		aForceLcase.SetAt(i, ForceLcase);
	}
	return TRUE;
}

BOOL CCRCForceCtrl::Get_Gilc_EX(ElemPairK ElemK, T_GILC_K GilcK, int nForType, BOOL bCalcStss, int iLcaseType, CString& strLcaseNa,
	_DGN_FORC_CRC_EX& ForceLcase, _DGN_STRS_CRC_EX& StressLcase, _DGN_SHRS_ADD_EX& StssLcase,
	_DGN_FORC_CRC_EX& ForcePart1, _DGN_STRS_CRC_EX& StressPart1, _DGN_FORC_CRC_EX& ForcePart2,
	_DGN_STRS_CRC_EX& StressPart2, int iMaxMinType)
{
	strLcaseNa = _T("");
	ForceLcase.Initialize();
	StressLcase.Initialize();
	StssLcase.Initialize();

	// iLcaseType.
	// 0:Dead, 1:Other Dead Load, 
	// 2:Vehicle Live Load, 3:Crowded Line Load, 4:Other Live Load (2,3,4는 일본 버전에만)  
	BOOL bMaxMin = (iLcaseType == 2 || iLcaseType == 3 || iLcaseType == 4 ? TRUE : FALSE);
	if (!bMaxMin)
	{
		_DGN_STRBFORC_LCASE_EX      DgnStrb;
		_DGN_STRBFORC_PART_LCASE_EX DgnStrbPart;
		GetStrb4Elem_EX(ElemK, nForType, D_LOADCASE_GRIDMODEL, GilcK, DgnStrb, DgnStrbPart);

		ForceLcase = DgnStrb.Force;
		StressLcase = DgnStrb.Stress;
		if (bCalcStss == TRUE) StssLcase = DgnStrb.Stss;

		if (nForType > 0)
		{
			ForcePart1 = DgnStrbPart.ForceP1;
			ForcePart2 = DgnStrbPart.ForceP2;
			StressPart1 = DgnStrb.Stress;
			StressPart2 = DgnStrbPart.StressP2;
		}

		// Set Force Type (D,L,W,...).
		if (iLcaseType == 0)		strLcaseNa = _T("GD");	// Dead Load.
		else if (iLcaseType == 1)	strLcaseNa = _T("GOD");	// Other Dead Load.
		else	ASSERT(0);
		ForceLcase.strType = StressLcase.strType = strLcaseNa;

	}
	else
	{
		if (iLcaseType == 2)		strLcaseNa = _T("GVH");	// Vehicle Live Load.
		else if (iLcaseType == 3)	strLcaseNa = _T("GCR");	// Crowded Line Load.
		else if (iLcaseType == 4)	strLcaseNa = _T("GOL");	// Other Live Load.
		else	ASSERT(0);

		_DGN_SBCFFORC_LCASE_EX      DgnSbcf;
		_DGN_SBCFFORC_PART_LCASE_EX DgnSbcfPart;
		GetSbcf4Elem_EX(ElemK, nForType, D_LOADCASE_GRIDMODEL, GilcK, DgnSbcf, DgnSbcfPart);

		int i = iMaxMinType - 1;
		ForceLcase = DgnSbcf.Force[i];
		StressLcase = DgnSbcf.Stress[i];
		if (bCalcStss == TRUE) StssLcase = DgnSbcf.Stss[i];
		// Set Force Type.
		ForceLcase.strType = StressLcase.strType = GetConCurrForceType(i);

		if (nForType > 0)
		{
			//       DgnSbcfPart.ForceP1[i].strType = strForType;
			//       aForceP1.SetAt(i, DgnSbcfPart.ForceP1[i]);
			//       DgnSbcfPart.ForceP2[i].strType = strForType;
			//       aForceP2.SetAt(i, DgnSbcfPart.ForceP2[i]);
			//
			StressPart1 = DgnSbcf.Stress[i];
			StressPart2 = DgnSbcfPart.StressP2[i];
		}
	}
	return TRUE;
}

BOOL CCRCForceCtrl::Get_Gilc_EX(ElemPairK ElemK, T_GILC_K GilcK, int nForType, BOOL bCalcStss, int iLcaseType, CString& strLcaseNa,
	ADGNFORCE_EX& aForceLcase)
{
	strLcaseNa = _T("");
	aForceLcase.RemoveAll();

	// Get Force Data by Load Case.
	T_LCOM_D LcasD;
	LcasD.Initialize();
	if (!m_pPostCtrl->MakeLoadComb(D_LOADCASE_GRIDMODEL, GilcK, LcasD)) { ASSERT(0); return FALSE; }
	m_pPostCtrl->SelectLoadCombNew(LcasD);

	// iLcaseType.
	// 0:Dead, 1:Other Dead Load, 
	// 2:Vehicle Live Load, 3:Crowded Line Load, 4:Other Live Load (2,3,4는 일본 버전에만)  
	BOOL bMaxMin = (iLcaseType == 2 || iLcaseType == 3 || iLcaseType == 4 ? TRUE : FALSE);
	if (!bMaxMin)
	{

		T_STRB_D StrMaxData; StrMaxData.Initialize();
		m_pPostCtrl->GetStrbNew(ElemK.first, &StrMaxData, 0, 0, TRUE, NULL, ElemK.second);

		_DGN_FORC_CRC_EX ForceLcase;
		// Set Force Type (D,L,W,...).
		if (iLcaseType == 0)				strLcaseNa = _T("GD");	// Dead Load.
		else if (iLcaseType == 1)	strLcaseNa = _T("GOD");	// Other Dead Load.
		else	ASSERT(0);
		ForceLcase.strType = strLcaseNa;
		// Set Forces.
		Get_StrbToForce_EX(StrMaxData, ForceLcase);
		aForceLcase.Add(ForceLcase);
	}
	else
	{
		aForceLcase.SetSize(cFORC_CON);

		if (iLcaseType == 2)				strLcaseNa = _T("GVH");	// Vehicle Live Load.
		else if (iLcaseType == 3)	strLcaseNa = _T("GCR");	// Crowded Line Load.
		else if (iLcaseType == 4)	strLcaseNa = _T("GOL");	// Other Live Load.
		else	ASSERT(0);

		// Concurrent Forces.
		T_SBCF_D StrMaxData; StrMaxData.Initialize();
		T_SBCF_D StrMinData; StrMinData.Initialize();

		m_pPostCtrl->GetSbcfNew(ElemK.first, &StrMaxData, &StrMinData, NULL, TRUE, FALSE, ElemK.second);

		for (int i = 0; i < cFORC_CON; ++i)
		{
			_DGN_FORC_CRC_EX ForceLcase;
			BOOL bMax = (i % 2 == 0 ? TRUE : FALSE);
			// Set Force Type.
			ForceLcase.strType = GetConCurrForceType(i);
			// Set Forces.
			Get_SbcfToForce_EX(bMax, i, StrMaxData, StrMinData, ForceLcase);
			aForceLcase.SetAt(i, ForceLcase);
		}
	}
	return TRUE;
}

BOOL CCRCForceCtrl::Get_Gilc_EX(ElemPairK ElemK, T_GILC_K GilcK, int nForType, BOOL bCalcStss, int iLcaseType, CString& strLcaseNa, ADGNFORCE_EX& aForceLcase,
	ADGNSTRESS_EX& aStressLcase, ADGNSHRSADD_EX &aStssLcase, ADGNFORCE_EX &aForceP1,
	ADGNSTRESS_EX& aStressP1, ADGNFORCE_EX &aForceP2, ADGNSTRESS_EX &aStressP2)
{
	strLcaseNa = _T("");
	aForceLcase.RemoveAll();
	aStressLcase.RemoveAll();
	aStssLcase.RemoveAll();

	// iLcaseType.
	// 0:Dead, 1:Other Dead Load, 
	// 2:Vehicle Live Load, 3:Crowded Line Load, 4:Other Live Load (2,3,4는 일본 버전에만)  
	BOOL bMaxMin = (iLcaseType == 2 || iLcaseType == 3 || iLcaseType == 4 ? TRUE : FALSE);
	if (!bMaxMin)
	{
		_DGN_STRBFORC_LCASE_EX      DgnStrb;
		_DGN_STRBFORC_PART_LCASE_EX DgnStrbPart;
		GetStrb4Elem_EX(ElemK, nForType, D_LOADCASE_GRIDMODEL, GilcK, DgnStrb, DgnStrbPart);

		// Set Force Type (D,L,W,...).
		if (iLcaseType == 0)		strLcaseNa = _T("GD");	// Dead Load.
		else if (iLcaseType == 1)	strLcaseNa = _T("GOD");	// Other Dead Load.
		else	ASSERT(0);
		DgnStrb.Force.strType = DgnStrb.Stress.strType = strLcaseNa;
		aForceLcase.Add(DgnStrb.Force);

		// Stress.
		aStressLcase.Add(DgnStrb.Stress);

		// Principle.    
		aStssLcase.Add(DgnStrb.Stss);

		if (nForType > 0)
		{
			aForceP1.Add(DgnStrbPart.ForceP1);
			aForceP2.Add(DgnStrbPart.ForceP2);
			aStressP1.Add(DgnStrb.Stress);
			aStressP2.Add(DgnStrbPart.StressP2);
		}
	}
	else
	{
		aForceLcase.SetSize(cFORC_CON);
		aStressLcase.SetSize(cFORC_CON);
		aStssLcase.SetSize(cFORC_CON);
		aForceP1.SetSize(cFORC_CON);
		aForceP2.SetSize(cFORC_CON);
		aStressP1.SetSize(cFORC_CON);
		aStressP2.SetSize(cFORC_CON);

		if (iLcaseType == 2)		strLcaseNa = _T("GVH");	// Vehicle Live Load.
		else if (iLcaseType == 3)	strLcaseNa = _T("GCR");	// Crowded Line Load.
		else if (iLcaseType == 4)	strLcaseNa = _T("GOL");	// Other Live Load.
		else	ASSERT(0);

		_DGN_SBCFFORC_LCASE_EX      DgnSbcf;
		_DGN_SBCFFORC_PART_LCASE_EX DgnSbcfPart;
		GetSbcf4Elem_EX(ElemK, nForType, D_LOADCASE_GRIDMODEL, GilcK, DgnSbcf, DgnSbcfPart);

		for (int i = 0; i < cFORC_CON; ++i)
		{
			BOOL bMax = (i % 2 == 0 ? TRUE : FALSE);
			// Set Force Type.
			CString strForType = GetConCurrForceType(i);
			DgnSbcf.Force[i].strType = strForType;
			// Set Forces.
			aForceLcase.SetAt(i, DgnSbcf.Force[i]);

			aStressLcase.SetAt(i, DgnSbcf.Stress[i]);

			if (bCalcStss == TRUE) aStssLcase.SetAt(i, DgnSbcf.Stss[i]);

			// Part별 Concurrent force는 없음. 해석에서 계산되면 적용 
			if (nForType > 0)
			{
				//       DgnSbcfPart.ForceP1[i].strType = strForType;
				//       aForceP1.SetAt(i, DgnSbcfPart.ForceP1[i]);
				//       DgnSbcfPart.ForceP2[i].strType = strForType;
				//       aForceP2.SetAt(i, DgnSbcfPart.ForceP2[i]);
				//
				aStressP1.SetAt(i, DgnSbcf.Stress[i]);
				aStressP2.SetAt(i, DgnSbcfPart.StressP2[i]);
			}
		}
	}
	return TRUE;
}

BOOL CCRCForceCtrl::Get_Lcom_EX(ElemPairK ElemK, T_LCOM_K LcomK, int nForType, BOOL bCalcStss,
	_DGN_FORC_CRC_EX& ForceLcase, _DGN_STRS_ADD_EX& StressAdd, _DGN_STRS_CRC_EX& StressLcase,
	_DGN_SHRS_ADD_EX& StssLcase, _DGN_FORC_CRC_EX& ForcePart1, _DGN_STRS_CRC_EX& StressPart1,
	_DGN_FORC_CRC_EX& ForcePart2, _DGN_STRS_CRC_EX& StressPart2, int iMaxMinType) // Add by GAY. MNET:2903. ('07.07.31).
{
	//PROFILING(_T("CCRCForceCtrl::Get_Lcom"));

	ForceLcase.Initialize();
	StressAdd.Initialize();
	StressLcase.Initialize();
	StssLcase.Initialize();

	// Get Load Combination Data.
	T_LCOM_D LcomD;
	LcomD.Initialize();
	if (CDBLib::IsCSGCode(m_iDgnCode) == TRUE)
	{
		if (m_iDgnCode == EUROCODE4_2_04_CSG || m_iDgnCode == IRC22_08_CSG || m_iDgnCode == IRC22_15_CSG) m_pAttrCtrl->GetLcom(D_LCOMTYPE_STEEL, LcomK, LcomD);
		else                                  m_pAttrCtrl->GetLcom(D_LCOMTYPE_STLCOMP, LcomK, LcomD);
	}
	else                                    m_pAttrCtrl->GetLcom(D_LCOMTYPE_CONCRETE, LcomK, LcomD);

	int iLcaseType = Get_LcaseCombType();

	// Get Member Force by Element.
	if (!m_pAttrCtrl->IsConCurrentComb12(LcomD))  // Not consider Concurrent Forces.
	{
		_DGN_STRBFORC_LCASE_EX      DgnStrb;
		_DGN_STRBFORC_PART_LCASE_EX DgnStrbPart;
		GetLcom4Elem_EX(ElemK, nForType, iLcaseType, LcomK, iMaxMinType, DgnStrb, DgnStrbPart);

		ForceLcase = DgnStrb.Force;
		StressLcase = DgnStrb.Stress;
		if (bCalcStss == TRUE) StssLcase = DgnStrb.Stss;

		if (nForType > 0)
		{
			ForcePart1 = DgnStrbPart.ForceP1;
			ForcePart2 = DgnStrbPart.ForceP2;
			StressPart1 = DgnStrb.Stress;
			StressPart2 = DgnStrbPart.StressP2;
		}

		ForceLcase.strType = StressLcase.strType = LcomD.LoadCombName;

		//     T_STRB_D StrbD;
		//     T_STSS_D StssD;  
		//   
		//     if(iMaxMinType == 0)
		//     {
		//       StrbD = StrMaxData;
		//       StssD = StssMaxData;
		//     }
		//     else
		//     {
		//       BOOL bMaxLcom = (iMaxMinType%2==1)? TRUE : FALSE;
		//       StrbD = (bMaxLcom)? StrMaxData  : StrMinData;
		//       StssD = (bMaxLcom)? StssMaxData : StssMinData;      
		//     }   

	}
	else // Consider Concurrent Forces.
	{
		_DGN_SBCFFORC_LCASE_EX      DgnSbcf;
		_DGN_SBCFFORC_PART_LCASE_EX DgnSbcfPart;
		GetSbcf4Elem_EX(ElemK, nForType, iLcaseType, LcomK, DgnSbcf, DgnSbcfPart);

		int i = iMaxMinType - 1;
		ForceLcase = DgnSbcf.Force[i];
		StressLcase = DgnSbcf.Stress[i];
		if (bCalcStss == TRUE) StssLcase = DgnSbcf.Stss[i];
		// Set Force Type.
		ForceLcase.strType = StressLcase.strType = GetConCurrForceType(i);

		if (nForType > 0)
		{
			//       DgnSbcfPart.ForceP1[i].strType = strForType;
			//       aForceP1.SetAt(i, DgnSbcfPart.ForceP1[i]);
			//       DgnSbcfPart.ForceP2[i].strType = strForType;
			//       aForceP2.SetAt(i, DgnSbcfPart.ForceP2[i]);
			//
			StressPart1 = DgnSbcf.Stress[i];
			StressPart2 = DgnSbcfPart.StressP2[i];
		}
	}

	return TRUE;
}


