BOOL CCRCForceCtrl::Get_Stld(ElemPairK ElemK, T_STLD_K StldK, int nForType, BOOL bCalcStss, double dFactor, BOOL bReciLcase)
{
	_DGN_FORC_CRC ForceLcase;
	_DGN_STRS_ADD StressAdd;
	_DGN_STRS_CRC StressLcase;
	_DGN_SHRS_ADD StssLcase;

	_DGN_FORC_CRC ForcePart1;
	_DGN_STRS_CRC StressPart1;
	_DGN_FORC_CRC ForcePart2;
	_DGN_STRS_CRC StressPart2;

	if (!Get_Stld(ElemK, StldK, nForType, bCalcStss, ForceLcase, StressAdd, StressLcase, StssLcase,
		ForcePart1, StressPart1, ForcePart2, StressPart2))	return FALSE;

	// Set Forces by DimType.
	Set_DimTypeForc(ForceLcase);
	// Apply Lcase Factor.
	ForceLcase *= dFactor;
	// Stress.
	StressLcase *= dFactor;

	_DGN_SCFP_PART_LCASE ScfpPartLcase;
	T_STLD_K StldScfpK = 0;
	if (m_arStldScfpK.Lookup(StldK, StldScfpK))
	{
		Get_StldScfp(ElemK, StldScfpK, ScfpPartLcase);

		ScfpPartLcase.ForceP1 *= dFactor;
		ScfpPartLcase.ForceP2 *= dFactor;

		if (CDBLib::IsStldTL(ForceLcase.strType))
		{
			m_StressScfpTe.ForceP1 += ScfpPartLcase.ForceP1;
			m_StressScfpTe.ForceP2 += ScfpPartLcase.ForceP2;
		}
		else
		{
			m_StressScfpRe.ForceP1 += ScfpPartLcase.ForceP1;
			m_StressScfpRe.ForceP2 += ScfpPartLcase.ForceP2;
		}
		// 
		m_ForceScfpSum += ForceLcase;
	}

	// Add by ZINU.('05.01.03). Consider Stress.
	StressAdd *= dFactor;
	m_StressAdd += StressAdd;
	// Principle.
	StssLcase *= dFactor;
	m_StressShr += StssLcase;

	if (nForType > 0)
	{
		ForcePart1 *= dFactor;
		StressPart1 *= dFactor;
		ForcePart2 *= dFactor;
		StressPart2 *= dFactor;

		m_ForceRemnP1 += ForcePart1;
		m_StressRemnP1 += StressPart1;
		m_ForceRemnP2 += ForcePart2;
		m_StressRemnP2 += StressPart2;
	}

	T_STLD_K TempK = 0;
	if (m_mapPlcbStldK.Lookup(StldK, TempK))
	{
		m_ForceAddDL += ForceLcase;
		// Stress
		m_StressNorDL += StressLcase;
		// JTG
		m_StressAddDL += StressLcase;
	}
	else if (CDBLib::IsStldDL(ForceLcase.strType))	// Dead.
	{
		if (bReciLcase)	m_ForceDrec += ForceLcase;
		else						m_ForceDnon += ForceLcase;

		if (m_bIsPLCB == FALSE)
		{
			m_ForceAddDL += ForceLcase;

			// Stress
			m_StressNorDL += StressLcase;
			// JTG
			m_StressAddDL += StressLcase;
		}
		if (CDBLib::IsStldLTerm(ForceLcase.strType))
		{
			m_ForceLTerm += ForceLcase;
			m_StressLTerm += StressLcase;
			m_StressLTermP2 += StressPart2;
		}
	}
	else if (CDBLib::IsStldLL(ForceLcase.strType))	// Live.
	{
		if (bReciLcase)	m_ForceLrec += ForceLcase;
		else						m_ForceLnon += ForceLcase;

		// Stress
		m_StressNorLL += StressLcase;
		m_StressSTermP2 += StressPart2;
	}
	else
	{
		m_ForceRemn += ForceLcase;
		// Stress.
		m_StressRemn += StressLcase;
	}

	if (Is_JtgStldLL(ForceLcase.strType))
	{
		m_ForceLL += ForceLcase;
		// Stress.
		m_StressJtgLL += StressLcase;
	}

	// For JTG, Tendon Stress.
	m_ForceJtgTndn += ForceLcase;

	// For TB 10002.3-2005, Force Stress
	// DL
	if (m_iDgnCode == TB_10002_3_05 || m_iDgnCode == RC_TB_10002_3_05)
	{
		if (Is_TB05StldDL(ForceLcase.strType))
		{
			m_ForceDL_TB05 += ForceLcase;
			m_StressDL_TB05 += StressLcase;
		}
		// LL
		if (Is_TB05StldLL(ForceLcase.strType))
		{
			m_ForceLL_TB05 += ForceLcase;
			m_StressLL_TB05 += StressLcase;
		}
	}
	else if (m_iDgnCode == RC_JTG_B02_01_2008 || m_iDgnCode == RC_CJJ_166_2011)
	{
		//		if(CDBLib::IsStldEL(ForceLcase.strType))
		//		{
		//			if(dFactor!=0.0)
		//				m_ForceEQE2_JTG += ForceLcase/dFactor;
		//		}
		if (IsPermanentLoad_JTG_B02(ForceLcase.strType))
		{
			m_ForceEQE2_JTG += ForceLcase;
		}
		if (IsSelfWeightLoad_JTG_B02(ForceLcase.strType))
		{
			m_ForceWeight_JTG += ForceLcase;
		}
	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_Splc(ElemPairK ElemK, T_SPLC_K SplcK, int nForType, BOOL bCalcStss, double dFactor)
{
	//PROFILING(_T("CCRCForceCtrl::Get_Splc"));

	_DGN_FORC_CRC ForceLcase;
	_DGN_STRS_CRC StressLcase;
	_DGN_SHRS_ADD StssLcase;
	//
	_DGN_FORC_CRC ForcePart1;
	_DGN_STRS_CRC StressPart1;
	_DGN_FORC_CRC ForcePart2;
	_DGN_STRS_CRC StressPart2;
	if (!Get_Splc(ElemK, SplcK, nForType, bCalcStss, ForceLcase, StressLcase, StssLcase,
		ForcePart1, StressPart1, ForcePart2, StressPart2))	return FALSE;
	// Set Forces by DimType.
	Set_DimTypeForc(ForceLcase);
	// Apply Lcase Factor.
	ForceLcase *= dFactor;
	m_ForceRemn += ForceLcase;
	// Stress
	StressLcase *= dFactor;
	m_StressRemn += StressLcase;
	// Principle.
	StssLcase *= dFactor;
	m_StressShr += StssLcase;

	// For JTG, Tendon Stress.
	m_ForceJtgTndn += ForceLcase;

	if (nForType > 0)
	{
		ForcePart1 *= dFactor;
		StressPart1 *= dFactor;
		ForcePart2 *= dFactor;
		StressPart2 *= dFactor;

		m_ForceRemnP1 += ForcePart1;
		m_StressRemnP1 += StressPart1;
		m_ForceRemnP2 += ForcePart2;
		m_StressRemnP2 += StressPart2;
	}

	return TRUE;
}

