BOOL CCRCForceCtrl::Get_This(ElemPairK ElemK, T_THIS_K ThisK, int nForType, BOOL bCalcStss, double dFactor)
{
	//PROFILING(_T("CCRCForceCtrl::Get_This"));

	_DGN_FORC_CRC ForceLcase;
	_DGN_STRS_CRC StressLcase;
	_DGN_SHRS_ADD StssLcase;
	//
	_DGN_FORC_CRC ForcePart1;
	_DGN_STRS_CRC StressPart1;
	_DGN_FORC_CRC ForcePart2;
	_DGN_STRS_CRC StressPart2;

	if (!Get_This(ElemK, ThisK, nForType, bCalcStss, ForceLcase, StressLcase, StssLcase,
		ForcePart1, StressPart1, ForcePart2, StressPart2))	return FALSE;
	// Set Forces by DimType.
	Set_DimTypeForc(ForceLcase);
	// Apply Lcase Factor.
	ForceLcase *= dFactor;
	m_ForceRemn += ForceLcase;
	// Stress
	StressLcase *= dFactor;
	m_StressRemn += StressLcase;
	// Principle.
	StssLcase *= dFactor;
	m_StressShr += StssLcase;

	// For JTG, Tendon Stress.
	m_ForceJtgTndn += ForceLcase;

	if (nForType > 0)
	{
		ForcePart1 *= dFactor;
		StressPart1 *= dFactor;
		ForcePart2 *= dFactor;
		StressPart2 *= dFactor;

		m_ForceRemnP1 += ForcePart1;
		m_StressRemnP1 += StressPart1;
		m_ForceRemnP2 += ForcePart2;
		m_StressRemnP2 += StressPart2;
	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_Sgld(ElemPairK ElemK, T_SGLD_K SgldK, int nForType, BOOL bCalcStss, double dFactor, BOOL bReciLcase, BOOL bIncludeTP, int iStepNo)
{
	//PROFILING(_T("CCRCForceCtrl::Get_Sgld"));

	_DGN_FORC_CRC ForceLcase;
	_DGN_STRS_CRC StressLcase;
	_DGN_SHRS_ADD StssLcase;
	//
	_DGN_FORC_CRC ForcePart1;
	_DGN_STRS_CRC StressPart1;
	_DGN_FORC_CRC ForcePart2;
	_DGN_STRS_CRC StressPart2;

	if (!Get_Sgld(ElemK, SgldK, nForType, bCalcStss, iStepNo, ForceLcase, StressLcase, StssLcase,
		ForcePart1, StressPart1, ForcePart2, StressPart2))	return FALSE;

	// Set Forces by DimType.
	Set_DimTypeForc(ForceLcase);
	// Apply Lcase Factor.
	ForceLcase *= dFactor;
	StressLcase *= dFactor;

	_DGN_SCFP_PART_LCASE ScfpPartLcase;
	T_SGLD_K SgldScfpK = 0;
	BOOL bIsScfp = m_arSgldScfpK.Lookup(SgldK, SgldScfpK);
	if (bIsScfp == TRUE)
	{
		Get_SgldScfp(ElemK, SgldK, ScfpPartLcase);

		ScfpPartLcase.ForceP1 *= dFactor;
		ScfpPartLcase.ForceP2 *= dFactor;

		if (ForceLcase.strType == _T("EL"))
		{
			// m_arSgldScfpK 에서 Erection은 온도만 추가 하고 있음
			// 연관함수 BOOL IsErectionScfp(int nType, T_STCT_D &StctD); 참고
			m_StressScfpTe.ForceP1 += ScfpPartLcase.ForceP1;
			m_StressScfpTe.ForceP2 += ScfpPartLcase.ForceP2;
		}
		else if (ForceLcase.strType == _T("CS"))
		{
			m_StressScfpCr.ForceP1 += ScfpPartLcase.ForceP1;
			m_StressScfpCr.ForceP2 += ScfpPartLcase.ForceP2;
			// Creep secondary만 적용한다. [5/26/2015 joahn] 이대근 이사보님, 박창신 사원님 요청
			m_ForceScfpCrp += ForceLcase;
			m_ForceScfpSum += ForceLcase;
		}
		else if (ForceLcase.strType == _T("SS"))
		{
			m_StressScfpSh.ForceP1 += ScfpPartLcase.ForceP1;
			m_StressScfpSh.ForceP2 += ScfpPartLcase.ForceP2;
			m_ForceScfpShr += ForceLcase;
			m_ForceScfpSum += ForceLcase;
		}
		else
		{
			m_StressScfpRe.ForceP1 += ScfpPartLcase.ForceP1;
			m_StressScfpRe.ForceP2 += ScfpPartLcase.ForceP2;
		}
	}

	// Principle.
	StssLcase *= dFactor;
	m_StressShr += StssLcase;

	if (nForType > 0)
	{
		ForcePart1 *= dFactor;
		StressPart1 *= dFactor;
		ForcePart2 *= dFactor;
		StressPart2 *= dFactor;

		m_ForceRemnP1 += ForcePart1;
		m_StressRemnP1 += StressPart1;
		m_ForceRemnP2 += ForcePart2;
		m_StressRemnP2 += StressPart2;
	}

	// Add by ZINU.('05.07.04). Get Force by All Sgld.
	m_ForceStag += ForceLcase;
	if (ForceLcase.strType == _T("DL"))	// Dead.
	{
		if (bReciLcase)	m_ForceDrec += ForceLcase;
		else			m_ForceDnon += ForceLcase;
		m_ForceAddDL += ForceLcase;
		m_ForceLTerm += ForceLcase;
		// Stress.
		m_StressNorDL += StressLcase;
		m_StressAddDL += StressLcase;
		m_StressLTerm += StressLcase;
		m_StressLTermP2 += StressPart2;
	}
	else if (ForceLcase.strType == _T("LL"))	// Live.
	{
		if (bReciLcase)	m_ForceLrec += ForceLcase;
		else			m_ForceLnon += ForceLcase;
		// Stress.
		m_StressNorLL += StressLcase;
	}
	else if (ForceLcase.strType == _T("EL"))	// Erection.
	{
		if (CDBLib::IsStldDL(ForceLcase.strLCSubType))
		{
			(bReciLcase ? m_ForceDrec : m_ForceDnon) += ForceLcase;
			m_ForceAddDL += ForceLcase;
			m_ForceLTerm += ForceLcase;
			// Stress.
			m_StressNorDL += StressLcase;
			m_StressAddDL += StressLcase;
			m_StressLTerm += StressLcase;
			m_StressLTermP2 += StressPart2;
		}
		else if (CDBLib::IsStldLL(ForceLcase.strLCSubType))
		{
			(bReciLcase ? m_ForceLrec : m_ForceLnon) += ForceLcase;
			m_ForceLL += ForceLcase;
			// Stress.
			m_StressNorLL += StressLcase;
			m_StressJtgLL += StressLcase;
		}
		else
		{
			m_ForceRemn += ForceLcase;
			// Stress.
			m_StressRemn += StressLcase;
		}
	}
	else if (ForceLcase.strType == _T("TP"))	// Tendon Primary.
	{
		if (bIncludeTP)
		{
			m_ForceRemn += ForceLcase;
			m_ForceSgldRe += ForceLcase;
			// Stress.
			m_StressRemn += StressLcase;
			m_StressSgldRe += StressLcase;
			// Remove by ZINU.('06.06.12). Remove it because of adding two times.
			//m_StressTnpr += StressLcase;
		}
		m_ForceTnpr += ForceLcase;
		// Stress.
		m_StressTnpr += StressLcase;
		if (nForType > 0) m_StressTnpr2 += StressPart2;
	}
	else if (ForceLcase.strType == _T("TS"))	// Tendon Secondary.
	{
		m_ForceRemn += ForceLcase;
		m_ForceSgldRe += ForceLcase;
		// Stress.
		m_StressRemn += StressLcase;
		m_StressSgldRe += StressLcase;
		// Remove by ZINU.('06.06.12). Remove it because of adding two times.
		//m_StressTnsc += StressLcase;
		m_ForceTnsc += ForceLcase;
		// Stress.
		m_StressTnsc += StressLcase;
		if (nForType > 0) m_StressTnsc2 += StressPart2;
	}
	else
	{
		// Force.
		m_ForceRemn += ForceLcase;
		m_ForceSgldRe += ForceLcase;
		// Stress.
		m_StressRemn += StressLcase;
		m_StressSgldRe += StressLcase;

		if (ForceLcase.strType == _T("CP") || ForceLcase.strType == _T("CS") ||
			ForceLcase.strType == _T("SP") || ForceLcase.strType == _T("SS"))
		{
			m_ForceLTerm += ForceLcase;
			m_StressLTerm += StressLcase;
			m_StressLTermP2 += StressPart2;
		}
	}

	// Add, Jaeoh. [11/7/2008], 시공단계 Load Case를 위해.(TB05), 시공단계도 m_ForceDL_TB05 에 더하는 것으로 함(Maxiao 요구)
	// For TB 10002.3-2005, Force, Stress
	// DL
	if (m_iDgnCode == TB_10002_3_05 || m_iDgnCode == RC_TB_10002_3_05)
	{
		if (Is_TB05SgldDL(ForceLcase.strType))
		{
			m_ForceDL_TB05 += ForceLcase;
			m_StressDL_TB05 += StressLcase;
		}
		// Add, Jaeoh. [12/23/2008], CS(SUM)안에 있는 TP를 넘기기 위해 (Maxiao 요구) 
		if (ForceLcase.strType == _T("SUM"))
		{
			ForceLcase.Initialize();
			StressLcase.Initialize();
			CString str;
			str.Format(_T("%s"), _LS(IDS_DB_SGLD_TP));
			T_SGLD_K SgldTempK = m_pAttrCtrl->GetSgldKey(str);
			T_STEP_K StepK = 0;
			T_LCOM_D LcasD;
			T_STRB_D StrbMax; StrbMax.Initialize();
			m_pPostCtrl->MakeLoadComb(D_LOADCASE_STAGE, SgldTempK, LcasD);
			m_pPostCtrl->SelectLoadCombNew(LcasD, StepK, 2);	// 0=Nonlinear, 1=Pushover, 2=Construction.	  
			m_pPostCtrl->GetStrbNew(ElemK.first, &StrbMax, 0, NULL, FALSE, NULL, ElemK.second);

			ForceLcase.strType = StressLcase.strType = _T("TP");

			// Set Forces.
			for (int j = 0; j < cPOSI_CRC; ++j)
			{
				int iPart = (j == 0 ? 0 : 3);
				int iKind = (j == 0 ? 0 : 6);
				ForceLcase.dFxx[j] = StrbMax.dblForce[iPart][iKind + 0];
				ForceLcase.dFyy[j] = StrbMax.dblForce[iPart][iKind + 1];
				ForceLcase.dFzz[j] = StrbMax.dblForce[iPart][iKind + 2];
				ForceLcase.dMux[j] = StrbMax.dblForce[iPart][iKind + 3];
				ForceLcase.dMuy[j] = StrbMax.dblForce[iPart][iKind + 4];
				ForceLcase.dMuz[j] = StrbMax.dblForce[iPart][iKind + 5];
				ForceLcase.dMbi[j] = StrbMax.dblForce[iPart][Mbi_Id + j]; // Bi-moment
				ForceLcase.dTst[j] = StrbMax.dblForce[iPart][Mst_Id + j]; // Pure torsion
				ForceLcase.dTwp[j] = StrbMax.dblForce[iPart][Mwp_Id + j]; // Warping torsion
			}

			// Normal Stress
			Get_LoadCaseStress(ElemK, StrbMax, StressLcase);

			/*
			ForceLcase.Initialize();
			StressLcase.Initialize();
			StssLcase.Initialize();
			if(!Get_Sgld(ElemK, SgldTempK, iStepNo, ForceLcase, StressLcase, StssLcase))	return FALSE;
			*/
			// Set Forces by DimType.
			Set_DimTypeForc(ForceLcase);
			// Apply Lcase Factor.
			ForceLcase *= dFactor;
			StressLcase *= dFactor;
			m_ForceCS_TP_TB05 += ForceLcase;
			m_StressCS_TP_TB05 += StressLcase;
		}
	}
	if (m_iDgnCode == RC_JTG_B02_01_2008 || m_iDgnCode == RC_CJJ_166_2011)
	{
		//			if(dFactor!=0.0)
		//				m_ForceEQE2_JTG += ForceLcase/dFactor;
		if (IsPermanentLoad_JTG_B02(ForceLcase.strType))
		{
			m_ForceEQE2_JTG += ForceLcase;
		}
		if (IsSelfWeightLoad_JTG_B02(ForceLcase.strType))
		{
			m_ForceWeight_JTG += ForceLcase;
		}
	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_Mvld(ElemPairK ElemK, T_MVLD_K MvldK, int nForType, BOOL bCalcStss, double dFactor, BOOL bReciLcase, int iMaxMinType, BOOL bSpc)
{
	//PROFILING(_T("CCRCForceCtrl::Get_Mvld"));

	// iMaxMinType (1=FX-MAX, 2=FX-MIN, 3=FY-MAX,..., 11=MZ-MAX, 12=MZ-MIN).
	if (iMaxMinType < 0 || iMaxMinType > cFORC_CON)	return FALSE;

	_DGN_FORC_CRC ForceLcase;
	_DGN_STRS_CRC StressLcase;
	_DGN_SHRS_ADD StssLcase;
	//
	_DGN_FORC_CRC ForcePart1;
	_DGN_STRS_CRC StressPart1;
	_DGN_FORC_CRC ForcePart2;
	_DGN_STRS_CRC StressPart2;

	CString strLcaseNa = _T("");
	if (!Get_Mvld(ElemK, MvldK, nForType, bCalcStss, strLcaseNa, ForceLcase, StressLcase, StssLcase,
		ForcePart1, StressPart1, ForcePart2, StressPart2, iMaxMinType, bSpc))	return FALSE; // Civil v891 US - BS Assessment - CS454 Special Moving Load Case (CIVIL-1069)

	Set_DimTypeForc(ForceLcase);
	// Apply Lcase Factor.
	ForceLcase *= dFactor;
	StressLcase *= dFactor;
	StssLcase *= dFactor;
	// Live.
	if (bReciLcase)	m_ForceLrec += ForceLcase;
	else			m_ForceLnon += ForceLcase;

	m_ForceLL += ForceLcase;

	// Stress.
	m_StressNorLL += StressLcase;
	// JTG
	m_StressJtgLL += StressLcase;
	// Principle.
	m_StressShr += StssLcase;

	// For JTG, Tendon Stress.
	m_ForceJtgTndn += ForceLcase;

	// For TB 10002.3-2005, LL
	if (m_iDgnCode == TB_10002_3_05 || m_iDgnCode == RC_TB_10002_3_05)
	{
		m_ForceLL_TB05 += ForceLcase;
		m_StressLL_TB05 += StressLcase;
	}

	if (nForType > 0)
	{
		ForcePart1 *= dFactor;
		StressPart1 *= dFactor;
		ForcePart2 *= dFactor;
		StressPart2 *= dFactor;

		m_ForceRemnP1 += ForcePart1;
		m_StressRemnP1 += StressPart1;
		m_ForceRemnP2 += ForcePart2;
		m_StressRemnP2 += StressPart2;
		m_StressSTermP2 += StressPart2;
	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_Smlc(ElemPairK ElemK, T_SMLC_K SmlcK, int nForType, BOOL bCalcStss, double dFactor, int iMaxMinType)
{
	//PROFILING(_T("CCRCForceCtrl::Get_Smlc"));

	// iMaxMinType (1=FX-MAX, 2=FX-MIN, 3=FY-MAX,..., 11=MZ-MAX, 12=MZ-MIN).
	if (iMaxMinType < 0 || iMaxMinType > cFORC_CON)	return FALSE;

	_DGN_FORC_CRC ForceLcase;
	_DGN_STRS_CRC StressLcase;
	_DGN_SHRS_ADD StssLcase;
	//
	_DGN_FORC_CRC ForcePart1;
	_DGN_STRS_CRC StressPart1;
	_DGN_FORC_CRC ForcePart2;
	_DGN_STRS_CRC StressPart2;

	CString strLcaseNa = _T("");
	if (!Get_Smlc(ElemK, SmlcK, nForType, bCalcStss, strLcaseNa, ForceLcase, StressLcase, StssLcase,
		ForcePart1, StressPart1, ForcePart2, StressPart2, iMaxMinType))	return FALSE;

	// Set Forces by DimType.
	Set_DimTypeForc(ForceLcase);
	// Apply Lcase Factor.
	ForceLcase *= dFactor;
	StressLcase *= dFactor;
	// Remnant.
	m_ForceRemn += ForceLcase;
	// Stress.
	m_StressRemn += StressLcase;
	// Principle.
	m_StressShr += StssLcase;

	// For JTG, Tendon Stress.
	m_ForceJtgTndn += ForceLcase;

	// Add, Jaeoh. [11/17/2008] Req.Maxiao, Settlement도 TB05, Dead Load에 포함.
	// For TB 10002.3-2005, LL
	if (m_iDgnCode == TB_10002_3_05 || m_iDgnCode == RC_TB_10002_3_05)
	{
		m_ForceDL_TB05 += ForceLcase;
		m_StressDL_TB05 += StressLcase;
	}

	if (nForType > 0)
	{
		ForcePart1 *= dFactor;
		StressPart1 *= dFactor;
		ForcePart2 *= dFactor;
		StressPart2 *= dFactor;

		m_ForceRemnP1 += ForcePart1;
		m_StressRemnP1 += StressPart1;
		m_ForceRemnP2 += ForcePart2;
		m_StressRemnP2 += StressPart2;
	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_Gilc(ElemPairK ElemK, T_GILC_K GilcK, int nForType, BOOL bCalcStss, double dFactor, BOOL bReciLcase, int iMaxMinType)
{
	//PROFILING(_T("CCRCForceCtrl::Get_Gilc"));

	// iMaxMinType (1=FX-MAX, 2=FX-MIN, 3=FY-MAX,..., 11=MZ-MAX, 12=MZ-MIN).
	if (iMaxMinType < 0 || iMaxMinType > cFORC_CON)	return FALSE;

	// Get Load Case Type.
	T_GILC_D GilcD;
	GilcD.Initialize();
	if (!m_pAttrCtrl->GetGilc(GilcK, GilcD))	return FALSE;
	int iLcaseType = GilcD.nLoadCaseType;

	CString strLcaseNa = _T("");
	_DGN_FORC_CRC ForceLcase;
	_DGN_STRS_CRC StressLcase;
	_DGN_SHRS_ADD StssLcase;
	//
	_DGN_FORC_CRC ForcePart1;
	_DGN_STRS_CRC StressPart1;
	_DGN_FORC_CRC ForcePart2;
	_DGN_STRS_CRC StressPart2;

	if (!Get_Gilc(ElemK, GilcK, nForType, bCalcStss, iLcaseType, strLcaseNa, ForceLcase, StressLcase, StssLcase,
		ForcePart1, StressPart1, ForcePart2, StressPart2, iMaxMinType))	return FALSE;
	BOOL bDL = (iLcaseType == 0 || iLcaseType == 1 ? TRUE : FALSE);
	// Set Forces by DimType.
	Set_DimTypeForc(ForceLcase);
	// Apply Lcase Factor.
	ForceLcase *= dFactor;
	StressLcase *= dFactor;
	StssLcase *= dFactor;
	// Principle.
	m_StressShr += StssLcase;

	// For JTG, Tendon Stress.
	m_ForceJtgTndn += ForceLcase;

	// 0:Dead, 1:Other Dead Load, 
	// 2:Vehicle Live Load, 3:Crowded Line Load, 4:Other Live Load (2,3,4는 일본 버전에만)
	if (iLcaseType == 0)
	{
		(bReciLcase ? m_ForceDrec : m_ForceDnon) += ForceLcase;	// Dead Load.
		m_ForceAddDL += ForceLcase;

		// Stress.
		m_StressNorDL += StressLcase;
		//Jtg
		m_StressAddDL += StressLcase;
		if (m_iDgnCode == TB_10002_3_05 || m_iDgnCode == RC_TB_10002_3_05)
		{
			// For TB 10002.3-2005
			m_ForceDL_TB05 += ForceLcase;
			m_StressDL_TB05 += StressLcase;
		}
	}
	else if (iLcaseType == 1)
	{
		(bReciLcase ? m_ForceDnon : m_ForceDnon) += ForceLcase;	// Other Dead Load.
		m_ForceAddDL += ForceLcase;

		// Stress.
		m_StressNorDL += StressLcase;
		//Jtg
		m_StressAddDL += StressLcase;
		// For TB 10002.3-2005
		if (m_iDgnCode == TB_10002_3_05 || m_iDgnCode == RC_TB_10002_3_05)
		{
			m_ForceDL_TB05 += ForceLcase;
			m_StressDL_TB05 += StressLcase;
		}
	}
	else if (iLcaseType == 2)
	{
		(bReciLcase ? m_ForceLrec : m_ForceLnon) += ForceLcase;	// Vehicle Live Load.
		// Stress.
		m_StressNorLL += StressLcase;
	}
	else if (iLcaseType == 3)
	{
		(bReciLcase ? m_ForceLrec : m_ForceLnon) += ForceLcase;	// Crowded Line Load.
		// Stress.
		m_StressNorLL += StressLcase;
	}
	else if (iLcaseType == 4)
	{
		(bReciLcase ? m_ForceLrec : m_ForceLnon) += ForceLcase;	// Other Live Load.
		// Stress.
		m_StressNorLL += StressLcase;
	}
	else	ASSERT(0);

	if (nForType > 0)
	{
		ForcePart1 *= dFactor;
		StressPart1 *= dFactor;
		ForcePart2 *= dFactor;
		StressPart2 *= dFactor;

		m_ForceRemnP1 += ForcePart1;
		m_StressRemnP1 += StressPart1;
		m_ForceRemnP2 += ForcePart2;
		m_StressRemnP2 += StressPart2;
		m_StressSTermP2 += StressPart2;
	}


	return TRUE;
}


BOOL CCRCForceCtrl::Get_Stld_EX(ElemPairK ElemK, T_STLD_K StldK, int nForType, BOOL bCalcStss, double dFactor, BOOL bReciLcase)
{
	_DGN_FORC_CRC_EX ForceLcase;
	_DGN_STRS_ADD_EX StressAdd;
	_DGN_STRS_CRC_EX StressLcase;
	_DGN_SHRS_ADD_EX StssLcase;

	_DGN_FORC_CRC_EX ForcePart1;
	_DGN_STRS_CRC_EX StressPart1;
	_DGN_FORC_CRC_EX ForcePart2;
	_DGN_STRS_CRC_EX StressPart2;

	if (!Get_Stld_EX(ElemK, StldK, nForType, bCalcStss, ForceLcase, StressAdd, StressLcase, StssLcase,
		ForcePart1, StressPart1, ForcePart2, StressPart2))	return FALSE;

	// Set Forces by DimType.
	Set_DimTypeForc_EX(ForceLcase);
	// Apply Lcase Factor.
	ForceLcase *= dFactor;
	// Stress.
	StressLcase *= dFactor;

	_DGN_SCFP_PART_LCASE_EX ScfpPartLcase;
	T_STLD_K StldScfpK = 0;
	if (m_arStldScfpK.Lookup(StldK, StldScfpK))
	{
		Get_StldScfp_EX(ElemK, StldScfpK, ScfpPartLcase);

		ScfpPartLcase.ForceP1 *= dFactor;
		ScfpPartLcase.ForceP2 *= dFactor;

		if (CDBLib::IsStldTL(ForceLcase.strType))
		{
			m_pStressScfpTe_EX->ForceP1 += ScfpPartLcase.ForceP1;
			m_pStressScfpTe_EX->ForceP2 += ScfpPartLcase.ForceP2;
		}
		else
		{
			m_pStressScfpRe_EX->ForceP1 += ScfpPartLcase.ForceP1;
			m_pStressScfpRe_EX->ForceP2 += ScfpPartLcase.ForceP2;
		}
		// 
		//m_ForceScfpSum += ForceLcase;
	}

	// Add by ZINU.('05.01.03). Consider Stress.
	StressAdd *= dFactor;
	*m_pStressAdd_EX += StressAdd;
	// Principle.
	StssLcase *= dFactor;
	*m_pStressShr_EX += StssLcase;

	if (nForType > 0)
	{
		ForcePart1 *= dFactor;
		StressPart1 *= dFactor;
		ForcePart2 *= dFactor;
		StressPart2 *= dFactor;

		*m_pForceRemnP1_EX += ForcePart1;
		*m_pStressRemnP1_EX += StressPart1;
		*m_pForceRemnP2_EX += ForcePart2;
		*m_pStressRemnP2_EX += StressPart2;
	}

	T_STLD_K TempK = 0;
	if (m_mapPlcbStldK.Lookup(StldK, TempK))
	{
		*m_pForceAddDL_EX += ForceLcase;
		// Stress
		*m_pStressNorDL_EX += StressLcase;
		// JTG
		*m_pStressAddDL_EX += StressLcase;
	}
	else if (CDBLib::IsStldDL(ForceLcase.strType))	// Dead.
	{
		if (bReciLcase)	*m_pForceDrec_EX += ForceLcase;
		else			*m_pForceDnon_EX += ForceLcase;

		if (m_bIsPLCB == FALSE)
		{
			*m_pForceAddDL_EX += ForceLcase;
			// Stress
			*m_pStressNorDL_EX += StressLcase;
			// JTG
			*m_pStressAddDL_EX += StressLcase;
		}
		if (CDBLib::IsStldLTerm(ForceLcase.strType))
		{
			*m_pForceLTerm_EX += ForceLcase;
			*m_pStressLTerm_EX += StressLcase;
		}
	}
	else if (CDBLib::IsStldLL(ForceLcase.strType))	// Live.
	{
		if (bReciLcase)	*m_pForceLrec_EX += ForceLcase;
		else			*m_pForceLnon_EX += ForceLcase;

		// Stress
		*m_pStressNorLL_EX += StressLcase;
	}
	else
	{
		*m_pForceRemn_EX += ForceLcase;
		// Stress.
		*m_pStressRemn_EX += StressLcase;
	}

	if (Is_JtgStldLL(ForceLcase.strType))
	{
		*m_pForceLL_EX += ForceLcase;
		// Stress.
		*m_pStressJtgLL_EX += StressLcase;
	}

	// For JTG, Tendon Stress.
	*m_pForceJtgTndn_EX += ForceLcase;

	// For TB 10002.3-2005, Force Stress
	// DL
	if (m_iDgnCode == TB_10002_3_05 || m_iDgnCode == RC_TB_10002_3_05)
	{
		if (Is_TB05StldDL(ForceLcase.strType))
		{
			*m_pForceDL_TB05_EX += ForceLcase;
			*m_pStressDL_TB05_EX += StressLcase;
		}
		// LL
		if (Is_TB05StldLL(ForceLcase.strType))
		{
			*m_pForceLL_TB05_EX += ForceLcase;
			*m_pStressLL_TB05_EX += StressLcase;
		}
	}
	else if (m_iDgnCode == RC_JTG_B02_01_2008 || m_iDgnCode == RC_CJJ_166_2011)
	{
		//		if(CDBLib::IsStldEL(ForceLcase.strType))
		//		{
		//			if(dFactor!=0.0)
		//				m_ForceEQE2_JTG += ForceLcase/dFactor;
		//		}
		if (IsPermanentLoad_JTG_B02(ForceLcase.strType))
		{
			*m_pForceEQE2_JTG_EX += ForceLcase;
		}
		if (IsSelfWeightLoad_JTG_B02(ForceLcase.strType))
		{
			*m_pForceWeight_JTG_EX += ForceLcase;
		}
	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_Splc_EX(ElemPairK ElemK, T_SPLC_K SplcK, int nForType, BOOL bCalcStss, double dFactor)
{
	//PROFILING(_T("CCRCForceCtrl::Get_Splc"));

	_DGN_FORC_CRC_EX ForceLcase;
	_DGN_STRS_CRC_EX StressLcase;
	_DGN_SHRS_ADD_EX StssLcase;
	//			 _EX
	_DGN_FORC_CRC_EX ForcePart1;
	_DGN_STRS_CRC_EX StressPart1;
	_DGN_FORC_CRC_EX ForcePart2;
	_DGN_STRS_CRC_EX StressPart2;

	if (!Get_Splc_EX(ElemK, SplcK, nForType, bCalcStss, ForceLcase, StressLcase, StssLcase,
		ForcePart1, StressPart1, ForcePart2, StressPart2))	return FALSE;
	// Set Forces by DimType.
	Set_DimTypeForc_EX(ForceLcase);
	// Apply Lcase Factor.
	ForceLcase *= dFactor;
	*m_pForceRemn_EX += ForceLcase;
	// Stress
	StressLcase *= dFactor;
	*m_pStressRemn_EX += StressLcase;
	// Principle.
	StssLcase *= dFactor;
	*m_pStressShr_EX += StssLcase;

	// For JTG, Tendon Stress.
	*m_pForceJtgTndn_EX += ForceLcase;

	if (nForType > 0)
	{
		ForcePart1 *= dFactor;
		StressPart1 *= dFactor;
		ForcePart2 *= dFactor;
		StressPart2 *= dFactor;

		*m_pForceRemnP1_EX += ForcePart1;
		*m_pStressRemnP1_EX += StressPart1;
		*m_pForceRemnP2_EX += ForcePart2;
		*m_pStressRemnP2_EX += StressPart2;
	}

	return TRUE;
}

