BOOL CCRCForceCtrl::Get_Sgld_EX(ElemPairK ElemK, T_SGLD_K SgldK, int nForType, BOOL bCalcStss, double dFactor, BOOL bReciLcase, BOOL bIncludeTP, int iStepNo)
{
	//PROFILING(_T("CCRCForceCtrl::Get_Sgld"));

	_DGN_FORC_CRC_EX ForceLcase;
	_DGN_STRS_CRC_EX StressLcase;
	_DGN_SHRS_ADD_EX StssLcase;
	//
	_DGN_FORC_CRC_EX ForcePart1;
	_DGN_STRS_CRC_EX StressPart1;
	_DGN_FORC_CRC_EX ForcePart2;
	_DGN_STRS_CRC_EX StressPart2;

	if (!Get_Sgld_EX(ElemK, SgldK, nForType, bCalcStss, iStepNo, ForceLcase, StressLcase, StssLcase,
		ForcePart1, StressPart1, ForcePart2, StressPart2))	return FALSE;

	// Set Forces by DimType.
	Set_DimTypeForc_EX(ForceLcase);
	// Apply Lcase Factor.
	ForceLcase *= dFactor;
	StressLcase *= dFactor;

	_DGN_SCFP_PART_LCASE_EX ScfpPartLcase;
	T_SGLD_K SgldScfpK = 0;
	BOOL bIsScfp = m_arSgldScfpK.Lookup(SgldK, SgldScfpK);
	if (bIsScfp == TRUE)
	{
		Get_SgldScfp_EX(ElemK, SgldK, ScfpPartLcase);

		ScfpPartLcase.ForceP1 *= dFactor;
		ScfpPartLcase.ForceP2 *= dFactor;

		if (ForceLcase.strType == _T("EL"))
		{
			// m_arSgldScfpK 에서 Erection은 온도만 추가 하고 있음
			// 연관함수 BOOL IsErectionScfp(int nType, T_STCT_D &StctD); 참고
			m_pStressScfpTe_EX->ForceP1 += ScfpPartLcase.ForceP1;
			m_pStressScfpTe_EX->ForceP2 += ScfpPartLcase.ForceP2;
		}
		else if (ForceLcase.strType == _T("CS"))
		{
			m_pStressScfpCr_EX->ForceP1 += ScfpPartLcase.ForceP1;
			m_pStressScfpCr_EX->ForceP2 += ScfpPartLcase.ForceP2;
			// Creep secondary만 적용한다. [5/26/2015 joahn] 이대근 이사보님, 박창신 사원님 요청
			*m_pForceScfpCrp_EX += ForceLcase;
			*m_pForceScfpSum_EX += ForceLcase;
		}
		else if (ForceLcase.strType == _T("SS"))
		{
			m_pStressScfpSh_EX->ForceP1 += ScfpPartLcase.ForceP1;
			m_pStressScfpSh_EX->ForceP2 += ScfpPartLcase.ForceP2;
			*m_pForceScfpShr_EX += ForceLcase;
			*m_pForceScfpSum_EX += ForceLcase;
		}
		else
		{
			m_pStressScfpRe_EX->ForceP1 += ScfpPartLcase.ForceP1;
			m_pStressScfpRe_EX->ForceP2 += ScfpPartLcase.ForceP2;
		}
		//
		//m_ForceScfpSum += ForceLcase;
		*m_pForceRemn_EX += ForceLcase;
	}
	else
	{
		// Principle.
		StssLcase *= dFactor;
		*m_pStressShr_EX += StssLcase;

		if (nForType > 0)
		{
			ForcePart1 *= dFactor;
			StressPart1 *= dFactor;
			ForcePart2 *= dFactor;
			StressPart2 *= dFactor;

			*m_pForceRemnP1_EX += ForcePart1;
			*m_pStressRemnP1_EX += StressPart1;
			*m_pForceRemnP2_EX += ForcePart2;
			*m_pStressRemnP2_EX += StressPart2;
		}

		// Add by ZINU.('05.07.04). Get Force by All Sgld.
		*m_pForceStag_EX += ForceLcase;
		if (ForceLcase.strType == _T("DL"))	// Dead.
		{
			if (bReciLcase)	*m_pForceDrec_EX += ForceLcase;
			else			*m_pForceDnon_EX += ForceLcase;

			*m_pForceAddDL_EX += ForceLcase;
			*m_pForceLTerm_EX += ForceLcase;
			// Stress.
			*m_pStressNorDL_EX += StressLcase;
			*m_pStressAddDL_EX += StressLcase;
			*m_pStressLTerm_EX += StressLcase;
		}
		else if (ForceLcase.strType == _T("LL"))	// Live.
		{
			if (bReciLcase)	*m_pForceLrec_EX += ForceLcase;
			else			*m_pForceLnon_EX += ForceLcase;
			// Stress.
			*m_pStressNorLL_EX += StressLcase;
		}
		else if (ForceLcase.strType == _T("EL"))	// Erection.
		{
			// Add by ZINU.('04.05.12). Apply EL LcaseType by Construction Stage Control. (Park IS).
			if (CDBLib::IsStldDL(ForceLcase.strLCSubType))
			{
				(bReciLcase ? *m_pForceDrec_EX : *m_pForceDnon_EX) += ForceLcase;
				*m_pForceAddDL_EX += ForceLcase;
				*m_pForceLTerm_EX += ForceLcase;
				// Stress.
				*m_pStressNorDL_EX += StressLcase;
				*m_pStressAddDL_EX += StressLcase;
				*m_pStressLTerm_EX += StressLcase;
			}
			else if (CDBLib::IsStldLL(ForceLcase.strLCSubType))
			{
				(bReciLcase ? *m_pForceLrec_EX : *m_pForceLnon_EX) += ForceLcase;
				*m_pForceLL_EX += ForceLcase;
				// Stress.
				*m_pStressNorLL_EX += StressLcase;
				*m_pStressJtgLL_EX += StressLcase;
			}
			else
			{
				*m_pForceRemn_EX += ForceLcase;
				// Stress.
				*m_pStressRemn_EX += StressLcase;
			}
		}
		else if (ForceLcase.strType == _T("TP"))	// Tendon Primary.
		{
			if (bIncludeTP)
			{
				*m_pForceRemn_EX += ForceLcase;
				*m_pForceSgldRe_EX += ForceLcase;
				// Stress.
				*m_pStressRemn_EX += StressLcase;
				*m_pStressSgldRe_EX += StressLcase;
				// Remove by ZINU.('06.06.12). Remove it because of adding two times.
				//m_StressTnpr += StressLcase;
			}
			*m_pForceTnpr_EX += ForceLcase;
			// Stress.
			*m_pStressTnpr_EX += StressLcase;
			if (nForType > 0) *m_pStressTnpr2_EX += StressPart2;
		}
		else if (ForceLcase.strType == _T("TS"))	// Tendon Secondary.
		{
			*m_pForceRemn_EX += ForceLcase;
			*m_pForceSgldRe_EX += ForceLcase;
			// Stress.
			*m_pStressRemn_EX += StressLcase;
			*m_pStressSgldRe_EX += StressLcase;
			// Remove by ZINU.('06.06.12). Remove it because of adding two times.
			//m_StressTnsc += StressLcase;
			*m_pForceTnsc_EX += ForceLcase;
			// Stress.
			*m_pStressTnsc_EX += StressLcase;
			if (nForType > 0) *m_pStressTnsc2_EX += StressPart2;
		}
		else
		{
			// Force.
			*m_pForceRemn_EX += ForceLcase;
			*m_pForceSgldRe_EX += ForceLcase;
			// Stress.
			*m_pStressRemn_EX += StressLcase;
			*m_pStressSgldRe_EX += StressLcase;

			if (ForceLcase.strType == _T("CP") || ForceLcase.strType == _T("CS") ||
				ForceLcase.strType == _T("SP") || ForceLcase.strType == _T("SS"))
			{
				*m_pForceLTerm_EX += ForceLcase;
				*m_pStressLTerm_EX += StressLcase;
			}
		}
	}

	// Add, Jaeoh. [11/7/2008], 시공단계 Load Case를 위해.(TB05), 시공단계도 m_ForceDL_TB05 에 더하는 것으로 함(Maxiao 요구)
	// For TB 10002.3-2005, Force, Stress
	// DL
	if (m_iDgnCode == TB_10002_3_05 || m_iDgnCode == RC_TB_10002_3_05)
	{
		if (Is_TB05SgldDL(ForceLcase.strType))
		{
			*m_pForceDL_TB05_EX += ForceLcase;
			*m_pStressDL_TB05_EX += StressLcase;
		}
		// Add, Jaeoh. [12/23/2008], CS(SUM)안에 있는 TP를 넘기기 위해 (Maxiao 요구) 
		if (ForceLcase.strType == _T("SUM"))
		{
			ForceLcase.Initialize();
			StressLcase.Initialize();
			CString str;
			str.Format(_T("%s"), _LS(IDS_DB_SGLD_TP));
			T_SGLD_K SgldTempK = m_pAttrCtrl->GetSgldKey(str);
			T_STEP_K StepK = 0;
			T_LCOM_D LcasD;
			T_STRB_D StrbMax; StrbMax.Initialize();
			m_pPostCtrl->MakeLoadComb(D_LOADCASE_STAGE, SgldTempK, LcasD);
			m_pPostCtrl->SelectLoadCombNew(LcasD, StepK, 2);	// 0=Nonlinear, 1=Pushover, 2=Construction.	  
			m_pPostCtrl->GetStrbNew(ElemK.first, &StrbMax, 0, NULL, FALSE, NULL, ElemK.second);

			ForceLcase.strType = StressLcase.strType = _T("TP");

			// Set Forces.
			for (int j = 0; j < cPOSI_CRC_EX; ++j)
			{
				int iPart = (j < cPOSI_CRC_EX - 1 ? j : j - 1);
				int iKind = (j < cPOSI_CRC_EX - 1 ? 0 : 6);
				ForceLcase.dFxx[j] = StrbMax.dblForce[iPart][iKind + 0];
				ForceLcase.dFyy[j] = StrbMax.dblForce[iPart][iKind + 1];
				ForceLcase.dFzz[j] = StrbMax.dblForce[iPart][iKind + 2];
				ForceLcase.dMux[j] = StrbMax.dblForce[iPart][iKind + 3];
				ForceLcase.dMuy[j] = StrbMax.dblForce[iPart][iKind + 4];
				ForceLcase.dMuz[j] = StrbMax.dblForce[iPart][iKind + 5];
				ForceLcase.dMbi[j] = StrbMax.dblForce[iPart][Mbi_Id + j]; // Bi-moment
				ForceLcase.dTst[j] = StrbMax.dblForce[iPart][Mst_Id + j]; // Pure torsion
				ForceLcase.dTwp[j] = StrbMax.dblForce[iPart][Mwp_Id + j]; // Warping torsion
			}

			// Normal Stress
			Get_LoadCaseStress_EX(ElemK, StrbMax, StressLcase);

			/*
			ForceLcase.Initialize();
			StressLcase.Initialize();
			StssLcase.Initialize();
			if(!Get_Sgld(ElemK, SgldTempK, iStepNo, ForceLcase, StressLcase, StssLcase))	return FALSE;
			*/
			// Set Forces by DimType.
			Set_DimTypeForc_EX(ForceLcase);
			// Apply Lcase Factor.
			ForceLcase *= dFactor;
			StressLcase *= dFactor;
			*m_pForceCS_TP_TB05_EX += ForceLcase;
			*m_pStressCS_TP_TB05_EX += StressLcase;
		}
	}
	if (m_iDgnCode == RC_JTG_B02_01_2008 || m_iDgnCode == RC_CJJ_166_2011)
	{
		//			if(dFactor!=0.0)
		//				m_ForceEQE2_JTG += ForceLcase/dFactor;
		if (IsPermanentLoad_JTG_B02(ForceLcase.strType))
		{
			*m_pForceEQE2_JTG_EX += ForceLcase;
		}
		if (IsSelfWeightLoad_JTG_B02(ForceLcase.strType))
		{
			*m_pForceWeight_JTG_EX += ForceLcase;
		}
	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_Mvld_EX(ElemPairK ElemK, T_MVLD_K MvldK, int nForType, BOOL bCalcStss, double dFactor, BOOL bReciLcase, int iMaxMinType, BOOL bSpc)
{
	//PROFILING(_T("CCRCForceCtrl::Get_Mvld"));

	// iMaxMinType (1=FX-MAX, 2=FX-MIN, 3=FY-MAX,..., 11=MZ-MAX, 12=MZ-MIN).
	if (iMaxMinType < 0 || iMaxMinType > cFORC_CON)	return FALSE;

	_DGN_FORC_CRC_EX ForceLcase;
	_DGN_STRS_CRC_EX StressLcase;
	_DGN_SHRS_ADD_EX StssLcase;
	//
	_DGN_FORC_CRC_EX ForcePart1;
	_DGN_STRS_CRC_EX StressPart1;
	_DGN_FORC_CRC_EX ForcePart2;
	_DGN_STRS_CRC_EX StressPart2;

	CString strLcaseNa = _T("");
	if (!Get_Mvld_EX(ElemK, MvldK, nForType, bCalcStss, strLcaseNa, ForceLcase, StressLcase, StssLcase,
		ForcePart1, StressPart1, ForcePart2, StressPart2, iMaxMinType, bSpc))	return FALSE;

	Set_DimTypeForc_EX(ForceLcase);
	// Apply Lcase Factor.
	ForceLcase *= dFactor;
	StressLcase *= dFactor;
	StssLcase *= dFactor;
	// Live.
	if (bReciLcase)	*m_pForceLrec_EX += ForceLcase;
	else			*m_pForceLnon_EX += ForceLcase;

	*m_pForceLL_EX += ForceLcase;

	// Stress.
	*m_pStressNorLL_EX += StressLcase;
	// JTG
	*m_pStressJtgLL_EX += StressLcase;
	// Principle.
	*m_pStressShr_EX += StssLcase;

	// For JTG, Tendon Stress.
	*m_pForceJtgTndn_EX += ForceLcase;

	// For TB 10002.3-2005, LL
	if (m_iDgnCode == TB_10002_3_05 || m_iDgnCode == RC_TB_10002_3_05)
	{
		*m_pForceLL_TB05_EX += ForceLcase;
		*m_pStressLL_TB05_EX += StressLcase;
	}

	if (nForType > 0)
	{
		ForcePart1 *= dFactor;
		StressPart1 *= dFactor;
		ForcePart2 *= dFactor;
		StressPart2 *= dFactor;

		*m_pForceRemnP1_EX += ForcePart1;
		*m_pStressRemnP1_EX += StressPart1;
		*m_pForceRemnP2_EX += ForcePart2;
		*m_pStressRemnP2_EX += StressPart2;
	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_Smlc_EX(ElemPairK ElemK, T_SMLC_K SmlcK, int nForType, BOOL bCalcStss, double dFactor, int iMaxMinType)
{
	//PROFILING(_T("CCRCForceCtrl::Get_Smlc"));

	// iMaxMinType (1=FX-MAX, 2=FX-MIN, 3=FY-MAX,..., 11=MZ-MAX, 12=MZ-MIN).
	if (iMaxMinType < 0 || iMaxMinType > cFORC_CON)	return FALSE;

	_DGN_FORC_CRC_EX ForceLcase;
	_DGN_STRS_CRC_EX StressLcase;
	_DGN_SHRS_ADD_EX StssLcase;
	//			 
	_DGN_FORC_CRC_EX ForcePart1;
	_DGN_STRS_CRC_EX StressPart1;
	_DGN_FORC_CRC_EX ForcePart2;
	_DGN_STRS_CRC_EX StressPart2;

	CString strLcaseNa = _T("");
	if (!Get_Smlc_EX(ElemK, SmlcK, nForType, bCalcStss, strLcaseNa, ForceLcase, StressLcase, StssLcase,
		ForcePart1, StressPart1, ForcePart2, StressPart2, iMaxMinType))	return FALSE;

	// Set Forces by DimType.
	Set_DimTypeForc_EX(ForceLcase);
	// Apply Lcase Factor.
	ForceLcase *= dFactor;
	StressLcase *= dFactor;
	// Remnant.
	*m_pForceRemn_EX += ForceLcase;
	// Stress.
	*m_pStressRemn_EX += StressLcase;
	// Principle.
	*m_pStressShr_EX += StssLcase;

	// For JTG, Tendon Stress.
	*m_pForceJtgTndn_EX += ForceLcase;

	// Add, Jaeoh. [11/17/2008] Req.Maxiao, Settlement도 TB05, Dead Load에 포함.
	// For TB 10002.3-2005, LL
	if (m_iDgnCode == TB_10002_3_05 || m_iDgnCode == RC_TB_10002_3_05)
	{
		*m_pForceDL_TB05_EX += ForceLcase;
		*m_pStressDL_TB05_EX += StressLcase;
	}

	if (nForType > 0)
	{
		ForcePart1 *= dFactor;
		StressPart1 *= dFactor;
		ForcePart2 *= dFactor;
		StressPart2 *= dFactor;

		*m_pForceRemnP1_EX += ForcePart1;
		*m_pStressRemnP1_EX += StressPart1;
		*m_pForceRemnP2_EX += ForcePart2;
		*m_pStressRemnP2_EX += StressPart2;
	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_Gilc_EX(ElemPairK ElemK, T_GILC_K GilcK, int nForType, BOOL bCalcStss, double dFactor, BOOL bReciLcase, int iMaxMinType)
{
	//PROFILING(_T("CCRCForceCtrl::Get_Gilc"));

	// iMaxMinType (1=FX-MAX, 2=FX-MIN, 3=FY-MAX,..., 11=MZ-MAX, 12=MZ-MIN).
	if (iMaxMinType < 0 || iMaxMinType > cFORC_CON)	return FALSE;

	// Get Load Case Type.
	T_GILC_D GilcD;
	GilcD.Initialize();
	if (!m_pAttrCtrl->GetGilc(GilcK, GilcD))	return FALSE;
	int iLcaseType = GilcD.nLoadCaseType;

	CString strLcaseNa = _T("");
	_DGN_FORC_CRC_EX ForceLcase;
	_DGN_STRS_CRC_EX StressLcase;
	_DGN_SHRS_ADD_EX StssLcase;
	//			 
	_DGN_FORC_CRC_EX ForcePart1;
	_DGN_STRS_CRC_EX StressPart1;
	_DGN_FORC_CRC_EX ForcePart2;
	_DGN_STRS_CRC_EX StressPart2;

	if (!Get_Gilc_EX(ElemK, GilcK, nForType, bCalcStss, iLcaseType, strLcaseNa, ForceLcase, StressLcase, StssLcase,
		ForcePart1, StressPart1, ForcePart2, StressPart2, iMaxMinType))	return FALSE;
	BOOL bDL = (iLcaseType == 0 || iLcaseType == 1 ? TRUE : FALSE);
	// Set Forces by DimType.
	Set_DimTypeForc_EX(ForceLcase);
	// Apply Lcase Factor.
	ForceLcase *= dFactor;
	StressLcase *= dFactor;
	StssLcase *= dFactor;
	// Principle.
	*m_pStressShr_EX += StssLcase;

	// For JTG, Tendon Stress.
	*m_pForceJtgTndn_EX += ForceLcase;

	// 0:Dead, 1:Other Dead Load, 
	// 2:Vehicle Live Load, 3:Crowded Line Load, 4:Other Live Load (2,3,4는 일본 버전에만)
	if (iLcaseType == 0)
	{
		(bReciLcase ? *m_pForceDrec_EX : *m_pForceDnon_EX) += ForceLcase;	// Dead Load.
		*m_pForceAddDL_EX += ForceLcase;

		// Stress.
		*m_pStressNorDL_EX += StressLcase;
		//Jtg
		*m_pStressAddDL_EX += StressLcase;
		if (m_iDgnCode == TB_10002_3_05 || m_iDgnCode == RC_TB_10002_3_05)
		{
			// For TB 10002.3-2005
			*m_pForceDL_TB05_EX += ForceLcase;
			*m_pStressDL_TB05_EX += StressLcase;
		}
	}
	else if (iLcaseType == 1)
	{
		(bReciLcase ? *m_pForceDnon_EX : *m_pForceDnon_EX) += ForceLcase;	// Other Dead Load.
		*m_pForceAddDL_EX += ForceLcase;

		// Stress.
		*m_pStressNorDL_EX += StressLcase;
		//Jtg
		*m_pStressAddDL_EX += StressLcase;
		// For TB 10002.3-2005
		if (m_iDgnCode == TB_10002_3_05 || m_iDgnCode == RC_TB_10002_3_05)
		{
			*m_pForceDL_TB05_EX += ForceLcase;
			*m_pStressDL_TB05_EX += StressLcase;
		}
	}
	else if (iLcaseType == 2)
	{
		(bReciLcase ? *m_pForceLrec_EX : *m_pForceLnon_EX) += ForceLcase;	// Vehicle Live Load.
		// Stress.
		*m_pStressNorLL_EX += StressLcase;
	}
	else if (iLcaseType == 3)
	{
		(bReciLcase ? *m_pForceLrec_EX : *m_pForceLnon_EX) += ForceLcase;	// Crowded Line Load.
		// Stress.
		*m_pStressNorLL_EX += StressLcase;
	}
	else if (iLcaseType == 4)
	{
		(bReciLcase ? *m_pForceLrec_EX : *m_pForceLnon_EX) += ForceLcase;	// Other Live Load.
		// Stress.
		*m_pStressNorLL_EX += StressLcase;
	}
	else	ASSERT(0);

	if (nForType > 0)
	{
		ForcePart1 *= dFactor;
		StressPart1 *= dFactor;
		ForcePart2 *= dFactor;
		StressPart2 *= dFactor;

		*m_pForceRemnP1_EX += ForcePart1;
		*m_pStressRemnP1_EX += StressPart1;
		*m_pForceRemnP2_EX += ForcePart2;
		*m_pStressRemnP2_EX += StressPart2;
	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_Lcom(ElemPairK ElemK, T_LCOM_K LcomK, int nForType, BOOL bCalcStss, double dFactor, int iMaxMinType)
{
	if (iMaxMinType < 0 || iMaxMinType > DGN_FORCE_LCOM_SUB_MAX)	return FALSE;

	_DGN_FORC_CRC ForceLcase;
	_DGN_STRS_ADD StressAdd;
	_DGN_STRS_CRC StressLcase;
	_DGN_SHRS_ADD StssLcase;
	//
	_DGN_FORC_CRC ForcePart1;
	_DGN_STRS_CRC StressPart1;
	_DGN_FORC_CRC ForcePart2;
	_DGN_STRS_CRC StressPart2;

	if (!Get_Lcom(ElemK, LcomK, nForType, bCalcStss, ForceLcase, StressAdd, StressLcase, StssLcase,
		ForcePart1, StressPart1, ForcePart2, StressPart2, iMaxMinType))	return FALSE;
	// Set Forces by DimType.
	Set_DimTypeForc(ForceLcase);
	// Apply Lcase Factor.
	ForceLcase *= dFactor;
	// Stress.
	StressLcase *= dFactor;
	// Add by ZINU.('05.01.03). Consider Stress.
	StressAdd *= dFactor;
	m_StressAdd += StressAdd;
	// Principle.
	StssLcase *= dFactor;
	m_StressShr += StssLcase;

	// Force and Stress.
	m_ForceRemn += ForceLcase;
	// Stress.
	m_StressRemn += StressLcase;

	//remove by maxiao   m_ForceEQE2_JTG is PermanentLoad_JTG_B02， why have this code？
	//	if(m_iDgnCode == RC_JTG_B02_01_2008)
	//	{ m_ForceEQE2_JTG += ForceLcase; }

	if (nForType > 0)
	{
		ForcePart1 *= dFactor;
		StressPart1 *= dFactor;
		ForcePart2 *= dFactor;
		StressPart2 *= dFactor;

		m_ForceRemnP1 += ForcePart1;
		m_StressRemnP1 += StressPart1;
		m_ForceRemnP2 += ForcePart2;
		m_StressRemnP2 += StressPart2;
	}


	return TRUE;
}

