BOOL CCRCForceCtrl::Get_EnvelopLcom(ElemPairK ElemK, int nForType, BOOL bIsCalcStss, BOOL bReciInput, BOOL bIncludeTP, _DGN_LCOM& LcomDesign, int nCompareType)
{
	if (LcomDesign.LcomUlData.LoadCombType != 1) return FALSE;

	int iLcaseNum = LcomDesign.LcomUlData.Combination.GetSize();

	CArray<_DGN_FORC_CRC, _DGN_FORC_CRC&>arForceLcase;
	CArray<_DGN_STRS_ADD, _DGN_STRS_ADD&>arStressAdd;
	CArray<_DGN_STRS_CRC, _DGN_STRS_CRC&>arStressLcase;
	CArray<_DGN_SHRS_ADD, _DGN_SHRS_ADD&>arStssLcase;
	CArray<_DGN_FORC_CRC, _DGN_FORC_CRC&>arForcePart1;
	CArray<_DGN_STRS_CRC, _DGN_STRS_CRC&>arStressPart1;
	CArray<_DGN_FORC_CRC, _DGN_FORC_CRC&>arForcePart2;
	CArray<_DGN_STRS_CRC, _DGN_STRS_CRC&>arStressPart2;

	_DGN_FORC_CRC ForceLcase;
	_DGN_STRS_ADD StressAdd;
	_DGN_STRS_CRC StressLcase;
	_DGN_SHRS_ADD StssLcase;

	_DGN_FORC_CRC ForcePart1;
	_DGN_STRS_CRC StressPart1;
	_DGN_FORC_CRC ForcePart2;
	_DGN_STRS_CRC StressPart2;

	//////////////////////////////////////////////////////////////////////////
	for (int j = 0; j < iLcaseNum; ++j)
	{
		const T_LCOM_BASE &LcomB = LcomDesign.LcomUlData.Combination[j];

		ForceLcase.Initialize();
		StressAdd.Initialize();
		StressLcase.Initialize();
		StssLcase.Initialize();
		ForcePart1.Initialize();
		StressPart1.Initialize();
		ForcePart2.Initialize();
		StressPart2.Initialize();

		unsigned int iAnalType = LcomB.AnalType;
		unsigned int iLcaseKey = LcomB.LoadCaseKey;
		double dFactor = LcomB.Factor;
		int iMaxMinType = LcomDesign.iDgnLcomType;
		BOOL bReciLcase = (bReciInput ? Is_Reciprocal(iAnalType, iLcaseKey) : FALSE);

		dFactor = AdjustCJJLoadCaseFactor(iAnalType, LcomDesign, dFactor, m_Chrp, m_Pscd);

		_DGN_FORC_CRC ForceLcase;
		if ((CDBLib::IsCSGCode(m_iDgnCode) == FALSE && iAnalType == D_LCOM_CB_CONCRETE) || (CDBLib::IsCSGCode(m_iDgnCode) == TRUE && (iAnalType == D_LCOM_CB_STEEL || iAnalType == D_LCOM_CB_STLCOMP)))
		{
			//O≫OEÐiOO×eºIA´½øÐÐ°uAc￡￢EcEo°uAcOÐOÐ¹¤¿o￡￢½¨OeOA≫§½≪¸A¹¤¿oμ￥¶A¶¨OaIªºEOØ×eºIA´´|Ai
			Get_Lcom(ElemK, iLcaseKey, nForType, bIsCalcStss, ForceLcase, StressAdd, StressLcase, StssLcase, ForcePart1, StressPart1, ForcePart2, StressPart2, iMaxMinType);
		}
		else
		{
			ASSERT(0);
		}

		Set_DimTypeForc(ForceLcase);

		ForceLcase *= dFactor;
		m_StressAdd *= dFactor;
		StressLcase *= dFactor;
		StssLcase *= dFactor;
		ForcePart1 *= dFactor;
		ForcePart2 *= dFactor;
		StressPart1 *= dFactor;
		StressPart2 *= dFactor;

		arForceLcase.Add(ForceLcase);//½≪°uAcOÐμAA¿O≫¸o×eºIμAAUA|´æÆðA´
		arStressAdd.Add(m_StressAdd);
		arStressLcase.Add(StressLcase);
		arStssLcase.Add(StssLcase);
		arForcePart1.Add(ForcePart1);
		arForcePart2.Add(ForcePart2);
		arStressPart1.Add(StressPart1);
		arStressPart2.Add(StressPart2);
	}
	//////////////////////////////////////////////////////////////////////////  
	//double dFxx[cPOSI_CRC], dFyy[cPOSI_CRC], dFzz[cPOSI_CRC];//18×eAUA|Oμ¶OO|μAOªEØ
	//double dMux[cPOSI_CRC], dMuy[cPOSI_CRC], dMuz[cPOSI_CRC];
	//double dMbi[cPOSI_CRC], dTst[cPOSI_CRC], dTwp[cPOSI_CRC]; 
	int nFlag = 0;//±e¼CAAO≫×eEC×iOμ
	_DGN_FORC_CRC TempForceLaseMax; TempForceLaseMax.Initialize(TRUE);
	_DGN_FORC_CRC TempForceLaseMin; TempForceLaseMin.Initialize(FALSE);

	for (int ii = 0; ii < iLcaseNum; ++ii)//E¡×i²≫Au
	{
		switch (nCompareType)
		{
		case 0://dFxxMax
			if (arForceLcase.GetAt(ii).dFxx[0] >= TempForceLaseMax.dFxx[0])
			{
				nFlag = ii;
				TempForceLaseMax = arForceLcase.GetAt(ii);
			}
			break;
		case 1://dFxxMin
			if (arForceLcase.GetAt(ii).dFxx[1] <= TempForceLaseMin.dFxx[1])
			{
				nFlag = ii;
				TempForceLaseMin = arForceLcase.GetAt(ii);
			}
			break;
		case 2://dFyyMax
			if (arForceLcase.GetAt(ii).dFyy[0] >= TempForceLaseMax.dFyy[0])
			{
				nFlag = ii;
				TempForceLaseMax = arForceLcase.GetAt(ii);
			}
			break;
		case 3://dFyyMin
			if (arForceLcase.GetAt(ii).dFyy[1] <= TempForceLaseMin.dFyy[1])
			{
				nFlag = ii;
				TempForceLaseMin = arForceLcase.GetAt(ii);
			}
			break;
		case 4://dFzzMax
			if (arForceLcase.GetAt(ii).dFzz[0] >= TempForceLaseMax.dFzz[0])
			{
				nFlag = ii;
				TempForceLaseMax = arForceLcase.GetAt(ii);
			}
			break;
		case 5://dFzzMin
			if (arForceLcase.GetAt(ii).dFzz[1] <= TempForceLaseMin.dFzz[1])
			{
				nFlag = ii;
				TempForceLaseMin = arForceLcase.GetAt(ii);
			}
			break;
		case 6://dMuxMax
			if (arForceLcase.GetAt(ii).dMux[0] >= TempForceLaseMax.dMux[0])
			{
				nFlag = ii;
				TempForceLaseMax = arForceLcase.GetAt(ii);
			}
			break;
		case 7://dMuxMin
			if (arForceLcase.GetAt(ii).dMux[1] <= TempForceLaseMin.dMux[1])
			{
				nFlag = ii;
				TempForceLaseMin = arForceLcase.GetAt(ii);
			}
			break;
		case 8://dMuyMax
			if (arForceLcase.GetAt(ii).dMuy[0] >= TempForceLaseMax.dMuy[0])
			{
				nFlag = ii;
				TempForceLaseMax = arForceLcase.GetAt(ii);
			}
			break;
		case 9://dMuyMin
			if (arForceLcase.GetAt(ii).dMuy[1] <= TempForceLaseMin.dMuy[1])
			{
				nFlag = ii;
				TempForceLaseMin = arForceLcase.GetAt(ii);
			}
			break;
		case 10://dMuzMax
			if (arForceLcase.GetAt(ii).dMuz[0] >= TempForceLaseMax.dMuz[0])
			{
				nFlag = ii;
				TempForceLaseMax = arForceLcase.GetAt(ii);
			}
			break;
		case 11://dMuzMin
			if (arForceLcase.GetAt(ii).dMuz[1] <= TempForceLaseMin.dMuz[1])
			{
				nFlag = ii;
				TempForceLaseMin = arForceLcase.GetAt(ii);
			}
			break;
		case 12://dMbiMax
			if (arForceLcase.GetAt(ii).dMbi[0] >= TempForceLaseMax.dMbi[0])
			{
				nFlag = ii;
				TempForceLaseMax = arForceLcase.GetAt(ii);
			}
			break;
		case 13://dMbiMin
			if (arForceLcase.GetAt(ii).dMbi[1] <= TempForceLaseMin.dMbi[1])
			{
				nFlag = ii;
				TempForceLaseMin = arForceLcase.GetAt(ii);
			}
			break;
		case 14://dTstMax
			if (arForceLcase.GetAt(ii).dTst[0] >= TempForceLaseMax.dTst[0])
			{
				nFlag = ii;
				TempForceLaseMax = arForceLcase.GetAt(ii);
			}
			break;
		case 15://dTstMin
			if (arForceLcase.GetAt(ii).dTst[1] <= TempForceLaseMin.dTst[1])
			{
				nFlag = ii;
				TempForceLaseMin = arForceLcase.GetAt(ii);
			}
			break;
		case 16://dTwpMax
			if (arForceLcase.GetAt(ii).dTwp[0] >= TempForceLaseMax.dTwp[0])
			{
				nFlag = ii;
				TempForceLaseMax = arForceLcase.GetAt(ii);
			}
			break;
		case 17://dTwpMin
			if (arForceLcase.GetAt(ii).dTwp[1] <= TempForceLaseMin.dTwp[1])
			{
				nFlag = ii;
				TempForceLaseMin = arForceLcase.GetAt(ii);
			}
			break;
		default:
			ASSERT(0);
			break;
		}
	}
	//////////////////////////////////////////////////////////////////////////
	m_ForceRemn = arForceLcase.GetAt(nFlag);
	m_StressAdd = arStressAdd.GetAt(nFlag);
	m_StressRemn = arStressLcase.GetAt(nFlag);
	m_StressShr = arStssLcase.GetAt(nFlag);

	if (nForType > 0)
	{
		m_ForceRemnP1 = arForcePart1.GetAt(nFlag);
		m_ForceRemnP2 = arForcePart2.GetAt(nFlag);
		m_StressRemnP1 = arStressPart1.GetAt(nFlag);
		m_StressRemnP2 = arStressPart2.GetAt(nFlag);
	}
	//////////////////////////////////////////////////////////////////////////
	return TRUE;
}

BOOL CCRCForceCtrl::Get_Force(_DGN_FORC_CRC& ForceLcom, _DGN_FORC_CRC& ForceStag, _DGN_SHRS_ADD& ShrsStage, _DGN_FORC_CRC& ForceTnpr, _DGN_FORC_CRC& ForceTnsc, _DGN_STRS_ADD& StressAdd, _DGN_FORC_CRC& ForceLTerm, _DGN_FORC_CRC& ForceLL, _DGN_FORC_CRC& ForceJtgTndn,
	_DGN_FORC_CRC& ForceDL_TB05, _DGN_FORC_CRC& ForceLL_TB05, _DGN_FORC_CRC& ForceCSTP_TB05, _DGN_FORC_CRC& ForceEQE2_JTG, _DGN_FORC_CRC& ForceWeight_JTG)
{
	ForceLcom.Initialize();
	ForceStag.Initialize();
	ShrsStage.Initialize();
	ForceTnpr.Initialize();
	ForceTnsc.Initialize();
	StressAdd.Initialize();
	ForceLTerm.Initialize();
	ForceJtgTndn.Initialize();
	//
	ForceDL_TB05.Initialize();
	ForceLL_TB05.Initialize();
	//
	ForceEQE2_JTG.Initialize();
	ForceLL.Initialize();
	// See Manual 상반응력부재의 처리.
	// Change by ZINU.('04.05.12). Agree with Ko-CJ.
	/*
	for(int i=0; i<cPOSI_CRC; ++i)
	{
	for(int j=0; j<6; ++j)	// Fxx,Fyy,Fzz,Mux,Muy,Muz.
	{
	double dForD=0.0, dForL=0.0;
	if(j==0)			{dForD = m_ForceDrec.dFxx[i]; dForL = m_ForceLrec.dFxx[i];}
	else if(j==1)	{dForD = m_ForceDrec.dFyy[i]; dForL = m_ForceLrec.dFyy[i];}
	else if(j==2)	{dForD = m_ForceDrec.dFzz[i]; dForL = m_ForceLrec.dFzz[i];}
	else if(j==3)	{dForD = m_ForceDrec.dMux[i]; dForL = m_ForceLrec.dMux[i];}
	else if(j==4)	{dForD = m_ForceDrec.dMuy[i]; dForL = m_ForceLrec.dMuy[i];}
	else if(j==5)	{dForD = m_ForceDrec.dMuz[i]; dForL = m_ForceLrec.dMuz[i];}
	else	ASSERT(0);
	if(dForD*dForL < 0.0)	// No Same Sign.
	{
	if(fabs(dForD) > 0.3*fabs(dForL))	dForL *= 1.3;
	else															dForD *= 0.0;
	}
	if(j==0)			{m_ForceDrec.dFxx[i] = dForD; m_ForceLrec.dFxx[i] = dForL;}
	else if(j==1)	{m_ForceDrec.dFyy[i] = dForD; m_ForceLrec.dFyy[i] = dForL;}
	else if(j==2)	{m_ForceDrec.dFzz[i] = dForD; m_ForceLrec.dFzz[i] = dForL;}
	else if(j==3)	{m_ForceDrec.dMux[i] = dForD; m_ForceLrec.dMux[i] = dForL;}
	else if(j==4)	{m_ForceDrec.dMuy[i] = dForD; m_ForceLrec.dMuy[i] = dForL;}
	else if(j==5)	{m_ForceDrec.dMuz[i] = dForD; m_ForceLrec.dMuz[i] = dForL;}
	else	ASSERT(0);
	}
	}
	*/
	ForceLcom += m_ForceDnon;
	ForceLcom += m_ForceDrec;
	ForceLcom += m_ForceLnon;
	ForceLcom += m_ForceLrec;
	ForceLcom += m_ForceRemn;
	// Forec by All Sgld.
	ForceStag = m_ForceStag;
	ShrsStage = m_ShrsStage;
	// Force by Tendon Primary.
	ForceTnpr = m_ForceTnpr;
	ForceTnsc = m_ForceTnsc;
	// Add by ZINU.('05.01.03). Stress by Beam Section Temperature.
	StressAdd = m_StressAdd;
	// Add by Jaeoh. ('05.08.16).
	//ForceSgldDL += m_ForceSgldRemn; // For Required Tendon , Mg1  
	//ForceAddDL  += m_ForceAddDL;  // For Add DL , JTG D6204, 
	//ForceLL     += m_ForceLL;     // For 균열검토, JTG D62-04, LL

	switch (m_iDgnCode)
	{
	case SNiP_20503_84_PSC:
	case SP_35_13330_11_PSC:
	case SNiP_20503_84_PSC_MKS:
	case SP_35_13330_11_PSC_MKS:
	case SNiP_20503_84_SOD:
	case SP_35_13330_11_SOD:
		ForceLTerm += m_ForceAddDL;
		break;
	case KDS_24_14_31_2018_CSG:
	case KSCE_LSD15_CSG:
	case AASHTO_LRFD12_CSG:
	case AASHTO_LRFD07_CSG:
	case KSSC_2014_CSG:
	case CSA_S6_10_CSG:
	case CSA_S6_14_CSG:
	case CSA_S6_19_CSG:
	case AASHTO_LRFD16_CSG:
	case AASHTO_LRFD17_CSG:
	case AASHTO_LRFD20_CSG:
	case EUROCODE4_2_04_CSG:
	case CS457_R1_CSG:
	case NR_GN_CIV_025_06_CSG:
	case AS5100_6_17_CSG:
		// Beforce force
		if (m_bIsPLCB == TRUE)
		{
			ForceStag = m_ForceAddDL;
			ForceLcom += m_ForceAddDL;
		}
		// 2014.03.31 이정우 GJ님 요청
		// After force는 Dead(CS), CP(CS), CS(CS), SP(CS), SS(CS) 으로 수정 
		ForceLTerm += m_ForceLTerm;
		break;
	case SNiP_20503_84_CSG:
	case SP_35_13330_11_CSG:
		// Beforce force
		if (m_bIsPLCB == TRUE)
		{
			ForceStag = m_ForceAddDL;
		}
		// 2014.03.31 이정우 GJ님 요청
		// After force는 Dead(CS), CP(CS), CS(CS), SP(CS), SS(CS) 으로 수정 
		ForceLTerm += m_ForceLTerm;
		ForceLTerm += m_ForceRemn;
		break;
	case TB_10002_3_05:
	case RC_TB_10002_3_05:
		ForceDL_TB05 += m_ForceDL_TB05;
		ForceLL_TB05 += m_ForceLL_TB05;
		ForceCSTP_TB05 += m_ForceCS_TP_TB05;
		break;
	case RC_JTG_B02_01_2008:
	case RC_CJJ_166_2011:
		ForceEQE2_JTG += m_ForceEQE2_JTG;
		ForceWeight_JTG += m_ForceWeight_JTG;
		break;
	default:
		// PSC 기준으로 분리 했던 것을 삭제, 
		// Beforce force
		if (m_bIsPLCB == TRUE)
		{
			ForceStag = m_ForceAddDL;
			// PSC Composite 경우 완성계의 Force는 해석과 같아야 하기 때문에..
			// Steel Composite과는 다름.
			ForceLcom += m_ForceAddDL;
		}
		ForceLTerm += m_ForceSgldRe;
		ForceLTerm += m_ForceAddDL;
		//ForceLTerm += m_ForceLL;  
		break;
	}
	ForceLL += m_ForceLnon;
	ForceLL += m_ForceLrec;
	// Add by Jaeoh. ('06.09.18)
	// 시공단계 Load Case를 
	ForceJtgTndn += m_ForceJtgTndn;
	//

	return TRUE;
}

BOOL CCRCForceCtrl::Get_Force_EX(_DGN_FORC_CRC_EX& ForceLcom, _DGN_FORC_CRC_EX& ForceStag, _DGN_SHRS_ADD_EX& ShrsStage, _DGN_FORC_CRC_EX& ForceTnpr,
	_DGN_FORC_CRC_EX& ForceTnsc, _DGN_STRS_ADD_EX& StressAdd, _DGN_FORC_CRC_EX& ForceLTerm, _DGN_FORC_CRC_EX& ForceJtgTndn,
	_DGN_FORC_CRC_EX& ForceDL_TB05, _DGN_FORC_CRC_EX& ForceLL_TB05, _DGN_FORC_CRC_EX& ForceCSTP_TB05,
	_DGN_FORC_CRC_EX& ForceEQE2_JTG, _DGN_FORC_CRC_EX& ForceWeight_JTG)
{
	ForceLcom.Initialize();
	ForceStag.Initialize();
	ShrsStage.Initialize();
	ForceTnpr.Initialize();
	ForceTnsc.Initialize();
	StressAdd.Initialize();
	ForceLTerm.Initialize();
	ForceJtgTndn.Initialize();
	//
	ForceDL_TB05.Initialize();
	ForceLL_TB05.Initialize();
	//
	ForceEQE2_JTG.Initialize();
	// See Manual 상반응력부재의 처리.
	// Change by ZINU.('04.05.12). Agree with Ko-CJ.
	/*
	for(int i=0; i<cPOSI_CRC; ++i)
	{
	for(int j=0; j<6; ++j)	// Fxx,Fyy,Fzz,Mux,Muy,Muz.
	{
	double dForD=0.0, dForL=0.0;
	if(j==0)			{dForD = m_ForceDrec.dFxx[i]; dForL = m_ForceLrec.dFxx[i];}
	else if(j==1)	{dForD = m_ForceDrec.dFyy[i]; dForL = m_ForceLrec.dFyy[i];}
	else if(j==2)	{dForD = m_ForceDrec.dFzz[i]; dForL = m_ForceLrec.dFzz[i];}
	else if(j==3)	{dForD = m_ForceDrec.dMux[i]; dForL = m_ForceLrec.dMux[i];}
	else if(j==4)	{dForD = m_ForceDrec.dMuy[i]; dForL = m_ForceLrec.dMuy[i];}
	else if(j==5)	{dForD = m_ForceDrec.dMuz[i]; dForL = m_ForceLrec.dMuz[i];}
	else	ASSERT(0);
	if(dForD*dForL < 0.0)	// No Same Sign.
	{
	if(fabs(dForD) > 0.3*fabs(dForL))	dForL *= 1.3;
	else															dForD *= 0.0;
	}
	if(j==0)			{m_ForceDrec.dFxx[i] = dForD; m_ForceLrec.dFxx[i] = dForL;}
	else if(j==1)	{m_ForceDrec.dFyy[i] = dForD; m_ForceLrec.dFyy[i] = dForL;}
	else if(j==2)	{m_ForceDrec.dFzz[i] = dForD; m_ForceLrec.dFzz[i] = dForL;}
	else if(j==3)	{m_ForceDrec.dMux[i] = dForD; m_ForceLrec.dMux[i] = dForL;}
	else if(j==4)	{m_ForceDrec.dMuy[i] = dForD; m_ForceLrec.dMuy[i] = dForL;}
	else if(j==5)	{m_ForceDrec.dMuz[i] = dForD; m_ForceLrec.dMuz[i] = dForL;}
	else	ASSERT(0);
	}
	}
	*/
	ForceLcom += *m_pForceDnon_EX;
	ForceLcom += *m_pForceDrec_EX;
	ForceLcom += *m_pForceLnon_EX;
	ForceLcom += *m_pForceLrec_EX;
	ForceLcom += *m_pForceRemn_EX;
	// Forec by All Sgld.
	ForceStag = *m_pForceStag_EX;
	ShrsStage = *m_pShrsStage_EX;
	// Force by Tendon Primary.
	ForceTnpr = *m_pForceTnpr_EX;
	ForceTnsc = *m_pForceTnsc_EX;
	// Add by ZINU.('05.01.03). Stress by Beam Section Temperature.
	StressAdd = *m_pStressAdd_EX;
	// Add by Jaeoh. ('05.08.16).
	//ForceSgldDL += m_ForceSgldRemn; // For Required Tendon , Mg1  
	//ForceAddDL  += m_ForceAddDL;  // For Add DL , JTG D6204, 
	//ForceLL     += m_ForceLL;     // For 균열검토, JTG D62-04, LL

	switch (m_iDgnCode)
	{
	case SNiP_20503_84_PSC:
	case SP_35_13330_11_PSC:
	case SNiP_20503_84_PSC_MKS:
	case SP_35_13330_11_PSC_MKS:
	case SNiP_20503_84_SOD:
	case SP_35_13330_11_SOD:
		ForceLTerm += *m_pForceAddDL_EX;
		break;
	case KDS_24_14_31_2018_CSG:
	case KSCE_LSD15_CSG:
	case AASHTO_LRFD12_CSG:
	case AASHTO_LRFD07_CSG:
	case KSSC_2014_CSG:
	case CSA_S6_10_CSG:
	case CSA_S6_14_CSG:
	case CSA_S6_19_CSG:
	case AASHTO_LRFD16_CSG:
	case AASHTO_LRFD17_CSG:
	case AASHTO_LRFD20_CSG:
	case EUROCODE4_2_04_CSG:
	case CS457_R1_CSG:
	case NR_GN_CIV_025_06_CSG:
	case AS5100_6_17_CSG:
		// Beforce force
		if (m_bIsPLCB == TRUE)
		{
			ForceStag = *m_pForceAddDL_EX;
		}
		// 2014.03.31 이정우 GJ님 요청
		// After force는 Dead(CS), CP(CS), CS(CS), SP(CS), SS(CS) 으로 수정 
		ForceLTerm += *m_pForceLTerm_EX;
		break;
	case SNiP_20503_84_CSG:
	case SP_35_13330_11_CSG:
		// Beforce force
		if (m_bIsPLCB == TRUE)
		{
			ForceStag = *m_pForceAddDL_EX;
		}
		// 2014.03.31 이정우 GJ님 요청
		// After force는 Dead(CS), CP(CS), CS(CS), SP(CS), SS(CS) 으로 수정 
		ForceLTerm += *m_pForceLTerm_EX;
		ForceLTerm += *m_pForceRemn_EX;
		break;
	case TB_10002_3_05:
	case RC_TB_10002_3_05:
		ForceDL_TB05 += *m_pForceDL_TB05_EX;
		ForceLL_TB05 += *m_pForceLL_TB05_EX;
		ForceCSTP_TB05 += *m_pForceCS_TP_TB05_EX;
		break;
	case RC_JTG_B02_01_2008:
	case RC_CJJ_166_2011:
		ForceEQE2_JTG += *m_pForceEQE2_JTG_EX;
		ForceWeight_JTG += *m_pForceWeight_JTG_EX;
		break;
	default:
		ForceLTerm += *m_pForceSgldRe_EX;
		ForceLTerm += *m_pForceAddDL_EX;
		ForceLTerm += *m_pForceLL_EX;
		break;
	}
	// Add by Jaeoh. ('06.09.18)
	// 시공단계 Load Case를 
	ForceJtgTndn += *m_pForceJtgTndn_EX;
	//
	return TRUE;
}

BOOL CCRCForceCtrl::Get_Stress(_DGN_STRS_CRC& StressLcom, _DGN_STRS_CRC& StressTnpr, _DGN_STRS_CRC& StressTnsc, _DGN_STRS_CRC& StressLTerm, _DGN_STRS_CRC& StressLL, _DGN_SHRS_ADD& StssLcom,
	_DGN_STRS_CRC& StressDL_TB05, _DGN_STRS_CRC& StressLL_TB05, _DGN_STRS_CRC& StressCSTP_TB05)
{
	StressLcom.Initialize();
	//StressStag.Initialize();
	//ShrsStage.Initialize();
	StressTnpr.Initialize();
	StressTnsc.Initialize();
	//StressAdd.Initialize();
	StressLTerm.Initialize();
	StressLL.Initialize();
	StressDL_TB05.Initialize();
	StressLL_TB05.Initialize();

	StressLcom += m_StressNorDL;
	StressLcom += m_StressNorLL;
	StressLcom += m_StressRemn;
	// Force by Tendon Primary.
	StressTnpr = m_StressTnpr;
	StressTnsc = m_StressTnsc;
	// JTG D62-04.

	switch (m_iDgnCode)
	{
	case SNiP_20503_84_PSC:
	case SP_35_13330_11_PSC:
	case SNiP_20503_84_PSC_MKS:
	case SP_35_13330_11_PSC_MKS:
		StressLTerm += m_StressTnpr;
		StressLTerm += m_StressTnsc;
		StressLTerm += m_StressAddDL;
		break;
	case KDS_24_14_31_2018_CSG:
	case KSCE_LSD15_CSG:
	case AASHTO_LRFD20_CSG:
	case AASHTO_LRFD17_CSG:
	case AASHTO_LRFD16_CSG:
	case AASHTO_LRFD12_CSG:
	case AASHTO_LRFD07_CSG:
	case SNiP_20503_84_CSG:
	case SP_35_13330_11_CSG:
	case CSA_S6_10_CSG:
	case CSA_S6_14_CSG:
	case CSA_S6_19_CSG:
	case EUROCODE4_2_04_CSG:
	case CS457_R1_CSG:
	case NR_GN_CIV_025_06_CSG:
	case AS5100_6_17_CSG:
		StressLTerm += m_StressLTerm;
		break;
	case TB_10002_3_05:
	case RC_TB_10002_3_05:
		StressDL_TB05 += m_StressDL_TB05;
		StressLL_TB05 += m_StressLL_TB05;
		StressCSTP_TB05 += m_StressCS_TP_TB05;
		break;
	default:
		StressLTerm += m_StressSgldRe;
		StressLTerm += m_StressAddDL;
		//StressLTerm += m_StressJtgLL;  
		break;
	}

	StressLL += m_StressNorLL;

	// Principle.
	//ssStag += m_StssStage;
	StssLcom += m_StressShr;

	return TRUE;
}


BOOL CCRCForceCtrl::Get_Stress_EX(_DGN_STRS_CRC_EX& StressLcom, _DGN_STRS_CRC_EX& StressTnpr, _DGN_STRS_CRC_EX& StressTnsc,
	_DGN_STRS_CRC_EX& StressLTerm, _DGN_SHRS_ADD_EX& StssLcom, _DGN_STRS_CRC_EX& StressDL_TB05,
	_DGN_STRS_CRC_EX& StressLL_TB05, _DGN_STRS_CRC_EX& StressCSTP_TB05)
{
	StressLcom.Initialize();
	//StressStag.Initialize();
	//ShrsStage.Initialize();
	StressTnpr.Initialize();
	StressTnsc.Initialize();
	//StressAdd.Initialize();
	StressLTerm.Initialize();
	StressDL_TB05.Initialize();
	StressLL_TB05.Initialize();

	StressLcom += *m_pStressNorDL_EX;
	StressLcom += *m_pStressNorLL_EX;
	StressLcom += *m_pStressRemn_EX;
	// Force by Tendon Primary.
	StressTnpr = *m_pStressTnpr_EX;
	StressTnsc = *m_pStressTnsc_EX;
	// JTG D62-04.

	switch (m_iDgnCode)
	{
	case SNiP_20503_84_PSC:
	case SP_35_13330_11_PSC:
	case SNiP_20503_84_PSC_MKS:
	case SP_35_13330_11_PSC_MKS:
		StressLTerm += *m_pStressTnpr_EX;
		StressLTerm += *m_pStressTnsc_EX;
		StressLTerm += *m_pStressAddDL_EX;
		break;
	case KSCE_LSD15_CSG:
	case AASHTO_LRFD20_CSG:
	case AASHTO_LRFD17_CSG:
	case AASHTO_LRFD16_CSG:
	case AASHTO_LRFD12_CSG:
	case AASHTO_LRFD07_CSG:
	case KDS_24_14_31_2018_CSG:
	case KSSC_2014_CSG:
	case SNiP_20503_84_CSG:
	case SP_35_13330_11_CSG:
	case CSA_S6_10_CSG:
	case CSA_S6_14_CSG:
	case CSA_S6_19_CSG:
	case EUROCODE4_2_04_CSG:
	case CS457_R1_CSG:
	case NR_GN_CIV_025_06_CSG:
	case AS5100_6_17_CSG:
		StressLTerm += *m_pStressLTerm_EX;
		break;
	case TB_10002_3_05:
	case RC_TB_10002_3_05:
		StressDL_TB05 += *m_pStressDL_TB05_EX;
		StressLL_TB05 += *m_pStressLL_TB05_EX;
		StressCSTP_TB05 += *m_pStressCS_TP_TB05_EX;
		break;
	default:
		StressLTerm += *m_pStressSgldRe_EX;
		StressLTerm += *m_pStressAddDL_EX;
		StressLTerm += *m_pStressJtgLL_EX;
		break;
	}

	// Principle.
	//ssStag += m_StssStage_EX;
	StssLcom += *m_pStressShr_EX;

	return TRUE;
}

