void CCRCForceCtrl::Set_LcomForElem(ArrElemPairKey& arElemK)
{
	int iTotalElement = arElemK.GetSize();
	m_SerialElemKey.clear();
	/*
	if(m_arStldK.GetCount()>0) m_arStldElem.SetSize(iTotalElement);
	if(m_arSplcK.GetCount()>0) m_arSplcElem.SetSize(iTotalElement);
	if(m_arEspcK.GetCount()>0) m_arEspcElem.SetSize(iTotalElement);
	if(m_arThisK.GetCount()>0) m_arThisElem.SetSize(iTotalElement);
	if(m_arSgldK.GetCount()>0) m_arSgldElem.SetSize(iTotalElement);
	if(m_arStepK.GetCount()>0) m_arStepElem.SetSize(iTotalElement);
	if(m_arMvldK.GetCount()>0) m_arMvldElem.SetSize(iTotalElement);
	if(m_arSmlcK.GetCount()>0) m_arSmlcElem.SetSize(iTotalElement);
	if(m_arMapGilcStrbK.GetCount()>0) m_arGilcStrbElem.SetSize(iTotalElement);
	if(m_arMapGilcSbcfK.GetCount()>0) m_arGilcSbcfElem.SetSize(iTotalElement);
	if(m_arMapLcomStrbK.GetCount()>0) m_arLcomStrbElem.SetSize(iTotalElement);  // Add by GAY. MNET:2903. ('07.07.31).
	if(m_arMapLcomSbcfK.GetCount()>0) m_arLcomSbcfElem.SetSize(iTotalElement);  // Add by GAY. MNET:2903. ('07.08.24).
	*/

	//
	Set_CheckElem(arElemK);
	// Load case용 Binary 생성.
	if (CDBLib::IsAdPscCode(m_iDgnCode))
	{
		//if(!CreatForceStressByLCaseFile()) return; 
		if (!CreatForceStressByLoadCaseFile()) return;
		if (!CreatPartForceStressByLoadCaseFile()) return;
	}
	else
	{
		//if(!CreatForceStressByLCaseFile()) return;      
		if (!CreatForceStressByLoadCaseFile()) return;
		if (!CreatPartForceStressByLoadCaseFile()) return;
	}

	for (UINT i = 0; i < arElemK.GetSize(); ++i)
	{
		ElemPairK EPairK = arElemK.GetAt(i);
		T_ELEM_K ElemK = EPairK.first;
		m_SerialElemKey.insert({ EPairK, i });

		m_pSectInfo->Get_StrsPscd(FALSE, ElemK, m_StrsPost);

		Set_StrbForDgn_Stld(EPairK, i);
		//GSaveHistoryNF(_T("Set_StrbForDgn_Stld"));
		Set_StrbForDgn_Splc(EPairK, i);
		//GSaveHistoryNF(_T("Set_StrbForDgn_Splc"));
		Set_StrbForDgn_Espc(EPairK, i);
		//GSaveHistoryNF(_T("Set_StrbForDgn_Espc"));
		Set_StrbForDgn_This(EPairK, i);
		//GSaveHistoryNF(_T("Set_StrbForDgn_This"));
		Set_StrbForDgn_Mvld(EPairK, i);
		Set_StrbForDgn_MvldBS(EPairK, i); // Civil v891 US - BS Assessment - CS454 Special Moving Load Case (CIVIL-1069)
		//GSaveHistoryNF(_T("Set_StrbForDgn_Mvld"));
		Set_StrbForDgn_Smlc(EPairK, i);
		//GSaveHistoryNF(_T("Set_StrbForDgn_Smlc"));
		Set_StrbForDgn_Sgld(EPairK, i);
		//GSaveHistoryNF(_T("Set_StrbForDgn_Sgld"));
		Set_StrbForDgn_GilcStrb(EPairK, i);
		//GSaveHistoryNF(_T("Set_StrbForDgn_GilcStrb"));
		Set_StrbForDgn_GilcSbcf(EPairK, i);
		//GSaveHistoryNF(_T("Set_StrbForDgn_GilcSbcf"));
		Set_StrbForDgn_LcomStrb(EPairK, i);
		//GSaveHistoryNF(_T("Set_StrbForDgn_LcomStrb"));
		Set_StrbForDgn_LcomSbcf(EPairK, i);
		//GSaveHistoryNF(_T("Set_StrbForDgn_LcomSbcf"));

		//     Set_StrbForDgn(ElemK, i);    
		//     GSaveHistoryNF(_T("Set_StrbForDgn"));
		// 		Set_StrbForDgn_new(ElemK, i);  //   Set_StrbForDgn에서 stack ove flow 에러가 자주 발생해서 두 부분으로 나눔
		//     GSaveHistoryNF(_T("Set_StrbForDgn_new"));

		if (m_bWrite5PositionDgnForce)
		{
			// PCS
			Set_StrbForDgn_Stld_EX(EPairK, i);
			Set_StrbForDgn_Splc_EX(EPairK, i);
			Set_StrbForDgn_Espc_EX(EPairK, i);
			Set_StrbForDgn_This_EX(EPairK, i);
			Set_StrbForDgn_Mvld_EX(EPairK, i);
			Set_StrbForDgn_MvldBS_EX(EPairK, i);
			Set_StrbForDgn_Smlc_EX(EPairK, i);
			Set_StrbForDgn_Sgld_EX(EPairK, i);
			Set_StrbForDgn_GilcStrb_EX(EPairK, i);
			Set_StrbForDgn_GilcSbcf_EX(EPairK, i);
			Set_StrbForDgn_LcomStrb_EX(EPairK, i);
			Set_StrbForDgn_LcomSbcf_EX(EPairK, i);
		}
	}


	//
	CloseDgnForceFile();
	//
	//m_pDataCtrl->CheckDesignLcaseForceData();
	m_pDataCtrl->CheckDgnLoadCaseForce();
	m_pDataCtrl->CheckDgnLoadCaseForcePart();
}

void CCRCForceCtrl::Set_StrbForDgn_Stld(ElemPairK ElemK, int iSerial)
{
	BOOL bImportForce = (m_bImportForce ? TRUE : FALSE);

	// PSC Composite
	BOOL bComposite = m_pDataCtrl->IsCompositeSect(ElemK);
	BOOL bIsPscSect = m_pDataCtrl->IsPSCSect(ElemK);
	BOOL bIsCalSlab = FALSE;

	int iPartId = 1;
	// Get Forces.
	// Static.
	if (m_arStldK.GetCount() > 0)
	{
		T_STLD_K StldK, StldGetK, ScfpGetK;
		UINT iSerStldK = 0;
		POSITION PosStld = m_arStldK.GetStartPosition();
		while (PosStld)
		{
			BOOL bIsSCFPWrite = FALSE;
			T_STRB_D StrbMax;   StrbMax.Initialize();
			T_STRB_D StrbMin;   StrbMin.Initialize();
			T_STRB_D StrbPartG; StrbPartG.Initialize();
			T_STRB_D StrbPartS; StrbPartS.Initialize();
			T_STSS_D StssMax;   StssMax.Initialize();
			T_STSS_D StssMin;   StssMin.Initialize();
			T_SCFP_D ScfpPartG; ScfpPartG.Initialize();
			T_SCFP_D ScfpPartS; ScfpPartS.Initialize();

			T_LCOM_D LcasD;
			m_arStldK.GetNextAssoc(PosStld, StldK, StldGetK);
			m_pPostCtrl->MakeLoadComb(D_LOADCASE_STATIC, StldGetK, LcasD);
			m_pPostCtrl->SelectLoadCombNew(LcasD);
			if (bImportForce && m_pPostCtrl->GetAnalysisResult()->GetStldDesignForceData(StldGetK, ElemK.first, StrbMax, StrbMin))
			{
				// Normal
				m_pSectInfo->Cal_StrsStrbCurrent(ElemK.first, &StrbMax, &StrbMin);
				// Principle
				m_pSectInfo->Cal_StrsStssCurrent(ElemK.first, &StrbMax, &StrbMin, &StssMax, &StssMin);
			}
			else
			{
				// Normal
				if (bComposite == TRUE) // psc composite
				{
					// 전체
					m_pPostCtrl->GetStrbNew(ElemK.first, &StrbMax, 0, 0, FALSE, NULL, ElemK.second);

					// 거더
					if (m_pPostCtrl->GetStrbPartNew(ElemK.first, 1, &StrbPartG, 0, 0))
					{
						Get_ChangeStrbStress(StrbMax, StrbPartG);
					}

					// 슬래브
					bIsCalSlab = m_pPostCtrl->GetStrbPartNew(ElemK.first, 2, &StrbPartS, 0, 0);

					if (m_arStldScfpK.Lookup(StldK, ScfpGetK))
					{
						bIsSCFPWrite = TRUE;
						m_pPostCtrl->GetScfpPartNew(ElemK.first, 1, &ScfpPartG, 0, 0);
						m_pPostCtrl->GetScfpPartNew(ElemK.first, 2, &ScfpPartS, 0, 0);
					}
				}
				else  // psc
				{
					m_pPostCtrl->GetStrbNew(ElemK.first, &StrbMax, 0, 0, FALSE, NULL, ElemK.second);
				}

				// Principle
				//GSaveHistoryNF(_T("Stld_GetStssNew"));
				if (bIsPscSect == TRUE) m_pPostCtrl->GetStssNew(ElemK.first, &StssMax, 0, 0);
			}

			_DGN_STRBFORC_LCASE DgnStrb;
			Get_StrbToForce(StrbMax, DgnStrb.Force);
			Get_LoadCaseStress(ElemK, StrbMax, DgnStrb.Stress);
			if (bIsPscSect == TRUE) Get_LoadCaseStss(StssMax, DgnStrb.Stss);
			WriteLoadCaseStld(ElemK, StldGetK, DgnStrb);

			if (bComposite == TRUE)
			{
				_DGN_STRBFORC_PART_LCASE DgnStrbPart;
				Get_StrbToForce(StrbPartG, DgnStrbPart.ForceP1);
				Get_StrbToForce(StrbPartS, DgnStrbPart.ForceP2);
				if (bIsCalSlab) Get_LoadCaseStress(ElemK, StrbPartS, DgnStrbPart.StressP2);
				else            Get_LoadCaseStressGilc(ElemK, StrbMax, DgnStrbPart.StressP2);
				WritePartLoadCaseStld(ElemK, StldGetK, DgnStrbPart);
			}

			if (bIsSCFPWrite == TRUE)
			{
				_DGN_SCFP_PART_LCASE ScfpPartLcase;
				Get_ScfpToDgnScfp(ScfpPartG, ScfpPartLcase.ForceP1);
				Get_ScfpToDgnScfp(ScfpPartS, ScfpPartLcase.ForceP2);
				WritePartLoadCaseStld_SCFP(ElemK, ScfpGetK, ScfpPartLcase);
			}
		}
	}

}

void CCRCForceCtrl::Set_StrbForDgn_Splc(ElemPairK ElemK, int iSerial)
{
	BOOL bImportForce = (m_bImportForce ? TRUE : FALSE);

	// PSC Composite
	BOOL bComposite = m_pDataCtrl->IsCompositeSect(ElemK);
	BOOL bIsPscSect = m_pDataCtrl->IsPSCSect(ElemK);
	BOOL bIsCalSlab = FALSE;

	int iPartId = 1;
	// Get Forces.
	if (m_arSplcK.GetCount() > 0)
	{
		T_SPLC_K SplcK, SplcGetK;
		UINT iSerSplcK = 0;
		POSITION PosSplc = m_arSplcK.GetStartPosition();
		while (PosSplc)
		{
			T_STRB_D StrbMax;   StrbMax.Initialize();
			T_STRB_D StrbMin;   StrbMin.Initialize();
			T_STRB_D StrbPartG; StrbPartG.Initialize();
			T_STRB_D StrbPartS; StrbPartS.Initialize();
			T_STSS_D StssMax;   StssMax.Initialize();
			T_STSS_D StssMin;   StssMin.Initialize();

			T_LCOM_D LcasD;
			m_arSplcK.GetNextAssoc(PosSplc, SplcK, SplcGetK);
			if (!m_pPostCtrl->MakeLoadComb(D_LOADCASE_SPECTRUM, SplcGetK, LcasD))	continue;
			m_pPostCtrl->SelectLoadCombNew(LcasD);
			// Import Data.
			if (bImportForce && m_pPostCtrl->GetAnalysisResult()->GetSplcDesignForceData(SplcGetK, ElemK.first, StrbMax, StrbMin))
			{
				// Normal
				m_pSectInfo->Cal_StrsStrbCurrent(ElemK.first, &StrbMax, &StrbMin);
				// Principle
				m_pSectInfo->Cal_StrsStssCurrent(ElemK.first, &StrbMax, &StrbMin, &StssMax, &StssMin);
			}
			else
			{
				// Normal
				if (bComposite == TRUE) // psc composite
				{
					// 전체
					m_pPostCtrl->GetStrbNew(ElemK.first, &StrbMax, 0, 0, FALSE, NULL, ElemK.second);

					// 거더
					if (m_pPostCtrl->GetStrbPartNew(ElemK.first, 1, &StrbPartG, 0, 0))
					{
						Get_ChangeStrbStress(StrbMax, StrbPartG);
					}

					// 슬래브
					bIsCalSlab = m_pPostCtrl->GetStrbPartNew(ElemK.first, 2, &StrbPartS, 0, 0);
				}
				else  // psc
				{
					m_pPostCtrl->GetStrbNew(ElemK.first, &StrbMax, 0, 0, FALSE, NULL, ElemK.second);
				}

				// Principle
				//GSaveHistoryNF(_T("Stld_GetStssNew"));
				if (bIsPscSect == TRUE) m_pPostCtrl->GetStssNew(ElemK.first, &StssMax, 0, 0);
			}

			_DGN_STRBFORC_LCASE DgnStrb;
			Get_StrbToForce(StrbMax, DgnStrb.Force);
			Get_LoadCaseStress(ElemK, StrbMax, DgnStrb.Stress);
			if (bIsPscSect == TRUE) Get_LoadCaseStss(StssMax, DgnStrb.Stss);
			WriteLoadCaseSplc(ElemK, SplcGetK, DgnStrb);

			if (bComposite == TRUE)
			{
				_DGN_STRBFORC_PART_LCASE DgnStrbPart;
				Get_StrbToForce(StrbPartG, DgnStrbPart.ForceP1);
				Get_StrbToForce(StrbPartS, DgnStrbPart.ForceP2);
				if (bIsCalSlab) Get_LoadCaseStress(ElemK, StrbPartS, DgnStrbPart.StressP2);
				else            Get_LoadCaseStressGilc(ElemK, StrbMax, DgnStrbPart.StressP2);
				WritePartLoadCaseSplc(ElemK, SplcGetK, DgnStrbPart);
			}
		}
	}
}

