void CCRCForceCtrl::Set_StrbForDgn_Stld_EX(ElemPairK ElemK, int iSerial)
{
	BOOL bImportForce = (m_bImportForce ? TRUE : FALSE);

	// PSC Composite
	BOOL bComposite = m_pDataCtrl->IsCompositeSect(ElemK);
	BOOL bIsPscSect = m_pDataCtrl->IsPSCSect(ElemK);
	BOOL bIsCalSlab = FALSE;

	int iPartId = 1;
	// Get Forces.
	// Static.
	if (m_arStldK.GetCount() > 0)
	{
		T_STLD_K StldK, StldGetK, ScfpGetK;
		UINT iSerStldK = 0;
		POSITION PosStld = m_arStldK.GetStartPosition();
		while (PosStld)
		{
			BOOL bIsSCFPWrite = FALSE;
			T_STRB_D StrbMax;   StrbMax.Initialize();
			T_STRB_D StrbMin;   StrbMin.Initialize();
			T_STRB_D StrbPartG; StrbPartG.Initialize();
			T_STRB_D StrbPartS; StrbPartS.Initialize();
			T_STSS_D StssMax;   StssMax.Initialize();
			T_STSS_D StssMin;   StssMin.Initialize();
			T_SCFP_D ScfpPartG; ScfpPartG.Initialize();
			T_SCFP_D ScfpPartS; ScfpPartS.Initialize();

			T_LCOM_D LcasD;
			m_arStldK.GetNextAssoc(PosStld, StldK, StldGetK);
			m_pPostCtrl->MakeLoadComb(D_LOADCASE_STATIC, StldGetK, LcasD);
			m_pPostCtrl->SelectLoadCombNew(LcasD);
			if (bImportForce && m_pPostCtrl->GetAnalysisResult()->GetStldDesignForceData(StldGetK, ElemK.first, StrbMax, StrbMin))
			{
				// Normal
				m_pSectInfo->Cal_StrsStrbCurrent(ElemK.first, &StrbMax, &StrbMin);
				// Principle
				m_pSectInfo->Cal_StrsStssCurrent(ElemK.first, &StrbMax, &StrbMin, &StssMax, &StssMin);
			}
			else
			{
				// Normal
				if (bComposite == TRUE) // psc composite
				{
					// 전체
					m_pPostCtrl->GetStrbNew(ElemK.first, &StrbMax, 0, 0, FALSE, NULL, ElemK.second);

					// 거더
					if (m_pPostCtrl->GetStrbPartNew(ElemK.first, 1, &StrbPartG, 0, 0))
					{
						Get_ChangeStrbStress(StrbMax, StrbPartG);
					}

					// 슬래브
					bIsCalSlab = m_pPostCtrl->GetStrbPartNew(ElemK.first, 2, &StrbPartS, 0, 0);

					if (m_arStldScfpK.Lookup(StldK, ScfpGetK))
					{
						bIsSCFPWrite = TRUE;
						m_pPostCtrl->GetScfpPartNew(ElemK.first, 1, &ScfpPartG, 0, 0);
						m_pPostCtrl->GetScfpPartNew(ElemK.first, 2, &ScfpPartS, 0, 0);
					}
				}
				else  // psc
				{
					m_pPostCtrl->GetStrbNew(ElemK.first, &StrbMax, 0, 0, FALSE, NULL, ElemK.second);
				}

				// Principle
				//GSaveHistoryNF(_T("Stld_GetStssNew"));
				if (bIsPscSect == TRUE) m_pPostCtrl->GetStssNew(ElemK.first, &StssMax, 0, 0);
			}

			_DGN_STRBFORC_LCASE_EX DgnStrb;
			Get_StrbToForce_EX(StrbMax, DgnStrb.Force);
			Get_LoadCaseStress_EX(ElemK, StrbMax, DgnStrb.Stress);
			if (bIsPscSect == TRUE) Get_LoadCaseStss_EX(StssMax, DgnStrb.Stss);
			WriteLoadCaseStld_EX(ElemK, StldGetK, DgnStrb);

			if (bComposite == TRUE)
			{
				_DGN_STRBFORC_PART_LCASE_EX DgnStrbPart;
				Get_StrbToForce_EX(StrbPartG, DgnStrbPart.ForceP1);
				Get_StrbToForce_EX(StrbPartS, DgnStrbPart.ForceP2);
				if (bIsCalSlab) Get_LoadCaseStress_EX(ElemK, StrbPartS, DgnStrbPart.StressP2);
				else            Get_LoadCaseStressGilc_EX(ElemK, StrbMax, DgnStrbPart.StressP2);
				WritePartLoadCaseStld_EX(ElemK, StldGetK, DgnStrbPart);
			}

			if (bIsSCFPWrite == TRUE)
			{
				_DGN_SCFP_PART_LCASE_EX ScfpPartLcase;
				Get_ScfpToDgnScfp_EX(ScfpPartG, ScfpPartLcase.ForceP1);
				Get_ScfpToDgnScfp_EX(ScfpPartS, ScfpPartLcase.ForceP2);
				WritePartLoadCaseStld_SCFP_EX(ElemK, ScfpGetK, ScfpPartLcase);
			}
		}
	}
}

void CCRCForceCtrl::Set_StrbForDgn_Splc_EX(ElemPairK ElemK, int iSerial)
{
	BOOL bImportForce = (m_bImportForce ? TRUE : FALSE);

	// PSC Composite
	BOOL bComposite = m_pDataCtrl->IsCompositeSect(ElemK);
	BOOL bIsPscSect = m_pDataCtrl->IsPSCSect(ElemK);
	BOOL bIsCalSlab = FALSE;

	int iPartId = 1;
	// Get Forces.
	if (m_arSplcK.GetCount() > 0)
	{
		T_SPLC_K SplcK, SplcGetK;
		UINT iSerSplcK = 0;
		POSITION PosSplc = m_arSplcK.GetStartPosition();
		while (PosSplc)
		{
			T_STRB_D StrbMax;   StrbMax.Initialize();
			T_STRB_D StrbMin;   StrbMin.Initialize();
			T_STRB_D StrbPartG; StrbPartG.Initialize();
			T_STRB_D StrbPartS; StrbPartS.Initialize();
			T_STSS_D StssMax;   StssMax.Initialize();
			T_STSS_D StssMin;   StssMin.Initialize();

			T_LCOM_D LcasD;
			m_arSplcK.GetNextAssoc(PosSplc, SplcK, SplcGetK);
			if (!m_pPostCtrl->MakeLoadComb(D_LOADCASE_SPECTRUM, SplcGetK, LcasD))	continue;
			m_pPostCtrl->SelectLoadCombNew(LcasD);
			// Import Data.
			if (bImportForce && m_pPostCtrl->GetAnalysisResult()->GetSplcDesignForceData(SplcGetK, ElemK.first, StrbMax, StrbMin))
			{
				// Normal
				m_pSectInfo->Cal_StrsStrbCurrent(ElemK.first, &StrbMax, &StrbMin);
				// Principle
				m_pSectInfo->Cal_StrsStssCurrent(ElemK.first, &StrbMax, &StrbMin, &StssMax, &StssMin);
			}
			else
			{
				// Normal
				if (bComposite == TRUE) // psc composite
				{
					// 전체
					m_pPostCtrl->GetStrbNew(ElemK.first, &StrbMax, 0, 0, FALSE, NULL, ElemK.second);

					// 거더
					if (m_pPostCtrl->GetStrbPartNew(ElemK.first, 1, &StrbPartG, 0, 0))
					{
						Get_ChangeStrbStress(StrbMax, StrbPartG);
					}

					// 슬래브
					bIsCalSlab = m_pPostCtrl->GetStrbPartNew(ElemK.first, 2, &StrbPartS, 0, 0);
				}
				else  // psc
				{
					m_pPostCtrl->GetStrbNew(ElemK.first, &StrbMax, 0, 0, FALSE, NULL, ElemK.second);
				}

				// Principle
				//GSaveHistoryNF(_T("Stld_GetStssNew"));
				if (bIsPscSect == TRUE) m_pPostCtrl->GetStssNew(ElemK.first, &StssMax, 0, 0);
			}

			_DGN_STRBFORC_LCASE_EX DgnStrb;
			Get_StrbToForce_EX(StrbMax, DgnStrb.Force);
			Get_LoadCaseStress_EX(ElemK, StrbMax, DgnStrb.Stress);
			if (bIsPscSect == TRUE) Get_LoadCaseStss_EX(StssMax, DgnStrb.Stss);
			WriteLoadCaseSplc_EX(ElemK, SplcGetK, DgnStrb);

			if (bComposite == TRUE)
			{
				_DGN_STRBFORC_PART_LCASE_EX DgnStrbPart;
				Get_StrbToForce_EX(StrbPartG, DgnStrbPart.ForceP1);
				Get_StrbToForce_EX(StrbPartS, DgnStrbPart.ForceP2);
				if (bIsCalSlab) Get_LoadCaseStress_EX(ElemK, StrbPartS, DgnStrbPart.StressP2);
				else            Get_LoadCaseStressGilc_EX(ElemK, StrbMax, DgnStrbPart.StressP2);
				WritePartLoadCaseSplc_EX(ElemK, SplcGetK, DgnStrbPart);
			}
		}
	}
}

