void CCRCForceCtrl::Set_StrbForDgn_Mvld_EX(ElemPairK ElemK, int iSerial)
{
	BOOL bImportForce = (m_bImportForce ? TRUE : FALSE);

	// PSC Composite
	BOOL bComposite = m_pDataCtrl->IsCompositeSect(ElemK);
	BOOL bIsPscSect = m_pDataCtrl->IsPSCSect(ElemK);

	// Concurrent Forces.

	int iPartId = 1;

	// Moving.
	if (m_arMvldK.GetCount() > 0)
	{
		T_MVLD_K MvldK, MvldGetK;
		UINT iSerMvldK = 0;
		POSITION PosMvld = m_arMvldK.GetStartPosition();
		while (PosMvld)
		{
			T_SBCF_D SbcfMax; SbcfMax.Initialize();
			T_SBCF_D SbcfMin; SbcfMin.Initialize();

			T_LCOM_D LcasD;
			m_arMvldK.GetNextAssoc(PosMvld, MvldK, MvldGetK);
			if (!m_pPostCtrl->MakeLoadComb(D_LOADCASE_MOVING, MvldGetK, LcasD))	continue;
			m_pPostCtrl->SelectLoadCombNew(LcasD);
			if (bImportForce && m_pPostCtrl->GetAnalysisResult()->GetMvldDesignForceData(MvldGetK, ElemK.first, SbcfMax, SbcfMin))
			{
				// Normal.
				m_pSectInfo->Cal_StrsSbcfCurrent(ElemK.first, &SbcfMax, &SbcfMin);
				// Principle.
				//m_pSectInfo->Cal_SbcfStssCurrent(ElemK,&SbcfMax,&SbcfMin,&StssMax,&StssMin);
			}
			else
			{
				// Normal.  	    

				if (bComposite)
				{
					// 전체
					m_pPostCtrl->GetSbcfNew(ElemK.first, &SbcfMax, &SbcfMin, 0, FALSE, FALSE, ElemK.second);

					//m_pPostCtrl->GetStssNew(ElemK, &StssMax,&StssMin,&StssAbs);          

					// MV는 Part에 대한 Sbcf는 값이 없음. 
					// 거더
					//m_pPostCtrl->GetStrbPartNew(ElemK, 1, &MVStrbMaxG, &MVStrbMinG, 0);

					// 슬래브
					//m_pPostCtrl->GetStrbPartNew(ElemK, 2, &MVStrbMaxS, &MVStrbMinS, 0); 
				}
				else
				{
					m_pPostCtrl->GetSbcfNew(ElemK.first, &SbcfMax, &SbcfMin, 0, FALSE, FALSE, ElemK.second);
				}
				// Principle.
				//m_pPostCtrl->GetStssNew(ElemK, &StssMax,&StssMin,&StssAbs);
			}

			//
			_DGN_SBCFFORC_LCASE_EX DgnSbcf;
			for (int i = 0; i < cFORC_CON; ++i)
			{
				BOOL bMax = (i % 2 == 0);
				// Set Force Type.
				DgnSbcf.Force[i].strType = GetConCurrForceType(i);
				// Set Forces.
				Get_SbcfToForce_EX(bMax, i, SbcfMax, SbcfMin, DgnSbcf.Force[i]);
			}

			ADGNSTRESS_EX aStressLcase;
			if (bComposite)
			{
				Get_LoadCaseStressGilc_EX(ElemK, SbcfMax, SbcfMin, aStressLcase);
			}
			else
			{
				Get_LoadCaseStress_EX(ElemK, SbcfMax, SbcfMin, aStressLcase);
			}

			for (int i = 0; i < cFORC_CON; ++i)
			{
				DgnSbcf.Stress[i] = aStressLcase[i];
			}

			if (bIsPscSect == TRUE)
			{
				ADGNSHRSADD_EX aStssLcase;
				Get_LoadCaseStss_EX(ElemK, FALSE, SbcfMax, SbcfMin, aStssLcase);
				for (int i = 0; i < cFORC_CON; ++i)
				{
					DgnSbcf.Stss[i] = aStssLcase[i];
				}
			}
			WriteLoadCaseMvld_EX(ElemK, MvldGetK, DgnSbcf);

			if (bComposite == TRUE && m_pDataCtrl->IsCrackedSectionOptionInSectionManger(ElemK) == FALSE)
			{
				_DGN_SBCFFORC_PART_LCASE_EX DgnSbcfPart;
				DgnSbcfPart.Initialize();
				Get_LoadCaseStressSlab_EX(ElemK, SbcfMax, SbcfMin, DgnSbcfPart.StressP2);
				WritePartLoadCaseMvld_EX(ElemK, MvldGetK, DgnSbcfPart);
			}
		}
	}
}

