BOOL CCRCForceCtrl::Get_ConvertStrb(int nType, T_SBCF_D &rSbcf, T_STRB_D &rData)
{
	if (nType < 0 || nType>8) return FALSE;

	for (int j = 0; j < 4; ++j)
	{
		for (int k = 0; k < cPOSI_CRC; ++k)
		{
			// Force.
			int iKind = (k == 0 ? 0 : 6);
			rData.dblForce[j][iKind + 0] = rSbcf.dblForce[j][k][nType][0];
			rData.dblForce[j][iKind + 1] = rSbcf.dblForce[j][k][nType][1];
			rData.dblForce[j][iKind + 2] = rSbcf.dblForce[j][k][nType][2];
			rData.dblForce[j][iKind + 3] = rSbcf.dblForce[j][k][nType][3];
			rData.dblForce[j][iKind + 4] = rSbcf.dblForce[j][k][nType][4];
			rData.dblForce[j][iKind + 5] = rSbcf.dblForce[j][k][nType][5];
			rData.dblForce[j][Mbi_Id + k] = rSbcf.dblForce[j][k][nType][6]; // Bi-moment
			rData.dblForce[j][Mst_Id + k] = rSbcf.dblForce[j][k][nType][7]; // Pure torsion
			rData.dblForce[j][Mwp_Id + k] = rSbcf.dblForce[j][k][nType][8]; // Warping torsion
			// Stress.
			int iKind1 = (k == 0 ? 0 : 7);
			int iKind2 = (k == 0 ? 0 : 1);
			// 스트레스도 더해준다.
			//ASSERT(0);
			rData.dblStress[j][iKind1 + 0] = rSbcf.dblStress[j][k][nType][0];
			rData.dblStress[j][iKind1 + 1] = rSbcf.dblStress[j][k][nType][1];
			rData.dblStress[j][iKind1 + 2] = rSbcf.dblStress[j][k][nType][2];
			rData.dblStress[j][iKind1 + 3] = rSbcf.dblStress[j][k][nType][3];
			rData.dblStress[j][iKind1 + 4] = rSbcf.dblStress[j][k][nType][4];
			rData.dblStress[j][iKind1 + 5] = rSbcf.dblStress[j][k][nType][5];
			rData.dblStress[j][iKind1 + 6] = rSbcf.dblStress[j][k][nType][6];

			rData.dblStress[j][iKind2 + 14] = rSbcf.dblStress[j][k][nType][7];
			rData.dblStress[j][iKind2 + 16] = rSbcf.dblStress[j][k][nType][8];
			rData.dblStress[j][iKind2 + 18] = rSbcf.dblStress[j][k][nType][9];
			rData.dblStress[j][iKind2 + 20] = rSbcf.dblStress[j][k][nType][10];
			rData.dblStress[j][iKind2 + 22] = rSbcf.dblStress[j][k][nType][11];

			// Index는 T_STRB_D, T_SBCF_D  참고 
			int nKind3 = (k == 0) ? 24 : 44;
			int nSbcfStressSta = 12;
			for (int l = 0; l < 20; ++l) rData.dblStress[j][nKind3 + l] = rSbcf.dblStress[j][k][nType][nSbcfStressSta + l];

			int nKind4 = (k == 0) ? 64 : 72;
			int nSbcfStressSta2 = 32;
			for (int l = 0; l < 8; ++l)  rData.dblStress[j][nKind4 + l] = rSbcf.dblStress[j][k][nType][nSbcfStressSta2 + l];
		}
	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_StrbToForce(T_STRB_D &Strb, _DGN_FORC_CRC &rData)
{
	for (int i = 0; i < cPOSI_CRC; ++i)
	{
		int iPart = (i == 0 ? 0 : 3);
		int iPart2 = (i == 0 ? 0 : 4);
		int iKind = (i == 0 ? 0 : 6);
		rData.dFxx[i] = Strb.dblForce[iPart][iKind + 0];
		rData.dFyy[i] = Strb.dblForce[iPart][iKind + 1];
		rData.dFzz[i] = Strb.dblForce[iPart][iKind + 2];
		rData.dMux[i] = Strb.dblForce[iPart][iKind + 3];
		rData.dMuy[i] = Strb.dblForce[iPart][iKind + 4];
		rData.dMuz[i] = Strb.dblForce[iPart][iKind + 5];
		rData.dMbi[i] = Strb.dblForce[iPart][Mbi_Id + i]; // Bi-moment
		rData.dTst[i] = Strb.dblForce[iPart][Mst_Id + i]; // Pure torsion
		rData.dTwp[i] = Strb.dblForce[iPart][Mwp_Id + i]; // Warping torsion
	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_SbcfToForce(BOOL bMax, int nIdx, T_SBCF_D &SbcfMax, T_SBCF_D &SbcfMin, _DGN_FORC_CRC &rData)
{
	T_SBCF_D &SbcfD = (bMax) ? SbcfMax : SbcfMin;
	for (int j = 0; j < cPOSI_CRC; ++j)
	{
		int iPart = (j == 0 ? 0 : 3);
		int nForId = nIdx / 2;

		rData.dFxx[j] = SbcfD.dblForce[iPart][j][nForId][0];
		rData.dFyy[j] = SbcfD.dblForce[iPart][j][nForId][1];
		rData.dFzz[j] = SbcfD.dblForce[iPart][j][nForId][2];
		rData.dMux[j] = SbcfD.dblForce[iPart][j][nForId][3];
		rData.dMuy[j] = SbcfD.dblForce[iPart][j][nForId][4];
		rData.dMuz[j] = SbcfD.dblForce[iPart][j][nForId][5];
		rData.dMbi[j] = SbcfD.dblForce[iPart][j][nForId][6]; // Bi-moment
		rData.dTst[j] = SbcfD.dblForce[iPart][j][nForId][7]; // Pure torsion
		rData.dTwp[j] = SbcfD.dblForce[iPart][j][nForId][8]; // Warping torsion
	}
	return TRUE;
}

BOOL CCRCForceCtrl::Get_ScfpToDgnScfp(const T_SCFP_D &Scfp, _DGN_SCFP_D &rData)
{
	for (int i = 0; i < cPOSI_CRC; ++i)
	{
		int nPart = (i == 0) ? 0 : 4;
		// Force
		for (int j = 0; j < 3; ++j)
		{
			rData.dbForce[i][j] = Scfp.dbForce[nPart][j];
		}
		for (int j = 0; j < 10; ++j)
		{
			rData.dbStress[i][j] = Scfp.dbStress[nPart][j];
		}
		for (int j = 0; j < 19; ++j)
		{
			rData.dbLStress[i][j] = Scfp.dbLStress[nPart][j];
		}
	}
	return TRUE;
}

BOOL CCRCForceCtrl::ConvertDgnScfpToScfp(const _DGN_SCFP_D& Scfp, T_SCFP_D& rData)
{
	for ( int i = 0; i < cPOSI_CRC; ++i )
	{
		int nPart = (i == 0) ? 0 : 4;
		// Force
		for ( int j = 0; j < 3; ++j )
		{
			rData.dbForce[nPart][j] = Scfp.dbForce[i][j];
		}
		for ( int j = 0; j < 10; ++j )
		{
			rData.dbStress[nPart][j] = Scfp.dbStress[i][j];
		}
		for ( int j = 0; j < 19; ++j )
		{
			rData.dbLStress[nPart][j] = Scfp.dbLStress[i][j];
		}
	}
	return TRUE;
}

BOOL CCRCForceCtrl::ConvertDgnForceToPSCForce(int nIdx, const _DGN_FORC_CRC &DgnForD, T_PSCD_FORCE& ForD)
{
	if ( nIdx < 0 || nIdx>1 ) return FALSE;
	ForD.dForce[0] = DgnForD.dFxx[nIdx];
	ForD.dForce[1] = DgnForD.dFyy[nIdx];
	ForD.dForce[2] = DgnForD.dFzz[nIdx];
	ForD.dForce[3] = DgnForD.dMux[nIdx];
	ForD.dForce[4] = DgnForD.dMuy[nIdx];
	ForD.dForce[5] = DgnForD.dMuz[nIdx];

	return TRUE;
}

BOOL CCRCForceCtrl::ConvertDgnPSCForceToDgnForce(int nIdx, const T_PSCD_FORCE& ForD, _DGN_FORC_CRC& rData)
{
	if ( nIdx < 0 || nIdx>1 ) return FALSE;
	rData.dFxx[nIdx] = ForD.dForce[0];
	rData.dFyy[nIdx] = ForD.dForce[1];
	rData.dFzz[nIdx] = ForD.dForce[2];
	rData.dMux[nIdx] = ForD.dForce[3];
	rData.dMuy[nIdx] = ForD.dForce[4];
	rData.dMuz[nIdx] = ForD.dForce[5];
	return TRUE;
}

BOOL CCRCForceCtrl::Get_StrbToForce_EX(T_STRB_D &Strb, _DGN_FORC_CRC_EX &rData)
{
	for (int i = 0; i < cPOSI_CRC_EX; ++i)
	{
		int iPart = (i < (cPOSI_CRC_EX - 1) ? i : 3);
		int iKind = (i < (cPOSI_CRC_EX - 1) ? 0 : 6);
		int nMbIJ = (iKind == 0) ? 0 : 1;
		rData.dFxx[i] = Strb.dblForce[iPart][iKind + 0];
		rData.dFyy[i] = Strb.dblForce[iPart][iKind + 1];
		rData.dFzz[i] = Strb.dblForce[iPart][iKind + 2];
		rData.dMux[i] = Strb.dblForce[iPart][iKind + 3];
		rData.dMuy[i] = Strb.dblForce[iPart][iKind + 4];
		rData.dMuz[i] = Strb.dblForce[iPart][iKind + 5];
		rData.dMbi[i] = Strb.dblForce[iPart][Mbi_Id + nMbIJ]; // Bi-moment
		rData.dTst[i] = Strb.dblForce[iPart][Mst_Id + nMbIJ]; // Pure torsion
		rData.dTwp[i] = Strb.dblForce[iPart][Mwp_Id + nMbIJ]; // Warping torsion
	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_SbcfToForce_EX(BOOL bMax, int nIdx, T_SBCF_D &SbcfMax, T_SBCF_D &SbcfMin, _DGN_FORC_CRC_EX &rData)
{
	T_SBCF_D &SbcfD = (bMax) ? SbcfMax : SbcfMin;
	for (int j = 0; j < cPOSI_CRC_EX; ++j)
	{
		int iPart = (j < cPOSI_CRC_EX - 1) ? j : j - 1;
		int nIJ = (j < cPOSI_CRC_EX - 1) ? 0 : 1;
		int nForId = nIdx / 2;

		rData.dFxx[j] = SbcfD.dblForce[iPart][nIJ][nForId][0];
		rData.dFyy[j] = SbcfD.dblForce[iPart][nIJ][nForId][1];
		rData.dFzz[j] = SbcfD.dblForce[iPart][nIJ][nForId][2];
		rData.dMux[j] = SbcfD.dblForce[iPart][nIJ][nForId][3];
		rData.dMuy[j] = SbcfD.dblForce[iPart][nIJ][nForId][4];
		rData.dMuz[j] = SbcfD.dblForce[iPart][nIJ][nForId][5];
		rData.dMbi[j] = SbcfD.dblForce[iPart][nIJ][nForId][6]; // Bi-moment
		rData.dTst[j] = SbcfD.dblForce[iPart][nIJ][nForId][7]; // Pure torsion
		rData.dTwp[j] = SbcfD.dblForce[iPart][nIJ][nForId][8]; // Warping torsion
	}
	return TRUE;
}

BOOL CCRCForceCtrl::Get_ScfpToDgnScfp_EX(T_SCFP_D &Scfp, _DGN_SCFP_EX_D &rData)
{
	for (int i = 0; i < cPOSI_CRC_EX; ++i)
	{
		int nPart = (i < cPOSI_CRC_EX - 1) ? i : i - 1;
		// Force
		for (int j = 0; j < 3; ++j)
		{
			rData.dbForce[i][j] = Scfp.dbForce[nPart][j];
		}
		for (int j = 0; j < 10; ++j)
		{
			rData.dbStress[i][j] = Scfp.dbStress[nPart][j];
		}
		for (int j = 0; j < 19; ++j)
		{
			rData.dbLStress[i][j] = Scfp.dbLStress[nPart][j];
		}
	}
	return TRUE;
}


// [18/12/2006 : maxiao] For CIVIL(CH) 2006
void CCRCForceCtrl::Set_LcomForColumnElem(ArrElemPairKey& arElemK) {
	int iTotalElement = arElemK.GetSize();
	m_SerialElemKey.clear();
	if (m_arStldK.GetCount() > 0) m_arStldElem.SetSize(iTotalElement);
	if (m_arSplcK.GetCount() > 0) m_arSplcElem.SetSize(iTotalElement);
	if (m_arEspcK.GetCount() > 0) m_arEspcElem.SetSize(iTotalElement);
	if (m_arThisK.GetCount() > 0) m_arThisElem.SetSize(iTotalElement);
	if (m_arSgldK.GetCount() > 0) m_arSgldElem.SetSize(iTotalElement);
	if (m_arStepK.GetCount() > 0) m_arStepElem.SetSize(iTotalElement);
	if (m_arMvldK.GetCount() > 0) m_arMvldElem.SetSize(iTotalElement);
	if (m_arSmlcK.GetCount() > 0) m_arSmlcElem.SetSize(iTotalElement);
	if (m_arMapGilcStrbK.GetCount() > 0) m_arGilcStrbElem.SetSize(iTotalElement);
	if (m_arMapGilcSbcfK.GetCount() > 0) m_arGilcSbcfElem.SetSize(iTotalElement);

	for (UINT iSerial = 0; iSerial < arElemK.GetSize(); iSerial++)
	{
		ElemPairK EPairK = arElemK.GetAt(iSerial);
		T_ELEM_K ElemK = EPairK.first;
		m_SerialElemKey.insert({ EPairK, iSerial });
		//////////////////////////////////////////////////////////////////////////
		int i;
		BOOL bImportForce = (m_bImportForce ? TRUE : FALSE);
		T_LCOM_D LcasD;
		T_STRB_D StrbMax, StrbMin, StrbAbs;
		//  T_STSS_D StssMax, StssMin, StssAbs;
		T_BTSS_D BtssMax, BtssMin;

		// Get Forces.
		// Static.
		if (m_arStldK.GetCount() > 0)
		{
			T_STLD_K StldK, StldGetK;
			UINT iSerStldK = 0;
			STLD_STRB_STSS StldStrbStss; StldStrbStss.Initialize();
			for (i = 0; i < 2; ++i)
			{
				StldStrbStss.arStldStrb[i].SetSize(m_arStldK.GetCount());
				StldStrbStss.arStldStss[i].SetSize(m_arStldK.GetCount());
				StldStrbStss.arStldBtss[i].SetSize(m_arStldK.GetCount());
			}
			POSITION PosStld = m_arStldK.GetStartPosition();
			while (PosStld)
			{
				m_arStldK.GetNextAssoc(PosStld, StldK, StldGetK);
				m_pPostCtrl->MakeLoadComb(D_LOADCASE_STATIC, StldGetK, LcasD);
				m_pPostCtrl->SelectLoadCombNew(LcasD);
				// 배열에 저장된 위치를 알기 위해.
				m_arMapStldK.Lookup(StldGetK, iSerStldK);
				if (bImportForce && m_pPostCtrl->GetAnalysisResult()->GetStldDesignForceData(StldGetK, ElemK, StrbMax, StrbMin))
				{
					// Normal
					m_pSectInfo->Cal_StrsStrbCurrent(ElemK, &StrbMax, &StrbMin);
				}
				else
				{
					// Normal
					m_pPostCtrl->GetStrbNew(EPairK.first, &StrbMax, &StrbMin, &StrbAbs, FALSE, NULL, EPairK.second);
				}
				// Normal
				StldStrbStss.arStldStrb[0].SetAt(iSerStldK, StrbMax);
				StldStrbStss.arStldStrb[1].SetAt(iSerStldK, StrbMin);
				// Btss
				StldStrbStss.arStldBtss[0].SetAt(iSerStldK, BtssMax);
				StldStrbStss.arStldBtss[1].SetAt(iSerStldK, BtssMin);
			}
			m_arStldElem.SetAt(iSerial, StldStrbStss);
		}

		// Spectrum.
		if (m_arSplcK.GetCount() > 0)
		{
			T_SPLC_K SplcK, SplcGetK;
			UINT iSerSplcK = 0;
			SPLC_STRB_STSS SplcStrbStss; SplcStrbStss.Initialize();
			for (i = 0; i < 2; ++i)
			{
				SplcStrbStss.arSplcStrb[i].SetSize(m_arSplcK.GetCount());
				SplcStrbStss.arSplcStss[i].SetSize(m_arSplcK.GetCount());
			}
			POSITION PosSplc = m_arSplcK.GetStartPosition();
			while (PosSplc)
			{
				m_arSplcK.GetNextAssoc(PosSplc, SplcK, SplcGetK);
				if (!m_pPostCtrl->MakeLoadComb(D_LOADCASE_SPECTRUM, SplcGetK, LcasD))	continue;
				m_pPostCtrl->SelectLoadCombNew(LcasD);
				// 배열에 저장된 위치를 알기 위해.
				m_arMapSplcK.Lookup(SplcGetK, iSerSplcK);
				// Import Data.
				if (bImportForce && m_pPostCtrl->GetAnalysisResult()->GetSplcDesignForceData(SplcGetK, ElemK, StrbMax, StrbMin))
				{
					// Normal.
					m_pSectInfo->Cal_StrsStrbCurrent(ElemK, &StrbMax, &StrbMin);
				}
				else
				{
					// Normal.
					m_pPostCtrl->GetStrbNew(EPairK.first, &StrbMax, &StrbMin, &StrbAbs, FALSE, NULL, EPairK.second);
				}
				// Normal
				SplcStrbStss.arSplcStrb[0].SetAt(iSerSplcK, StrbMax);
				SplcStrbStss.arSplcStrb[1].SetAt(iSerSplcK, StrbMin);
			}
			m_arSplcElem.SetAt(iSerial, SplcStrbStss);
		}

		// Eccentric Response Spectrum.
		if (m_arEspcK.GetCount() > 0)
		{
			T_ESPC_K EspcK, EspcGetK;
			UINT iSerEspcK = 0;
			ESPC_STRB_STSS EspcStrbStss; EspcStrbStss.Initialize();
			for (i = 0; i < 2; ++i)
			{
				EspcStrbStss.arEspcStrb[i].SetSize(m_arEspcK.GetCount());
				EspcStrbStss.arEspcStss[i].SetSize(m_arEspcK.GetCount());
			}
			POSITION PosEspc = m_arEspcK.GetStartPosition();
			while (PosEspc)
			{
				m_arEspcK.GetNextAssoc(PosEspc, EspcK, EspcGetK);
				if (!m_pPostCtrl->MakeLoadComb(D_LOADCASE_ECCENSPEC, EspcGetK, LcasD))	continue;
				m_pPostCtrl->SelectLoadCombNew(LcasD);
				// 배열에 저장된 위치를 알기 위해.
				m_arMapEspcK.Lookup(EspcGetK, iSerEspcK);
				// Import Data.
				if (bImportForce && m_pPostCtrl->GetAnalysisResult()->GetEspcDesignForceData(EspcGetK, ElemK, StrbMax, StrbMin))
				{
					// Normal.
					m_pSectInfo->Cal_StrsStrbCurrent(ElemK, &StrbMax, &StrbMin);
				}
				else
				{
					// Normal.
					m_pPostCtrl->GetStrbNew(EPairK.first, &StrbMax, &StrbMin, &StrbAbs, FALSE, NULL, EPairK.second);
				}
				// Normal
				EspcStrbStss.arEspcStrb[0].SetAt(iSerEspcK, StrbMax);
				EspcStrbStss.arEspcStrb[1].SetAt(iSerEspcK, StrbMin);
			}
			m_arEspcElem.SetAt(iSerial, EspcStrbStss);
		}

		// Time History.
		if (m_arThisK.GetCount() > 0)
		{
			T_THIS_K ThisK, ThisGetK;
			UINT iSerThisK = 0;
			THIS_STRB_STSS ThisStrbStss; ThisStrbStss.Initialize();
			for (i = 0; i < 2; ++i)
			{
				ThisStrbStss.arThisStrb[i].SetSize(m_arThisK.GetCount());
				ThisStrbStss.arThisStss[i].SetSize(m_arThisK.GetCount());
			}
			POSITION PosThis = m_arThisK.GetStartPosition();
			while (PosThis)
			{
				m_arThisK.GetNextAssoc(PosThis, ThisK, ThisGetK);
				if (!m_pPostCtrl->MakeLoadComb(D_LOADCASE_HISTORY, ThisGetK, LcasD))	continue;
				m_pPostCtrl->SelectLoadCombNew(LcasD);
				// 배열에 저장된 위치를 알기 위해.
				m_arMapThisK.Lookup(ThisGetK, iSerThisK);
				if (bImportForce && m_pPostCtrl->GetAnalysisResult()->GetThisDesignForceData(ThisGetK, ElemK, StrbMax, StrbMin))
				{
					// Normal.
					m_pSectInfo->Cal_StrsStrbCurrent(ElemK, &StrbMax, &StrbMin);
				}
				else
				{
					// Normal.
					m_pPostCtrl->GetStrbNew(EPairK.first, &StrbMax, &StrbMin, &StrbAbs, FALSE, NULL, EPairK.second);
				}
				// Normal
				ThisStrbStss.arThisStrb[0].SetAt(iSerThisK, StrbMax);
				ThisStrbStss.arThisStrb[1].SetAt(iSerThisK, StrbMin);
			}
			m_arThisElem.SetAt(iSerial, ThisStrbStss);
		}

		// Concurrent Forces.
		T_SBCF_D SbcfMax, SbcfMin, SbcfAbs;
		// Moving.
		if (m_arMvldK.GetCount() > 0)
		{
			T_MVLD_K MvldK, MvldGetK;
			UINT iSerMvldK = 0;
			MVLD_SBCF MvldSbcf; MvldSbcf.Initialize();
			for (i = 0; i < 2; ++i)
			{
				MvldSbcf.arMvldSbcf[i].SetSize(m_arMvldK.GetCount());
			}
			POSITION PosMvld = m_arMvldK.GetStartPosition();
			while (PosMvld)
			{
				m_arMvldK.GetNextAssoc(PosMvld, MvldK, MvldGetK);
				if (!m_pPostCtrl->MakeLoadComb(D_LOADCASE_MOVING, MvldGetK, LcasD))	continue;
				m_pPostCtrl->SelectLoadCombNew(LcasD);
				// 배열에 저장된 위치를 알기 위해.
				m_arMapMvldK.Lookup(MvldGetK, iSerMvldK);
				if (bImportForce && m_pPostCtrl->GetAnalysisResult()->GetMvldDesignForceData(MvldGetK, ElemK, SbcfMax, SbcfMin))
				{
					// Normal.
					m_pSectInfo->Cal_StrsSbcfCurrent(ElemK, &SbcfMax, &SbcfMin);
				}
				else
				{
					// Normal.
					m_pPostCtrl->GetSbcfNew(ElemK, &SbcfMax, &SbcfMin, &SbcfAbs, FALSE);
				}
				// Normal
				MvldSbcf.arMvldSbcf[0].SetAt(iSerMvldK, SbcfMax);
				MvldSbcf.arMvldSbcf[1].SetAt(iSerMvldK, SbcfMin);
			}
			m_arMvldElem.SetAt(iSerial, MvldSbcf);
		}

		// Settlement.
		if (m_arSmlcK.GetCount() > 0)
		{
			T_SMLC_K SmlcK, SmlcGetK;
			UINT iSerSmlcK = 0;
			SMLC_SBCF SmlcSbcf; SmlcSbcf.Initialize();
			for (i = 0; i < 2; ++i)
			{
				SmlcSbcf.arSmlcSbcf[i].SetSize(m_arSmlcK.GetCount());
			}
			POSITION PosSmlc = m_arSmlcK.GetStartPosition();
			while (PosSmlc)
			{
				m_arSmlcK.GetNextAssoc(PosSmlc, SmlcK, SmlcGetK);
				if (!m_pPostCtrl->MakeLoadComb(D_LOADCASE_SETTLE, SmlcGetK, LcasD))	continue;
				m_pPostCtrl->SelectLoadCombNew(LcasD);
				// 배열에 저장된 위치를 알기 위해.
				m_arMapSmlcK.Lookup(SmlcGetK, iSerSmlcK);
				if (bImportForce && m_pPostCtrl->GetAnalysisResult()->GetSmlcDesignForceData(SmlcGetK, ElemK, SbcfMax, SbcfMin))
				{
					// Normal.
					m_pSectInfo->Cal_StrsSbcfCurrent(ElemK, &SbcfMax, &SbcfMin);
				}
				else
				{
					// Normal.
					m_pPostCtrl->GetSbcfNew(ElemK, &SbcfMax, &SbcfMin, &SbcfAbs, FALSE);
				}
				// Normal
				SmlcSbcf.arSmlcSbcf[0].SetAt(iSerSmlcK, SbcfMax);
				SmlcSbcf.arSmlcSbcf[1].SetAt(iSerSmlcK, SbcfMin);
			}
			m_arSmlcElem.SetAt(iSerial, SmlcSbcf);
		}

		// Stage.
		if (m_arSgldK.GetCount() > 0)
		{
			T_SGLD_K SgldK, SgldGetK;
			UINT iSerSgldK = 0;
			SGLD_STRB_STSS SgldStrbStss; SgldStrbStss.Initialize();
			for (i = 0; i < 2; ++i)
			{
				SgldStrbStss.arSgldStrb[i].SetSize(m_arSgldK.GetCount());
				SgldStrbStss.arSgldStss[i].SetSize(m_arSgldK.GetCount());
			}
			POSITION PosSgld = m_arSgldK.GetStartPosition();
			while (PosSgld)
			{
				m_arSgldK.GetNextAssoc(PosSgld, SgldK, SgldGetK);
				m_pPostCtrl->MakeLoadComb(D_LOADCASE_STAGE, SgldGetK, LcasD);
				m_pPostCtrl->SelectLoadCombNew(LcasD);
				// 배열에 저장된 위치를 알기 위해.
				m_arMapSgldK.Lookup(SgldGetK, iSerSgldK);
				m_pPostCtrl->GetStrbNew(EPairK.first, &StrbMax, &StrbMin, &StrbAbs, FALSE, NULL, EPairK.second);
				SgldStrbStss.arSgldStrb[0].SetAt(iSerSgldK, StrbMax);
				SgldStrbStss.arSgldStrb[1].SetAt(iSerSgldK, StrbMin);
			}
			m_arSgldElem.SetAt(iSerial, SgldStrbStss);
		}

		// Grid Model - Strb
		T_GILC_K GilcGetK;
		UINT iSerGilcK = 0;
		if (m_arMapGilcStrbK.GetCount() > 0)
		{
			GILC_STRB_STSS GilcStrbStss; GilcStrbStss.Initialize();
			for (i = 0; i < 2; ++i)
			{
				GilcStrbStss.arGilcStrb[i].SetSize(m_arMapGilcStrbK.GetCount());
				GilcStrbStss.arGilcStss[i].SetSize(m_arMapGilcStrbK.GetCount());
			}
			POSITION PosGilcStrb = m_arMapGilcStrbK.GetStartPosition();
			while (PosGilcStrb)
			{
				m_arMapGilcStrbK.GetNextAssoc(PosGilcStrb, GilcGetK, iSerGilcK); // GilcK로 바로 iSerGilcK를 받음.
				m_pPostCtrl->MakeLoadComb(D_LOADCASE_GRIDMODEL, GilcGetK, LcasD);
				m_pPostCtrl->SelectLoadCombNew(LcasD);
				if (bImportForce && m_pPostCtrl->GetAnalysisResult()->GetGridDesignForceData(GilcGetK, ElemK, StrbMax, StrbMin))
				{
					// Normal.
					m_pSectInfo->Cal_StrsStrbCurrent(ElemK, &StrbMax, &StrbMin);
				}
				else
				{
					// Normal.
					m_pPostCtrl->GetStrbNew(EPairK.first, &StrbMax, &StrbMin, &StrbAbs, FALSE, NULL, EPairK.second);
				}
				// Normal
				GilcStrbStss.arGilcStrb[0].SetAt(iSerGilcK, StrbMax);
				GilcStrbStss.arGilcStrb[1].SetAt(iSerGilcK, StrbMin);
			}
			m_arGilcStrbElem.SetAt(iSerial, GilcStrbStss);
		}

		// Grid Model - Sbcf
		if (m_arMapGilcSbcfK.GetCount() > 0)
		{
			GILC_SBCF GilcSbcf; GilcSbcf.Initialize();
			for (i = 0; i < 2; ++i)
			{
				GilcSbcf.arGilcSbcf[i].SetSize(m_arMapGilcSbcfK.GetCount());
			}
			POSITION PosGilcSbcf = m_arMapGilcSbcfK.GetStartPosition();
			while (PosGilcSbcf)
			{
				m_arMapGilcSbcfK.GetNextAssoc(PosGilcSbcf, GilcGetK, iSerGilcK); // GilcK로 바로 iSerGilcK를 받음.
				m_pPostCtrl->MakeLoadComb(D_LOADCASE_GRIDMODEL, GilcGetK, LcasD);
				m_pPostCtrl->SelectLoadCombNew(LcasD);
				if (bImportForce && m_pPostCtrl->GetAnalysisResult()->GetGilcDesignForceData(GilcGetK, ElemK, SbcfMax, SbcfMin))
				{
					// Normal.
					if (!m_pSectInfo->Cal_StrsSbcfCurrent(ElemK, &SbcfMax, &SbcfMin)) continue;
				}
				else
				{
					// Normal.
					if (!m_pPostCtrl->GetSbcfNew(ElemK, &SbcfMax, &SbcfMin, &SbcfAbs, FALSE))	continue;
				}
				// Normal
				GilcSbcf.arGilcSbcf[0].SetAt(iSerGilcK, SbcfMax);
				GilcSbcf.arGilcSbcf[1].SetAt(iSerGilcK, SbcfMin);
			}
			m_arGilcSbcfElem.SetAt(iSerial, GilcSbcf);
		}

		// Step in Stage.
		if (m_arStepK.GetCount() > 0)
		{
			T_SGLD_K SgldSumK;
			T_STEP_K StepK, StepGetK;
			CString strSgldSUM = _LS(IDS_DB_SGLD_SUM);	// SUM.
			SgldSumK = m_pAttrCtrl->GetSgldKey(strSgldSUM);
			UINT iSerStepK = 0;
			STEP_STRB_STSS StepStrbStss; StepStrbStss.Initialize();
			for (i = 0; i < 2; ++i)
			{
				StepStrbStss.arStepStrb[i].SetSize(m_arStepK.GetCount());
				StepStrbStss.arStepStss[i].SetSize(m_arStepK.GetCount());
			}
			POSITION PosStep = m_arStepK.GetStartPosition();
			while (PosStep)
			{
				m_arStepK.GetNextAssoc(PosStep, StepK, StepGetK);
				m_pPostCtrl->MakeLoadComb(D_LOADCASE_STAGE, SgldSumK, LcasD);
				m_pPostCtrl->SelectLoadCombNew(LcasD, StepK, 2);	// 0=Nonlinear, 1=Pushover, 2=Construction.	  
				// 배열에 저장된 위치를 알기 위해.
				m_arMapStepK.Lookup(StepGetK, iSerStepK);
				m_pPostCtrl->GetStrbNew(EPairK.first, &StrbMax, &StrbMin, &StrbAbs, FALSE, NULL, EPairK.second);
				StepStrbStss.arStepStrb[0].SetAt(iSerStepK, StrbMax);
				StepStrbStss.arStepStrb[1].SetAt(iSerStepK, StrbMin);
			}
			m_arStepElem.SetAt(iSerial, StepStrbStss);
		}

		//////////////////////////////////////////////////////////////////////////    
	}
}



// 
BOOL CCRCForceCtrl::GetStldForElem(ElemPairK ElemK, int nForType, int iLcaseType, unsigned LcaseK, T_STRB_D& StrbMax, T_STSS_D& StssMax, T_BTSS_D& BtssMax, T_STRB_D &StrbP1, T_STRB_D &StrbP2)
{
	if (iLcaseType != D_LOADCASE_STATIC) return FALSE;

	T_STLD_LCASE StldLcase;
	StldLcase.Initialize();
	m_pDgnForceResult->GetLcaseForceStld(ElemK, LcaseK, StldLcase);

	// Strb
	StrbMax = StldLcase.StldStrb[0];
	//StrbMin = StldLcase.StldStrb[1];
	// Stss
	StssMax = StldLcase.StldStss[0];
	//StssMin = StldLcase.StldStss[1];
	// Btss
	BtssMax = StldLcase.StldBtss[0];
	//BtssMin = StldLcase.StldBtss[1]; 

	if (nForType > 0)
	{
		StrbP1 = StldLcase.StldStrb[2]; // girder
		StrbP2 = StldLcase.StldStrb[4]; // slab  
	}

	return TRUE;
}

BOOL CCRCForceCtrl::GetStrbForElem(ElemPairK ElemK, int nForType, int iLcaseType, unsigned LcaseK, T_STRB_D& StrbMax, T_STRB_D& StrbMin, T_STSS_D& StssMax, T_STSS_D& StssMin, T_STRB_D &StrbP1, T_STRB_D &StrbP2)
{
	T_STRB_LCASE StrbLcase;

	switch (iLcaseType)
	{
	case D_LOADCASE_SPECTRUM:
	{
		//
		m_pDgnForceResult->GetLcaseForceSplc(ElemK, LcaseK, StrbLcase);
		break;
	}
	case D_LOADCASE_ECCENSPEC:
	{
		//
		m_pDgnForceResult->GetLcaseForceEspc(ElemK, LcaseK, StrbLcase);
		break;
	}
	case D_LOADCASE_HISTORY:
	{
		//
		m_pDgnForceResult->GetLcaseForceThis(ElemK, LcaseK, StrbLcase);
		break;
	}
	case D_LOADCASE_STAGE:
	{
		//
		m_pDgnForceResult->GetLcaseForceSgld(ElemK, LcaseK, StrbLcase);
		break;
	}
	case D_LOADCASE_GRIDMODEL:
	{
		// Non-Max/Min type
		//
		m_pDgnForceResult->GetLcaseForceGilcStrb(ElemK, LcaseK, StrbLcase);
		break;
	}
	default:	ASSERT(0);
	}

	// Strb
	StrbMax = StrbLcase.StrbLcase[0];
	//StrbMin = StrbLcase.StrbLcase[1];
	// Stss
	StssMax = StrbLcase.StssLcase[0];
	//StssMin = StrbLcase.StssLcase[1];

	if (nForType > 0)
	{
		StrbP1 = StrbLcase.StrbLcase[2]; // girder
		StrbP2 = StrbLcase.StrbLcase[4]; // slab  
	}

	return TRUE;
}

BOOL CCRCForceCtrl::GetLcomForElem(ElemPairK ElemK, int nForType, int iLcaseType, unsigned LcaseK, T_STRB_D& StrbMax, T_STRB_D& StrbMin, T_STSS_D& StssMax, T_STSS_D& StssMin, T_STRB_D &StrbP1, T_STRB_D &StrbP2)  // Add by GAY. MNET:2903. ('07.07.31)
{
	if (CDBLib::IsCSGCode(m_iDgnCode) == TRUE)
	{
		if (m_iDgnCode == EUROCODE4_2_04_CSG || m_iDgnCode == IRC22_08_CSG || m_iDgnCode == IRC22_15_CSG)
		{
			if (iLcaseType != D_LOADCASE_COMB_STEEL) return FALSE;
		}
		else
		{
			if (iLcaseType != D_LOADCASE_COMB_STLCOMP) return FALSE;
		}
	}
	else
	{
		if (iLcaseType != D_LOADCASE_COMB_CONCRETE) return FALSE;
	}

	T_STRB_LCASE StrbLcase;
	StrbLcase.Initialize();
	//
	m_pDgnForceResult->GetLcaseForceLcomStrb(ElemK, LcaseK, StrbLcase);

	// Strb
	StrbMax = StrbLcase.StrbLcase[0];
	StrbMin = StrbLcase.StrbLcase[1];
	// Stss
	StssMax = StrbLcase.StssLcase[0];
	StssMin = StrbLcase.StssLcase[1];

	if (nForType > 0)
	{
		StrbP1 = StrbLcase.StrbLcase[2]; // girder
		StrbP2 = StrbLcase.StrbLcase[4]; // slab  
	}

	return TRUE;
}

BOOL CCRCForceCtrl::GetSbcfForElem(ElemPairK ElemK, int nForType, int iLcaseType, unsigned LcaseK, T_SBCF_D& SbcfMax, T_SBCF_D& SbcfMin,
	T_SBCF_D& SbcfMaxP1, T_SBCF_D& SbcfMinP1, T_SBCF_D& SbcfMaxP2, T_SBCF_D& SbcfMinP2)
{
	SbcfMax.Initialize();
	SbcfMin.Initialize();

	T_SBCF_LCASE SbcfLC;

	switch (iLcaseType)
	{
	case D_LOADCASE_MOVING:
	{
		//
		m_pDgnForceResult->GetLcaseForceMvld(ElemK, LcaseK, SbcfLC);
		break;
	}
	case D_LOADCASE_SETTLE:
	{
		//
		m_pDgnForceResult->GetLcaseForceSmlc(ElemK, LcaseK, SbcfLC);
		break;
	}
	case D_LOADCASE_GRIDMODEL:
	{
		//
		m_pDgnForceResult->GetLcaseForceGilcSbcf(ElemK, LcaseK, SbcfLC);
		break;
	}
	// Add by GAY. MNET:2903. ('07.08.24). Consider Load Combination Type (for Concurrent Forces).
	case D_LOADCASE_COMB_STEEL:
	case D_LOADCASE_COMB_CONCRETE:
	case D_LOADCASE_COMB_STLCOMP:
	{
		//
		m_pDgnForceResult->GetLcaseForceLcomSbcf(ElemK, LcaseK, SbcfLC);
		break;
	}
	default:	ASSERT(0);
	}

	// Sbcf
	SbcfMax = SbcfLC.SbcfLcase[0];
	SbcfMin = SbcfLC.SbcfLcase[1];

	if (nForType > 0)
	{
		// Sbcf
		SbcfMaxP1 = SbcfLC.SbcfLcase[2];
		SbcfMinP1 = SbcfLC.SbcfLcase[3];
		SbcfMaxP2 = SbcfLC.SbcfLcase[4];
		SbcfMinP2 = SbcfLC.SbcfLcase[5];
	}

	return TRUE;
}

BOOL CCRCForceCtrl::GetStld4Elem(ElemPairK ElemK, int nForType, int nLcaseType, unsigned LcaseK, _DGN_STRBFORC_LCASE &Strb, _DGN_STRBFORC_PART_LCASE &StrbPart)
{
	if (nLcaseType != D_LOADCASE_STATIC) return FALSE;

	m_pDgnForceResult->GetLoadCaseForceStld(ElemK, LcaseK, Strb);

	if (nForType > 0)
	{
		m_pDgnForceResult->GetPartLoadCaseForceStld(ElemK, LcaseK, StrbPart);
	}

	return TRUE;
}

BOOL CCRCForceCtrl::GetStrb4Elem(ElemPairK ElemK, int nForType, int nLcaseType, unsigned LcaseK, _DGN_STRBFORC_LCASE &Strb, _DGN_STRBFORC_PART_LCASE &StrbPart)
{
	switch (nLcaseType)
	{
	case D_LOADCASE_SPECTRUM:
	{
		//
		m_pDgnForceResult->GetLoadCaseForceSplc(ElemK, LcaseK, Strb);
		if (nForType > 0) m_pDgnForceResult->GetPartLoadCaseForceSplc(ElemK, LcaseK, StrbPart);
		break;
	}
	case D_LOADCASE_ECCENSPEC:
	{
		//
		m_pDgnForceResult->GetLoadCaseForceEspc(ElemK, LcaseK, Strb);
		if (nForType > 0) m_pDgnForceResult->GetPartLoadCaseForceEspc(ElemK, LcaseK, StrbPart);
		break;
	}
	case D_LOADCASE_HISTORY:
	{
		//
		m_pDgnForceResult->GetLoadCaseForceThis(ElemK, LcaseK, Strb);
		if (nForType > 0) m_pDgnForceResult->GetPartLoadCaseForceThis(ElemK, LcaseK, StrbPart);
		break;
	}
	case D_LOADCASE_STAGE:
	{
		//
		m_pDgnForceResult->GetLoadCaseForceSgld(ElemK, LcaseK, Strb);
		if (nForType > 0) m_pDgnForceResult->GetPartLoadCaseForceSgld(ElemK, LcaseK, StrbPart);
		break;
	}
	case D_LOADCASE_GRIDMODEL:
	{
		// Non-Max/Min type
		//
		m_pDgnForceResult->GetLoadCaseForceGilcStrb(ElemK, LcaseK, Strb);
		if (nForType > 0) m_pDgnForceResult->GetPartLoadCaseForceGilcStrb(ElemK, LcaseK, StrbPart);
		break;
	}
	default:	ASSERT(0);
	}

	return TRUE;
}

BOOL CCRCForceCtrl::GetLcom4Elem(ElemPairK ElemK, int nForType, int nLcaseType, unsigned LcaseK, int iMaxMinType, _DGN_STRBFORC_LCASE &Strb, _DGN_STRBFORC_PART_LCASE &StrbPart)
{
	if (CDBLib::IsCSGCode(m_iDgnCode) == TRUE)
	{
		if (m_iDgnCode == EUROCODE4_2_04_CSG || m_iDgnCode == IRC22_08_CSG || m_iDgnCode == IRC22_15_CSG)
		{
			if (nLcaseType != D_LOADCASE_COMB_STEEL) return FALSE;
		}
		else
		{
			if (nLcaseType != D_LOADCASE_COMB_STLCOMP) return FALSE;
		}
	}
	else
	{
		if (nLcaseType != D_LOADCASE_COMB_CONCRETE) return FALSE;
	}

	if (iMaxMinType == 0 || (iMaxMinType % 2 == 1))
	{
		m_pDgnForceResult->GetLoadCaseForceLcomStrb(ElemK, LcaseK, Strb);
		if (nForType > 0) m_pDgnForceResult->GetPartLoadCaseForceLcomStrb(ElemK, LcaseK, StrbPart);
	}
	else if (iMaxMinType % 2 == 0)
	{
		m_pDgnForceResult->GetLoadCaseForceLcomStrbMin(ElemK, LcaseK, Strb);
		if (nForType > 0) m_pDgnForceResult->GetPartLoadCaseForceLcomStrbMin(ElemK, LcaseK, StrbPart);
	}
	else ASSERT(0);

	return TRUE;
}

BOOL CCRCForceCtrl::GetSbcf4Elem(ElemPairK ElemK, int nForType, int nLcaseType, unsigned LcaseK, _DGN_SBCFFORC_LCASE &Sbcf, _DGN_SBCFFORC_PART_LCASE &SbcfPart, BOOL bSpc)
{
	switch (nLcaseType)
	{
	case D_LOADCASE_MOVING:
	{
		// Civil v891 US - BS Assessment - CS454 Special Moving Load Case (CIVIL-1069)
		if (!bSpc)
		{
			m_pDgnForceResult->GetLoadCaseForceMvld(ElemK, LcaseK, Sbcf);
			if (nForType > 0) m_pDgnForceResult->GetPartLoadCaseForceMvld(ElemK, LcaseK, SbcfPart);
		}
		else
		{
			m_pDgnForceResult->GetLoadCaseForceMvldBS(ElemK, LcaseK, Sbcf);
			if (nForType > 0) m_pDgnForceResult->GetPartLoadCaseForceMvldBS(ElemK, LcaseK, SbcfPart);
		}

		break;
	}
	case D_LOADCASE_SETTLE:
	{
		//
		m_pDgnForceResult->GetLoadCaseForceSmlc(ElemK, LcaseK, Sbcf);
		if (nForType > 0) m_pDgnForceResult->GetPartLoadCaseForceSmlc(ElemK, LcaseK, SbcfPart);
		break;
	}
	case D_LOADCASE_GRIDMODEL:
	{
		//
		m_pDgnForceResult->GetLoadCaseForceGilcSbcf(ElemK, LcaseK, Sbcf);
		if (nForType > 0) m_pDgnForceResult->GetPartLoadCaseForceGilcSbcf(ElemK, LcaseK, SbcfPart);
		break;
	}
	// Add by GAY. MNET:2903. ('07.08.24). Consider Load Combination Type (for Concurrent Forces).
	case D_LOADCASE_COMB_STEEL:
	case D_LOADCASE_COMB_CONCRETE:
	case D_LOADCASE_COMB_STLCOMP:
	{
		//
		m_pDgnForceResult->GetLoadCaseForceLcomSbcf(ElemK, LcaseK, Sbcf);
		if (nForType > 0) m_pDgnForceResult->GetPartLoadCaseForceLcomSbcf(ElemK, LcaseK, SbcfPart);
		break;
	}
	default:	ASSERT(0);
	}

	return TRUE;
}

