BOOL CCRCForceCtrl::GetLcom4Elem_EX(ElemPairK ElemK, int nForType, int nLcaseType, unsigned LcaseK, int iMaxMinType,
	_DGN_STRBFORC_LCASE_EX &Strb, _DGN_STRBFORC_PART_LCASE_EX &StrbPart)
{
	if (CDBLib::IsCSGCode(m_iDgnCode) == TRUE)
	{
		if (m_iDgnCode == EUROCODE4_2_04_CSG || m_iDgnCode == IRC22_08_CSG || m_iDgnCode == IRC22_15_CSG)
		{
			if (nLcaseType != D_LOADCASE_COMB_STEEL) return FALSE;
		}
		else
		{
			if (nLcaseType != D_LOADCASE_COMB_STLCOMP) return FALSE;
		}
	}
	else
	{
		if (nLcaseType != D_LOADCASE_COMB_CONCRETE) return FALSE;
	}

	if (iMaxMinType == 0 || (iMaxMinType % 2 == 1))
	{
		m_pDgnForceResult->GetLoadCaseForceLcomStrb_EX(ElemK, LcaseK, Strb);
		if (nForType > 0) m_pDgnForceResult->GetPartLoadCaseForceLcomStrb_EX(ElemK, LcaseK, StrbPart);
	}
	else if (iMaxMinType % 2 == 0)
	{
		m_pDgnForceResult->GetLoadCaseForceLcomStrbMin_EX(ElemK, LcaseK, Strb);
		if (nForType > 0) m_pDgnForceResult->GetPartLoadCaseForceLcomStrbMin_EX(ElemK, LcaseK, StrbPart);
	}
	else ASSERT(0);

	return TRUE;
}

BOOL CCRCForceCtrl::GetSbcf4Elem_EX(ElemPairK ElemK, int nForType, int nLcaseType, unsigned LcaseK,
	_DGN_SBCFFORC_LCASE_EX &Sbcf, _DGN_SBCFFORC_PART_LCASE_EX &SbcfPart, BOOL bSpc)
{
	switch (nLcaseType)
	{
	case D_LOADCASE_MOVING:
	{
		//
		// Civil v891 US - BS Assessment - CS454 Special Moving Load Case (CIVIL-1069)
		if (!bSpc)
		{
			m_pDgnForceResult->GetLoadCaseForceMvld_EX(ElemK, LcaseK, Sbcf);
			if (nForType > 0) m_pDgnForceResult->GetPartLoadCaseForceMvld_EX(ElemK, LcaseK, SbcfPart);
		}
		else
		{
			m_pDgnForceResult->GetLoadCaseForceMvldBS_EX(ElemK, LcaseK, Sbcf);
			if (nForType > 0) m_pDgnForceResult->GetPartLoadCaseForceMvldBS_EX(ElemK, LcaseK, SbcfPart);
		}
		break;
	}
	case D_LOADCASE_SETTLE:
	{
		//
		m_pDgnForceResult->GetLoadCaseForceSmlc_EX(ElemK, LcaseK, Sbcf);
		if (nForType > 0) m_pDgnForceResult->GetPartLoadCaseForceSmlc_EX(ElemK, LcaseK, SbcfPart);
		break;
	}
	case D_LOADCASE_GRIDMODEL:
	{
		//
		m_pDgnForceResult->GetLoadCaseForceGilcSbcf_EX(ElemK, LcaseK, Sbcf);
		if (nForType > 0) m_pDgnForceResult->GetPartLoadCaseForceGilcSbcf_EX(ElemK, LcaseK, SbcfPart);
		break;
	}
	// Add by GAY. MNET:2903. ('07.08.24). Consider Load Combination Type (for Concurrent Forces).
	case D_LOADCASE_COMB_STEEL:
	case D_LOADCASE_COMB_CONCRETE:
	case D_LOADCASE_COMB_STLCOMP:
	{
		//
		m_pDgnForceResult->GetLoadCaseForceLcomSbcf_EX(ElemK, LcaseK, Sbcf);
		if (nForType > 0) m_pDgnForceResult->GetPartLoadCaseForceLcomSbcf_EX(ElemK, LcaseK, SbcfPart);
		break;
	}
	default:	ASSERT(0);
	}

	return TRUE;
}


