void CCRCForceCtrl::Set_RatNoEffectZone(ElemPairK ElemK)
{
	m_dRatNoEffectZone[0] = 1.0;
	m_dRatNoEffectZone[1] = 1.0;
	T_SPSC_TNDN SpscTndnI; SpscTndnI.Initialize();
	T_SPSC_TNDN SpscTndnJ; SpscTndnJ.Initialize();
	if (CSectUtil::GetPscTndnGrup(m_pDoc->IsPostMode(), ElemK, 0, TRUE, SpscTndnI))	m_dRatNoEffectZone[0] = SpscTndnI.dRatioForStr;
	if (CSectUtil::GetPscTndnGrup(m_pDoc->IsPostMode(), ElemK, 0, FALSE, SpscTndnJ))	m_dRatNoEffectZone[1] = SpscTndnJ.dRatioForStr;
}

