	ADGNFORCE_EX aForceStag_EX;
	ADGNSHRSADD_EX aShrsStage_EX;
	ADGNFORCE_EX aForceTnpr_EX;
	ADGNFORCE_EX aForceTnsc_EX;
	ADGNSTRSADD_EX aStressAdd_EX;
	ADGNFORCE_EX aForceLTerm_EX;
	ADGNFORCE_EX aForceJtgTndn_EX;
