BOOL CCRCForceCtrl::Get_LcomDataForDesign_EX(ElemPairK ElemK, int nForType, BOOL bIncludeTP, BOOL bAlways3D,
	ADGNFORCE_EX& aForceLcom, int iLcomNum)
{
	if (iLcomNum <= 0)
	{
		_DGN_FORC_CRC_EX_ELEM ForceElem;
		ForceElem.Initialize();
		BOOL bGetOK = FALSE;
		if (bIncludeTP)
		{
			const auto& iter = m_arForcElemInTP_EX.find(ElemK);
			if (iter != m_arForcElemInTP_EX.end())
			{
				ForceElem = iter->second;
				bGetOK = TRUE;
			}
		}
		else
		{
			const auto& iter = m_arForcElemExTP_EX.find(ElemK);
			if (iter != m_arForcElemExTP_EX.end())
			{
				ForceElem = iter->second;
				bGetOK = TRUE;
			}
		}

		if (bGetOK)
		{
			aForceLcom.Copy(ForceElem.aForceLcom);
			return TRUE;
		}
		else
		{
			ADGNFORCE_EX aForceStag;
			ADGNSHRSADD_EX aShrsStage;
			ADGNFORCE_EX aForceTnpr;
			ADGNFORCE_EX aForceTnsc;
			ADGNSTRSADD_EX aStressAdd;
			ADGNFORCE_EX aForceLTerm;
			ADGNFORCE_EX aForceJtgTndn;
			ADGNSTRESS_EX aStressLcom;
			ADGNSTRESS_EX aStressTnpr;
			ADGNSTRESS_EX aStressTnsc;
			ADGNSTRESS_EX aStressLTerm;
			ADGNSHRSADD_EX aStssLcom;

			return Get_LcomDataForDesign_EX(ElemK, nForType, 0, bIncludeTP, bAlways3D, aForceLcom, aForceStag, aShrsStage,
				aForceTnpr, aForceTnsc, aStressAdd, aForceLTerm, aForceJtgTndn,
				aStressLcom, aStressTnpr, aStressTnsc, aStressLTerm, aStssLcom);
		}
	}
	else
	{
		aForceLcom.RemoveAll();
		aForceLcom.SetSize(iLcomNum);
		for (int i = 0; i < iLcomNum; ++i)
		{
			int iSerialLcom = i + 1;
			_DGN_FORC_CRC_EX ForceLcom;
			if (bIncludeTP)
			{
				if (nForType == 0)   m_pDgnForceResult->GetForceLcomResult_EX(ElemK, iSerialLcom, ForceLcom);
				else if (nForType == 1)   m_pDgnForceResult->GetForceLcomResult_Part1_EX(ElemK, iSerialLcom, ForceLcom);
				else if (nForType == 2)   m_pDgnForceResult->GetForceLcomResult_Part2_EX(ElemK, iSerialLcom, ForceLcom);
				else ASSERT(0);
			}
			else
				m_pDgnForceResult->GetForceLcomExTpResult_EX(ElemK, iSerialLcom, ForceLcom);
			//
			aForceLcom.SetAt(i, ForceLcom);
		}
		return TRUE;
	}
}

