BOOL CCRCForceCtrl::Get_LcomDataForStress(ElemPairK ElemK, BOOL bIncludeTP, BOOL bAlways3D, ADGNSTRESS& aStressLcom, ADGNSTRSADD& aStressAdd, ADGNSTRESS& aStressLTerm, ADGNSTRESS& aStressSTerm, int iLcomNum)
{
	if (iLcomNum <= 0)
	{
		// Lcom Forces.
		if (bIncludeTP)
		{
			const auto& iter = m_arStressElemInTP.find(ElemK);
			if (iter != m_arStressElemInTP.end())
			{
				aStressLcom.Copy(iter->second.aStressLcom);
			}
		}
		else
		{
			const auto& iter = m_arStressElemExTP.find(ElemK);
			if (iter != m_arStressElemExTP.end())
			{
				aStressLcom.Copy(iter->second.aStressLcom);
			}
		}
		// Add by ZINU.('04.01.04). Stress for Beam Section Temperature.
		const auto& itAdd = m_arStrsAddData.find(ElemK);
		if (itAdd != m_arStrsAddData.end())
		{
			aStressAdd.Copy(itAdd->second.aStressAdd);
		}
		//
		if (bIncludeTP)
		{
			const auto& iter = m_arStressElemLTerm.find(ElemK);
			if (iter != m_arStressElemLTerm.end())
			{
				aStressLTerm.Copy(iter->second.aStressLcom);
			}
		}
		else
		{
			const auto& iter = m_arStressElemLTermExTP.find(ElemK);
			if (iter != m_arStressElemLTermExTP.end())
			{
				aStressLTerm.Copy(iter->second.aStressLcom);
			}
		}

		if (aStressLcom.GetSize() > 0 && aStressAdd.GetSize() > 0 && aStressLTerm.GetSize() > 0)	return TRUE;
		else
		{
			ADGNFORCE aForceLcom;
			ADGNFORCE aForceStag;
			ADGNSHRSADD aShrsStage;
			ADGNFORCE aForceTnpr;
			ADGNFORCE aForceTnsc;
			ADGNFORCE aForceLTerm;
			ADGNFORCE aForceJtgTndn;
			ADGNSTRESS aStressTnpr;
			ADGNSTRESS aStressTnsc;
			ADGNSHRSADD aStssLcom;
			int nForType = 0;
			return Get_LcomDataForDesign(ElemK, nForType, 0, bIncludeTP, bAlways3D, aForceLcom, aForceStag, aShrsStage, aForceTnpr, aForceTnsc, aStressAdd, aForceLTerm, aForceJtgTndn,
				aStressLcom, aStressTnpr, aStressTnsc, aStressLTerm, aStssLcom);
		}
	}
	else
	{
		aStressLcom.RemoveAll();
		aStressAdd.RemoveAll();
		aStressLTerm.RemoveAll();
		aStressLcom.SetSize(iLcomNum);
		aStressAdd.SetSize(iLcomNum);
		aStressLTerm.SetSize(iLcomNum);
		aStressSTerm.SetSize(iLcomNum);
		for (int i = 0; i < iLcomNum; ++i)
		{
			int nSerialLcom = i + 1;
			_DGN_STRS_CRC StressLcom;
			_DGN_STRS_ADD StrsAdd;
			if (bIncludeTP)
				m_pDgnForceResult->GetStressLcomResult(ElemK, nSerialLcom, StressLcom);
			else
			{
				StressLcom.Initialize();
				ASSERT(0);
				// Stress인데 Tendon primary를 제외 하는가?
				// 여길 사용하려면 Binary 작업        
			}
			aStressLcom.SetAt(i, StressLcom);
			//
			m_pDgnForceResult->GetStressAddResult(ElemK, nSerialLcom, StrsAdd);
			aStressAdd.SetAt(i, StrsAdd);
			//
			_DGN_STRS_CRC StressLTerm;
			m_pDgnForceResult->GetStressLTermResult(ElemK, nSerialLcom, StressLTerm);
			aStressLTerm.SetAt(i, StressLTerm);

			_DGN_STRS_CRC StressSTerm;
			m_pDgnForceResult->GetStressSTermResult(ElemK, nSerialLcom, StressSTerm);
			aStressSTerm.SetAt(i, StressSTerm);
		}
		return TRUE;
	}
}

BOOL CCRCForceCtrl::Get_LcomDataForStress(ElemPairK ElemK, int nForType, BOOL bIncludeTP, BOOL bAlways3D, ADGNSTRESS& aStressLcom, ADGNSTRESS& aStressTnpr, int iLcomNum)
{
	if (iLcomNum <= 0)
	{
		// Lcom Stresses.
		if (bIncludeTP)
		{
			const auto& iter = m_arStressElemInTP.find(ElemK);
			if (iter != m_arStressElemInTP.end())
			{
				aStressLcom.Copy(iter->second.aStressLcom);
			}
		}
		else
		{
			const auto& iter = m_arStressElemExTP.find(ElemK);
			if (iter != m_arStressElemExTP.end())
			{
				aStressLcom.Copy(iter->second.aStressLcom);
			}
		}
		// Tendon Primary Stresses.
		const auto& itStrTnpr = m_arStressTnprData.find(ElemK);
		if (itStrTnpr != m_arStressTnprData.end())
		{
			aStressTnpr.Copy(itStrTnpr->second.aStressLcom);
		}

		if (aStressLcom.GetSize() > 0 && aStressTnpr.GetSize() > 0)	return TRUE;
		else
		{
			ADGNFORCE aForceLcom;
			ADGNFORCE aForceStag;
			ADGNSHRSADD aShrsStage;
			ADGNFORCE aForceTnpr;
			ADGNFORCE aForceTnsc;
			ADGNSTRSADD aStressAdd;
			ADGNFORCE aForceLTerm;
			ADGNFORCE aForceJtgTndn;
			ADGNSTRESS aStressTnsc;
			ADGNSTRESS aStressLTerm;
			ADGNSHRSADD aStssLcom;
			//int nForType =0;
			return Get_LcomDataForDesign(ElemK, nForType, 0, bIncludeTP, bAlways3D, aForceLcom, aForceStag, aShrsStage, aForceTnpr, aForceTnsc, aStressAdd, aForceLTerm, aForceJtgTndn,
				aStressLcom, aStressTnpr, aStressTnsc, aStressLTerm, aStssLcom);
		}
	}
	else
	{
		aStressLcom.RemoveAll();
		aStressTnpr.RemoveAll();
		aStressLcom.SetSize(iLcomNum);
		aStressTnpr.SetSize(iLcomNum);
		for (int i = 0; i < iLcomNum; ++i)
		{
			int iSerialLcom = i + 1;
			_DGN_STRS_CRC StressLcom;
			_DGN_STRS_CRC StressTnpr;
			if (bIncludeTP)
			{
				if (nForType == 0) m_pDgnForceResult->GetStressLcomResult(ElemK, iSerialLcom, StressLcom);
				else if (nForType == 1) m_pDgnForceResult->GetStressLcomResult_Part1(ElemK, iSerialLcom, StressLcom);
				else if (nForType == 2) m_pDgnForceResult->GetStressLcomResult_Part2(ElemK, iSerialLcom, StressLcom);
				else ASSERT(0);
			}
			else
			{
				StressLcom.Initialize();
				ASSERT(0);
				// Stress인데 Tendon primary를 제외 하는가?
				// 여길 사용하려면 Binary 작업        
			}
			aStressLcom.SetAt(i, StressLcom);
			//
			m_pDgnForceResult->GetStressTnprResult(ElemK, iSerialLcom, StressTnpr);
			aStressTnpr.SetAt(i, StressTnpr);
		}
		return TRUE;
	}
}

