BOOL CCRCForceCtrl::Get_LcomStressScfp(ElemPairK ElemK, int nLcomNum, ASCFPSTRESS &aCrD, ASCFPSTRESS &aShD, ASCFPSTRESS &aTeD, ASCFPSTRESS &aReD)
{
	aCrD.SetSize(nLcomNum);
	aShD.SetSize(nLcomNum);
	aTeD.SetSize(nLcomNum);
	aReD.SetSize(nLcomNum);

	for (int i = 0; i < nLcomNum; ++i)
	{
		int nSerialLcom = i + 1;
		_DGN_SCFP_PART_LCASE ScfpStr;
		m_pDgnForceResult->GetStressLcomResult_PartScfpCr(ElemK, nSerialLcom, ScfpStr);
		aCrD.SetAt(i, ScfpStr);
		//
		ScfpStr.Initialize();
		m_pDgnForceResult->GetStressLcomResult_PartScfpSh(ElemK, nSerialLcom, ScfpStr);
		aShD.SetAt(i, ScfpStr);
		//
		ScfpStr.Initialize();
		m_pDgnForceResult->GetStressLcomResult_PartScfpTe(ElemK, nSerialLcom, ScfpStr);
		aTeD.SetAt(i, ScfpStr);
		//
		ScfpStr.Initialize();
		m_pDgnForceResult->GetStressLcomResult_PartScfpRe(ElemK, nSerialLcom, ScfpStr);
		aReD.SetAt(i, ScfpStr);
	}
	return TRUE;
}

