int CCRCForceCtrl::Get_LcomDataCount() { return m_arLcomData.GetCount(); }

BOOL CCRCForceCtrl::Get_LcomDataMap(CMap<T_LCOM_K, T_LCOM_K, T_LCOM_K, T_LCOM_K>& aLcomK)
{
	aLcomK.RemoveAll();
	_DGN_LCOM LcomDesign;
	T_LCOM_K Index = 0;
	POSITION Pos = m_arLcomData.GetStartPosition();
	while (Pos)
	{
		LcomDesign.Initialize();
		m_arLcomData.GetNextAssoc(Pos, Index, LcomDesign);
		int iDgnLcomNo = Index;
		int iOrgLcomNo = LcomDesign.OriginalLcomKey;
		aLcomK.SetAt(iDgnLcomNo, iOrgLcomNo);
	}
	if (aLcomK.GetCount() > 0)	return TRUE;
	else											return FALSE;
}

BOOL CCRCForceCtrl::Get_LcomListDL(CArray<_DGN_LCOM, _DGN_LCOM>& aLcomDesign)
{
	aLcomDesign.RemoveAll();
	T_LCOM_K iIndex = 0;
	POSITION Pos = m_arLcomData.GetStartPosition();
	_DGN_LCOM LcomDesign;
	while (Pos)
	{
		LcomDesign.Initialize();
		m_arLcomData.GetNextAssoc(Pos, iIndex, LcomDesign);
		if (LcomDesign.bLongTerm != 1)	continue;	// Only 사하중시.
		aLcomDesign.Add(LcomDesign);
	}
	return TRUE;
}

BOOL CCRCForceCtrl::Get_LcomListLL(CArray<_DGN_LCOM, _DGN_LCOM>& aLcomDesign)
{
	aLcomDesign.RemoveAll();
	T_LCOM_K iIndex = 0;
	POSITION Pos = m_arLcomData.GetStartPosition();
	_DGN_LCOM LcomDesign;
	while (Pos)
	{
		LcomDesign.Initialize();
		m_arLcomData.GetNextAssoc(Pos, iIndex, LcomDesign);
		if (LcomDesign.bLongTerm != 2)	continue;	// Only 설계시.
		aLcomDesign.Add(LcomDesign);
	}
	return TRUE;
}

BOOL CCRCForceCtrl::Get_LcomListTL(CArray<_DGN_LCOM, _DGN_LCOM>& aLcomDesign)
{
	aLcomDesign.RemoveAll();
	T_LCOM_K iIndex = 0;
	POSITION Pos = m_arLcomData.GetStartPosition();
	_DGN_LCOM LcomDesign;
	while (Pos)
	{
		LcomDesign.Initialize();
		m_arLcomData.GetNextAssoc(Pos, iIndex, LcomDesign);
		if (LcomDesign.bLongTerm != 3)	continue;	// Only 온도시.
		aLcomDesign.Add(LcomDesign);
	}
	return TRUE;
}

BOOL CCRCForceCtrl::Get_LcomListEQ(CArray<_DGN_LCOM, _DGN_LCOM>& aLcomDesign)
{
	aLcomDesign.RemoveAll();
	T_LCOM_K iIndex = 0;
	POSITION Pos = m_arLcomData.GetStartPosition();
	_DGN_LCOM LcomDesign;
	while (Pos)
	{
		LcomDesign.Initialize();
		m_arLcomData.GetNextAssoc(Pos, iIndex, LcomDesign);
		if (LcomDesign.bLongTerm != 4)	continue;	// Only 지진시.
		aLcomDesign.Add(LcomDesign);
	}
	return TRUE;
}

