BOOL CCRCForceCtrl::Is_LcomForStrn(int iDgnLcomNo)
{
	int iDgnLcomKind = Get_LcomKind(iDgnLcomNo);
	BOOL bStrs = (iDgnLcomKind < 1 || iDgnLcomKind >  9 ? FALSE : TRUE);
	BOOL bStrn = FALSE;
	if (m_iDgnCode == AASHTO_LRFD08)
	{
		bStrs = (AASHTO_LCOMTYPE_SERVICE0 <= iDgnLcomKind && iDgnLcomKind <= AASHTO_LCOMTYPE_FATIGUE) || iDgnLcomKind == AASHTO_LCOMTYPE_SERVICE_IN_LIVE ? TRUE : FALSE;
		bStrn = (AASHTO_LCOMTYPE_STRENGTH0 <= iDgnLcomKind && iDgnLcomKind <= AASHTO_LCOMTYPE_STRENGTH5 ? TRUE : FALSE);
	}
	else if (CDBLib::IsPscCodeAASHTOSince12(m_iDgnCode) ||
		CDBLib::IsPscCodeCSA(m_iDgnCode))
	{
		// 다시 확인하기..
		bStrs = (AASHTO_LCOMTYPE_SERVICE0 <= iDgnLcomKind && iDgnLcomKind <= AASHTO_LCOMTYPE_FATIGUE) || iDgnLcomKind == AASHTO_LCOMTYPE_SERVICE_IN_LIVE ? TRUE : FALSE;
		bStrn = (AASHTO_LCOMTYPE_STRENGTH0 <= iDgnLcomKind && iDgnLcomKind <= AASHTO_LCOMTYPE_STRENGTH5 ? TRUE : FALSE);
	}
	else if (m_iDgnCode == EUROCODE2_2_05_PSC || m_iCivilCode == KDS_24_14_21_2022_PSC || m_iCivilCode == KSCE_LSD15_PSC || m_iDgnCode == IRC_112_2011_PSC || m_iDgnCode == IRC22_15_CSG ||
		m_iDgnCode == IRS_PSC || m_iDgnCode == ABNT_NBR_6118_2023_PSC)
	{
		bStrn = iDgnLcomKind < 11 ? FALSE : TRUE;
	}
	else if (m_iDgnCode == SNiP_20503_84_PSC || m_iDgnCode == SP_35_13330_11_PSC || m_iDgnCode == SNiP_20503_84_PSC_MKS || m_iDgnCode == SP_35_13330_11_PSC_MKS)
	{
		bStrn = iDgnLcomKind < 11 ? FALSE : TRUE;
	}
	else if (m_iDgnCode == BS5400_90_PSC || m_iDgnCode == BD_44_15_PSC || m_iDgnCode == CS_455_PSC)
	{
		bStrn = iDgnLcomKind < 11 ? FALSE : TRUE;
	}
	else if (m_iDgnCode == AS_5100_5_17_PSC)
	{
		bStrn = iDgnLcomKind < 11 ? FALSE : TRUE;
	}
	else bStrn = (iDgnLcomKind < 11 || iDgnLcomKind > 13 ? FALSE : TRUE);
	BOOL bCHTB = (iDgnLcomKind < 101 || iDgnLcomKind >103 ? FALSE : TRUE);
	//if(!(bStrs || bStrn || bCHTB))	ASSERT(0);
	return bStrn;
}

BOOL CCRCForceCtrl::Is_LcomForStrs(int iDgnLcomNo)
{
	int iDgnLcomKind = Get_LcomKind(iDgnLcomNo);
	BOOL bStrs = (iDgnLcomKind < 1 || iDgnLcomKind >  9 ? FALSE : TRUE);
	BOOL bStrn = FALSE;
	if (m_iDgnCode == AASHTO_LRFD08)
	{
	}
	else if (CDBLib::IsPscCodeAASHTOSince12(m_iDgnCode) ||
		CDBLib::IsPscCodeCSA(m_iDgnCode))
	{
	}
	else if (m_iDgnCode == EUROCODE2_2_05_PSC || m_iDgnCode == KDS_24_14_21_2022_PSC || m_iDgnCode == KSCE_LSD15_PSC || m_iDgnCode == IRC_112_2011_PSC || m_iDgnCode == IRS_PSC ||
             m_iDgnCode == IRC_112_2020_PSC || m_iDgnCode == ABNT_NBR_6118_2023_PSC)
	{
		bStrs = iDgnLcomKind < 11 ? TRUE : FALSE;
		bStrn = iDgnLcomKind < 11 ? FALSE : TRUE;
	}
	else if (m_iDgnCode == BS5400_90_PSC)
	{
		// 		bStrs = iDgnLcomKind < 11 ? TRUE : FALSE;
		// 		bStrn = iDgnLcomKind < 11 ? FALSE: TRUE;
	}
	else if (CDBLib::IsCSGCode(m_iDgnCode) == TRUE)
	{
		bStrs = iDgnLcomKind < 11 ? TRUE : FALSE;
		bStrn = iDgnLcomKind < 11 ? FALSE : TRUE;
	}
	else if (m_iDgnCode == AS_5100_5_17_PSC)
	{

	}
	else {/* 다른 기준에서는 고려안됨*/ }


	switch (m_iDgnCode)
	{
	case AASHTO_LRFD08:
	{
		bStrs = (AASHTO_LCOMTYPE_SERVICE0 <= iDgnLcomKind && iDgnLcomKind <= AASHTO_LCOMTYPE_FATIGUE) || iDgnLcomKind == AASHTO_LCOMTYPE_SERVICE_IN_LIVE ? TRUE : FALSE;
		bStrn = AASHTO_LCOMTYPE_STRENGTH0 <= iDgnLcomKind && iDgnLcomKind <= AASHTO_LCOMTYPE_STRENGTH5 ? TRUE : FALSE;
		break;
	}
	case AASHTO_LRFD12:
	case AASHTO_LRFD14:
	case AASHTO_LRFD16:
	case AASHTO_LRFD17:
	case AASHTO_LRFD20:
	case AASHTO_LRFD24:
	case CSA_S6_10:
	case CSA_S6_14:
	case CSA_S6_19:
	case AREMA_23:
	{
		// 다시 확인하기..
		bStrs = (AASHTO_LCOMTYPE_SERVICE0 <= iDgnLcomKind && iDgnLcomKind <= AASHTO_LCOMTYPE_FATIGUE) || iDgnLcomKind == AASHTO_LCOMTYPE_SERVICE_IN_LIVE ? TRUE : FALSE;
		bStrn = AASHTO_LCOMTYPE_STRENGTH0 <= iDgnLcomKind && iDgnLcomKind <= AASHTO_LCOMTYPE_STRENGTH5 ? TRUE : FALSE;
		break;
	}
	case EUROCODE2_2_05_PSC:
	case IRC_112_2011_PSC:
	case IRC_112_2020_PSC:
	case AS_5100_5_17_PSC:
	case KDS_24_14_21_2022_PSC:
	case KSCE_LSD15_PSC:
	case BS5400_90_PSC:
	case TMH07_3_1989:
	case BD_44_15_PSC:
	case CS_455_PSC:
	case EUROCODE4_2_04_CSG:
	case IRC22_08_CSG:
	case AASHTO_LRFD20_CSG:
	case AASHTO_LRFD17_CSG:
	case AASHTO_LRFD16_CSG:
	case AASHTO_LRFD12_CSG:
	case AASHTO_LRFD07_CSG:
	case KDS_24_14_31_2018_CSG:
	case CSA_S6_10_CSG:
	case CSA_S6_14_CSG:
	case CSA_S6_19_CSG:
	case IRS_PSC:
	case CS457_R1_CSG:
	case NR_GN_CIV_025_06_CSG:
	case AS5100_6_17_CSG:
	case ABNT_NBR_6118_2023_PSC:
	{
		bStrs = iDgnLcomKind < 11 ? TRUE : FALSE;
		bStrn = iDgnLcomKind < 11 ? FALSE : TRUE;
		break;
	}
	default:
	{
		bStrn = (iDgnLcomKind < 11 || iDgnLcomKind > 13) ? FALSE : TRUE;
		break;
	}
	}

	BOOL bCHTB = (iDgnLcomKind < 101 || iDgnLcomKind >103 ? FALSE : TRUE);
	//if(!(bStrs || bStrn || bCHTB))	ASSERT(0);
	BOOL bStress = bStrs || bCHTB ? TRUE : FALSE;
	return bStress;
}

BOOL CCRCForceCtrl::Is_LcomForElst(int iDgnLcomNo)
{
	if (!Is_LcomForStrs(iDgnLcomNo))	return FALSE;
	// Add by ZINU.('05.03.10). Check 탄성단계 only if JTG D62-04.
	if (m_iDgnCode == JTG_D62_04 || m_iDgnCode == RC_JTG_D62_04
		|| m_iDgnCode == CJJ_11_2011 || m_iDgnCode == RC_CJJ_11_2011)
	{
		int iDgnLcomKind = Get_LcomKind(iDgnLcomNo);
		if (iDgnLcomKind == 8)	return TRUE;
		else								return FALSE;
	}
	else	return TRUE;
}

BOOL CCRCForceCtrl::Is_LcomForServ(int iDgnLcomNo)	// NOT Elastic.
{
	if (!Is_LcomForStrs(iDgnLcomNo))	return FALSE;
	if (m_iDgnCode == JTG_D62_04 || m_iDgnCode == RC_JTG_D62_04
		|| m_iDgnCode == CJJ_11_2011 || m_iDgnCode == RC_CJJ_11_2011)
	{
		if (Is_LcomForElst(iDgnLcomNo))	return FALSE;
		else														return TRUE;
	}
	else	return TRUE;
}

