double CCRCForceCtrl::Cng_LengthUnit(T_UNIT_INDEX FromUnit, T_UNIT_INDEX ToUnit, double dLength, int iUp)
{
	double dToLen = 0.0;
	switch (ToUnit.nBase_Length)
	{
	case D_UNITSYS_LENGTH_INDEX_M: {dToLen = 1.0;		break; }
	case D_UNITSYS_LENGTH_INDEX_CM: {dToLen = 0.01;		break; }
	case D_UNITSYS_LENGTH_INDEX_MM: {dToLen = 0.001;	break; }
	case D_UNITSYS_LENGTH_INDEX_IN: {dToLen = 0.0254;	break; }
	case D_UNITSYS_LENGTH_INDEX_FT: {dToLen = 0.3048;	break; }
	default:	ASSERT(0);
	}
	double dFromLen = 0.0;
	switch (FromUnit.nBase_Length)
	{
	case D_UNITSYS_LENGTH_INDEX_M: {dFromLen = 1.0;		break; }
	case D_UNITSYS_LENGTH_INDEX_CM: {dFromLen = 0.01;		break; }
	case D_UNITSYS_LENGTH_INDEX_MM: {dFromLen = 0.001;	break; }
	case D_UNITSYS_LENGTH_INDEX_IN: {dFromLen = 0.0254;	break; }
	case D_UNITSYS_LENGTH_INDEX_FT: {dFromLen = 0.3048;	break; }
	default:	ASSERT(0);
	}
	return dLength * pow(dFromLen / dToLen, iUp);
}

double CCRCForceCtrl::Cng_ForceUnit(T_UNIT_INDEX FromUnit, T_UNIT_INDEX ToUnit, double dForce)
{
	double dToFor = 0.0;
	switch (ToUnit.nBase_Force)
	{
	case D_UNITSYS_FORCE_INDEX_KG: {dToFor = 9.80665;	break; }
	case D_UNITSYS_FORCE_INDEX_TON: {dToFor = 9806.65;	break; }
	case D_UNITSYS_FORCE_INDEX_N: {dToFor = 1.0;			break; }
	case D_UNITSYS_FORCE_INDEX_KN: {dToFor = 1000.0;		break; }
	case D_UNITSYS_FORCE_INDEX_LBF: {dToFor = 4.448223;	break; }
	case D_UNITSYS_FORCE_INDEX_KIP: {dToFor = 4448.223;	break; }
	default:	ASSERT(0);
	}
	double dFromFor = 0.0;
	switch (FromUnit.nBase_Force)
	{
	case D_UNITSYS_FORCE_INDEX_KG: {dFromFor = 9.80665;	break; }
	case D_UNITSYS_FORCE_INDEX_TON: {dFromFor = 9806.65;	break; }
	case D_UNITSYS_FORCE_INDEX_N: {dFromFor = 1.0;			break; }
	case D_UNITSYS_FORCE_INDEX_KN: {dFromFor = 1000.0;		break; }
	case D_UNITSYS_FORCE_INDEX_LBF: {dFromFor = 4.448223;	break; }
	case D_UNITSYS_FORCE_INDEX_KIP: {dFromFor = 4448.223;	break; }
	default:	ASSERT(0);
	}
	return dForce * (dFromFor / dToFor);
}

double CCRCForceCtrl::Cng_StressUnit(T_UNIT_INDEX FromUnit, T_UNIT_INDEX ToUnit, double dStress)
{
	double dLength = 1.0;
	dLength = Cng_LengthUnit(FromUnit, ToUnit, dLength, 1);
	double dForce = 1.0;
	dForce = Cng_ForceUnit(FromUnit, ToUnit, dForce);
	return dStress * (dForce / pow(dLength, 2));
}

BOOL CCRCForceCtrl::Get_LoadCaseStress(ElemPairK ElemK, T_STRB_D& StrData, _DGN_STRS_CRC& StressLcase)
{

	// 	T_STRSPOST_D StrsPost;
	// 	StrsPost.Initialize();
	// 	if(!m_pSectInfo->Get_StrsPscd(FALSE,ElemK,StrsPost))	return FALSE;
	/*
	// Get Elem Data.
	T_ELEM_D ElemD;
	ElemD.Initialize();
	if(!m_pPostCtrl->GetElemPost(ElemK,ElemD))	return FALSE;
	T_SECT_K SectK = ElemD.elpro;
	// Get Sect Data.
	T_SECT_D SectD;
	SectD.Initialize();
	if(!m_pPostCtrl->GetSectPost(SectK,SectD))	return FALSE;

	int iPosi = (CDBLib::IsSectI(j==0, SectD.nStype) ? 0 : 1);
	double dCzp	 = (iPosi==0 ? SectD.SectBefore.SectI.Stiffness.Czp : SectD.SectBefore.SectJ.Stiffness.Czp);
	double dCzm	 = (iPosi==0 ? SectD.SectBefore.SectI.Stiffness.Czm : SectD.SectBefore.SectJ.Stiffness.Czm);
	*/

	// Stress  
	int iPart;
	int iKind1;
	int iKind2;
	for (int i = 0; i < cPOSI_CRC; ++i)
	{
		T_STRSPOST_BASE &StrsBase = (i == 0 ? m_StrsPost.StrsBaseI : m_StrsPost.StrsBaseJ);
		double dCy0 = StrsBase.dyzM[0][0];	double dCz0 = StrsBase.dyzM[1][0];
		double dCy1 = StrsBase.dyzM[0][1];	double dCz1 = StrsBase.dyzM[1][1];
		double dCy2 = StrsBase.dyzM[0][2];	double dCz2 = StrsBase.dyzM[1][2];
		double dCy3 = StrsBase.dyzM[0][3];	double dCz3 = StrsBase.dyzM[1][3];
		double dCzp = max(dCz0, dCz1);	// z-Top.
		double dCzm = min(dCz2, dCz3);	// z-Bot.

		if (i == 0)
		{
			iPart = 0;
			iKind1 = 0;
			iKind2 = 0;
		}
		else
		{
			iPart = 3;
			iKind1 = 7;
			iKind2 = 1;
		}
		double dStop = (StrData.dblStress[iPart][iKind1 + 0] + StrData.dblStress[iPart][iKind1 + 5]);
		double dSbot = (StrData.dblStress[iPart][iKind1 + 0] + StrData.dblStress[iPart][iKind1 + 6]);
		double dSxx = StrData.dblStress[iPart][iKind1 + 0];

		StressLcase.dSbot[i] = dSxx;
		StressLcase.dStop[i] = dStop;
		StressLcase.dSbot[i] = dSbot;
		double dStl2D = (dCzp == 0.0 ? 0.0 : dStop * dCz0 / dCzp);
		double dStr2D = (dCzp == 0.0 ? 0.0 : dStop * dCz1 / dCzp);
		double dSbl2D = (dCzm == 0.0 ? 0.0 : dSbot * dCz3 / dCzm);
		double dSbr2D = (dCzm == 0.0 ? 0.0 : dSbot * dCz2 / dCzm);
		if (m_iDimType < 2)
		{
			StressLcase.dStl[i] = dStl2D;
			StressLcase.dStr[i] = dStr2D;
			StressLcase.dSbl[i] = dSbl2D;
			StressLcase.dSbr[i] = dSbr2D;
		}
		else
		{
			StressLcase.dStl[i] = StrData.dblStress[iPart][iKind2 + 16];
			StressLcase.dStr[i] = StrData.dblStress[iPart][iKind2 + 18];
			StressLcase.dSbl[i] = StrData.dblStress[iPart][iKind2 + 22];
			StressLcase.dSbr[i] = StrData.dblStress[iPart][iKind2 + 20];
		}
	}
	return TRUE;
}

BOOL CCRCForceCtrl::Get_LoadCaseStress(ElemPairK ElemK, T_SBCF_D& StrMaxData, T_SBCF_D& StrMinData, ADGNSTRESS& aStressLcase)
{

	aStressLcase.RemoveAll();
	aStressLcase.SetSize(cFORC_CON);

	// Stress  
	int i, j;
	for (i = 0; i < cFORC_CON; ++i)
	{
		_DGN_STRS_CRC &StressLcase = aStressLcase[i];
		T_SBCF_D &StrData = (i % 2 == 0 ? StrMaxData : StrMinData);
		for (j = 0; j < cPOSI_CRC; ++j)
		{
			T_STRSPOST_BASE &StrsBase = (j == 0 ? m_StrsPost.StrsBaseI : m_StrsPost.StrsBaseJ);
			double dCy0 = StrsBase.dyzM[0][0];	double dCz0 = StrsBase.dyzM[1][0];
			double dCy1 = StrsBase.dyzM[0][1];	double dCz1 = StrsBase.dyzM[1][1];
			double dCy2 = StrsBase.dyzM[0][2];	double dCz2 = StrsBase.dyzM[1][2];
			double dCy3 = StrsBase.dyzM[0][3];	double dCz3 = StrsBase.dyzM[1][3];
			double dCzp = max(dCz0, dCz1);	// z-Top.
			double dCzm = min(dCz2, dCz3);	// z-Bot.

			int iPart = (j == 0 ? 0 : 3);
			double dStop = (StrData.dblStress[iPart][j][i / 2][0] + StrData.dblStress[iPart][j][i / 2][5]);
			double dSbot = (StrData.dblStress[iPart][j][i / 2][0] + StrData.dblStress[iPart][j][i / 2][6]);
			double dSxx = StrData.dblStress[iPart][j][i / 2][0];
			StressLcase.dStop[j] = dStop;
			StressLcase.dSbot[j] = dSbot;
			StressLcase.dSxx[j] = dSxx;
			double dStl2D = (dCzp == 0.0 ? 0.0 : dStop * dCz0 / dCzp);
			double dStr2D = (dCzp == 0.0 ? 0.0 : dStop * dCz1 / dCzp);
			double dSbl2D = (dCzm == 0.0 ? 0.0 : dSbot * dCz3 / dCzm);
			double dSbr2D = (dCzm == 0.0 ? 0.0 : dSbot * dCz2 / dCzm);
			if (m_iDimType < 2)
			{
				StressLcase.dStl[j] = dStl2D;
				StressLcase.dStr[j] = dStr2D;
				StressLcase.dSbl[j] = dSbl2D;
				StressLcase.dSbr[j] = dSbr2D;
			}
			else
			{
				StressLcase.dStl[j] = StrData.dblStress[iPart][j][i / 2][8];
				StressLcase.dStr[j] = StrData.dblStress[iPart][j][i / 2][9];
				StressLcase.dSbl[j] = StrData.dblStress[iPart][j][i / 2][11];
				StressLcase.dSbr[j] = StrData.dblStress[iPart][j][i / 2][10];
			}
		}
	}
	return TRUE;
}

BOOL CCRCForceCtrl::Get_LoadCaseStressGilc(ElemPairK ElemK, T_STRB_D& StrData, _DGN_STRS_CRC& StressLcase)
{

	int i = 0, j = 0, k = 0;
	// Remove by ZINU.('06.04.24). Use Data at StrsPost.
	/*
	// Add by ZINU.('04.12.17). Set Effective Width Scale Factor.
	double dScaleIy=1.0, dScaleZt=1.0, dScaleZb=1.0;
	T_EWSF_D EwsfD;
	EwsfD.Initialize();
	if(m_pAttrCtrl->GetEwsfElem(ElemK,EwsfD))
	{
	dScaleIy = EwsfD.dScaleFactor;
	dScaleZt = EwsfD.dZtopFactor;
	dScaleZb = EwsfD.dZbotFactor;
	}
	*/
	// Get Elem Data.
	T_ELEM_D ElemD;
	if (!m_pPostCtrl->GetElemPost(ElemK.first, ElemD))	return FALSE;
	////////////////////////////
	// Get Sect Data.
	T_SECT_D SectD;
	if (!m_pPostCtrl->GetSectPost(ElemD.elpro, SectD))	return FALSE;
	BOOL bIs7Dof = SectD.SectBefore.bConsiderWarpingEffect;

	// Force.
	_DGN_FORC_CRC ForceLcase;
	for (i = 0; i < cPOSI_CRC; ++i)
	{
		int iPart = (i == 0 ? 0 : 3);
		int iKind = (i == 0 ? 0 : 6);
		ForceLcase.dFxx[i] = StrData.dblForce[iPart][iKind + 0];
		ForceLcase.dFyy[i] = StrData.dblForce[iPart][iKind + 1];
		ForceLcase.dFzz[i] = StrData.dblForce[iPart][iKind + 2];
		ForceLcase.dMux[i] = StrData.dblForce[iPart][iKind + 3];
		ForceLcase.dMuy[i] = StrData.dblForce[iPart][iKind + 4];
		ForceLcase.dMuz[i] = StrData.dblForce[iPart][iKind + 5];
		ForceLcase.dMbi[i] = StrData.dblForce[iPart][Mbi_Id + i]; // Bi-moment
		ForceLcase.dTst[i] = StrData.dblForce[iPart][Mst_Id + i]; // Pure torsion
		ForceLcase.dTwp[i] = StrData.dblForce[iPart][Mwp_Id + i]; // Warping torsion
	}

	Set_DimTypeForc(ForceLcase);

	T_STRSPROP_D StrsPropD;
	if (bIs7Dof)
	{
		m_pSectInfo->ReadSectPostProp(ElemK.first, StrsPropD);
	}

	for (i = 0; i < cPOSI_CRC; ++i)
	{
		T_STRSPOST_BASE &StrsBase = (i == 0) ? m_StrsPost.StrsBaseI : m_StrsPost.StrsBaseJ;
		double dArea = StrsBase.dArea;
		double dQyb = StrsBase.dQyb;
		double dQzb = StrsBase.dQzb;
		double dIyy = StrsBase.dIyy * StrsBase.dScaleIy;
		double dIzz = StrsBase.dIzz;
		double dIw = 0.0;

		double dCy0 = StrsBase.dyzM[0][0];	double dCz0 = StrsBase.dyzM[1][0] - StrsBase.dMoveTop;
		double dCy1 = StrsBase.dyzM[0][1];	double dCz1 = StrsBase.dyzM[1][1] - StrsBase.dMoveTop;
		double dCy2 = StrsBase.dyzM[0][2];	double dCz2 = StrsBase.dyzM[1][2] - StrsBase.dMoveBot;
		double dCy3 = StrsBase.dyzM[0][3];	double dCz3 = StrsBase.dyzM[1][3] - StrsBase.dMoveBot;

		int nPosIJ = (i == 0) ? 0 : 4;
		T_SECT_STIFFNESS &StiffD = StrsPropD.PropB[nPosIJ].Stiff.Stiffness;
		if (bIs7Dof)
		{
			dArea = StiffD.Area;
			//dQyb	= StrsBase[i+j].dQyb;
			//dQzb	= StrsBase[i+j].dQzb;
			dIyy = StiffD.Ryy * StrsBase.dScaleIy;
			dIzz = StiffD.Rzz;
			dIw = StiffD.dIw;

			dCy0 = StiffD.dx1;  dCz0 = StiffD.dy1;
			dCy1 = StiffD.dx2;  dCz1 = StiffD.dy2;
			dCy2 = StiffD.dx3;	dCz2 = StiffD.dy3;
			dCy3 = StiffD.dx4;	dCz3 = StiffD.dy4;
		}

		double dSy0 = (dCz0 == 0.0 ? 0.0 : dIyy / dCz0);	double dSz0 = (dCy0 == 0.0 ? 0.0 : dIzz / dCy0);
		double dSy1 = (dCz1 == 0.0 ? 0.0 : dIyy / dCz1);	double dSz1 = (dCy1 == 0.0 ? 0.0 : dIzz / dCy1);
		double dSy2 = (dCz2 == 0.0 ? 0.0 : dIyy / dCz2);	double dSz2 = (dCy2 == 0.0 ? 0.0 : dIzz / dCy2);
		double dSy3 = (dCz3 == 0.0 ? 0.0 : dIyy / dCz3);	double dSz3 = (dCy3 == 0.0 ? 0.0 : dIzz / dCy3);

		double dCyp = max(dCy1, dCy2);	// y-Right.
		double dCym = min(dCy0, dCy3);	// y-Left.
		double dCzp = max(dCz0, dCz1);	// z-Top.
		double dCzm = min(dCz2, dCz3);	// z-Bot.
		double dSyp = (dCzp == 0.0 ? 0.0 : dIyy / dCzp);
		double dSym = (dCzm == 0.0 ? 0.0 : dIyy / dCzm);
		double dSzp = (dCyp == 0.0 ? 0.0 : dIzz / dCyp);
		double dSzm = (dCym == 0.0 ? 0.0 : dIzz / dCym);

		// Tension(+), Compression(-).
		double dSxx = (dArea == 0.0 ? 0.0 : ForceLcase.dFxx[i] / dArea);			// Sxx.
		double dSyy = (dIzz == 0.0 ? 0.0 : ForceLcase.dFyy[i] * dQzb / dIzz);	// Syy.
		double dSzz = (dIyy == 0.0 ? 0.0 : ForceLcase.dFzz[i] * dQyb / (dIyy / StrsBase.dScaleIy));	// Szz.
		double dByp = (-1)*(dSyp == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSyp);			// Byp.
		double dBym = (-1)*(dSym == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSym);			// Bym.
		double dBzp = (dSzp == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSzp);			// Bzp.
		double dBzm = (dSzm == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSzm);			// Bzm.
		// For Combined Stresses.
		// Change by ZINU.('04.12.27). Multiply (-1) at dBz0,dBz1,dBz2,dBz3.
		double dBy0 = (-1)*(dSy0 == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSy0);	// By0.
		double dBy1 = (-1)*(dSy1 == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSy1);	// By1.
		double dBy2 = (-1)*(dSy2 == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSy2);	// By2.
		double dBy3 = (-1)*(dSy3 == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSy3);	// By3.
		double dBz0 = (-1)*(dSz0 == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSz0);	// Bz0.
		double dBz1 = (-1)*(dSz1 == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSz1);	// Bz1.
		double dBz2 = (-1)*(dSz2 == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSz2);	// Bz2.
		double dBz3 = (-1)*(dSz3 == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSz3);	// Bz3.
		double dBi0 = 0.0, dBi1 = 0.0, dBi2 = 0.0, dBi3 = 0.0;
		if (bIs7Dof)
		{
			double dMwIw = (dIw == 0.0) ? 0.0 : (-1)*ForceLcase.dMbi[i] / dIw;
			dBi0 = dMwIw * StiffD.dw1;
			dBi1 = dMwIw * StiffD.dw2;
			dBi2 = dMwIw * StiffD.dw3;
			dBi3 = dMwIw * StiffD.dw4;
		}
		// Combined Stresses.
		int iPart = (i == 0 ? 0 : 3);
		double dStop = dSxx + dByp;				  // 상단.
		double dSbot = dSxx + dBym;				  // 하단.
		double dStl = dSxx + dBy0 + dBz0 + dBi0; //(m_iDimType !=2 ? dSxx + dBy0 + dBz0 : StrData.dblStress[iPart][iKind2+16]);	// 상단좌단.
		double dStr = dSxx + dBy1 + dBz1 + dBi1; //(m_iDimType !=2 ? dSxx + dBy1 + dBz1 : StrData.dblStress[iPart][iKind2+18]);	// 상단우단.
		double dSbr = dSxx + dBy2 + dBz2 + dBi2; //(m_iDimType !=2 ? dSxx + dBy2 + dBz2 : StrData.dblStress[iPart][iKind2+22]);	// 하단우단.
		double dSbl = dSxx + dBy3 + dBz3 + dBi3; //(m_iDimType !=2 ? dSxx + dBy3 + dBz3 : StrData.dblStress[iPart][iKind2+20]);	// 하단좌단.

		StressLcase.dStop[i] = dStop;
		StressLcase.dSbot[i] = dSbot;
		StressLcase.dStl[i] = dStl;
		StressLcase.dStr[i] = dStr;
		StressLcase.dSbl[i] = dSbl;
		StressLcase.dSbr[i] = dSbr;
	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_LoadCaseStressGilc(ElemPairK ElemK, T_SBCF_D& StrMaxData, T_SBCF_D& StrMinData, ADGNSTRESS& aStressLcase)
{

	aStressLcase.RemoveAll();
	aStressLcase.SetSize(cFORC_CON);

	T_STRB_D StrData;
	for (int i = 0; i < cFORC_CON; ++i)
	{
		T_SBCF_D &SbcfData = (i % 2 == 0 ? StrMaxData : StrMinData);

		StrData.Initialize();
		int nForceType = i / 2;
		Get_ConvertStrb(nForceType, SbcfData, StrData);

		Get_LoadCaseStressGilc(ElemK, StrData, aStressLcase[i]);
	}
	return TRUE;
}

BOOL CCRCForceCtrl::Get_LoadCaseStressSlab(ElemPairK ElemK, T_STRB_D& StrData, _DGN_STRS_CRC& StressLcase)
{
	// Get Elem Data.
	T_ELEM_D ElemD;
	if (!m_pPostCtrl->GetElemPost(ElemK.first, ElemD))	return FALSE;
	////////////////////////////
	// Get Sect Data.
	T_SECT_D SectD;
	if (!m_pPostCtrl->GetSectPost(ElemD.elpro, SectD))	return FALSE;
	BOOL bIs7Dof = SectD.SectBefore.bConsiderWarpingEffect;

	int nSectType = SectD.nStype;
	BOOL bTapered = (SectD.nStype == D_SECT_TYPE_TAPERED);
	if (bTapered == TRUE) nSectType = SectD.SectBefore.nStype;

	// Force.
	_DGN_FORC_CRC ForceLcase;
	for (int i = 0; i < cPOSI_CRC; ++i)
	{
		int iPart = (i == 0 ? 0 : 3);
		int iKind = (i == 0 ? 0 : 6);
		ForceLcase.dFxx[i] = StrData.dblForce[iPart][iKind + 0];
		ForceLcase.dFyy[i] = StrData.dblForce[iPart][iKind + 1];
		ForceLcase.dFzz[i] = StrData.dblForce[iPart][iKind + 2];
		ForceLcase.dMux[i] = StrData.dblForce[iPart][iKind + 3];
		ForceLcase.dMuy[i] = StrData.dblForce[iPart][iKind + 4];
		ForceLcase.dMuz[i] = StrData.dblForce[iPart][iKind + 5];
		ForceLcase.dMbi[i] = StrData.dblForce[iPart][Mbi_Id + i]; // Bi-moment
		ForceLcase.dTst[i] = StrData.dblForce[iPart][Mst_Id + i]; // Pure torsion
		ForceLcase.dTwp[i] = StrData.dblForce[iPart][Mwp_Id + i]; // Warping torsion
	}

	Set_DimTypeForc(ForceLcase);

	T_STRSPROP_D StrsPropD;
	if (bIs7Dof)
	{
		m_pSectInfo->ReadSectPostProp(ElemK.first, StrsPropD);
	}

	double Er = SectD.SectBefore.Matl_Elast;
	double Bc = SectD.SectAfter.SectJ.Size[0];
	double tc = SectD.SectAfter.SectJ.Size[1];
	double Hh = SectD.SectAfter.SectJ.Size[2];

	double dys1 = 0.0, dys2 = 0.0, dys3 = 0.0, dys4 = 0.0;
	double dzs1 = 0.0, dzs2 = 0.0, dzs3 = 0.0, dzs4 = 0.0;
	double dYbars = 0.0;
	double dZbars = 0.0;

	double dYbar_c = 0.0, dZbar_c = 0.0;
	double dyc2 = 0.0, dzc2 = 0.0;

	//if (nSectType==D_SECT_TYPE_COMPO_CI || nSectType==D_SECT_TYPE_COMPO_CT ||
	//    nSectType==D_SECT_TYPE_COMPO_PC)

	for (int i = 0; i < cPOSI_CRC; ++i)
	{
		T_STRSPOST_BASE &StrsBase = (i == 0) ? m_StrsPost.StrsBaseI : m_StrsPost.StrsBaseJ;
		double dArea = StrsBase.dArea;
		double dQyb = StrsBase.dQyb;
		double dQzb = StrsBase.dQzb;
		double dIyy = StrsBase.dIyy * StrsBase.dScaleIy;
		double dIzz = StrsBase.dIzz;
		double dIw = 0.0;

		double dCy0 = StrsBase.dyzM[0][0];	double dCz0 = StrsBase.dyzM[1][0] - StrsBase.dMoveTop;
		double dCy1 = StrsBase.dyzM[0][1];	double dCz1 = StrsBase.dyzM[1][1] - StrsBase.dMoveTop;
		double dCy2 = StrsBase.dyzM[0][2];	double dCz2 = StrsBase.dyzM[1][2] - StrsBase.dMoveBot;
		double dCy3 = StrsBase.dyzM[0][3];	double dCz3 = StrsBase.dyzM[1][3] - StrsBase.dMoveBot;

		int nPosIJ = (i == 0) ? 0 : 4;
		T_SECT_STIFFNESS &StiffD = StrsPropD.PropB[nPosIJ].Stiff.Stiffness;
		if (bIs7Dof)
		{
			dArea = StiffD.Area;
			//dQyb	= StrsBase[i+j].dQyb;
			//dQzb	= StrsBase[i+j].dQzb;
			dIyy = StiffD.Ryy * StrsBase.dScaleIy;
			dIzz = StiffD.Rzz;
			dIw = StiffD.dIw;

			dCy0 = StiffD.dx1;  dCz0 = StiffD.dy1;
			dCy1 = StiffD.dx2;  dCz1 = StiffD.dy2;
			dCy2 = StiffD.dx3;	dCz2 = StiffD.dy3;
			dCy3 = StiffD.dx4;	dCz3 = StiffD.dy4;
		}

		T_SECT_SECTBASE_D* pSectBefore = (i == 1 && bTapered) ? &SectD.SectBefore.SectJ : &SectD.SectBefore.SectI;
		T_SECT_SECTBASE_D* pSectAfter = (i == 1 && bTapered) ? &SectD.SectAfter.SectJ : &SectD.SectAfter.SectI;

		T_SECT_STIFFNESS* pBeforeStiff;
		if (bTapered)
		{
			pBeforeStiff = &pSectBefore->Stiffness;
		}
		else
		{
			pBeforeStiff = &SectD.SectBefore.Stiffness;
		}

		if (nSectType == D_SECT_TYPE_COMPO_G)
		{
			if (pSectBefore->aGeneralPart.GetSize() != 2) return FALSE;

			const T_GSEC_PART &GBase = pSectBefore->aGeneralPart[0];
			const T_GSEC_PART &GPart = pSectBefore->aGeneralPart[1];

			Er = (GPart.dElastic < cDgn_Zero) ? 0.0 : GBase.dElastic / GPart.dElastic;

			dYbars = GPart.YBar;
			dZbars = GPart.ZBar;
			dys1 = GPart.Stiffness.dx1;
			dys2 = GPart.Stiffness.dx2;
			dys3 = GPart.Stiffness.dx3;
			dys4 = GPart.Stiffness.dx4;
			dzs1 = GPart.Stiffness.dy1;
			dzs2 = GPart.Stiffness.dy2;
			dzs3 = GPart.Stiffness.dy3;
			dzs4 = GPart.Stiffness.dy4;

			dYbar_c = pSectAfter->Design.YBar;
			dZbar_c = pSectAfter->Design.ZBar;
			dyc2 = pSectAfter->Stiffness.dx2;
			dzc2 = pSectAfter->Stiffness.dy2;
		}
		else
		{
			if (bTapered == FALSE)
			{
				dYbar_c = SectD.SectAfter.Design.YBar;
				dZbar_c = SectD.SectAfter.Design.ZBar;
				dyc2 = SectD.SectAfter.Stiffness.dx2;
				dzc2 = SectD.SectAfter.Stiffness.dy2;
			}
			else
			{
				dYbar_c = pSectAfter->Design.YBar;
				dZbar_c = pSectAfter->Design.ZBar;
				dyc2 = pSectAfter->Stiffness.dx2;
				dzc2 = pSectAfter->Stiffness.dy2;
			}

			double dBg = pBeforeStiff->Cym + pBeforeStiff->Cyp;
			double dHg = pBeforeStiff->Czm + pBeforeStiff->Czp;
			double dtc2 = 0.5*tc;
			dYbars = Bc < dBg ? pBeforeStiff->Cym : 0.5*Bc;
			dZbars = dHg + Hh + dtc2;
			dys1 = -dYbars;
			dys2 = dYbars;
			dys3 = dys2;
			dys4 = dys1;
			dzs1 = dZbars + dtc2 - dZbar_c;
			dzs2 = dzs1;
			dzs3 = dZbars - dtc2 - dZbar_c;
			dzs4 = dzs3;

		}

		// 슬래브와 합성의 차이
		double dDy = dYbar_c - dYbars;
		double dDz = dZbar_c - dZbars;
		// 합성순단면과 합성환산단면의 차이
		double dTy = dCy1 - dyc2;
		double dTz = dCz1 - dzc2;

		dys1 = dys1 - dTy;
		dys2 = dys2 - dTy;
		dys3 = dys3 - dTy;
		dys4 = dys4 - dTy;
		dzs1 = dzs1 - dTz;
		dzs2 = dzs2 - dTz;
		dzs3 = dzs3 - dTz;
		dzs4 = dzs4 - dTz;

		double dSy0 = (dzs1 == 0.0 ? 0.0 : dIyy / dzs1);	double dSz0 = (dys1 == 0.0 ? 0.0 : dIzz / dys1);
		double dSy1 = (dzs2 == 0.0 ? 0.0 : dIyy / dzs2);	double dSz1 = (dys2 == 0.0 ? 0.0 : dIzz / dys2);
		double dSy2 = (dzs3 == 0.0 ? 0.0 : dIyy / dzs3);	double dSz2 = (dys3 == 0.0 ? 0.0 : dIzz / dys3);
		double dSy3 = (dzs4 == 0.0 ? 0.0 : dIyy / dzs4);	double dSz3 = (dys4 == 0.0 ? 0.0 : dIzz / dys4);

		//mqc17512 (Part2:Slab Top, Bot 계산)
		double dCyp = max(dys2, dys3);	// y-Right.
		double dCym = min(dys1, dys4);	// y-Left.
		double dCzp = max(dzs1, dzs2);	// z-Top.
		double dCzm = min(dzs3, dzs4);	// z-Bot.
		double dSyp = (dCzp == 0.0 ? 0.0 : dIyy / dCzp);
		double dSym = (dCzm == 0.0 ? 0.0 : dIyy / dCzm);
		double dSzp = (dCyp == 0.0 ? 0.0 : dIzz / dCyp);
		double dSzm = (dCym == 0.0 ? 0.0 : dIzz / dCym);

		// Tension(+), Compression(-).
		double dSxx = (dArea == 0.0 ? 0.0 : ForceLcase.dFxx[i] / dArea);			// Sxx.
		double dSyy = (dIzz == 0.0 ? 0.0 : ForceLcase.dFyy[i] * dQzb / dIzz);	// Syy.
		double dSzz = (dIyy == 0.0 ? 0.0 : ForceLcase.dFzz[i] * dQyb / (dIyy / StrsBase.dScaleIy));	// Szz.
		double dByp = (-1)*(dSyp == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSyp);			// Byp.
		double dBym = (-1)*(dSym == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSym);			// Bym.
		double dBzp = (dSzp == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSzp);			// Bzp.
		double dBzm = (dSzm == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSzm);			// Bzm.
		// For Combined Stresses.
		// Change by ZINU.('04.12.27). Multiply (-1) at dBz0,dBz1,dBz2,dBz3.
		double dBy0 = (-1)*(dSy0 == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSy0);	// By0.
		double dBy1 = (-1)*(dSy1 == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSy1);	// By1.
		double dBy2 = (-1)*(dSy2 == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSy2);	// By2.
		double dBy3 = (-1)*(dSy3 == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSy3);	// By3.
		double dBz0 = (-1)*(dSz0 == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSz0);	// Bz0.
		double dBz1 = (-1)*(dSz1 == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSz1);	// Bz1.
		double dBz2 = (-1)*(dSz2 == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSz2);	// Bz2.
		double dBz3 = (-1)*(dSz3 == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSz3);	// Bz3.
		double dBi0 = 0.0, dBi1 = 0.0, dBi2 = 0.0, dBi3 = 0.0;
		//     if (bIs7Dof)
		//     {
		//       double dMwIw = (dIw==0.0) ? 0.0 : (-1)*ForceLcase.dMbi[i]/dIw;
		//       dBi0 = dMwIw * StiffD.dw1;
		//       dBi1 = dMwIw * StiffD.dw2;
		//       dBi2 = dMwIw * StiffD.dw3;
		//       dBi3 = dMwIw * StiffD.dw4;          
		//     }
		// Combined Stresses.
		int iPart = (i == 0 ? 0 : 3);
		double dStop = dSxx + dByp;				  // 상단.
		double dSbot = dSxx + dBym;				  // 하단.
		double dStl = dSxx + dBy0 + dBz0 + dBi0; //(m_iDimType !=2 ? dSxx + dBy0 + dBz0 : StrData.dblStress[iPart][iKind2+16]);	// 상단좌단.
		double dStr = dSxx + dBy1 + dBz1 + dBi1; //(m_iDimType !=2 ? dSxx + dBy1 + dBz1 : StrData.dblStress[iPart][iKind2+18]);	// 상단우단.
		double dSbr = dSxx + dBy2 + dBz2 + dBi2; //(m_iDimType !=2 ? dSxx + dBy2 + dBz2 : StrData.dblStress[iPart][iKind2+22]);	// 하단우단.
		double dSbl = dSxx + dBy3 + dBz3 + dBi3; //(m_iDimType !=2 ? dSxx + dBy3 + dBz3 : StrData.dblStress[iPart][iKind2+20]);	// 하단좌단.

		if (Er > cDGN_Zero)
		{
			dStop /= Er;
			dSbot /= Er;
			dStl /= Er;
			dStr /= Er;
			dSbl /= Er;
			dSbr /= Er;
		}

		StressLcase.dStop[i] = dStop;
		StressLcase.dSbot[i] = dSbot;
		StressLcase.dStl[i] = dStl;
		StressLcase.dStr[i] = dStr;
		StressLcase.dSbl[i] = dSbl;
		StressLcase.dSbr[i] = dSbr;
	}

	return TRUE;

}

BOOL CCRCForceCtrl::Get_LoadCaseStressSlab(ElemPairK ElemK, T_SBCF_D& StrMaxData, T_SBCF_D& StrMinData, _DGN_STRS_CRC aStrsLcase[12])
{
	T_STRB_D StrData;
	for (int i = 0; i < cFORC_CON; ++i)
	{
		T_SBCF_D &SbcfData = (i % 2 == 0 ? StrMaxData : StrMinData);

		StrData.Initialize();
		int nForceType = i / 2;
		Get_ConvertStrb(nForceType, SbcfData, StrData);

		_DGN_STRS_CRC StressLcase;
		Get_LoadCaseStressSlab(ElemK, StrData, aStrsLcase[i]);

	}
	return TRUE;
}

BOOL CCRCForceCtrl::Get_LoadCaseStss(T_STSS_D& StrData, _DGN_SHRS_ADD& StssLcase)
{
	// 1.Axial X Normal Stress
	// 2.Moment-y X Normal Stress 
	// 3.Moment-z X Normal Stress       
	// 4.강봉 X Normal Stres
	// 5.Sum
	// 6.강봉 z Normal Stress
	// 7.Shear z Shear Stress
	// 8.Torsion Shear Stress  
	// 9.강봉 Shear Stress
	// 10.비틀림 제외 사인장 응력 
	// 11.비틀림 포함 사인장 응력 / 주응력 최대
	// 12.주응력 최소  
	// 13.warping normal stress
	// 14.pure torsion xy
	// 15.warping torsion xy
	// 16.pure torsion xz
	// 17.warping torsion xz
	// 18.summation shear xy
	// 19.summation shear xz
	for (int i = 0; i < cPOSI_CRC; ++i)
	{
		int iPart = (i == 0 ? 0 : 4);
		for (int j = 0; j < 10; ++j)
		{
			for (int k = 0; k < 19; ++k)
			{
				StssLcase.dShr[i][j][k] = StrData.dblStress[iPart][j][k];
			}
			double dSxx = StrData.dblStress[iPart][j][0];
			double dByi = StrData.dblStress[iPart][j][1];
			double dSxi = StrData.dblStress[iPart][j][3];
			StssLcase.dShr[i][j][2] = (m_iDimType == 0 ? 0.0 : StrData.dblStress[iPart][j][2]); // 3.Moment-z X Normal Stress
			StssLcase.dShr[i][j][4] = (m_iDimType != 2 ? dSxx + dByi + dSxi : StrData.dblStress[iPart][j][4]); // 5.Sum
			StssLcase.dShr[i][j][7] = (m_iDimType == 0 ? 0.0 : StrData.dblStress[iPart][j][7]); // 8.Torsion Shear Stress
			if (m_iDimType == 0)
			{
				for (int l = 0; l < 7; ++l) StssLcase.dShr[i][j][l + 12] = 0.0;
			}
		}
	}
	// 10,11,12는 할당하지만 사용하지 않음.
	return TRUE;
}

BOOL CCRCForceCtrl::Get_LoadCaseStss(ElemPairK ElemK, BOOL bTndnPs, T_STRB_D& StrData, _DGN_SHRS_ADD& StssLcase)
{

	StssLcase.Initialize();

	int i = 0, j = 0, k = 0; // dyzM(4군데).
	// Get Elem Data.
	T_ELEM_D ElemD;
	ElemD.Initialize();
	if (!m_pPostCtrl->GetElemPost(ElemK.first, ElemD))	return FALSE;
	T_SECT_K SectK = ElemD.elpro;
	// Get Sect Data.
	T_SECT_D SectD;
	SectD.Initialize();
	if (!m_pPostCtrl->GetSectPost(SectK, SectD))	return FALSE;
	T_SECT_K OrgSectK = m_pPostCtrl->GetOrgSectKeyPost(SectK);

	BOOL bComposit = FALSE;
	BOOL bCompositGen = FALSE;
	double dtc = 0.0;
	double dHh = 0.0;
	if (SectD.nStype == D_SECT_TYPE_COMPO_CI || SectD.nStype == D_SECT_TYPE_COMPO_CT || SectD.nStype == D_SECT_TYPE_COMPO_PC)
	{
		bComposit = TRUE;
		//   double dBc = SectD.SectAfter.SectJ.Size[0];
		dtc = SectD.SectAfter.SectJ.Size[1];
		dHh = SectD.SectAfter.SectJ.Size[2];
	}
	else if (SectD.nStype == D_SECT_TYPE_COMPO_G)
	{
		ASSERT(0);
		bCompositGen = TRUE;
	}

	BOOL bIs7Dof = SectD.SectBefore.bConsiderWarpingEffect;
	BOOL bIsPscOpen = CDBLib::IsPscOpenSect(SectD.SectBefore.Shape);

	// Get Rbar Data.
	T_RPSC_D RpscMbar, RpscSbar;
	RpscMbar.Initialize();
	m_pAttrCtrl->GetRpscByConsiderRbar(TRUE, OrgSectK, RpscMbar);
	RpscSbar.Initialize();
	m_pAttrCtrl->GetRpscByConsiderRbar(FALSE, OrgSectK, RpscSbar);
	// Remove by ZINU.('06.04.24). Use Data at StrsPost.
	/*
	// Add by ZINU.('04.12.17). Set Effective Width Scale Factor.
	double dScaleIy=1.0, dScaleZt=1.0, dScaleZb=1.0;
	T_EWSF_D EwsfD;
	EwsfD.Initialize();
	if(m_pAttrCtrl->GetEwsfElem(ElemK,EwsfD))
	{
	dScaleIy = EwsfD.dScaleFactor;
	dScaleZt = EwsfD.dZtopFactor;
	dScaleZb = EwsfD.dZbotFactor;
	}
	*/
	// Force.
	_DGN_FORC_CRC ForceLcase;
	for (j = 0; j < cPOSI_CRC; ++j)
	{
		int iPart = (j == 0 ? 0 : 3);
		int iKind = (j == 0 ? 0 : 6);
		ForceLcase.dFxx[j] = StrData.dblForce[iPart][iKind + 0];
		ForceLcase.dFyy[j] = StrData.dblForce[iPart][iKind + 1];
		ForceLcase.dFzz[j] = StrData.dblForce[iPart][iKind + 2];
		ForceLcase.dMux[j] = StrData.dblForce[iPart][iKind + 3];
		ForceLcase.dMuy[j] = StrData.dblForce[iPart][iKind + 4];
		ForceLcase.dMuz[j] = StrData.dblForce[iPart][iKind + 5];
		ForceLcase.dMbi[j] = StrData.dblForce[iPart][Mbi_Id + j]; // Bi-moment
		ForceLcase.dTst[j] = StrData.dblForce[iPart][Mst_Id + j]; // Pure torsion
		ForceLcase.dTwp[j] = StrData.dblForce[iPart][Mwp_Id + j]; // Warping torsion
	}

	Set_DimTypeForc(ForceLcase);

	T_STRSPROP_D StrsPropD;
	if (bIs7Dof || bIsPscOpen)
	{
		m_pSectInfo->ReadSectPostProp(ElemK.first, StrsPropD);
	}

	for (j = 0; j < cPOSI_CRC; ++j)
	{
		// Get Depth.
		int iPosi = (CDBLib::IsSectI(j == 0, SectD.nStype) ? 0 : 1);
		T_SECT_STIFFNESS &SectStiff = (iPosi == 0) ? SectD.SectBefore.SectI.Stiffness : SectD.SectBefore.SectJ.Stiffness;
		double dCzp = SectStiff.Czp;
		double dCzm = SectStiff.Czm;
		double dzDim = 0.0;
		if (bCompositGen) dzDim = m_dHeight[i];
		else             dzDim = dCzp + dCzm + (bComposit ? dtc : 0.0);

		int iPosiM = (RpscMbar.bMbarJ && j != 0 ? 1 : 0);
		int iMbarNum = RpscMbar.Mbar[iPosiM].GetSize();
		// Change by ZINU.('04.06.30). If No Rbar, Effective Depth is Total Depth (by Kouno).
		double ddT = (iMbarNum == 0 ? 0.0 : dCzp);
		double ddB = (iMbarNum == 0 ? 0.0 : dCzm);
		for (k = 0; k < iMbarNum; ++k)
		{
			T_RPSC_MBAR &Mbar = RpscMbar.Mbar[iPosiM].GetAt(k);
			ddT = min(ddT, (Mbar.iStaZRef == 0 ? Mbar.dStaZ : dzDim - Mbar.dStaZ));
			ddB = min(ddB, (Mbar.iStaZRef == 1 ? Mbar.dStaZ : dzDim - Mbar.dStaZ));
			if (ddT < 0.0) { ddT = 0.0; /*ASSERT(0);*/ }
			if (ddB < 0.0) { ddB = 0.0; /*ASSERT(0);*/ }
		}

		T_STRSPOST_BASE &StrsBase = (j == 0 ? m_StrsPost.StrsBaseI : m_StrsPost.StrsBaseJ);
		T_STRSPROP_BASE &StrsProp = (j == 0) ? StrsPropD.PropB[0] : StrsPropD.PropB[4];
		double dArea = StrsBase.dArea;
		double dIyy = StrsBase.dIyy * StrsBase.dScaleIy;
		double dIzz = StrsBase.dIzz;
		double dJ = 0.0;
		double dIp = dIyy + dIzz;
		double dIw = 0.0;

		int nPosIJ = (j == 0) ? 0 : 4;
		T_SECT_STIFFNESS &StiffD = StrsProp.Stiff.Stiffness;
		if (bIs7Dof || bIsPscOpen)
		{
			dArea = StiffD.Area;
			//dQyb	= StrsBase[i+j].dQyb;
			//dQzb	= StrsBase[i+j].dQzb;
			dIyy = StiffD.Ryy * StrsBase.dScaleIy;
			dIzz = StiffD.Rzz;
			dIw = StiffD.dIw;
			dJ = StiffD.Rxx;
			dIp = dIyy + dIzz;

			//dCy0 = StiffD.dx1;  dCz0 = StiffD.dy1;
			//dCy1 = StiffD.dx2;  dCz1 = StiffD.dy2;
			//dCy2 = StiffD.dx3;	dCz2 = StiffD.dy3;
			//dCy3 = StiffD.dx4;	dCz3 = StiffD.dy4;
		}

		// Tendon Data.
		// Change by ZINU.('04.12.06). Set Tndn Reduction Factor (_CH=0.6, else=1.0).
		// Change by ZINU.('05.09.09). Add bTndnPs Option.
		double dTndnPs = 0.0, dTndnDist = 0.0, dTndnRad = 0.0, dCngRad = 0.0, dCngSign = 0.0;
		if (bTndnPs)
		{
			int iPosiS = (RpscSbar.bSbarJ && j != 0 ? 1 : 0);
			dTndnPs = (RpscSbar.Sbar[iPosiS].bTndnExist ? RpscSbar.Sbar[iPosiS].dTndnPs * RpscSbar.Sbar[iPosiS].dTndnFactor : 0.0);
			dTndnDist = (RpscSbar.Sbar[iPosiS].bTndnExist ? RpscSbar.Sbar[iPosiS].dTndnDist : 0.0);
			dTndnRad = (RpscSbar.Sbar[iPosiS].bTndnExist ? RpscSbar.Sbar[iPosiS].dTndnTheta / (180. / m_dPi) : 0.0);	// Deg -> Rad.
			// Change by ZINU.('05.11.19). Make All Deg -180 ~ 180 Deg.
			dCngRad = fmod(dTndnRad, m_dPi);
			dCngSign = (dCngRad >= 0.0 ? 1.0 : -1.0);
		}

		double dWcoef[10] = { 0.0 };
		double dXZsh[10] = { 0.0 };
		double dXYsh[10] = { 0.0 };
		if (bIs7Dof)
		{
			dWcoef[0] = StrsProp.Stiff.Stiffness.dw1;
			dWcoef[1] = StrsProp.Stiff.Stiffness.dw2;
			dWcoef[2] = StrsProp.Stiff.Stiffness.dw3;
			dWcoef[3] = StrsProp.Stiff.Stiffness.dw4;
			dWcoef[4] = StrsProp.Stiff.dw5;
			dWcoef[5] = StrsProp.Stiff.dw6;
			dWcoef[6] = StrsProp.Stiff.dw7;
			dWcoef[7] = StrsProp.Stiff.dw8;
			dWcoef[8] = StrsProp.Stiff.dw9;
			dWcoef[9] = StrsProp.Stiff.dw10;
		}

		if (bIs7Dof || bIsPscOpen)
		{
			dXYsh[0] = StrsProp.Stiff.Stiffness.dxy1;
			dXYsh[1] = StrsProp.Stiff.Stiffness.dxy2;
			dXYsh[2] = StrsProp.Stiff.Stiffness.dxy3;
			dXYsh[3] = StrsProp.Stiff.Stiffness.dxy4;
			dXYsh[4] = StrsProp.Stiff.dxy5;
			dXYsh[5] = StrsProp.Stiff.dxy6;
			dXYsh[6] = StrsProp.Stiff.dxy7;
			dXYsh[7] = StrsProp.Stiff.dxy8;
			dXYsh[8] = StrsProp.Stiff.dxy9;
			dXYsh[9] = StrsProp.Stiff.dxy10;
			//
			dXZsh[0] = StrsProp.Stiff.Stiffness.dxz1;
			dXZsh[1] = StrsProp.Stiff.Stiffness.dxz2;
			dXZsh[2] = StrsProp.Stiff.Stiffness.dxz3;
			dXZsh[3] = StrsProp.Stiff.Stiffness.dxz4;
			dXZsh[4] = StrsProp.Stiff.dxz5;
			dXZsh[5] = StrsProp.Stiff.dxz6;
			dXZsh[6] = StrsProp.Stiff.dxz7;
			dXZsh[7] = StrsProp.Stiff.dxz8;
			dXZsh[8] = StrsProp.Stiff.dxz9;
			dXZsh[9] = StrsProp.Stiff.dxz10;
		}

		// Change by ZINU.('04.12.01). Modify Checking Position. dyzV(6) -> dyzM(4) + dyzV(6).
		for (k = 0; k < 10; ++k)	// 0~3=dyzM, 4=TL, 5=TR, 6=CL, 7=CR, 8=BL, 9=BR.
		{
			// Change by ZINU.('05.11.09). Apply dScaleZ, Position 1~4 -> Position 1~4 + 5,6,9,10.
			// Change by ZINU.('06.04.24). Consider N.A by Eeffective Width Scale Factor.
			// Change by ZINU.('06.05.23). dMoveZ : Top(1,2,5,6),Bot(3,4,9,10) -> dCzi Sign.
			double dCyi = (k < 4 ? StrsBase.dyzM[0][k] : StrsBase.dyzV[0][k - 4]);
			double dCzi = (k < 4 ? StrsBase.dyzM[1][k] : StrsBase.dyzV[1][k - 4]);
			double dMoveZ = 0.0;
			if (k == 0 || k == 1)									dMoveZ = StrsBase.dMoveTop;
			else if (k == 2 || k == 3)									dMoveZ = StrsBase.dMoveBot;
			else if (k == 4 || k == 5 || k == 8 || k == 9)	dMoveZ = (dCzi > 0.0 ? StrsBase.dMoveTop : StrsBase.dMoveBot);
			dCzi -= dMoveZ;
			double dZyi = (dCzi == 0.0 ? 0.0 : dIyy / dCzi);
			double dZzi = (dCyi == 0.0 ? 0.0 : dIzz / dCyi);
			double dQ = (k < 4 ? 0.0 : StrsBase.dQ[(k - 4) / 2]);
			double db = (k < 4 ? 0.0 : StrsBase.db[(k - 4) / 2]);
			double dd = (ForceLcase.dMuy[j] > 0.0 ? dzDim - ddB : dzDim - ddT);
			double da = dTndnDist;

			// Kt값을 위치별로 받음 - PKS
			//      double dKt	= StrsBase.dKt;
			double dKt = 0.0;
			if (k == 0)      dKt = StrsBase.dKtweb[0]; // stress point 0
			else if (k == 1) dKt = StrsBase.dKtweb[1]; // 
			else if (k == 2) dKt = StrsBase.dKtweb[5];
			else if (k == 3) dKt = StrsBase.dKtweb[4];
			else          dKt = StrsBase.dKtweb[k - 4];
			double dwi = dWcoef[k];

			// For Combined Stresses.
			// Change by ZINU.('04.12.27). Multiply (-1) at dBzi.
			double dSxx = (dArea == 0.0 ? 0.0 : ForceLcase.dFxx[j] / dArea);							// Sxx.
			double dByi = (-1)*(dZyi == 0.0 ? 0.0 : ForceLcase.dMuy[j] / dZyi);							// Byi.
			double dBzi = (-1)*(dZzi == 0.0 ? 0.0 : ForceLcase.dMuz[j] / dZzi);							// Bzi.
			double dBIi = (1)*(dIw == 0.0 ? 0.0 : ForceLcase.dMbi[j] / dIw * dwi);	          // Mw/Iw*w, Bi-moment
			double dSxi = (-1)*(dArea == 0.0 ? 0.0 : dTndnPs * fabs(cos(dTndnRad)) / dArea);		// Sxi.
			double dSzi = (-1)*(db*da == 0.0 ? 0.0 : dTndnPs * fabs(sin(dTndnRad)) / (db*da));	// Szi.
			double dTas = (dIyy*db == 0.0 ? 0.0 : ForceLcase.dFzz[j] * dQ / ((dIyy / StrsBase.dScaleIy)*db));			// Tau_s.
			double dTat = (dKt == 0.0 ? 0.0 : ForceLcase.dMux[j] / dKt);								// Tau_t.
			double dTap = (db*da == 0.0 ? 0.0 : dTndnPs * dCngSign*cos(dCngRad) / (db*da));// Tau_p.
			//double dTasm=			 (db*dd==0.0 ? 0.0 : ForceLcase.dFzz[j]/(db*dd));						// Tau_s(average).
			//double dTatm=	dTat;																														// Tau_t(average).
			double dTat_xy = 0.0, dTat_xz = 0.0;
			double dSwt = 0.0;
			double dSwt_xy = 0.0;
			if (bIs7Dof || bIsPscOpen)
			{
				Calc_Tat(bIs7Dof, dCyi, dCzi, dIp, dJ, ForceLcase.dMux[j], ForceLcase.dTst[j], ForceLcase.dTwp[j], dXYsh[k], dXZsh[k], dTat_xy, dTat_xz, dSwt, dSwt_xy, dTat);
			}
			double dSxm = dSxx + dByi + dBzi + dBIi;
			double dSx = dSxm + dSxi;

			// Change by ZINU.('05.11.16). Consider Sign(+/-) of dTat.
			if (k == 0 || k == 3 || k == 4 || k == 6 || k == 8)	dTat *= -1;	// Left Side.

			StssLcase.dShr[j][k][0] = dSxx;                                     // 1.Axial X Normal Stress
			StssLcase.dShr[j][k][1] = dByi;                                     // 2.Moment-y X Normal Stress 
			StssLcase.dShr[j][k][2] = (m_iDimType == 0 ? 0.0 : dBzi);             // 3.Moment-z X Normal Stress       
			StssLcase.dShr[j][k][3] = dSxi;                                     // 4.강봉 X Normal Stres
			StssLcase.dShr[j][k][4] = (m_iDimType != 2 ? dSxx + dByi + dSxi : dSx);   // 5.Sum
			StssLcase.dShr[j][k][5] = dSzi;                                     // 6.강봉 z Normal Stress
			StssLcase.dShr[j][k][6] = dTas;                                     // 7.Shear z Shear Stress
			StssLcase.dShr[j][k][7] = (m_iDimType == 0 ? 0.0 : dTat);             // 8.Torsion Shear Stress  
			StssLcase.dShr[j][k][8] = dTap;                                     // 9.강봉 Shear Stress   
			StssLcase.dShr[j][k][16] = dSwt;                                     // 17.warping torsion xz   
		}
	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_LoadCaseStss(ElemPairK ElemK, BOOL bTndnPs, T_SBCF_D& StrMaxData, T_SBCF_D& StrMinData, ADGNSHRSADD &aStssLcase)
{

	aStssLcase.RemoveAll();

	int i = 0, j = 0, k = 0; // dyzM(4군데).
	// Get Elem Data.
	T_ELEM_D ElemD;
	ElemD.Initialize();
	if (!m_pPostCtrl->GetElemPost(ElemK.first, ElemD))	return FALSE;
	T_SECT_K SectK = ElemD.elpro;
	// Get Sect Data.
	T_SECT_D SectD;
	SectD.Initialize();
	if (!m_pPostCtrl->GetSectPost(SectK, SectD))	return FALSE;
	T_SECT_K OrgSectK = m_pPostCtrl->GetOrgSectKeyPost(SectK);

	BOOL bComposit = FALSE;
	BOOL bCompositGen = FALSE;
	double dtc = 0.0;
	double dHh = 0.0;
	if (SectD.nStype == D_SECT_TYPE_COMPO_CI || SectD.nStype == D_SECT_TYPE_COMPO_CT || SectD.nStype == D_SECT_TYPE_COMPO_PC)
	{
		bComposit = TRUE;
		//   double dBc = SectD.SectAfter.SectJ.Size[0];
		dtc = SectD.SectAfter.SectJ.Size[1];
		dHh = SectD.SectAfter.SectJ.Size[2];
	}
	else if (SectD.nStype == D_SECT_TYPE_COMPO_G)
	{
		ASSERT(0);
		bCompositGen = TRUE;
	}

	// Get Rbar Data.
	T_RPSC_D RpscMbar, RpscSbar;
	RpscMbar.Initialize();
	m_pAttrCtrl->GetRpscByConsiderRbar(TRUE, OrgSectK, RpscMbar);
	RpscSbar.Initialize();
	m_pAttrCtrl->GetRpscByConsiderRbar(FALSE, OrgSectK, RpscSbar);
	// Remove by ZINU.('06.04.24). Use Data at StrsPost.
	/*
	// Add by ZINU.('04.12.17). Set Effective Width Scale Factor.
	double dScaleIy=1.0, dScaleZt=1.0, dScaleZb=1.0;
	T_EWSF_D EwsfD;
	EwsfD.Initialize();
	if(m_pAttrCtrl->GetEwsfElem(ElemK,EwsfD))
	{
	dScaleIy = EwsfD.dScaleFactor;
	dScaleZt = EwsfD.dZtopFactor;
	dScaleZb = EwsfD.dZbotFactor;
	}
	*/
	BOOL bIs7Dof = SectD.SectBefore.bConsiderWarpingEffect;
	BOOL bIsPscOpen = CDBLib::IsPscOpenSect(SectD.SectBefore.Shape);
	T_STRSPROP_D StrsPropD;
	if (bIs7Dof || bIsPscOpen)
	{
		m_pSectInfo->ReadSectPostProp(ElemK.first, StrsPropD);
	}

	for (i = 0; i < cFORC_CON; ++i)
	{
		T_SBCF_D &SbcfData = (i % 2 == 0) ? StrMaxData : StrMinData;

		// Force.
		_DGN_FORC_CRC ForceLcase;
		for (j = 0; j < cPOSI_CRC; ++j)
		{
			int iPart = (j == 0 ? 0 : 3);
			int iKind = (j == 0 ? 0 : 6);
			ForceLcase.dFxx[j] = SbcfData.dblForce[iPart][j][i / 2][0];
			ForceLcase.dFyy[j] = SbcfData.dblForce[iPart][j][i / 2][1];
			ForceLcase.dFzz[j] = SbcfData.dblForce[iPart][j][i / 2][2];
			ForceLcase.dMux[j] = SbcfData.dblForce[iPart][j][i / 2][3];
			ForceLcase.dMuy[j] = SbcfData.dblForce[iPart][j][i / 2][4];
			ForceLcase.dMuz[j] = SbcfData.dblForce[iPart][j][i / 2][5];
			ForceLcase.dMbi[j] = SbcfData.dblForce[iPart][j][i / 2][6];
			ForceLcase.dTst[j] = SbcfData.dblForce[iPart][j][i / 2][7];
			ForceLcase.dTwp[j] = SbcfData.dblForce[iPart][j][i / 2][8];
		}

		Set_DimTypeForc(ForceLcase);

		_DGN_SHRS_ADD StssLcase;
		StssLcase.Initialize();
		for (j = 0; j < cPOSI_CRC; ++j)
		{
			// Get Depth.
			int iPosi = (CDBLib::IsSectI(j == 0, SectD.nStype) ? 0 : 1);
			T_SECT_STIFFNESS &SectStiff = (iPosi == 0) ? SectD.SectBefore.SectI.Stiffness : SectD.SectBefore.SectJ.Stiffness;
			double dCzp = SectStiff.Czp;
			double dCzm = SectStiff.Czm;
			double dzDim = 0.0;
			if (bCompositGen) dzDim = m_dHeight[i];
			else             dzDim = dCzp + dCzm + (bComposit ? dtc : 0.0);

			int iPosiM = (RpscMbar.bMbarJ && j != 0 ? 1 : 0);
			int iMbarNum = RpscMbar.Mbar[iPosiM].GetSize();
			// Change by ZINU.('04.06.30). If No Rbar, Effective Depth is Total Depth (by Kouno).
			double ddT = (iMbarNum == 0 ? 0.0 : dCzp);
			double ddB = (iMbarNum == 0 ? 0.0 : dCzm);
			for (k = 0; k < iMbarNum; ++k)
			{
				T_RPSC_MBAR &Mbar = RpscMbar.Mbar[iPosiM].GetAt(k);
				ddT = min(ddT, (Mbar.iStaZRef == 0 ? Mbar.dStaZ : dzDim - Mbar.dStaZ));
				ddB = min(ddB, (Mbar.iStaZRef == 1 ? Mbar.dStaZ : dzDim - Mbar.dStaZ));
				if (ddT < 0.0) { ddT = 0.0; /*ASSERT(0);*/ }
				if (ddB < 0.0) { ddB = 0.0; /*ASSERT(0);*/ }
			}

			T_STRSPOST_BASE &StrsBase = (j == 0) ? m_StrsPost.StrsBaseI : m_StrsPost.StrsBaseJ;
			T_STRSPROP_BASE &StrsProp = (j == 0) ? StrsPropD.PropB[0] : StrsPropD.PropB[4];
			double dArea = StrsBase.dArea;
			double dIyy = StrsBase.dIyy * StrsBase.dScaleIy;
			double dIzz = StrsBase.dIzz;
			double dIw = 0.0;
			double dJ = 0.0;
			double dIp = 0.0;

			int nPosIJ = (j == 0) ? 0 : 4;
			T_SECT_STIFFNESS &StiffD = StrsPropD.PropB[nPosIJ].Stiff.Stiffness;
			double dYs[10] = { 0.0 }, dZs[10] = { 0.0 };
			double dWi[10] = { 0.0 }, dXYsh[10] = { 0.0 }, dXZsh[10] = { 0.0 };
			GetStressPointData4STSS(StrsBase, StrsPropD.PropB[nPosIJ], dYs, dZs, dWi, dXYsh, dXZsh);

			// Tendon Data.
			// Change by ZINU.('04.12.06). Set Tndn Reduction Factor (_CH=0.6, else=1.0).
			// Change by ZINU.('05.09.09). Add bTndnPs Option.
			double dTndnPs = 0.0, dTndnDist = 0.0, dTndnRad = 0.0, dCngRad = 0.0, dCngSign = 0.0;
			if (bTndnPs)
			{
				int iPosiS = (RpscSbar.bSbarJ && j != 0 ? 1 : 0);
				dTndnPs = (RpscSbar.Sbar[iPosiS].bTndnExist ? RpscSbar.Sbar[iPosiS].dTndnPs * RpscSbar.Sbar[iPosiS].dTndnFactor : 0.0);
				dTndnDist = (RpscSbar.Sbar[iPosiS].bTndnExist ? RpscSbar.Sbar[iPosiS].dTndnDist : 0.0);
				dTndnRad = (RpscSbar.Sbar[iPosiS].bTndnExist ? RpscSbar.Sbar[iPosiS].dTndnTheta / (180. / m_dPi) : 0.0);	// Deg -> Rad.
				// Change by ZINU.('05.11.19). Make All Deg -180 ~ 180 Deg.
				dCngRad = fmod(dTndnRad, m_dPi);
				dCngSign = (dCngRad >= 0.0 ? 1.0 : -1.0);
			}

			// Change by ZINU.('04.12.01). Modify Checking Position. dyzV(6) -> dyzM(4) + dyzV(6).
			for (k = 0; k < 10; ++k)	// 0~3=dyzM, 4=TL, 5=TR, 6=CL, 7=CR, 8=BL, 9=BR.
			{
				// Change by ZINU.('05.11.09). Apply dScaleZ, Position 1~4 -> Position 1~4 + 5,6,9,10.
				// Change by ZINU.('06.04.24). Consider N.A by Eeffective Width Scale Factor.
				// Change by ZINU.('06.05.23). dMoveZ : Top(1,2,5,6),Bot(3,4,9,10) -> dCzi Sign.
				double dCyi = (k < 4 ? StrsBase.dyzM[0][k] : StrsBase.dyzV[0][k - 4]);
				double dCzi = (k < 4 ? StrsBase.dyzM[1][k] : StrsBase.dyzV[1][k - 4]);
				double dMoveZ = 0.0;
				if (k == 0 || k == 1)									dMoveZ = StrsBase.dMoveTop;
				else if (k == 2 || k == 3)									dMoveZ = StrsBase.dMoveBot;
				else if (k == 4 || k == 5 || k == 8 || k == 9)	dMoveZ = (dCzi > 0.0 ? StrsBase.dMoveTop : StrsBase.dMoveBot);
				dCzi -= dMoveZ;
				if (bIs7Dof || bIsPscOpen)
				{
					dArea = StiffD.Area;
					//dQyb	= StrsBase[i+j].dQyb;
					//dQzb	= StrsBase[i+j].dQzb;
					dIyy = StiffD.Ryy * StrsBase.dScaleIy;
					dIzz = StiffD.Rzz;
					dIw = StiffD.dIw;
					dJ = StiffD.Rxx;
					dIp = dIyy + dIzz;

					dCyi = dYs[k];
					dCzi = dZs[k];
				}

				double dZyi = (dCzi == 0.0 ? 0.0 : dIyy / dCzi);
				double dZzi = (dCyi == 0.0 ? 0.0 : dIzz / dCyi);
				double dQ = (k < 4 ? 0.0 : StrsBase.dQ[(k - 4) / 2]);
				double db = (k < 4 ? 0.0 : StrsBase.db[(k - 4) / 2]);
				double dd = (ForceLcase.dMuy[j] > 0.0 ? dzDim - ddB : dzDim - ddT);
				double da = dTndnDist;

				// Kt값을 위치별로 받음 - PKS
				//      double dKt	= StrsBase.dKt;
				double dKt = 0.0;
				if (k == 0)      dKt = StrsBase.dKtweb[0]; // stress point 0
				else if (k == 1) dKt = StrsBase.dKtweb[1]; // 
				else if (k == 2) dKt = StrsBase.dKtweb[5];
				else if (k == 3) dKt = StrsBase.dKtweb[4];
				else          dKt = StrsBase.dKtweb[k - 4];

				// For Combined Stresses.
				// Change by ZINU.('04.12.27). Multiply (-1) at dBzi.
				double dSxx = (dArea == 0.0 ? 0.0 : ForceLcase.dFxx[j] / dArea);							// Sxx.
				double dByi = (-1)*(dZyi == 0.0 ? 0.0 : ForceLcase.dMuy[j] / dZyi);							// Byi.
				double dBzi = (-1)*(dZzi == 0.0 ? 0.0 : ForceLcase.dMuz[j] / dZzi);							// Bzi.        
				double dSxi = (-1)*(dArea == 0.0 ? 0.0 : dTndnPs * fabs(cos(dTndnRad)) / dArea);		// Sxi.
				double dSzi = (-1)*(db*da == 0.0 ? 0.0 : dTndnPs * fabs(sin(dTndnRad)) / (db*da));	// Szi.
				double dTas = (dIyy*db == 0.0 ? 0.0 : ForceLcase.dFzz[j] * dQ / ((dIyy / StrsBase.dScaleIy)*db));			// Tau_s.
				double dTat = (dKt == 0.0 ? 0.0 : ForceLcase.dMux[j] / dKt);								// Tau_t.
				double dTap = (db*da == 0.0 ? 0.0 : dTndnPs * dCngSign*cos(dCngRad) / (db*da));// Tau_p.
				//double dTasm=			 (db*dd==0.0 ? 0.0 : ForceLcase.dFzz[j]/(db*dd));						// Tau_s(average).
				//double dTatm=	dTat;																														// Tau_t(average).        
				double dBwi = 0.0;
				double dTat_xy = 0.0, dTat_xz = 0.0;
				double dSwt = 0.0;
				double dSwt_xy = 0.0;
				if (bIs7Dof || bIsPscOpen)
				{
					Calc_Tat(bIs7Dof, dCyi, dCzi, dIp, dJ, ForceLcase.dMux[j], ForceLcase.dTst[j], ForceLcase.dTwp[j], dXYsh[k], dXZsh[k], dTat_xy, dTat_xz, dSwt, dSwt_xy, dTat);
					dBwi = (-1)*(dIw == 0.0) ? 0.0 : ForceLcase.dMbi[j] / dIw * dWi[k];                // Bi-moment
				}
				double dSxm = dSxx + dByi + dBzi + dBwi;
				double dSx = dSxm + dSxi;
				// Change by ZINU.('05.11.16). Consider Sign(+/-) of dTat.
				if (k == 0 || k == 3 || k == 4 || k == 6 || k == 8)	dTat *= -1;	// Left Side.

				StssLcase.dShr[j][k][0] = dSxx;                                   // 1.Axial X Normal Stress
				StssLcase.dShr[j][k][1] = dByi;                                   // 2.Moment-y X Normal Stress 
				StssLcase.dShr[j][k][2] = (m_iDimType == 0 ? 0.0 : dBzi);           // 3.Moment-z X Normal Stress       
				StssLcase.dShr[j][k][3] = dSxi;                                   // 4.강봉 X Normal Stres
				StssLcase.dShr[j][k][4] = (m_iDimType != 2 ? dSxx + dByi + dSxi : dSx); // 5.Sum
				StssLcase.dShr[j][k][5] = dSzi;                                   // 6.강봉 z Normal Stress
				StssLcase.dShr[j][k][6] = dTas;                                   // 7.Shear z Shear Stress
				StssLcase.dShr[j][k][7] = (m_iDimType == 0 ? 0.0 : dTat);           // 8.Torsion Shear Stress  
				StssLcase.dShr[j][k][8] = dTap;                                   // 9.강봉 Shear Stress 
				StssLcase.dShr[j][k][16] = dSwt;                                     // 17.warping torsion xz   
			}
		}

		aStssLcase.Add(StssLcase);
	}

	return TRUE;
}

BOOL CCRCForceCtrl::Calc_Tat(BOOL bIs7Dof, double dCyi, double dCzi, double dIp, double dJ, double dMux, double dTst, double dTwp, double dXYsh, double dXZsh,
	double &dTat_xy, double &dTat_xz, double &dSwt, double &dSwt_xy, double &dTat)
{
	if (!bIs7Dof)
	{
		dTat_xy = (dJ == 0.0) ? 0.0 : dMux / dJ * dXYsh;
		dTat_xz = (dJ == 0.0) ? 0.0 : dMux / dJ * dXZsh;
	}
	else
	{
		dTat_xy = (dJ == 0.0) ? 0.0 : dTst / dJ * dXYsh; // Tp/J*dXYsh
		dTat_xz = (dJ == 0.0) ? 0.0 : dTst / dJ * dXZsh; // Tp/J*dXZsh
	}

	// MQC-15109 관련 SectInfo.cpp에서 주응력 계산 방법이 수정되었기 때문에 여기도 수정
	if (bIs7Dof)
	{
		dSwt = (dIp - dJ == 0.0) ? 0.0 : (-dCyi - dXZsh)*dTwp / (dIp - dJ); // Warping, tau_xz = G[(zc-z)-(xz+y)]*(Mw/(G*(Iw-J)))
		dSwt_xy = (dIp - dJ == 0.0) ? 0.0 : (dCzi - dXYsh)*dTwp / (dIp - dJ); // Warping, tau_xy = G[(y-yc)-(xy-z)]*(Mw/(G*(Iw-J)))
		double dSh_pa = pow(dTat_xy + dSwt_xy, 2) + pow(dTat_xz + dSwt, 2);
		if (dSh_pa != 0.0)
			dTat = sqrt(dSh_pa);
		else
			dTat = 0.0;
	}
	else
	{
		double dSh_pa = pow(dXYsh, 2) + pow(dXZsh, 2);
		if (dSh_pa != 0.0)
			dTat = ((dJ == 0.0) ? 0.0 : dMux / dJ) * sqrt(dSh_pa);
		else
			dTat = 0.0;
	}

	return TRUE;
}


void CCRCForceCtrl::Set_DimTypeForc_EX(_DGN_FORC_CRC_EX& ForcCrc)
{
	if (m_iDimType == 2)	return;
	// Force Factor  FX,FY,FZ,MX,MY,MZ,Mbi,Mst,Mwp			
	double dFact[9] = { 0.0 };
	for (int j = 0; j < 9; j++)
	{
		dFact[j] = 1.0;
	}
	if (m_iDimType == 0) { dFact[1] = dFact[3] = dFact[5] = dFact[6] = dFact[7] = dFact[8] = 0.0; }	// 2D.
	else if (m_iDimType == 1) { dFact[1] = dFact[5] = dFact[6] = 0.0; }								// 2D+Tor.
	else	ASSERT(0);
	for (int i = 0; i < cPOSI_CRC_EX; ++i)
	{
		ForcCrc.dFxx[i] *= dFact[0];
		ForcCrc.dFyy[i] *= dFact[1];
		ForcCrc.dFzz[i] *= dFact[2];
		ForcCrc.dMux[i] *= dFact[3];
		ForcCrc.dMuy[i] *= dFact[4];
		ForcCrc.dMuz[i] *= dFact[5];
		ForcCrc.dMbi[i] *= dFact[6];
		ForcCrc.dTst[i] *= dFact[7];
		ForcCrc.dTwp[i] *= dFact[8];
	}
}

BOOL CCRCForceCtrl::Get_LoadCaseStress_EX(ElemPairK ElemK, T_STRB_D& StrData, _DGN_STRS_CRC_EX& StressLcase)
{
	// Stress  
	int iPart;
	int iKind1;
	int iKind2;
	for (int i = 0; i < cPOSI_CRC_EX; ++i)
	{
		T_STRSPOST_BASE &StrsBase = (i == 0 ? m_StrsPost.StrsBaseI : m_StrsPost.StrsBaseJ);
		double dCy0 = StrsBase.dyzM[0][0];	double dCz0 = StrsBase.dyzM[1][0];
		double dCy1 = StrsBase.dyzM[0][1];	double dCz1 = StrsBase.dyzM[1][1];
		double dCy2 = StrsBase.dyzM[0][2];	double dCz2 = StrsBase.dyzM[1][2];
		double dCy3 = StrsBase.dyzM[0][3];	double dCz3 = StrsBase.dyzM[1][3];
		double dCzp = max(dCz0, dCz1);	// z-Top.
		double dCzm = min(dCz2, dCz3);	// z-Bot.

		if (i < cPOSI_CRC_EX - 1)
		{
			iPart = 0;
			iKind1 = 0;
			iKind2 = 0;
		}
		else
		{
			iPart = 3;
			iKind1 = 7;
			iKind2 = 1;
		}
		double dStop = (StrData.dblStress[iPart][iKind1 + 0] + StrData.dblStress[iPart][iKind1 + 5]);
		double dSbot = (StrData.dblStress[iPart][iKind1 + 0] + StrData.dblStress[iPart][iKind1 + 6]);
		double dSxx = StrData.dblStress[iPart][iKind1 + 0];

		StressLcase.dSbot[i] = dSxx;
		StressLcase.dStop[i] = dStop;
		StressLcase.dSbot[i] = dSbot;
		double dStl2D = (fabs(dCzp) < cDGN_Zero ? 0.0 : dStop * dCz0 / dCzp);
		double dStr2D = (fabs(dCzp) < cDGN_Zero ? 0.0 : dStop * dCz1 / dCzp);
		double dSbl2D = (fabs(dCzm) < cDGN_Zero ? 0.0 : dSbot * dCz3 / dCzm);
		double dSbr2D = (fabs(dCzm) < cDGN_Zero ? 0.0 : dSbot * dCz2 / dCzm);

		if (m_iDimType < 2)
		{
			StressLcase.dStl[i] = dStl2D;
			StressLcase.dStr[i] = dStr2D;
			StressLcase.dSbl[i] = dSbl2D;
			StressLcase.dSbr[i] = dSbr2D;
		}
		else
		{
			StressLcase.dStl[i] = StrData.dblStress[iPart][iKind2 + 16];
			StressLcase.dStr[i] = StrData.dblStress[iPart][iKind2 + 18];
			StressLcase.dSbl[i] = StrData.dblStress[iPart][iKind2 + 22];
			StressLcase.dSbr[i] = StrData.dblStress[iPart][iKind2 + 20];
		}
	}
	return TRUE;
}

BOOL CCRCForceCtrl::Get_LoadCaseStress_EX(ElemPairK ElemK, T_SBCF_D& StrMaxData, T_SBCF_D& StrMinData, ADGNSTRESS_EX &aStressLcase)
{
	aStressLcase.RemoveAll();
	aStressLcase.SetSize(cFORC_CON);

	// Stress  
	int i, j;
	for (i = 0; i < cFORC_CON; ++i)
	{
		_DGN_STRS_CRC_EX &StressLcase = aStressLcase[i];
		T_SBCF_D &StrData = (i % 2 == 0 ? StrMaxData : StrMinData);
		for (j = 0; j < cPOSI_CRC_EX; ++j)
		{
			T_STRSPOST_BASE &StrsBase = (j == 0 ? m_StrsPost.StrsBaseI : m_StrsPost.StrsBaseJ);
			double dCy0 = StrsBase.dyzM[0][0];	double dCz0 = StrsBase.dyzM[1][0];
			double dCy1 = StrsBase.dyzM[0][1];	double dCz1 = StrsBase.dyzM[1][1];
			double dCy2 = StrsBase.dyzM[0][2];	double dCz2 = StrsBase.dyzM[1][2];
			double dCy3 = StrsBase.dyzM[0][3];	double dCz3 = StrsBase.dyzM[1][3];
			double dCzp = max(dCz0, dCz1);	// z-Top.
			double dCzm = min(dCz2, dCz3);	// z-Bot.

			int iPart = (j < cPOSI_CRC_EX - 1 ? j : j - 1);
			int nIJ = (j < cPOSI_CRC_EX - 1 ? 0 : 1);
			double dStop = (StrData.dblStress[iPart][nIJ][i / 2][0] + StrData.dblStress[iPart][nIJ][i / 2][5]);
			double dSbot = (StrData.dblStress[iPart][nIJ][i / 2][0] + StrData.dblStress[iPart][nIJ][i / 2][6]);
			double dSxx = StrData.dblStress[iPart][nIJ][i / 2][0];
			StressLcase.dStop[j] = dStop;
			StressLcase.dSbot[j] = dSbot;
			StressLcase.dSxx[j] = dSxx;
			double dStl2D = (dCzp == 0.0 ? 0.0 : dStop * dCz0 / dCzp);
			double dStr2D = (dCzp == 0.0 ? 0.0 : dStop * dCz1 / dCzp);
			double dSbl2D = (dCzm == 0.0 ? 0.0 : dSbot * dCz3 / dCzm);
			double dSbr2D = (dCzm == 0.0 ? 0.0 : dSbot * dCz2 / dCzm);
			if (m_iDimType < 2)
			{
				StressLcase.dStl[j] = dStl2D;
				StressLcase.dStr[j] = dStr2D;
				StressLcase.dSbl[j] = dSbl2D;
				StressLcase.dSbr[j] = dSbr2D;
			}
			else
			{
				StressLcase.dStl[j] = StrData.dblStress[iPart][nIJ][i / 2][8];
				StressLcase.dStr[j] = StrData.dblStress[iPart][nIJ][i / 2][9];
				StressLcase.dSbl[j] = StrData.dblStress[iPart][nIJ][i / 2][11];
				StressLcase.dSbr[j] = StrData.dblStress[iPart][nIJ][i / 2][10];
			}
		}
	}
	return TRUE;
}


BOOL CCRCForceCtrl::Get_LoadCaseStressGilc_EX(ElemPairK ElemK, T_STRB_D& StrData, _DGN_STRS_CRC_EX& StressLcase)
{
	int i = 0, j = 0, k = 0;
	// Remove by ZINU.('06.04.24). Use Data at StrsPost.
	/*
	// Add by ZINU.('04.12.17). Set Effective Width Scale Factor.
	double dScaleIy=1.0, dScaleZt=1.0, dScaleZb=1.0;
	T_EWSF_D EwsfD;
	EwsfD.Initialize();
	if(m_pAttrCtrl->GetEwsfElem(ElemK,EwsfD))
	{
	dScaleIy = EwsfD.dScaleFactor;
	dScaleZt = EwsfD.dZtopFactor;
	dScaleZb = EwsfD.dZbotFactor;
	}
	*/
	// Get Elem Data.
	T_ELEM_D ElemD;
	if (!m_pPostCtrl->GetElemPost(ElemK.first, ElemD))	return FALSE;
	////////////////////////////
	// Get Sect Data.
	T_SECT_D SectD;
	if (!m_pPostCtrl->GetSectPost(ElemD.elpro, SectD))	return FALSE;
	BOOL bIs7Dof = SectD.SectBefore.bConsiderWarpingEffect;

	// Force.
	_DGN_FORC_CRC_EX ForceLcase;
	for (i = 0; i < cPOSI_CRC_EX; ++i)
	{
		int iPart = (i < cPOSI_CRC_EX - 1 ? i : i - 1);
		int iKind = (i < cPOSI_CRC_EX - 1 ? 0 : 6);
		ForceLcase.dFxx[i] = StrData.dblForce[iPart][iKind + 0];
		ForceLcase.dFyy[i] = StrData.dblForce[iPart][iKind + 1];
		ForceLcase.dFzz[i] = StrData.dblForce[iPart][iKind + 2];
		ForceLcase.dMux[i] = StrData.dblForce[iPart][iKind + 3];
		ForceLcase.dMuy[i] = StrData.dblForce[iPart][iKind + 4];
		ForceLcase.dMuz[i] = StrData.dblForce[iPart][iKind + 5];
		ForceLcase.dMbi[i] = StrData.dblForce[iPart][Mbi_Id + i]; // Bi-moment
		ForceLcase.dTst[i] = StrData.dblForce[iPart][Mst_Id + i]; // Pure torsion
		ForceLcase.dTwp[i] = StrData.dblForce[iPart][Mwp_Id + i]; // Warping torsion
	}

	Set_DimTypeForc_EX(ForceLcase);

	T_STRSPROP_D StrsPropD;
	if (bIs7Dof)
	{
		m_pSectInfo->ReadSectPostProp(ElemK.first, StrsPropD);
	}

	for (i = 0; i < cPOSI_CRC_EX; ++i)
	{
		T_STRSPOST_BASE &StrsBase = (i < cPOSI_CRC_EX - 1) ? m_StrsPost.StrsBaseI : m_StrsPost.StrsBaseJ;
		double dArea = StrsBase.dArea;
		double dQyb = StrsBase.dQyb;
		double dQzb = StrsBase.dQzb;
		double dIyy = StrsBase.dIyy * StrsBase.dScaleIy;
		double dIzz = StrsBase.dIzz;
		double dIw = 0.0;

		double dCy0 = StrsBase.dyzM[0][0];	double dCz0 = StrsBase.dyzM[1][0] - StrsBase.dMoveTop;
		double dCy1 = StrsBase.dyzM[0][1];	double dCz1 = StrsBase.dyzM[1][1] - StrsBase.dMoveTop;
		double dCy2 = StrsBase.dyzM[0][2];	double dCz2 = StrsBase.dyzM[1][2] - StrsBase.dMoveBot;
		double dCy3 = StrsBase.dyzM[0][3];	double dCz3 = StrsBase.dyzM[1][3] - StrsBase.dMoveBot;

		int nPosIJ = (i < cPOSI_CRC_EX - 1) ? 0 : 4;
		T_SECT_STIFFNESS &StiffD = StrsPropD.PropB[nPosIJ].Stiff.Stiffness;
		if (bIs7Dof)
		{
			dArea = StiffD.Area;
			//dQyb	= StrsBase[i+j].dQyb;
			//dQzb	= StrsBase[i+j].dQzb;
			dIyy = StiffD.Ryy * StrsBase.dScaleIy;
			dIzz = StiffD.Rzz;
			dIw = StiffD.dIw;

			dCy0 = StiffD.dx1;  dCz0 = StiffD.dy1;
			dCy1 = StiffD.dx2;  dCz1 = StiffD.dy2;
			dCy2 = StiffD.dx3;	dCz2 = StiffD.dy3;
			dCy3 = StiffD.dx4;	dCz3 = StiffD.dy4;
		}

		double dSy0 = (dCz0 == 0.0 ? 0.0 : dIyy / dCz0);	double dSz0 = (dCy0 == 0.0 ? 0.0 : dIzz / dCy0);
		double dSy1 = (dCz1 == 0.0 ? 0.0 : dIyy / dCz1);	double dSz1 = (dCy1 == 0.0 ? 0.0 : dIzz / dCy1);
		double dSy2 = (dCz2 == 0.0 ? 0.0 : dIyy / dCz2);	double dSz2 = (dCy2 == 0.0 ? 0.0 : dIzz / dCy2);
		double dSy3 = (dCz3 == 0.0 ? 0.0 : dIyy / dCz3);	double dSz3 = (dCy3 == 0.0 ? 0.0 : dIzz / dCy3);

		double dCyp = max(dCy1, dCy2);	// y-Right.
		double dCym = min(dCy0, dCy3);	// y-Left.
		double dCzp = max(dCz0, dCz1);	// z-Top.
		double dCzm = min(dCz2, dCz3);	// z-Bot.
		double dSyp = (dCzp == 0.0 ? 0.0 : dIyy / dCzp);
		double dSym = (dCzm == 0.0 ? 0.0 : dIyy / dCzm);
		double dSzp = (dCyp == 0.0 ? 0.0 : dIzz / dCyp);
		double dSzm = (dCym == 0.0 ? 0.0 : dIzz / dCym);

		// Tension(+), Compression(-).
		double dSxx = (dArea == 0.0 ? 0.0 : ForceLcase.dFxx[i] / dArea);			// Sxx.
		double dSyy = (dIzz == 0.0 ? 0.0 : ForceLcase.dFyy[i] * dQzb / dIzz);	// Syy.
		double dSzz = (dIyy == 0.0 ? 0.0 : ForceLcase.dFzz[i] * dQyb / (dIyy / StrsBase.dScaleIy));	// Szz.
		double dByp = (-1)*(dSyp == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSyp);			// Byp.
		double dBym = (-1)*(dSym == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSym);			// Bym.
		double dBzp = (dSzp == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSzp);			// Bzp.
		double dBzm = (dSzm == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSzm);			// Bzm.
		// For Combined Stresses.
		// Change by ZINU.('04.12.27). Multiply (-1) at dBz0,dBz1,dBz2,dBz3.
		double dBy0 = (-1)*(dSy0 == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSy0);	// By0.
		double dBy1 = (-1)*(dSy1 == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSy1);	// By1.
		double dBy2 = (-1)*(dSy2 == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSy2);	// By2.
		double dBy3 = (-1)*(dSy3 == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSy3);	// By3.
		double dBz0 = (-1)*(dSz0 == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSz0);	// Bz0.
		double dBz1 = (-1)*(dSz1 == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSz1);	// Bz1.
		double dBz2 = (-1)*(dSz2 == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSz2);	// Bz2.
		double dBz3 = (-1)*(dSz3 == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSz3);	// Bz3.
		double dBi0 = 0.0, dBi1 = 0.0, dBi2 = 0.0, dBi3 = 0.0;

		if (bIs7Dof)
		{
			double dMwIw = (dIw == 0.0) ? 0.0 : (-1)*ForceLcase.dMbi[i] / dIw;
			dBi0 = dMwIw * StiffD.dw1;
			dBi1 = dMwIw * StiffD.dw2;
			dBi2 = dMwIw * StiffD.dw3;
			dBi3 = dMwIw * StiffD.dw4;
		}
		// Combined Stresses.

		double dStop = dSxx + dByp;				  // 상단.
		double dSbot = dSxx + dBym;				  // 하단.
		double dStl = dSxx + dBy0 + dBz0 + dBi0; //(m_iDimType !=2 ? dSxx + dBy0 + dBz0 : StrData.dblStress[iPart][iKind2+16]);	// 상단좌단.
		double dStr = dSxx + dBy1 + dBz1 + dBi1; //(m_iDimType !=2 ? dSxx + dBy1 + dBz1 : StrData.dblStress[iPart][iKind2+18]);	// 상단우단.
		double dSbr = dSxx + dBy2 + dBz2 + dBi2; //(m_iDimType !=2 ? dSxx + dBy2 + dBz2 : StrData.dblStress[iPart][iKind2+22]);	// 하단우단.
		double dSbl = dSxx + dBy3 + dBz3 + dBi3; //(m_iDimType !=2 ? dSxx + dBy3 + dBz3 : StrData.dblStress[iPart][iKind2+20]);	// 하단좌단.

		StressLcase.dStop[i] = dStop;
		StressLcase.dSbot[i] = dSbot;
		StressLcase.dStl[i] = dStl;
		StressLcase.dStr[i] = dStr;
		StressLcase.dSbl[i] = dSbl;
		StressLcase.dSbr[i] = dSbr;

	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_LoadCaseStressGilc_EX(ElemPairK ElemK, T_SBCF_D& StrMaxData, T_SBCF_D& StrMinData, ADGNSTRESS_EX& aStressLcase)
{

	aStressLcase.RemoveAll();
	aStressLcase.SetSize(cFORC_CON);

	T_STRB_D StrData;
	for (int i = 0; i < cFORC_CON; ++i)
	{
		T_SBCF_D &SbcfData = (i % 2 == 0 ? StrMaxData : StrMinData);

		StrData.Initialize();
		int nForceType = i / 2;
		Get_ConvertStrb(nForceType, SbcfData, StrData);

		Get_LoadCaseStressGilc_EX(ElemK, StrData, aStressLcase[i]);
	}
	return TRUE;
}

BOOL CCRCForceCtrl::Get_LoadCaseStressSlab_EX(ElemPairK ElemK, T_STRB_D& StrData, _DGN_STRS_CRC_EX& StressLcase)
{
	// Get Elem Data.
	T_ELEM_D ElemD;
	if (!m_pPostCtrl->GetElemPost(ElemK.first, ElemD))	return FALSE;
	////////////////////////////
	// Get Sect Data.
	T_SECT_D SectD;
	if (!m_pPostCtrl->GetSectPost(ElemD.elpro, SectD))	return FALSE;
	BOOL bIs7Dof = SectD.SectBefore.bConsiderWarpingEffect;

	int nSectType = SectD.nStype;
	BOOL bTapered = (SectD.nStype == D_SECT_TYPE_TAPERED);
	if (bTapered == TRUE) nSectType = SectD.SectBefore.nStype;

	// Force.
	_DGN_FORC_CRC_EX ForceLcase;
	for (int i = 0; i < cPOSI_CRC_EX; ++i)
	{
		int iPart = (i < cPOSI_CRC_EX - 1 ? i : i - 1);
		int iKind = (i < cPOSI_CRC_EX - 1 ? 0 : 6);
		ForceLcase.dFxx[i] = StrData.dblForce[iPart][iKind + 0];
		ForceLcase.dFyy[i] = StrData.dblForce[iPart][iKind + 1];
		ForceLcase.dFzz[i] = StrData.dblForce[iPart][iKind + 2];
		ForceLcase.dMux[i] = StrData.dblForce[iPart][iKind + 3];
		ForceLcase.dMuy[i] = StrData.dblForce[iPart][iKind + 4];
		ForceLcase.dMuz[i] = StrData.dblForce[iPart][iKind + 5];
		ForceLcase.dMbi[i] = StrData.dblForce[iPart][Mbi_Id + i]; // Bi-moment
		ForceLcase.dTst[i] = StrData.dblForce[iPart][Mst_Id + i]; // Pure torsion
		ForceLcase.dTwp[i] = StrData.dblForce[iPart][Mwp_Id + i]; // Warping torsion
	}

	Set_DimTypeForc_EX(ForceLcase);

	T_STRSPROP_D StrsPropD;
	if (bIs7Dof)
	{
		m_pSectInfo->ReadSectPostProp(ElemK.first, StrsPropD);
	}

	double Er = SectD.SectBefore.Matl_Elast;
	double Bc = SectD.SectAfter.SectJ.Size[0];
	double tc = SectD.SectAfter.SectJ.Size[1];
	double Hh = SectD.SectAfter.SectJ.Size[2];

	double dys1 = 0.0, dys2 = 0.0, dys3 = 0.0, dys4 = 0.0;
	double dzs1 = 0.0, dzs2 = 0.0, dzs3 = 0.0, dzs4 = 0.0;
	double dYbars = 0.0;
	double dZbars = 0.0;

	double dYbar_c = 0.0, dZbar_c = 0.0;
	double dyc2 = 0.0, dzc2 = 0.0;

	//if (nSectType==D_SECT_TYPE_COMPO_CI || nSectType==D_SECT_TYPE_COMPO_CT ||
	//    nSectType==D_SECT_TYPE_COMPO_PC)

	for (int i = 0; i < cPOSI_CRC_EX; ++i)
	{
		T_STRSPOST_BASE &StrsBase = (i < cPOSI_CRC_EX - 1) ? m_StrsPost.StrsBaseI : m_StrsPost.StrsBaseJ;
		double dArea = StrsBase.dArea;
		double dQyb = StrsBase.dQyb;
		double dQzb = StrsBase.dQzb;
		double dIyy = StrsBase.dIyy * StrsBase.dScaleIy;
		double dIzz = StrsBase.dIzz;
		double dIw = 0.0;

		double dCy0 = StrsBase.dyzM[0][0];	double dCz0 = StrsBase.dyzM[1][0] - StrsBase.dMoveTop;
		double dCy1 = StrsBase.dyzM[0][1];	double dCz1 = StrsBase.dyzM[1][1] - StrsBase.dMoveTop;
		double dCy2 = StrsBase.dyzM[0][2];	double dCz2 = StrsBase.dyzM[1][2] - StrsBase.dMoveBot;
		double dCy3 = StrsBase.dyzM[0][3];	double dCz3 = StrsBase.dyzM[1][3] - StrsBase.dMoveBot;

		int nPosIJ = (i < cPOSI_CRC_EX - 1) ? 0 : 4;
		T_SECT_STIFFNESS &StiffD = StrsPropD.PropB[nPosIJ].Stiff.Stiffness;
		if (bIs7Dof)
		{
			dArea = StiffD.Area;
			//dQyb	= StrsBase[i+j].dQyb;
			//dQzb	= StrsBase[i+j].dQzb;
			dIyy = StiffD.Ryy * StrsBase.dScaleIy;
			dIzz = StiffD.Rzz;
			dIw = StiffD.dIw;

			dCy0 = StiffD.dx1;  dCz0 = StiffD.dy1;
			dCy1 = StiffD.dx2;  dCz1 = StiffD.dy2;
			dCy2 = StiffD.dx3;	dCz2 = StiffD.dy3;
			dCy3 = StiffD.dx4;	dCz3 = StiffD.dy4;
		}

		T_SECT_SECTBASE_D* pSectBefore = (i == 1 && bTapered) ? &SectD.SectBefore.SectJ : &SectD.SectBefore.SectI;
		T_SECT_SECTBASE_D* pSectAfter = (i == 1 && bTapered) ? &SectD.SectAfter.SectJ : &SectD.SectAfter.SectI;

		T_SECT_STIFFNESS* pBeforeStiff;
		if (bTapered)
		{
			pBeforeStiff = &pSectBefore->Stiffness;
		}
		else
		{
			pBeforeStiff = &SectD.SectBefore.Stiffness;
		}

		if (nSectType == D_SECT_TYPE_COMPO_G)
		{
			if (pSectBefore->aGeneralPart.GetSize() != 2) return FALSE;

			const T_GSEC_PART &GBase = pSectBefore->aGeneralPart[0];
			const T_GSEC_PART &GPart = pSectBefore->aGeneralPart[1];

			Er = (GPart.dElastic < cDgn_Zero) ? 0.0 : GBase.dElastic / GPart.dElastic;

			dYbars = GPart.YBar;
			dZbars = GPart.ZBar;
			dys1 = GPart.Stiffness.dx1;
			dys2 = GPart.Stiffness.dx2;
			dys3 = GPart.Stiffness.dx3;
			dys4 = GPart.Stiffness.dx4;
			dzs1 = GPart.Stiffness.dy1;
			dzs2 = GPart.Stiffness.dy2;
			dzs3 = GPart.Stiffness.dy3;
			dzs4 = GPart.Stiffness.dy4;

			dYbar_c = pSectAfter->Design.YBar;
			dZbar_c = pSectAfter->Design.ZBar;
			dyc2 = pSectAfter->Stiffness.dx2;
			dzc2 = pSectAfter->Stiffness.dy2;
		}
		else
		{
			double dBg = pBeforeStiff->Cym + pBeforeStiff->Cyp;
			double dHg = pBeforeStiff->Czm + pBeforeStiff->Czp;
			double dtc2 = 0.5*tc;
			dYbars = Bc < dBg ? pBeforeStiff->Cym : 0.5*Bc;
			dZbars = dHg + Hh + dtc2;
			dys1 = -dYbars;
			dys2 = dYbars;
			dys3 = dys2;
			dys4 = dys1;
			dzs1 = dZbars + dtc2;
			dzs2 = dzs1;
			dzs3 = dZbars - dtc2;
			dzs4 = dzs3;

			if (bTapered == FALSE)
			{
				dYbar_c = SectD.SectAfter.Design.YBar;
				dZbar_c = SectD.SectAfter.Design.ZBar;
				dyc2 = SectD.SectAfter.Stiffness.dx2;
				dzc2 = SectD.SectAfter.Stiffness.dy2;
			}
			else
			{
				dYbar_c = pSectAfter->Design.YBar;
				dZbar_c = pSectAfter->Design.ZBar;
				dyc2 = pSectAfter->Stiffness.dx2;
				dzc2 = pSectAfter->Stiffness.dy2;
			}
		}

		// 슬래브와 합성의 차이
		double dDy = dYbar_c - dYbars;
		double dDz = dZbar_c - dZbars;
		// 합성순단면과 합성환산단면의 차이
		double dTy = dCy1 - dyc2;
		double dTz = dCz1 - dzc2;

		dys1 = dys1 - dTy;
		dys2 = dys2 - dTy;
		dys3 = dys3 - dTy;
		dys4 = dys4 - dTy;
		dzs1 = dzs1 - dTz;
		dzs2 = dzs2 - dTz;
		dzs3 = dzs3 - dTz;
		dzs4 = dzs4 - dTz;

		double dSy0 = (dzs1 == 0.0 ? 0.0 : dIyy / dzs1);	double dSz0 = (dys1 == 0.0 ? 0.0 : dIzz / dys1);
		double dSy1 = (dzs2 == 0.0 ? 0.0 : dIyy / dzs2);	double dSz1 = (dys2 == 0.0 ? 0.0 : dIzz / dys2);
		double dSy2 = (dzs3 == 0.0 ? 0.0 : dIyy / dzs3);	double dSz2 = (dys3 == 0.0 ? 0.0 : dIzz / dys3);
		double dSy3 = (dzs4 == 0.0 ? 0.0 : dIyy / dzs4);	double dSz3 = (dys4 == 0.0 ? 0.0 : dIzz / dys4);

		double dCyp = max(dCy1, dCy2);	// y-Right.
		double dCym = min(dCy0, dCy3);	// y-Left.
		double dCzp = max(dCz0, dCz1);	// z-Top.
		double dCzm = min(dCz2, dCz3);	// z-Bot.
		double dSyp = (dCzp == 0.0 ? 0.0 : dIyy / dCzp);
		double dSym = (dCzm == 0.0 ? 0.0 : dIyy / dCzm);
		double dSzp = (dCyp == 0.0 ? 0.0 : dIzz / dCyp);
		double dSzm = (dCym == 0.0 ? 0.0 : dIzz / dCym);

		// Tension(+), Compression(-).
		double dSxx = (dArea == 0.0 ? 0.0 : ForceLcase.dFxx[i] / dArea);			// Sxx.
		double dSyy = (dIzz == 0.0 ? 0.0 : ForceLcase.dFyy[i] * dQzb / dIzz);	// Syy.
		double dSzz = (dIyy == 0.0 ? 0.0 : ForceLcase.dFzz[i] * dQyb / (dIyy / StrsBase.dScaleIy));	// Szz.
		double dByp = (-1)*(dSyp == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSyp);			// Byp.
		double dBym = (-1)*(dSym == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSym);			// Bym.
		double dBzp = (dSzp == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSzp);			// Bzp.
		double dBzm = (dSzm == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSzm);			// Bzm.
		// For Combined Stresses.
		// Change by ZINU.('04.12.27). Multiply (-1) at dBz0,dBz1,dBz2,dBz3.
		double dBy0 = (-1)*(dSy0 == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSy0);	// By0.
		double dBy1 = (-1)*(dSy1 == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSy1);	// By1.
		double dBy2 = (-1)*(dSy2 == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSy2);	// By2.
		double dBy3 = (-1)*(dSy3 == 0.0 ? 0.0 : ForceLcase.dMuy[i] / dSy3);	// By3.
		double dBz0 = (-1)*(dSz0 == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSz0);	// Bz0.
		double dBz1 = (-1)*(dSz1 == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSz1);	// Bz1.
		double dBz2 = (-1)*(dSz2 == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSz2);	// Bz2.
		double dBz3 = (-1)*(dSz3 == 0.0 ? 0.0 : ForceLcase.dMuz[i] / dSz3);	// Bz3.
		double dBi0 = 0.0, dBi1 = 0.0, dBi2 = 0.0, dBi3 = 0.0;
		//     if (bIs7Dof)
		//     {
		//       double dMwIw = (dIw==0.0) ? 0.0 : (-1)*ForceLcase.dMbi[i]/dIw;
		//       dBi0 = dMwIw * StiffD.dw1;
		//       dBi1 = dMwIw * StiffD.dw2;
		//       dBi2 = dMwIw * StiffD.dw3;
		//       dBi3 = dMwIw * StiffD.dw4;          
		//     }

		// Combined Stresses.
		double dStop = dSxx + dByp;				  // 상단.
		double dSbot = dSxx + dBym;				  // 하단.
		double dStl = dSxx + dBy0 + dBz0 + dBi0; //(m_iDimType !=2 ? dSxx + dBy0 + dBz0 : StrData.dblStress[iPart][iKind2+16]);	// 상단좌단.
		double dStr = dSxx + dBy1 + dBz1 + dBi1; //(m_iDimType !=2 ? dSxx + dBy1 + dBz1 : StrData.dblStress[iPart][iKind2+18]);	// 상단우단.
		double dSbr = dSxx + dBy2 + dBz2 + dBi2; //(m_iDimType !=2 ? dSxx + dBy2 + dBz2 : StrData.dblStress[iPart][iKind2+22]);	// 하단우단.
		double dSbl = dSxx + dBy3 + dBz3 + dBi3; //(m_iDimType !=2 ? dSxx + dBy3 + dBz3 : StrData.dblStress[iPart][iKind2+20]);	// 하단좌단.

		if (Er > cDGN_Zero)
		{
			dStop /= Er;
			dSbot /= Er;
			dStl /= Er;
			dStr /= Er;
			dSbl /= Er;
			dSbr /= Er;
		}

		StressLcase.dStop[i] = dStop;
		StressLcase.dSbot[i] = dSbot;
		StressLcase.dStl[i] = dStl;
		StressLcase.dStr[i] = dStr;
		StressLcase.dSbl[i] = dSbl;
		StressLcase.dSbr[i] = dSbr;
	}

	return TRUE;

}

BOOL CCRCForceCtrl::Get_LoadCaseStressSlab_EX(ElemPairK ElemK, T_SBCF_D& StrMaxData, T_SBCF_D& StrMinData, _DGN_STRS_CRC_EX aStrsLcase[12])
{
	T_STRB_D StrData;
	for (int i = 0; i < cFORC_CON; ++i)
	{
		T_SBCF_D &SbcfData = (i % 2 == 0 ? StrMaxData : StrMinData);

		StrData.Initialize();
		int nForceType = i / 2;
		Get_ConvertStrb(nForceType, SbcfData, StrData);

		_DGN_STRS_CRC_EX StressLcase;
		Get_LoadCaseStressSlab_EX(ElemK, StrData, aStrsLcase[i]);

	}
	return TRUE;
}

BOOL CCRCForceCtrl::Get_LoadCaseStss_EX(T_STSS_D& StrData, _DGN_SHRS_ADD_EX& StssLcase)
{
	// 1.Axial X Normal Stress
	// 2.Moment-y X Normal Stress 
	// 3.Moment-z X Normal Stress       
	// 4.강봉 X Normal Stres
	// 5.Sum
	// 6.강봉 z Normal Stress
	// 7.Shear z Shear Stress
	// 8.Torsion Shear Stress  
	// 9.강봉 Shear Stress
	// 10.비틀림 제외 사인장 응력 
	// 11.비틀림 포함 사인장 응력 / 주응력 최대
	// 12.주응력 최소  
	// 13.warping normal stress
	// 14.pure torsion xy
	// 15.warping torsion xy
	// 16.pure torsion xz
	// 17.warping torsion xz
	// 18.summation shear xy
	// 19.summation shear xz
	for (int i = 0; i < cPOSI_CRC_EX; ++i)
	{
		int iPart = (i < (cPOSI_CRC_EX - 1) ? i : i - 1);
		for (int j = 0; j < 10; ++j)
		{
			for (int k = 0; k < 19; ++k)
			{
				StssLcase.dShr[i][j][k] = StrData.dblStress[iPart][j][k];
			}
			double dSxx = StrData.dblStress[iPart][j][0];
			double dByi = StrData.dblStress[iPart][j][1];
			double dSxi = StrData.dblStress[iPart][j][3];
			StssLcase.dShr[i][j][2] = (m_iDimType == 0 ? 0.0 : StrData.dblStress[iPart][j][2]); // 3.Moment-z X Normal Stress
			StssLcase.dShr[i][j][4] = (m_iDimType != 2 ? dSxx + dByi + dSxi : StrData.dblStress[iPart][j][4]); // 5.Sum
			StssLcase.dShr[i][j][7] = (m_iDimType == 0 ? 0.0 : StrData.dblStress[iPart][j][7]); // 8.Torsion Shear Stress
			if (m_iDimType == 0)
			{
				for (int l = 0; l < 7; ++l) StssLcase.dShr[i][j][l + 12] = 0.0;
			}
		}
	}
	// 10,11,12는 할당하지만 사용하지 않음.
	return TRUE;
}

BOOL CCRCForceCtrl::Get_LoadCaseStss_EX(ElemPairK ElemK, BOOL bTndnPs, T_STRB_D& StrData, _DGN_SHRS_ADD_EX& StssLcase)
{
	StssLcase.Initialize();

	int i = 0, j = 0, k = 0; // dyzM(4군데).
	// Get Elem Data.
	T_ELEM_D ElemD;
	ElemD.Initialize();
	if (!m_pPostCtrl->GetElemPost(ElemK.first, ElemD))	return FALSE;
	T_SECT_K SectK = ElemD.elpro;
	// Get Sect Data.
	T_SECT_D SectD;
	SectD.Initialize();
	if (!m_pPostCtrl->GetSectPost(SectK, SectD))	return FALSE;
	T_SECT_K OrgSectK = m_pPostCtrl->GetOrgSectKeyPost(SectK);

	BOOL bComposit = FALSE;
	BOOL bCompositGen = FALSE;
	double dtc = 0.0;
	double dHh = 0.0;
	if (SectD.nStype == D_SECT_TYPE_COMPO_CI || SectD.nStype == D_SECT_TYPE_COMPO_CT || SectD.nStype == D_SECT_TYPE_COMPO_PC)
	{
		bComposit = TRUE;
		//   double dBc = SectD.SectAfter.SectJ.Size[0];
		dtc = SectD.SectAfter.SectJ.Size[1];
		dHh = SectD.SectAfter.SectJ.Size[2];
	}
	else if (SectD.nStype == D_SECT_TYPE_COMPO_G)
	{
		ASSERT(0);
		bCompositGen = TRUE;
	}

	BOOL bIs7Dof = SectD.SectBefore.bConsiderWarpingEffect;
	BOOL bIsPscOpen = CDBLib::IsPscOpenSect(SectD.SectBefore.Shape);

	// Get Rbar Data.
	T_RPSC_D RpscMbar, RpscSbar;
	RpscMbar.Initialize();
	m_pAttrCtrl->GetRpscByConsiderRbar(TRUE, OrgSectK, RpscMbar);
	RpscSbar.Initialize();
	m_pAttrCtrl->GetRpscByConsiderRbar(FALSE, OrgSectK, RpscSbar);
	// Remove by ZINU.('06.04.24). Use Data at StrsPost.
	/*
	// Add by ZINU.('04.12.17). Set Effective Width Scale Factor.
	double dScaleIy=1.0, dScaleZt=1.0, dScaleZb=1.0;
	T_EWSF_D EwsfD;
	EwsfD.Initialize();
	if(m_pAttrCtrl->GetEwsfElem(ElemK,EwsfD))
	{
	dScaleIy = EwsfD.dScaleFactor;
	dScaleZt = EwsfD.dZtopFactor;
	dScaleZb = EwsfD.dZbotFactor;
	}
	*/
	// Force.
	_DGN_FORC_CRC_EX ForceLcase;
	for (j = 0; j < cPOSI_CRC_EX; ++j)
	{
		int iPart = (j < (cPOSI_CRC_EX - 1) ? j : j - 1);
		int iKind = (j < (cPOSI_CRC_EX - 1) ? 0 : 6);
		ForceLcase.dFxx[j] = StrData.dblForce[iPart][iKind + 0];
		ForceLcase.dFyy[j] = StrData.dblForce[iPart][iKind + 1];
		ForceLcase.dFzz[j] = StrData.dblForce[iPart][iKind + 2];
		ForceLcase.dMux[j] = StrData.dblForce[iPart][iKind + 3];
		ForceLcase.dMuy[j] = StrData.dblForce[iPart][iKind + 4];
		ForceLcase.dMuz[j] = StrData.dblForce[iPart][iKind + 5];
		ForceLcase.dMbi[j] = StrData.dblForce[iPart][Mbi_Id + j]; // Bi-moment
		ForceLcase.dTst[j] = StrData.dblForce[iPart][Mst_Id + j]; // Pure torsion
		ForceLcase.dTwp[j] = StrData.dblForce[iPart][Mwp_Id + j]; // Warping torsion
	}

	Set_DimTypeForc_EX(ForceLcase);

	T_STRSPROP_D StrsPropD;
	if (bIs7Dof || bIsPscOpen)
	{
		m_pSectInfo->ReadSectPostProp(ElemK.first, StrsPropD);
	}

	for (j = 0; j < cPOSI_CRC_EX; ++j)
	{
		// Get Depth.
		int iPosi = (CDBLib::IsSectI((j < cPOSI_CRC_EX - 1), SectD.nStype) ? 0 : 1);
		T_SECT_STIFFNESS &SectStiff = (iPosi == 0) ? SectD.SectBefore.SectI.Stiffness : SectD.SectBefore.SectJ.Stiffness;
		double dCzp = SectStiff.Czp;
		double dCzm = SectStiff.Czm;
		double dzDim = 0.0;
		if (bCompositGen) dzDim = m_dHeight[i];
		else             dzDim = dCzp + dCzm + (bComposit ? dtc : 0.0);

		int iPosiM = (RpscMbar.bMbarJ && j == (cPOSI_CRC_EX - 1) ? 1 : 0); // Mid terms considered I-End
		int iMbarNum = RpscMbar.Mbar[iPosiM].GetSize();
		// Change by ZINU.('04.06.30). If No Rbar, Effective Depth is Total Depth (by Kouno).
		double ddT = (iMbarNum == 0 ? 0.0 : dCzp);
		double ddB = (iMbarNum == 0 ? 0.0 : dCzm);
		for (k = 0; k < iMbarNum; ++k)
		{
			T_RPSC_MBAR &Mbar = RpscMbar.Mbar[iPosiM].GetAt(k);
			ddT = min(ddT, (Mbar.iStaZRef == 0 ? Mbar.dStaZ : dzDim - Mbar.dStaZ));
			ddB = min(ddB, (Mbar.iStaZRef == 1 ? Mbar.dStaZ : dzDim - Mbar.dStaZ));
			if (ddT < 0.0) { ddT = 0.0; /*ASSERT(0);*/ }
			if (ddB < 0.0) { ddB = 0.0; /*ASSERT(0);*/ }
		}

		T_STRSPOST_BASE &StrsBase = (j == 0 ? m_StrsPost.StrsBaseI : m_StrsPost.StrsBaseJ);
		T_STRSPROP_BASE &StrsProp = (j == 0) ? StrsPropD.PropB[0] : StrsPropD.PropB[4];
		double dArea = StrsBase.dArea;
		double dIyy = StrsBase.dIyy * StrsBase.dScaleIy;
		double dIzz = StrsBase.dIzz;
		double dJ = 0.0;
		double dIp = dIyy + dIzz;
		double dIw = 0.0;

		int nPosIJ = (j != cPOSI_CRC_EX - 1) ? 0 : 4;
		T_SECT_STIFFNESS &StiffD = StrsProp.Stiff.Stiffness;
		if (bIs7Dof || bIsPscOpen)
		{
			dArea = StiffD.Area;
			//dQyb	= StrsBase[i+j].dQyb;
			//dQzb	= StrsBase[i+j].dQzb;
			dIyy = StiffD.Ryy * StrsBase.dScaleIy;
			dIzz = StiffD.Rzz;
			dIw = StiffD.dIw;
			dJ = StiffD.Rxx;
			dIp = dIyy + dIzz;

			//dCy0 = StiffD.dx1;  dCz0 = StiffD.dy1;
			//dCy1 = StiffD.dx2;  dCz1 = StiffD.dy2;
			//dCy2 = StiffD.dx3;	dCz2 = StiffD.dy3;
			//dCy3 = StiffD.dx4;	dCz3 = StiffD.dy4;
		}

		// Tendon Data.
		// Change by ZINU.('04.12.06). Set Tndn Reduction Factor (_CH=0.6, else=1.0).
		// Change by ZINU.('05.09.09). Add bTndnPs Option.
		double dTndnPs = 0.0, dTndnDist = 0.0, dTndnRad = 0.0, dCngRad = 0.0, dCngSign = 0.0;
		if (bTndnPs)
		{
			int iPosiS = (RpscSbar.bSbarJ && j == (cPOSI_CRC_EX - 1) ? 1 : 0);
			dTndnPs = (RpscSbar.Sbar[iPosiS].bTndnExist ? RpscSbar.Sbar[iPosiS].dTndnPs * RpscSbar.Sbar[iPosiS].dTndnFactor : 0.0);
			dTndnDist = (RpscSbar.Sbar[iPosiS].bTndnExist ? RpscSbar.Sbar[iPosiS].dTndnDist : 0.0);
			dTndnRad = (RpscSbar.Sbar[iPosiS].bTndnExist ? RpscSbar.Sbar[iPosiS].dTndnTheta / (180. / m_dPi) : 0.0);	// Deg -> Rad.
			// Change by ZINU.('05.11.19). Make All Deg -180 ~ 180 Deg.
			dCngRad = fmod(dTndnRad, m_dPi);
			dCngSign = (dCngRad >= 0.0 ? 1.0 : -1.0);
		}

		double dWcoef[10] = { 0.0 };
		double dXZsh[10] = { 0.0 };
		double dXYsh[10] = { 0.0 };
		if (bIs7Dof)
		{
			dWcoef[0] = StrsProp.Stiff.Stiffness.dw1;
			dWcoef[1] = StrsProp.Stiff.Stiffness.dw2;
			dWcoef[2] = StrsProp.Stiff.Stiffness.dw3;
			dWcoef[3] = StrsProp.Stiff.Stiffness.dw4;
			dWcoef[4] = StrsProp.Stiff.dw5;
			dWcoef[5] = StrsProp.Stiff.dw6;
			dWcoef[6] = StrsProp.Stiff.dw7;
			dWcoef[7] = StrsProp.Stiff.dw8;
			dWcoef[8] = StrsProp.Stiff.dw9;
			dWcoef[9] = StrsProp.Stiff.dw10;
		}

		if (bIs7Dof || bIsPscOpen)
		{
			dXYsh[0] = StrsProp.Stiff.Stiffness.dxy1;
			dXYsh[1] = StrsProp.Stiff.Stiffness.dxy2;
			dXYsh[2] = StrsProp.Stiff.Stiffness.dxy3;
			dXYsh[3] = StrsProp.Stiff.Stiffness.dxy4;
			dXYsh[4] = StrsProp.Stiff.dxy5;
			dXYsh[5] = StrsProp.Stiff.dxy6;
			dXYsh[6] = StrsProp.Stiff.dxy7;
			dXYsh[7] = StrsProp.Stiff.dxy8;
			dXYsh[8] = StrsProp.Stiff.dxy9;
			dXYsh[9] = StrsProp.Stiff.dxy10;
			//
			dXZsh[0] = StrsProp.Stiff.Stiffness.dxz1;
			dXZsh[1] = StrsProp.Stiff.Stiffness.dxz2;
			dXZsh[2] = StrsProp.Stiff.Stiffness.dxz3;
			dXZsh[3] = StrsProp.Stiff.Stiffness.dxz4;
			dXZsh[4] = StrsProp.Stiff.dxz5;
			dXZsh[5] = StrsProp.Stiff.dxz6;
			dXZsh[6] = StrsProp.Stiff.dxz7;
			dXZsh[7] = StrsProp.Stiff.dxz8;
			dXZsh[8] = StrsProp.Stiff.dxz9;
			dXZsh[9] = StrsProp.Stiff.dxz10;
		}

		// Change by ZINU.('04.12.01). Modify Checking Position. dyzV(6) -> dyzM(4) + dyzV(6).
		for (k = 0; k < 10; ++k)	// 0~3=dyzM, 4=TL, 5=TR, 6=CL, 7=CR, 8=BL, 9=BR.
		{
			// Change by ZINU.('05.11.09). Apply dScaleZ, Position 1~4 -> Position 1~4 + 5,6,9,10.
			// Change by ZINU.('06.04.24). Consider N.A by Eeffective Width Scale Factor.
			// Change by ZINU.('06.05.23). dMoveZ : Top(1,2,5,6),Bot(3,4,9,10) -> dCzi Sign.
			double dCyi = (k < 4 ? StrsBase.dyzM[0][k] : StrsBase.dyzV[0][k - 4]);
			double dCzi = (k < 4 ? StrsBase.dyzM[1][k] : StrsBase.dyzV[1][k - 4]);
			double dMoveZ = 0.0;

			if (k == 0 || k == 1)						dMoveZ = StrsBase.dMoveTop;
			else if (k == 2 || k == 3)					dMoveZ = StrsBase.dMoveBot;
			else if (k == 4 || k == 5 || k == 8 || k == 9)	dMoveZ = (dCzi > 0.0 ? StrsBase.dMoveTop : StrsBase.dMoveBot);
			dCzi -= dMoveZ;
			double dZyi = (dCzi == 0.0 ? 0.0 : dIyy / dCzi);
			double dZzi = (dCyi == 0.0 ? 0.0 : dIzz / dCyi);
			double dQ = (k < 4 ? 0.0 : StrsBase.dQ[(k - 4) / 2]);
			double db = (k < 4 ? 0.0 : StrsBase.db[(k - 4) / 2]);
			double dd = (ForceLcase.dMuy[j] > 0.0 ? dzDim - ddB : dzDim - ddT);
			double da = dTndnDist;

			// Kt값을 위치별로 받음 - PKS
			//      double dKt	= StrsBase.dKt;
			double dKt = 0.0;
			if (k == 0)      dKt = StrsBase.dKtweb[0]; // stress point 0
			else if (k == 1) dKt = StrsBase.dKtweb[1]; // 
			else if (k == 2) dKt = StrsBase.dKtweb[5];
			else if (k == 3) dKt = StrsBase.dKtweb[4];
			else          dKt = StrsBase.dKtweb[k - 4];
			double dwi = dWcoef[k];

			// For Combined Stresses.
			// Change by ZINU.('04.12.27). Multiply (-1) at dBzi.
			double dSxx = (dArea == 0.0 ? 0.0 : ForceLcase.dFxx[j] / dArea);							// Sxx.
			double dByi = (-1)*(dZyi == 0.0 ? 0.0 : ForceLcase.dMuy[j] / dZyi);							// Byi.
			double dBzi = (-1)*(dZzi == 0.0 ? 0.0 : ForceLcase.dMuz[j] / dZzi);							// Bzi.
			double dBIi = (1)*(dIw == 0.0 ? 0.0 : ForceLcase.dMbi[j] / dIw * dwi);	          // Mw/Iw*w, Bi-moment
			double dSxi = (-1)*(dArea == 0.0 ? 0.0 : dTndnPs * fabs(cos(dTndnRad)) / dArea);		// Sxi.
			double dSzi = (-1)*(db*da == 0.0 ? 0.0 : dTndnPs * fabs(sin(dTndnRad)) / (db*da));	// Szi.
			double dTas = (dIyy*db == 0.0 ? 0.0 : ForceLcase.dFzz[j] * dQ / ((dIyy / StrsBase.dScaleIy)*db));			// Tau_s.
			double dTat = (dKt == 0.0 ? 0.0 : ForceLcase.dMux[j] / dKt);								// Tau_t.
			double dTap = (db*da == 0.0 ? 0.0 : dTndnPs * dCngSign*cos(dCngRad) / (db*da));// Tau_p.
			//double dTasm= (db*dd==0.0 ? 0.0 : ForceLcase.dFzz[j]/(db*dd));						// Tau_s(average).
			//double dTatm= dTat;																														// Tau_t(average).
			double dTat_xy = 0.0, dTat_xz = 0.0;
			double dSwt = 0.0;
			double dSwt_xy = 0.0;
			if (bIs7Dof || bIsPscOpen)
			{
				Calc_Tat(bIs7Dof, dCyi, dCzi, dIp, dJ, ForceLcase.dMux[j], ForceLcase.dTst[j], ForceLcase.dTwp[j], dXYsh[k], dXZsh[k], dTat_xy, dTat_xz, dSwt, dSwt_xy, dTat);
			}

			double dSxm = dSxx + dByi + dBzi + dBIi;
			double dSx = dSxm + dSxi;

			// Change by ZINU.('05.11.16). Consider Sign(+/-) of dTat.
			if (k == 0 || k == 3 || k == 4 || k == 6 || k == 8)	dTat *= -1;	// Left Side.

			StssLcase.dShr[j][k][0] = dSxx;                                     // 1.Axial X Normal Stress
			StssLcase.dShr[j][k][1] = dByi;                                     // 2.Moment-y X Normal Stress 
			StssLcase.dShr[j][k][2] = (m_iDimType == 0 ? 0.0 : dBzi);             // 3.Moment-z X Normal Stress       
			StssLcase.dShr[j][k][3] = dSxi;                                     // 4.강봉 X Normal Stres
			StssLcase.dShr[j][k][4] = (m_iDimType != 2 ? dSxx + dByi + dSxi : dSx);   // 5.Sum
			StssLcase.dShr[j][k][5] = dSzi;                                     // 6.강봉 z Normal Stress
			StssLcase.dShr[j][k][6] = dTas;                                     // 7.Shear z Shear Stress
			StssLcase.dShr[j][k][7] = (m_iDimType == 0 ? 0.0 : dTat);             // 8.Torsion Shear Stress  
			StssLcase.dShr[j][k][8] = dTap;                                     // 9.강봉 Shear Stress   
			StssLcase.dShr[j][k][16] = dSwt;                                     // 17.warping torsion xz   
		}
	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_LoadCaseStss_EX(ElemPairK ElemK, BOOL bTndnPs, T_SBCF_D& StrMaxData, T_SBCF_D& StrMinData, ADGNSHRSADD_EX &aStssLcase)
{
	aStssLcase.RemoveAll();

	int i = 0, j = 0, k = 0; // dyzM(4군데).
	// Get Elem Data.
	T_ELEM_D ElemD;
	ElemD.Initialize();
	if (!m_pPostCtrl->GetElemPost(ElemK.first, ElemD))	return FALSE;
	T_SECT_K SectK = ElemD.elpro;
	// Get Sect Data.
	T_SECT_D SectD;
	SectD.Initialize();
	if (!m_pPostCtrl->GetSectPost(SectK, SectD))	return FALSE;
	T_SECT_K OrgSectK = m_pPostCtrl->GetOrgSectKeyPost(SectK);

	BOOL bComposit = FALSE;
	BOOL bCompositGen = FALSE;
	double dtc = 0.0;
	double dHh = 0.0;
	if (SectD.nStype == D_SECT_TYPE_COMPO_CI || SectD.nStype == D_SECT_TYPE_COMPO_CT || SectD.nStype == D_SECT_TYPE_COMPO_PC)
	{
		bComposit = TRUE;
		//   double dBc = SectD.SectAfter.SectJ.Size[0];
		dtc = SectD.SectAfter.SectJ.Size[1];
		dHh = SectD.SectAfter.SectJ.Size[2];
	}
	else if (SectD.nStype == D_SECT_TYPE_COMPO_G)
	{
		ASSERT(0);
		bCompositGen = TRUE;
	}

	// Get Rbar Data.
	T_RPSC_D RpscMbar, RpscSbar;
	RpscMbar.Initialize();
	m_pAttrCtrl->GetRpscByConsiderRbar(TRUE, OrgSectK, RpscMbar);
	RpscSbar.Initialize();
	m_pAttrCtrl->GetRpscByConsiderRbar(FALSE, OrgSectK, RpscSbar);
	// Remove by ZINU.('06.04.24). Use Data at StrsPost.
	/*
	// Add by ZINU.('04.12.17). Set Effective Width Scale Factor.
	double dScaleIy=1.0, dScaleZt=1.0, dScaleZb=1.0;
	T_EWSF_D EwsfD;
	EwsfD.Initialize();
	if(m_pAttrCtrl->GetEwsfElem(ElemK,EwsfD))
	{
	dScaleIy = EwsfD.dScaleFactor;
	dScaleZt = EwsfD.dZtopFactor;
	dScaleZb = EwsfD.dZbotFactor;
	}
	*/
	BOOL bIs7Dof = SectD.SectBefore.bConsiderWarpingEffect;
	BOOL bIsPscOpen = CDBLib::IsPscOpenSect(SectD.SectBefore.Shape);
	T_STRSPROP_D StrsPropD;
	if (bIs7Dof || bIsPscOpen)
	{
		m_pSectInfo->ReadSectPostProp(ElemK.first, StrsPropD);
	}

	for (i = 0; i < cFORC_CON; ++i)
	{
		T_SBCF_D &SbcfData = (i % 2 == 0) ? StrMaxData : StrMinData;

		// Force.
		_DGN_FORC_CRC_EX ForceLcase;
		for (j = 0; j < cPOSI_CRC_EX; ++j)
		{
			int iPart = (j < cPOSI_CRC_EX - 1 ? j : j - 1);
			int iKind = (j == 0 ? 0 : 6);
			ForceLcase.dFxx[j] = SbcfData.dblForce[iPart][j][i / 2][0];
			ForceLcase.dFyy[j] = SbcfData.dblForce[iPart][j][i / 2][1];
			ForceLcase.dFzz[j] = SbcfData.dblForce[iPart][j][i / 2][2];
			ForceLcase.dMux[j] = SbcfData.dblForce[iPart][j][i / 2][3];
			ForceLcase.dMuy[j] = SbcfData.dblForce[iPart][j][i / 2][4];
			ForceLcase.dMuz[j] = SbcfData.dblForce[iPart][j][i / 2][5];
			ForceLcase.dMbi[j] = SbcfData.dblForce[iPart][j][i / 2][6];
			ForceLcase.dTst[j] = SbcfData.dblForce[iPart][j][i / 2][7];
			ForceLcase.dTwp[j] = SbcfData.dblForce[iPart][j][i / 2][8];
		}

		Set_DimTypeForc_EX(ForceLcase);

		_DGN_SHRS_ADD_EX StssLcase;
		StssLcase.Initialize();
		for (j = 0; j < cPOSI_CRC_EX; ++j)
		{
			// Get Depth.
			int iPosi = (CDBLib::IsSectI((j < cPOSI_CRC_EX - 1), SectD.nStype) ? 0 : 1);
			T_SECT_STIFFNESS &SectStiff = (iPosi == 0) ? SectD.SectBefore.SectI.Stiffness : SectD.SectBefore.SectJ.Stiffness;
			double dCzp = SectStiff.Czp;
			double dCzm = SectStiff.Czm;
			double dzDim = 0.0;
			if (bCompositGen) dzDim = m_dHeight[i];
			else             dzDim = dCzp + dCzm + (bComposit ? dtc : 0.0);

			int iPosiM = (RpscMbar.bMbarJ && (j < cPOSI_CRC_EX - 1) ? 0 : 1);
			int iMbarNum = RpscMbar.Mbar[iPosiM].GetSize();
			// Change by ZINU.('04.06.30). If No Rbar, Effective Depth is Total Depth (by Kouno).
			double ddT = (iMbarNum == 0 ? 0.0 : dCzp);
			double ddB = (iMbarNum == 0 ? 0.0 : dCzm);
			for (k = 0; k < iMbarNum; ++k)
			{
				T_RPSC_MBAR &Mbar = RpscMbar.Mbar[iPosiM].GetAt(k);
				ddT = min(ddT, (Mbar.iStaZRef == 0 ? Mbar.dStaZ : dzDim - Mbar.dStaZ));
				ddB = min(ddB, (Mbar.iStaZRef == 1 ? Mbar.dStaZ : dzDim - Mbar.dStaZ));
				if (ddT < 0.0) { ddT = 0.0; /*ASSERT(0);*/ }
				if (ddB < 0.0) { ddB = 0.0; /*ASSERT(0);*/ }
			}

			T_STRSPOST_BASE &StrsBase = (j < cPOSI_CRC_EX - 1) ? m_StrsPost.StrsBaseI : m_StrsPost.StrsBaseJ;
			T_STRSPROP_BASE &StrsProp = (j < cPOSI_CRC_EX - 1) ? StrsPropD.PropB[0] : StrsPropD.PropB[4];
			double dArea = StrsBase.dArea;
			double dIyy = StrsBase.dIyy * StrsBase.dScaleIy;
			double dIzz = StrsBase.dIzz;
			double dIw = 0.0;
			double dJ = 0.0;
			double dIp = 0.0;

			int nPosIJ = (j < cPOSI_CRC_EX - 1) ? 0 : 4;
			T_SECT_STIFFNESS &StiffD = StrsPropD.PropB[nPosIJ].Stiff.Stiffness;
			double dYs[10] = { 0.0 }, dZs[10] = { 0.0 };
			double dWi[10] = { 0.0 }, dXYsh[10] = { 0.0 }, dXZsh[10] = { 0.0 };
			GetStressPointData4STSS(StrsBase, StrsPropD.PropB[nPosIJ], dYs, dZs, dWi, dXYsh, dXZsh);

			// Tendon Data.
			// Change by ZINU.('04.12.06). Set Tndn Reduction Factor (_CH=0.6, else=1.0).
			// Change by ZINU.('05.09.09). Add bTndnPs Option.
			double dTndnPs = 0.0, dTndnDist = 0.0, dTndnRad = 0.0, dCngRad = 0.0, dCngSign = 0.0;
			if (bTndnPs)
			{
				int iPosiS = (RpscSbar.bSbarJ && (j < cPOSI_CRC_EX - 1) ? 0 : 1);
				dTndnPs = (RpscSbar.Sbar[iPosiS].bTndnExist ? RpscSbar.Sbar[iPosiS].dTndnPs * RpscSbar.Sbar[iPosiS].dTndnFactor : 0.0);
				dTndnDist = (RpscSbar.Sbar[iPosiS].bTndnExist ? RpscSbar.Sbar[iPosiS].dTndnDist : 0.0);
				dTndnRad = (RpscSbar.Sbar[iPosiS].bTndnExist ? RpscSbar.Sbar[iPosiS].dTndnTheta / (180. / m_dPi) : 0.0);	// Deg -> Rad.
				// Change by ZINU.('05.11.19). Make All Deg -180 ~ 180 Deg.
				dCngRad = fmod(dTndnRad, m_dPi);
				dCngSign = (dCngRad >= 0.0 ? 1.0 : -1.0);
			}

			// Change by ZINU.('04.12.01). Modify Checking Position. dyzV(6) -> dyzM(4) + dyzV(6).
			for (k = 0; k < 10; ++k)	// 0~3=dyzM, 4=TL, 5=TR, 6=CL, 7=CR, 8=BL, 9=BR.
			{
				// Change by ZINU.('05.11.09). Apply dScaleZ, Position 1~4 -> Position 1~4 + 5,6,9,10.
				// Change by ZINU.('06.04.24). Consider N.A by Eeffective Width Scale Factor.
				// Change by ZINU.('06.05.23). dMoveZ : Top(1,2,5,6),Bot(3,4,9,10) -> dCzi Sign.
				double dCyi = (k < 4 ? StrsBase.dyzM[0][k] : StrsBase.dyzV[0][k - 4]);
				double dCzi = (k < 4 ? StrsBase.dyzM[1][k] : StrsBase.dyzV[1][k - 4]);
				double dMoveZ = 0.0;
				if (k == 0 || k == 1)				dMoveZ = StrsBase.dMoveTop;
				else if (k == 2 || k == 3)					dMoveZ = StrsBase.dMoveBot;
				else if (k == 4 || k == 5 || k == 8 || k == 9)	dMoveZ = (dCzi > 0.0 ? StrsBase.dMoveTop : StrsBase.dMoveBot);
				dCzi -= dMoveZ;
				if (bIs7Dof || bIsPscOpen)
				{
					dArea = StiffD.Area;
					//dQyb	= StrsBase[i+j].dQyb;
					//dQzb	= StrsBase[i+j].dQzb;
					dIyy = StiffD.Ryy * StrsBase.dScaleIy;
					dIzz = StiffD.Rzz;
					dIw = StiffD.dIw;
					dJ = StiffD.Rxx;
					dIp = dIyy + dIzz;

					dCyi = dYs[k];
					dCzi = dZs[k];
				}

				double dZyi = (dCzi == 0.0 ? 0.0 : dIyy / dCzi);
				double dZzi = (dCyi == 0.0 ? 0.0 : dIzz / dCyi);
				double dQ = (k < 4 ? 0.0 : StrsBase.dQ[(k - 4) / 2]);
				double db = (k < 4 ? 0.0 : StrsBase.db[(k - 4) / 2]);
				double dd = (ForceLcase.dMuy[j] > 0.0 ? dzDim - ddB : dzDim - ddT);
				double da = dTndnDist;

				// Kt값을 위치별로 받음 - PKS
				//      double dKt	= StrsBase.dKt;
				double dKt = 0.0;
				if (k == 0)      dKt = StrsBase.dKtweb[0]; // stress point 0
				else if (k == 1) dKt = StrsBase.dKtweb[1]; // 
				else if (k == 2) dKt = StrsBase.dKtweb[5];
				else if (k == 3) dKt = StrsBase.dKtweb[4];
				else          dKt = StrsBase.dKtweb[k - 4];

				// For Combined Stresses.
				// Change by ZINU.('04.12.27). Multiply (-1) at dBzi.
				double dSxx = (dArea == 0.0 ? 0.0 : ForceLcase.dFxx[j] / dArea);							// Sxx.
				double dByi = (-1)*(dZyi == 0.0 ? 0.0 : ForceLcase.dMuy[j] / dZyi);							// Byi.
				double dBzi = (-1)*(dZzi == 0.0 ? 0.0 : ForceLcase.dMuz[j] / dZzi);							// Bzi.        
				double dSxi = (-1)*(dArea == 0.0 ? 0.0 : dTndnPs * fabs(cos(dTndnRad)) / dArea);		// Sxi.
				double dSzi = (-1)*(db*da == 0.0 ? 0.0 : dTndnPs * fabs(sin(dTndnRad)) / (db*da));	// Szi.
				double dTas = (dIyy*db == 0.0 ? 0.0 : ForceLcase.dFzz[j] * dQ / ((dIyy / StrsBase.dScaleIy)*db));			// Tau_s.
				double dTat = (dKt == 0.0 ? 0.0 : ForceLcase.dMux[j] / dKt);								// Tau_t.
				double dTap = (db*da == 0.0 ? 0.0 : dTndnPs * dCngSign*cos(dCngRad) / (db*da));// Tau_p.
				//double dTasm=			 (db*dd==0.0 ? 0.0 : ForceLcase.dFzz[j]/(db*dd));						// Tau_s(average).
				//double dTatm=	dTat;																														// Tau_t(average).        
				double dBwi = 0.0;
				double dTat_xy = 0.0, dTat_xz = 0.0;
				double dSwt = 0.0;
				double dSwt_xy = 0.0;
				if (bIs7Dof || bIsPscOpen)
				{
					Calc_Tat(bIs7Dof, dCyi, dCzi, dIp, dJ, ForceLcase.dMux[j], ForceLcase.dTst[j], ForceLcase.dTwp[j], dXYsh[k], dXZsh[k], dTat_xy, dTat_xz, dSwt, dSwt_xy, dTat);
					dBwi = (-1)*(dIw == 0.0) ? 0.0 : ForceLcase.dMbi[j] / dIw * dWi[k];                // Bi-moment
				}
				double dSxm = dSxx + dByi + dBzi + dBwi;
				double dSx = dSxm + dSxi;
				// Change by ZINU.('05.11.16). Consider Sign(+/-) of dTat.
				if (k == 0 || k == 3 || k == 4 || k == 6 || k == 8)	dTat *= -1;	// Left Side.

				StssLcase.dShr[j][k][0] = dSxx;                                   // 1.Axial X Normal Stress
				StssLcase.dShr[j][k][1] = dByi;                                   // 2.Moment-y X Normal Stress 
				StssLcase.dShr[j][k][2] = (m_iDimType == 0 ? 0.0 : dBzi);           // 3.Moment-z X Normal Stress       
				StssLcase.dShr[j][k][3] = dSxi;                                   // 4.강봉 X Normal Stres
				StssLcase.dShr[j][k][4] = (m_iDimType != 2 ? dSxx + dByi + dSxi : dSx); // 5.Sum
				StssLcase.dShr[j][k][5] = dSzi;                                   // 6.강봉 z Normal Stress
				StssLcase.dShr[j][k][6] = dTas;                                   // 7.Shear z Shear Stress
				StssLcase.dShr[j][k][7] = (m_iDimType == 0 ? 0.0 : dTat);           // 8.Torsion Shear Stress  
				StssLcase.dShr[j][k][8] = dTap;                                   // 9.강봉 Shear Stress 
				StssLcase.dShr[j][k][16] = dSwt;                                     // 17.warping torsion xz   
			}
		}

		aStssLcase.Add(StssLcase);
	}

	return TRUE;
}


void CCRCForceCtrl::MakePLCBStldKey(int nDgnCode)
{
	m_mapPlcbStldK.RemoveAll();
	// Pre-Combined Composite Bridge
	T_PLCB_D PlcbD; PlcbD.Initialize();

	switch (nDgnCode)
	{
	case EUROCODE4_2_04_CSG:
	case KSCE_LSD15_CSG:
	case AASHTO_LRFD07_CSG:
	case AASHTO_LRFD12_CSG:
	case AASHTO_LRFD16_CSG:
	case AASHTO_LRFD17_CSG:
	case AASHTO_LRFD20_CSG:
	case KDS_24_14_31_2018_CSG:
	case KSSC_2014_CSG:
	case SNiP_20503_84_CSG:
	case SP_35_13330_11_CSG:
	case CSA_S6_10_CSG:
	case CSA_S6_14_CSG:
	case CSA_S6_19_CSG:
	case CS457_R1_CSG:
	case NR_GN_CIV_025_06_CSG:
	case AS5100_6_17_CSG:
	case AASHTO_LRFD12_PSC_RATING:
	case AASHTO_LRFD19_PSC_RATING:
	case STL_CS454_20:
	case AASHTO_LRFD08:
	case AASHTO_LRFD12:
	case AASHTO_LRFD14:
	case AASHTO_LRFD16:
	case AASHTO_LRFD17:
	case AASHTO_LRFD20:
	case AASHTO_LRFD24:
	case EUROCODE2_2_05_PSC:
	case IRC_112_2011_PSC:
	case IRC_112_2020_PSC:
	case AS_5100_5_17_PSC:
	case KDS_24_14_21_2022_PSC:
	case KSCE_LSD15_PSC:
	case TMH07_3_1989:
	case BS5400_90_PSC:
	case BD_44_15_PSC:
	case CS_455_PSC:
	case CSA_S6_10:
	case CSA_S6_14:
	case CSA_S6_19:
	case SNiP_20503_84_PSC:
	case SP_35_13330_11_PSC:
	case SNiP_20503_84_PSC_MKS:
	case SP_35_13330_11_PSC_MKS:
	case IRS_PSC:
	case STL_AASHTO_LRFD12:
	case STL_AASHTO_LRFD19:
	case STL_NR_GN_CIV_025_06:
	case ABNT_NBR_6118_2023_PSC:
	case AREMA_23:
		m_bIsPLCB = m_pAttrCtrl->ExistPlcb();
		if (m_bIsPLCB == TRUE)
		{
			if (m_pAttrCtrl->GetPlcb(PlcbD))
			{
				int nPlcbStldSize = PlcbD.arLoad.GetSize();
				for (int j = 0; j < nPlcbStldSize; ++j)
				{
					const T_STLD_K &PlcbStldK = PlcbD.arLoad[j];
					m_mapPlcbStldK.SetAt(PlcbStldK, PlcbStldK);
				}
			}
		}
		break;
	default:
		ASSERT(0);
		break;
	}
}

/////////////////////////////////////
// Bridge Load Rating Design.
/////////////////////////////////////
void CCRCForceCtrl::PrestressStldKey(ArrElemPairKey& arElemK)
{

	m_mapPrstStldKey.clear();
	m_mapTdplStldKey.clear();

	CMap<T_STLD_K, T_STLD_K, T_STLD_K, T_STLD_K> mapStldK;

	int i, j, k;
	for (i = 0; i < arElemK.GetSize(); ++i)
	{
		ElemPairK ElemK = arElemK[i];
		CArray<T_PRST_K, T_PRST_K> arPrstKey;
		CArray<T_PRST_D, T_PRST_D&> arPrstD;
		m_pAttrCtrl->GetPrst(ElemK.first, arPrstKey, arPrstD);

		// Get Prestress Beam Load.
		mapStldK.RemoveAll();
		mapStldK.InitHashTable(HASHSIZESTLD);
		for (j = 0; j < arPrstD.GetSize(); ++j)
		{
			T_PRST_D PrstD = arPrstD[j];
			// T_STLD_K
			T_STLD_K StldK = PrstD.LoadCaseKey;
			mapStldK.SetAt(StldK, StldK);
		}
		PRESTRESS_STLD_KEY PrestrssStldKey;
		PrestrssStldKey.Initialize();

		POSITION Pos = mapStldK.GetStartPosition();
		T_STLD_K TempStldK, StldKey;
		while (Pos)
		{
			mapStldK.GetNextAssoc(Pos, TempStldK, StldKey);
			PrestrssStldKey.mapStldK.SetAt(StldKey, StldKey);
		}
		m_mapPrstStldKey.insert({ ElemK, PrestrssStldKey });

		// Get Tendon Prestress Load.
		mapStldK.RemoveAll();
		mapStldK.InitHashTable(HASHSIZESTLD);
		T_TENDON_ELEMINFO TndnElemInfo;
		TndnElemInfo.Initialize();
		m_pPostCtrl->GetTendonInfo()->GetTendonElemInfo(ElemK.first, TndnElemInfo);
		int iTndnNum = TndnElemInfo.aTendonElemInfoTendon.GetSize();
		for (j = 0; j < iTndnNum; ++j)
		{
			T_TENDON_ELEMINFO_TENDON TndnD = TndnElemInfo.aTendonElemInfoTendon.GetAt(j);
			// Check if Prestressed Tendon.
			if (!TndnD.bPrestressed)	continue;
			CArray<T_TDPL_K, T_TDPL_K>  aTdplK;
			CArray<T_TDPL_D, T_TDPL_D&> aTdplD;
			m_pAttrCtrl->GetTdpl(TndnD.KeyTdna, aTdplK, aTdplD);
			for (k = 0; k < aTdplD.GetSize(); ++k)
			{
				T_TDPL_D TdplD = aTdplD[k];
				T_STLD_K StldK = TdplD.LoadCaseKey;
				mapStldK.SetAt(StldK, StldK);
			}
		}
		//
		PrestrssStldKey.Initialize();
		Pos = mapStldK.GetStartPosition();
		while (Pos)
		{
			mapStldK.GetNextAssoc(Pos, TempStldK, StldKey);
			PrestrssStldKey.mapStldK.SetAt(StldKey, StldKey);
		}
		m_mapTdplStldKey.insert({ ElemK, PrestrssStldKey });
		//
	}
}

int  CCRCForceCtrl::GetStlRCDgnLcomKey(const int nLCSize, const int nConcSize, int nRCase, int nLC, int nConc)
{
	int nRCDgnSize = nLCSize * nConcSize;
	int nRCDgnKey = nRCDgnSize * nRCase + nConcSize * nLC + nConc;

	return nRCDgnKey;
}

BOOL CCRCForceCtrl::Get_ForceStressPSCDataForAASHTO(ElemPairK ElemK, CArray<FORCE_BLRD_RCASE, FORCE_BLRD_RCASE>& arForceRCase, CArray<STRESS_BLRD_RCASE, STRESS_BLRD_RCASE>& arStressRCase,
	CArray<STRESS_BLRD_RCASE, STRESS_BLRD_RCASE>& arSlabStressRCase, CArray<FORCE_BLRD_RCASE, FORCE_BLRD_RCASE>& arPreCompoRCase)
{
	arForceRCase.RemoveAll();
	arStressRCase.RemoveAll();
	arSlabStressRCase.RemoveAll();

	// Reset DimType.
	m_iDimType = 2;	// Set 3D.
	// Consider No Effect Zone.
	Set_RatNoEffectZone(ElemK);

	m_StrsPost.Initialize();
	m_pSectInfo->Get_StrsPscd(FALSE, ElemK.first, m_StrsPost);

	T_ELEM_D ElemD;
	ElemD.Initialize();
	if (!m_pPostCtrl->GetElemPost(ElemK.first, ElemD))	return FALSE;

	T_SECT_D SectD;   SectD.Initialize();
	if (!m_pPostCtrl->GetSectPost(ElemD.elpro, SectD))	return FALSE;

	BOOL bIsCptPSC = m_pDataCtrl->IsComPSCSect(SectD.nStype, SectD.SectBefore.nStype);
	// Composite 경우 Part force/stress를 위해..
	int nForceType = (bIsCptPSC == TRUE) ? 1 : 0;

	BOOL IsPLCB = m_pAttrCtrl->ExistPlcb();

	// 이 함수에 Rating Case별 계산을 한다.

	CArray<unsigned int, unsigned int> arBlrcKey;

	m_pAttrCtrl->GetBlrcKeyList(arBlrcKey);

	int i = 0, j = 0, k = 0, m = 0;

	int iRatingCaseNum = arBlrcKey.GetSize();
	if (iRatingCaseNum == 0)	return FALSE;
	arForceRCase.SetSize(iRatingCaseNum);
	arStressRCase.SetSize(iRatingCaseNum);
	if (bIsCptPSC)
	{
		arSlabStressRCase.SetSize(iRatingCaseNum);
		if (IsPLCB == TRUE)    arPreCompoRCase.SetSize(iRatingCaseNum);
	}


	for (i = 0; i < iRatingCaseNum; ++i)
	{
		// Initialize Forces.
		_DGN_FORC_CRC_EX ForceDCBe[2], ForceDC[2], ForceDW[2], ForceT[2], ForceTG[2], ForceSEC, ForcePERM, ForceUSER, ForcePrVehi[12], ForceAdVehi[12];
		_DGN_STRS_CRC_EX StressDCBe[2], StressDC[2], StressDW[2], StressT[2], StressTG[2], StressSEC, StressPERM, StressUSER, StressPrVehi[12], StressAdVehi[12];

		STRESS_BLRD_RCASE *pSlabStr;

		// Check Existing Reciprocal Stress.
		T_LCRS_D LcrsD;
		LcrsD.Initialize();
		BOOL bReciInput = m_pAttrCtrl->GetLcrs(LcrsD);

		int nRatLoadCaseNum = 0;
		BOOL bCalcStss = FALSE;
		T_BLRC_D BlrcData; BlrcData.Initialize();
		T_RLCS_D RlcsD; RlcsD.Initialize();

		T_LCOM_BASE *pPrimaryVeh;
		T_LCOM_BASE *pAdjacentVeh;

		m_pAttrCtrl->GetBlrc(arBlrcKey[i], BlrcData);
		bCalcStss = (BlrcData.iLimitState == 0);
		nRatLoadCaseNum = RATING_LOAD_CASE_NUM;
		pPrimaryVeh = &BlrcData.PrimaryVeh;
		pAdjacentVeh = &BlrcData.AdjacentVeh;
		if (bIsCptPSC == TRUE) pSlabStr = &arSlabStressRCase[i];

		// Static
		unsigned int iAnalType;
		unsigned int iLcaseKey;
		double dFactor;
		BOOL bReciLcase;
		for (j = 0; j < nRatLoadCaseNum; ++j)
		{
			T_RTLD_D *pRtldD;
			pRtldD = &BlrcData.RateLoad[j];

			// DC (Dead-load effect due to structural components and attachment)
			int iLoadCaseNum = pRtldD->Combination.GetSize();
			int FactorType = pRtldD->FactorType;
			int iIter = 0;
			if ((j >= 0 && j < 3) || j == 6) iIter = 2; // 6= Temperature gradient
			else                      iIter = 1;

			for (k = 0; k < iIter; ++k)
			{
				Set_ForceIni();
				for (m = 0; m < iLoadCaseNum; m++)
				{
					T_LCOM_BASE &BlrcBase = pRtldD->Combination[m];
					iAnalType = BlrcBase.AnalType;
					iLcaseKey = BlrcBase.LoadCaseKey;
					dFactor = pRtldD->dFactor[k];
					bReciLcase = (bReciInput ? Is_Reciprocal(iAnalType, iLcaseKey) : FALSE);
					if (j == 3)
					{
						if (iAnalType == D_LCOM_STATIC)
						{
							BOOL bPrst = FALSE;
							BOOL bTdpl = FALSE;
							// Prst
							PRESTRESS_STLD_KEY PreStldKey;
							const auto& itPrst = m_mapPrstStldKey.find(ElemK);
							if (itPrst != m_mapPrstStldKey.end())
							{
								T_STLD_K StldKey;
								if (itPrst->second.mapStldK.Lookup(iLcaseKey, StldKey)) bPrst = TRUE;
							}
							// Tdpl              
							const auto& itTdpl = m_mapTdplStldKey.find(ElemK);
							if (itTdpl != m_mapTdplStldKey.end())
							{
								T_STLD_K StldKey;
								if (itTdpl->second.mapStldK.Lookup(iLcaseKey, StldKey)) bTdpl = TRUE;
							}

							if (bPrst || bTdpl)
							{
								Get_Stld_TndnSecondary(ElemK, iLcaseKey, dFactor, bReciLcase);
							}
							else
							{
								Get_Stld(ElemK, iLcaseKey, 0, bCalcStss, dFactor, bReciLcase);
							}
						}
						else if (iAnalType == D_LCOM_SPECTRUM)	Get_Splc_EX(ElemK, iLcaseKey, nForceType, bCalcStss, dFactor);
						else if (iAnalType == D_LCOM_ECCENSPEC)	Get_Espc_EX(ElemK, iLcaseKey, nForceType, bCalcStss, dFactor);
						else if (iAnalType == D_LCOM_HISTORY)	Get_This_EX(ElemK, iLcaseKey, nForceType, bCalcStss, dFactor);
						else if (iAnalType == D_LCOM_STAGE)		Get_Sgld_EX(ElemK, iLcaseKey, nForceType, bCalcStss, dFactor, bReciLcase, TRUE, 0);	// If iStepNo=0, Final Stage.
						else ASSERT(0);
						if (j == 0)
						{
							if (arPreCompoRCase.GetSize() > 0)
							{
								_DGN_STRS_CRC_EX StressTemp;
								Get_PreForceStress4RatingDL_EX(arPreCompoRCase[i].ForceDCBe[k], StressTemp);
							}
						}
					}
					else
					{
						if (iAnalType == D_LCOM_STATIC)    Get_Stld_EX(ElemK, iLcaseKey, nForceType, bCalcStss, dFactor, bReciLcase);
						else if (iAnalType == D_LCOM_SPECTRUM)	Get_Splc_EX(ElemK, iLcaseKey, nForceType, bCalcStss, dFactor);
						else if (iAnalType == D_LCOM_ECCENSPEC)	Get_Espc_EX(ElemK, iLcaseKey, nForceType, bCalcStss, dFactor);
						else if (iAnalType == D_LCOM_HISTORY)	Get_This_EX(ElemK, iLcaseKey, nForceType, bCalcStss, dFactor);
						else if (iAnalType == D_LCOM_STAGE)		Get_Sgld_EX(ElemK, iLcaseKey, nForceType, bCalcStss, dFactor, bReciLcase, TRUE, 0);	// If iStepNo=0, Final Stage.
						else	ASSERT(0);
					}
				}
				// Get Data.
				if (j == 0)      Get_BlrdForceStress_EX(ForceDC[k], StressDC[k]);  // DC
				else if (j == 1) Get_BlrdForceStress_EX(ForceDW[k], StressDW[k]);  // DW
				else if (j == 2) Get_BlrdForceStress_EX(ForceT[k], StressT[k]);    // T
				else if (j == 3) Get_BlrdForceStress_EX(ForceSEC, StressSEC);      // SEC        
				else if (j == 4) Get_BlrdForceStress_EX(ForcePERM, StressPERM);    // Permanent
				else if (j == 5) Get_BlrdForceStress_EX(ForceUSER, StressUSER);    // User    
				else if (j == 6) Get_BlrdForceStress_EX(ForceTG[k], StressTG[k]);  // TG(Temperature gradient)
				else ASSERT(0);
				//
				if (bIsCptPSC == TRUE)
				{
					if (j == 0)      Get_StressPart2_EX(pSlabStr->StressDC[k]);    // DC
					else if (j == 1) Get_StressPart2_EX(pSlabStr->StressDW[k]);    // DW
					else if (j == 2) Get_StressPart2_EX(pSlabStr->StressTemp[k]);  // T
					else if (j == 3) Get_StressPart2_EX(pSlabStr->StressSec);      // SEC        
					else if (j == 4) Get_StressPart2_EX(pSlabStr->StressPerm);     // Permanent
					else if (j == 5) Get_StressPart2_EX(pSlabStr->StressUser);     // User    
					else if (j == 6) Get_StressPart2_EX(pSlabStr->StressTempG[k]); // TG(Temperature gradient)
					else ASSERT(0);
				}
				if (j == 0)
				{
					if (arPreCompoRCase.GetSize() > 0)
					{
						_DGN_STRS_CRC_EX StressTemp;
						Get_PreForceStress4RatingDL_EX(arPreCompoRCase[i].ForceDCBe[k], StressTemp);
					}
				}
			}
		}
		//int nForType =0; // 전체단면부재력 받아옴.
		// Primary Vehicle
		iAnalType = pPrimaryVeh->AnalType;
		iLcaseKey = pPrimaryVeh->LoadCaseKey;
		dFactor = pPrimaryVeh->Factor;
		bReciLcase = (bReciInput ? Is_Reciprocal(iAnalType, iLcaseKey) : FALSE);
		for (j = 0; j < 12; ++j)
		{
			Set_ForceIni();
			int iMaxMinType = j + 1;
			if (iAnalType == D_LCOM_MOVING)			Get_Mvld_EX(ElemK, iLcaseKey, nForceType, bCalcStss, dFactor, bReciLcase, iMaxMinType);
			else	ASSERT(0);
			Get_BlrdForceStress_EX(ForcePrVehi[j], StressPrVehi[j]);
			if (bIsCptPSC == TRUE) Get_StressPart2_EX(pSlabStr->StressPrVehicle[j]);
		}
		// Adjacent Vehicle
		iAnalType = pAdjacentVeh->AnalType;
		iLcaseKey = pAdjacentVeh->LoadCaseKey;
		dFactor = pAdjacentVeh->Factor;
		bReciLcase = (bReciInput ? Is_Reciprocal(iAnalType, iLcaseKey) : FALSE);
		for (j = 0; j < 12; ++j)
		{
			Set_ForceIni();
			int iMaxMinType = j + 1;
			if (iAnalType == D_LCOM_MOVING)			Get_Mvld_EX(ElemK, iLcaseKey, nForceType, bCalcStss, dFactor, bReciLcase, iMaxMinType);
			else	ASSERT(0);
			Get_BlrdForceStress_EX(ForceAdVehi[j], StressAdVehi[j]);
			if (bIsCptPSC == TRUE) Get_StressPart2_EX(pSlabStr->StressAdVehicle[j]);
		}

		FORCE_BLRD_RCASE ForceBlrdRcase; ForceBlrdRcase.Initialize();
		STRESS_BLRD_RCASE StressBlrdRcase; StressBlrdRcase.Initialize();

		for (j = 0; j < 2; ++j)
		{
			// Force
			ForceBlrdRcase.ForceDCBe[j] = ForceDCBe[j];
			ForceBlrdRcase.ForceDC[j] = ForceDC[j];
			ForceBlrdRcase.ForceDW[j] = ForceDW[j];
			ForceBlrdRcase.ForceTemp[j] = ForceT[j];
			ForceBlrdRcase.ForceTempG[j] = ForceTG[j];
			// Stress
			StressBlrdRcase.StressDC[j] = StressDC[j];
			StressBlrdRcase.StressDW[j] = StressDW[j];
			StressBlrdRcase.StressTemp[j] = StressT[j];
			StressBlrdRcase.StressTempG[j] = StressTG[j];
		}
		// Force
		ForceBlrdRcase.ForceSec = ForceSEC;
		ForceBlrdRcase.ForcePerm = ForcePERM;
		ForceBlrdRcase.ForceUser = ForceUSER;
		// Stress
		StressBlrdRcase.StressSec = StressSEC;
		StressBlrdRcase.StressPerm = StressPERM;
		StressBlrdRcase.StressUser = StressUSER;
		for (j = 0; j < 12; ++j)
		{
			ForceBlrdRcase.ForcePrVehicle[j] = ForcePrVehi[j];
			ForceBlrdRcase.ForceAdVehicle[j] = ForceAdVehi[j];
			StressBlrdRcase.StressPrVehicle[j] = StressPrVehi[j];
			StressBlrdRcase.StressAdVehicle[j] = StressAdVehi[j];
		}

		arForceRCase.SetAt(i, ForceBlrdRcase);
		arStressRCase.SetAt(i, StressBlrdRcase);
	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_ForceStressSTLDataForAASHTO(ElemPairK ElemK, CArray<FORCE_BLRD_RCASE, FORCE_BLRD_RCASE>& arForceRCase, CArray<STRESS_BLRD_RCASE, STRESS_BLRD_RCASE>& arStressRCase,
	CArray<STRESS_BLRD_RCASE, STRESS_BLRD_RCASE>& arSlabStressRCase, CArray<FORCE_BLRD_RCASE, FORCE_BLRD_RCASE>& arPreCompoRCase)
{
	arForceRCase.RemoveAll();
	arStressRCase.RemoveAll();
	arSlabStressRCase.RemoveAll();

	// Reset DimType.
	m_iDimType = 2;	// Set 3D.
	// Consider No Effect Zone.
	Set_RatNoEffectZone(ElemK);

	m_StrsPost.Initialize();
	m_pSectInfo->Get_StrsPscd(FALSE, ElemK.first, m_StrsPost);

	T_ELEM_D ElemD;
	ElemD.Initialize();
	if (!m_pPostCtrl->GetElemPost(ElemK.first, ElemD))	return FALSE;

	T_SECT_D SectD;   SectD.Initialize();
	if (!m_pPostCtrl->GetSectPost(ElemD.elpro, SectD))	return FALSE;

	BOOL bIsCsgSect = m_pDataCtrl->IsCsgSect(SectD.nStype, SectD.SectBefore.nStype);
	// Composite 경우 Part force/stress를 위해..
	int nForceType = (bIsCsgSect == TRUE) ? 1 : 0;

	BOOL IsPLCB = m_pAttrCtrl->ExistPlcb();

	// 이 함수에 Rating Case별 계산을 한다.

	CArray<unsigned int, unsigned int> arBlrcKey;

	m_pAttrCtrl2->GetRlcsKeyList(arBlrcKey);

	int i = 0, j = 0, k = 0, m = 0;

	int iRatingCaseNum = arBlrcKey.GetSize();
	if (iRatingCaseNum == 0)	return FALSE;
	arForceRCase.SetSize(iRatingCaseNum);
	arStressRCase.SetSize(iRatingCaseNum);
	if (bIsCsgSect)
	{
		if (IsPLCB == TRUE)    arPreCompoRCase.SetSize(iRatingCaseNum);
	}


	for (i = 0; i < iRatingCaseNum; ++i)
	{
		// Initialize Forces.
		_DGN_FORC_CRC_EX ForceDCBe[2], ForceDC[2], ForceDW[2], ForceT[2], ForceTG[2], ForceSEC, ForcePERM, ForceUSER, ForcePrVehi[12], ForceAdVehi[12];
		_DGN_STRS_CRC_EX StressDCBe[2], StressDC[2], StressDW[2], StressT[2], StressTG[2], StressSEC, StressPERM, StressUSER, StressPrVehi[12], StressAdVehi[12];

		// Check Existing Reciprocal Stress.
		T_LCRS_D LcrsD;
		LcrsD.Initialize();
		BOOL bReciInput = m_pAttrCtrl->GetLcrs(LcrsD);

		int nRatLoadCaseNum = 0;
		BOOL bCalcStss = FALSE;
		T_BLRC_D BlrcData; BlrcData.Initialize();
		T_RLCS_D RlcsD; RlcsD.Initialize();

		T_LCOM_BASE *pPrimaryVeh;
		T_LCOM_BASE *pAdjacentVeh;

		m_pAttrCtrl2->GetRlcs(arBlrcKey[i], RlcsD);
		nRatLoadCaseNum = RATING_LOAD_CASE_STL_NUM;
		pPrimaryVeh = &RlcsD.PrimaryVeh;
		pAdjacentVeh = &RlcsD.AdjacentVeh;

		BOOL bAdjacentVehSkip = (m_iCivilCode == STL_AASHTO_LRFD19 && RlcsD.nLimitState == 2);

		// Static
		unsigned int iAnalType;
		unsigned int iLcaseKey;
		double dFactor;
		BOOL bReciLcase;
		for (j = 0; j < nRatLoadCaseNum; ++j)
		{
			T_RTLD_D *pRtldD;
			pRtldD = &RlcsD.RateLoad[j];
			// DC (Dead-load effect due to structural components and attachment)
			int iLoadCaseNum = pRtldD->Combination.GetSize();
			int FactorType = pRtldD->FactorType;
			int iIter = 0;
			if (j >= 0 && j < 5) iIter = 2;
			else            iIter = 1;

			if (j == 0)
			{
				iLoadCaseNum += 1;
			}
			for (k = 0; k < iIter; ++k)
			{
				Set_ForceIni();
				for (m = 0; m < iLoadCaseNum; m++)
				{
					if (j == 0)
					{
						if (m == 0) // 시공단계 있을 경우 DL을 고려하기 위해
						{
							CString strSgldNameT = _LS(IDS_DB_SGLD_DL);	// DL.
							T_SGLD_K TSgldK = m_pAttrCtrl->GetSgldKey(strSgldNameT);
							iAnalType = D_LCOM_STAGE;
							iLcaseKey = TSgldK;
						}
						else
						{
							T_LCOM_BASE& BlrcBase = pRtldD->Combination[m-1];
							iAnalType = BlrcBase.AnalType;
							iLcaseKey = BlrcBase.LoadCaseKey;
						}
					}
					else
					{
						T_LCOM_BASE &BlrcBase = pRtldD->Combination[m];
						iAnalType = BlrcBase.AnalType;
						iLcaseKey = BlrcBase.LoadCaseKey;
					}
					dFactor = pRtldD->dFactor[k];
					bReciLcase = (bReciInput ? Is_Reciprocal(iAnalType, iLcaseKey) : FALSE);

					if (iAnalType == D_LCOM_STATIC)       Get_Stld_EX(ElemK, iLcaseKey, nForceType, bCalcStss, dFactor, bReciLcase);
					else if (iAnalType == D_LCOM_SPECTRUM)		Get_Splc_EX(ElemK, iLcaseKey, nForceType, bCalcStss, dFactor);
					else if (iAnalType == D_LCOM_ECCENSPEC)	Get_Espc_EX(ElemK, iLcaseKey, nForceType, bCalcStss, dFactor);
					else if (iAnalType == D_LCOM_HISTORY)		Get_This_EX(ElemK, iLcaseKey, nForceType, bCalcStss, dFactor);
					else if (iAnalType == D_LCOM_STAGE)		Get_Sgld_EX(ElemK, iLcaseKey, nForceType, bCalcStss, dFactor, bReciLcase, TRUE, 0);	// If iStepNo=0, Final Stage.
					else	ASSERT(0);

				}
				// Get Data.
				if (j == 0)      Get_BlrdForceStress_EX(ForceDCBe[k], StressDCBe[k]);  // DC Before
				else if (j == 1) Get_BlrdForceStress_EX(ForceDC[k], StressDC[k]);  // DC
				else if (j == 2) Get_BlrdForceStress_EX(ForceDW[k], StressDW[k]);  // DW
				else if (j == 3) Get_BlrdForceStress_EX(ForceT[k], StressT[k]);    // T
				else if (j == 4) Get_BlrdForceStress_EX(ForceTG[k], StressTG[k]);  // TG(Temperature gradient)
				else if (j == 5) Get_BlrdForceStress_EX(ForceSEC, StressSEC);      // SEC        
				else if (j == 6) Get_BlrdForceStress_EX(ForcePERM, StressPERM);    // Permanent
				else if (j == 7) Get_BlrdForceStress_EX(ForceUSER, StressUSER);    // User              
				else ASSERT(0);
				// MQC-17218, Load Case for Pre-composite을 적용할 경우 Before 부재력이 고려 안되는 문제 수정
				if (j == 0)
				{
					if (arPreCompoRCase.GetSize() > 0)
					{
						_DGN_STRS_CRC_EX StressTemp;
						Get_PreForceStress4RatingDL_EX(arPreCompoRCase[i].ForceDCBe[k], StressTemp);
					}
				}
			}
		}
		//int nForType =0; // 전체단면부재력 받아옴.
		// Primary Vehicle
		iAnalType = pPrimaryVeh->AnalType;
		iLcaseKey = pPrimaryVeh->LoadCaseKey;
		dFactor = pPrimaryVeh->Factor;
		bReciLcase = (bReciInput ? Is_Reciprocal(iAnalType, iLcaseKey) : FALSE);
		for (j = 0; j < 12; ++j)
		{
			Set_ForceIni();
			int iMaxMinType = j + 1;
			if (iAnalType == D_LCOM_MOVING)			Get_Mvld_EX(ElemK, iLcaseKey, nForceType, bCalcStss, dFactor, bReciLcase, iMaxMinType);
			else	ASSERT(0);
			Get_BlrdForceStress_EX(ForcePrVehi[j], StressPrVehi[j]);
		}
		// Adjacent Vehicle
		if (!bAdjacentVehSkip)
		{
			iAnalType = pAdjacentVeh->AnalType;
			iLcaseKey = pAdjacentVeh->LoadCaseKey;
			dFactor = pAdjacentVeh->Factor;
			bReciLcase = (bReciInput ? Is_Reciprocal(iAnalType, iLcaseKey) : FALSE);
			for (j = 0; j < 12; ++j)
			{
				Set_ForceIni();
				int iMaxMinType = j + 1;
				if (iAnalType == D_LCOM_MOVING)			Get_Mvld_EX(ElemK, iLcaseKey, nForceType, bCalcStss, dFactor, bReciLcase, iMaxMinType);
				else	ASSERT(0);
				Get_BlrdForceStress_EX(ForceAdVehi[j], StressAdVehi[j]);
			}
		}

		FORCE_BLRD_RCASE ForceBlrdRcase; ForceBlrdRcase.Initialize();
		STRESS_BLRD_RCASE StressBlrdRcase; StressBlrdRcase.Initialize();

		for (j = 0; j < 2; ++j)
		{
			// Force
			ForceBlrdRcase.ForceDCBe[j] = ForceDCBe[j];
			ForceBlrdRcase.ForceDC[j] = ForceDC[j];
			ForceBlrdRcase.ForceDW[j] = ForceDW[j];
			ForceBlrdRcase.ForceTemp[j] = ForceT[j];
			ForceBlrdRcase.ForceTempG[j] = ForceTG[j];
			// Stress
			StressBlrdRcase.StressDC[j] = StressDC[j];
			StressBlrdRcase.StressDW[j] = StressDW[j];
			StressBlrdRcase.StressTemp[j] = StressT[j];
			StressBlrdRcase.StressTempG[j] = StressTG[j];
		}
		// Force
		ForceBlrdRcase.ForceSec = ForceSEC;
		ForceBlrdRcase.ForcePerm = ForcePERM;
		ForceBlrdRcase.ForceUser = ForceUSER;
		// Stress
		StressBlrdRcase.StressSec = StressSEC;
		StressBlrdRcase.StressPerm = StressPERM;
		StressBlrdRcase.StressUser = StressUSER;

		for (j = 0; j < 12; ++j)
		{
			ForceBlrdRcase.ForcePrVehicle[j] = ForcePrVehi[j];
			ForceBlrdRcase.ForceAdVehicle[j] = ForceAdVehi[j];
			StressBlrdRcase.StressPrVehicle[j] = StressPrVehi[j];
			StressBlrdRcase.StressAdVehicle[j] = StressAdVehi[j];
		}

		arForceRCase.SetAt(i, ForceBlrdRcase);
		arStressRCase.SetAt(i, StressBlrdRcase);
	}

	return TRUE;
}

