BOOL CCRCForceCtrl::Get_ForceStressDataForRatingKSCE05(BOOL bIsPLCB, ElemPairK ElemK,
	CArray<FORCE_RCASE_KR, FORCE_RCASE_KR>& arForceRCase,
	CArray<STRESS_RCASE_KR, STRESS_RCASE_KR>& arStressRCase,
	FORCE_RCASE_PRECOMP_ELEM &ForcePreComElem,
	const int &nDgnCode, BOOL bAll)
{
	BOOL bBinary = FALSE;
	arForceRCase.RemoveAll();
	arStressRCase.RemoveAll();
	ForcePreComElem.Initialize();


	// Reset DimType.
	m_iDimType = 2;	// Set 3D.
	// Consider No Effect Zone.
	Set_RatNoEffectZone(ElemK);

	m_StrsPost.Initialize();
	m_pSectInfo->Get_StrsPscd(FALSE, ElemK.first, m_StrsPost);

	int iLcomNum = m_arLcomData.GetCount();
	if (iLcomNum == 0)	return FALSE;

	// Check Existing Reciprocal Stress.
	T_LCRS_D LcrsD;
	LcrsD.Initialize();
	BOOL bReciInput = m_pAttrCtrl->GetLcrs(LcrsD);

	BOOL bIncludeTP = TRUE;

	int nForType = 0; // 단면 부재력 받아옴

	for (int i = 0; i < iLcomNum; ++i)
	{
		// Initialize Forces.
		Set_ForceIni();

		_DGN_LCOM LcomDesign;
		LcomDesign.Initialize();
		if (!m_arLcomData.Lookup(i + 1, LcomDesign))	continue;

		BOOL bCalcStss = TRUE;
		BOOL bGetStrengthServiceForce = FALSE;
		CArray<T_LCOM_BASE, T_LCOM_BASE&> aLcom;
		CArray<BOOL, BOOL&> arbStaticLCase; arbStaticLCase.RemoveAll();
		T_LCOM_BASE* pMvCase = NULL;
		aLcom.RemoveAll();
		//MvCase.Initialize();

		BOOL bPreCompForce = FALSE;
		CString strRatingLcomName = _T("");
		T_RLCS_D RlcsD; RlcsD.Initialize();
		T_RKLC_D RklcD; RklcD.Initialize();
		T_RLCS_K RlcsKey;
		T_RKLC_K RklcKey;
		switch (nDgnCode)
		{
		case STL_KSCE_ASD05:
		case STL_KSCE_ASD10:
		case STL_KSCE_RAIL_ASD04:
		case STL_KSCE_RAIL_ASD11:
		case STL_KSCE_LSD15:
			RlcsKey = LcomDesign.OriginalLcomKey;
			m_pAttrCtrl2->GetRlcs(RlcsKey, RlcsD);
			aLcom.Copy(RlcsD.arLoadComb);
			arbStaticLCase.Copy(RlcsD.arStaticLoadComb);
			pMvCase = &RlcsD.MoveLoadCase;
			bGetStrengthServiceForce = TRUE;
			bPreCompForce = bIsPLCB;
			strRatingLcomName = RlcsD.strCaseName;
			break;
		case KSCE_USD05_RATING:
		case KSCE_USD10_RATING:
		case KSCE_RAIL_USD11_RATING:
		case KSCE_LSD15_RATING:
			RklcKey = LcomDesign.OriginalLcomKey;
			m_pAttrCtrl->GetRklc(RklcKey, RklcD);
			aLcom.Copy(RklcD.arLoadComb);
			arbStaticLCase.Copy(RklcD.arStaticLoadComb);
			pMvCase = &RklcD.MoveLoadCase;
			bCalcStss = (RklcD.iRatingCase == 0);
			break;
		case KSCE_USD10_RC_RATING:
		case KSCE_RAIL_USD11_RC_RATING:
		case KSCE_LSD15_RC_RATING:
			RklcKey = LcomDesign.OriginalLcomKey;
			m_pAttrCtrl->GetRklc(RklcKey, RklcD);
			aLcom.Copy(RklcD.arLoadComb);
			arbStaticLCase.Copy(RklcD.arStaticLoadComb);
			pMvCase = &RklcD.MoveLoadCase;
			bCalcStss = (RklcD.iRatingCase == 0);
			break;
		default:
			ASSERT(0);
			break;
		}

		int iLcaseNum = aLcom.GetSize();
		int ibLaseStaticNum = arbStaticLCase.GetSize();
		if (iLcaseNum != ibLaseStaticNum) ASSERT(FALSE);
		for (int j = 0; j < iLcaseNum; ++j)
		{
			T_LCOM_BASE &LcomBase = aLcom[j];
			unsigned int iAnalType = LcomBase.AnalType;
			unsigned int iLcaseKey = LcomBase.LoadCaseKey;
			double dFactor = LcomBase.Factor;
			int iMaxMinType = LcomDesign.iMoveLcaseType;//  LcomDesign.iDgnLcomType; - 확인필요!!
			// Lcase for Reciprocal Stress.
			BOOL bReciLcase = (bReciInput ? Is_Reciprocal(iAnalType, iLcaseKey) : FALSE);
			// LcomUlData.Combination[i].AnalType is...
			// D_LCOM_STATIC       1
			// D_LCOM_SPECTRUM     2
			// D_LCOM_ECCENSPEC		14
			// D_LCOM_HISTORY      3 
			// D_LCOM_STAGE       13
			// D_LCOM_MOVING       4 (Load Combination - Max, Min)
			// D_LCOM_SETTLEMENT   5 (Load Combination - Max, Min)
			// D_LCOM_GRIDMODEL   15 (Load Combination - Max, Min)
			_DGN_FORC_CRC ForceLcase;

			BOOL bIncludeStaitcLCase = arbStaticLCase[j];
			if (bAll || bIncludeStaitcLCase)
			{
				switch (iAnalType)
				{
				case D_LCOM_STATIC:
					Get_Stld(ElemK, iLcaseKey, nForType, bCalcStss, dFactor, bReciLcase);
					break;
				case D_LCOM_SPECTRUM:
					Get_Splc(ElemK, iLcaseKey, nForType, bCalcStss, dFactor);
					break;
				case D_LCOM_ECCENSPEC:
					Get_Espc(ElemK, iLcaseKey, nForType, bCalcStss, dFactor);
					break;
				case D_LCOM_HISTORY:
					Get_This(ElemK, iLcaseKey, nForType, bCalcStss, dFactor);
					break;
				case D_LCOM_STAGE:
					Get_Sgld(ElemK, iLcaseKey, nForType, bCalcStss, dFactor, bReciLcase, bIncludeTP, 0);	// If iStepNo=0, Final Stage.
					break;
				case D_LCOM_MOVING:
					Get_Mvld(ElemK, iLcaseKey, nForType, bCalcStss, dFactor, bReciLcase, iMaxMinType);
					break;
				case D_LCOM_SETTLEMENT:
					Get_Smlc(ElemK, iLcaseKey, nForType, bCalcStss, dFactor, iMaxMinType);
					break;
				case D_LCOM_GRIDMODEL:
					Get_Gilc(ElemK, iLcaseKey, nForType, bCalcStss, dFactor, bReciLcase, iMaxMinType);
					break;
				case D_LCOM_CB_CONCRETE:
				case D_LCOM_CB_STEEL:
				case D_LCOM_CB_STLCOMP:
					Get_Lcom(ElemK, iLcaseKey, nForType, bCalcStss, dFactor, iMaxMinType);  // Add by GAY. MNET:2903. ('07.07.31).
					break;
				default:
					ASSERT(0);
					break;
				}
			}
		}

		// Force.
		_DGN_FORC_CRC ForceLcom;
		_DGN_FORC_CRC ForceTnpr;
		_DGN_FORC_CRC ForceTnsc;
		if (!Get_Force4RatingDL(ForceLcom, ForceTnpr, ForceTnsc))	ASSERT(0);
		ForceLcom.strType = LcomDesign.DesignLcomNa;	// For Design LcomNa (cLCB-DA+1,...).

		// Stress.
		_DGN_STRS_CRC StressLcom;
		if (!Get_Stress4RatingDL(StressLcom)) ASSERT(0);
		StressLcom.strType = LcomDesign.DesignLcomNa;

		// PreCompForce
		_DGN_FORC_CRC PreCompForce;
		_DGN_STRS_CRC PreCompStress;
		Get_PreForceStress4RatingDL(PreCompForce, PreCompStress);

		// Initial force,stress
		Set_ForceIni();

		// Moving case
		unsigned int iAnalType_Move = pMvCase->AnalType;
		unsigned int iLcaseKey_Move = pMvCase->LoadCaseKey;
		double dFactor_Move = pMvCase->Factor;
		int iMaxMinType_Move = LcomDesign.iMoveLcaseType;
		BOOL bReciLcase_Move = (bReciInput ? Is_Reciprocal(iAnalType_Move, iLcaseKey_Move) : FALSE);
		if (iAnalType_Move == D_LCOM_STATIC)      Get_Stld(ElemK, iLcaseKey_Move, nForType, bCalcStss, dFactor_Move, bReciLcase_Move);
		else if (iAnalType_Move == D_LCOM_MOVING) Get_Mvld(ElemK, iLcaseKey_Move, nForType, bCalcStss, dFactor_Move, bReciLcase_Move, iMaxMinType_Move);

		_DGN_FORC_CRC ForceMove;
		if (!Get_Force4RatingLL(ForceMove)) ASSERT(0);

		_DGN_STRS_CRC StressMove;
		if (!Get_Stress4RatingLL(StressMove)) ASSERT(0);

		if (!bBinary && (bGetStrengthServiceForce || LcomDesign.iRatingCase == 1)) // Strength.
		{
			// Force
			FORCE_RCASE_KR ForceRcase;
			ForceRcase.Initialize();
			ForceRcase.ForceDL = ForceLcom;
			ForceRcase.ForceLL = ForceMove;//
			ForceRcase.ForceG += ForceLcom;
			ForceRcase.ForceG += ForceMove;
			ForceRcase.ForceLL.strType = strRatingLcomName;//PMS:RATING BSC-20140429 기존에 사용하지 않은 변수에다 저장.
			ForceRcase.ForceLL.iRefNo[0] = LcomDesign.iMoveLcaseType;
			arForceRCase.Add(ForceRcase);

			// Stress
			STRESS_RCASE_KR StressRcase;
			StressRcase.Initialize();
			StressRcase.StressDL = StressLcom;
			StressRcase.StressLL = StressMove;
			StressRcase.StressG += StressLcom;
			StressRcase.StressG += StressMove;
			arStressRCase.Add(StressRcase);
		}
		else
		{
			//
		}

		if (!bBinary && (bGetStrengthServiceForce || LcomDesign.iRatingCase == 0)) // Service.
		{
			STRESS_RCASE_KR StressRcase;
			StressRcase.Initialize();
			StressRcase.StressDL = StressLcom;
			StressRcase.StressLL = StressMove;
			StressRcase.StressG += StressLcom;
			StressRcase.StressG += StressMove;
			arStressRCase.Add(StressRcase);
		}
		else
		{
			//
		}
		if (bPreCompForce == TRUE)
		{
			FORCE_RCASE_PRECOMP PreComForD;
			PreComForD.Force = PreCompForce;
			PreComForD.Stress = PreCompStress;

			ForcePreComElem.aForceRCase.Add(PreComForD);
		}
	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_Force4RatingDL(_DGN_FORC_CRC& ForceLcom, _DGN_FORC_CRC& ForceTnpr, _DGN_FORC_CRC& ForceTnsc)
{
	ForceLcom += m_ForceDnon;
	ForceLcom += m_ForceDrec;
	ForceLcom += m_ForceLnon;
	ForceLcom += m_ForceLrec;
	ForceLcom += m_ForceRemn;
	// Force by Tendon Primary.
	ForceTnpr = m_ForceTnpr;
	ForceTnsc = m_ForceTnsc;

	return TRUE;
}

