	if (!m_pPostCtrl->MakeLoadComb(D_LOADCASE_STAGE, SgldK, LcasD)) { ASSERT(0); return FALSE; }
	if (nStepNo > 0)	m_pPostCtrl->SelectLoadCombNew(LcasD, nStepNo, 2);	// 0=Nonlinear, 1=Pushover, 2=Construction.
