BOOL CCRCForceCtrl::Get_GirderForce4CSLoadOfLCOM(BOOL bIsRating, T_STCT_D &StctD, ElemPairK ElemK, T_STAG_K GirderLastStagK, int nStepNo, int nDgnLcomKey, int nType, _DGN_FORC_CRC& ForceCS, double dFactorDL, BOOL bUnfactored)
{
	ForceCS.Initialize();

	_DGN_LCOM LcomDesign;
	if (!Get_DgnLcomData(nDgnLcomKey, LcomDesign)) return FALSE;

	if (bIsRating)
	{
		CString strSgldName = _LS(IDS_DB_SGLD_DL);	// DL.
		T_SGLD_K SgldK = m_pAttrCtrl->GetSgldKey(strSgldName);

		T_LCOM_BASE LcomB; LcomB.Initialize();
		LcomB.AnalType = D_LCOM_STAGE;
		LcomB.Factor = dFactorDL;
		LcomB.LoadCaseKey = SgldK;

		if (LcomDesign.LcomUlData.Combination.GetSize() > 0)
		{
			LcomDesign.LcomUlData.Combination.InsertAt(0, LcomB);
		}
		else
		{
			LcomDesign.LcomUlData.Combination.Add(LcomB);
		}
		

		//         for ( INT_PTR i=0; i<StctD.aErection.GetSize(); ++i )
		//         {
		//             T_STCT_EREC &ErecD = StctD.aErection[i];
		//             if ( ErecD.nNumStctCase>0 )
		//             {
		//                 if ( CDBLib::IsStldDL(ErecD.LoadCaseType) )
		//                 {
		//                     SgldK = m_pAttrCtrl->GetSgldKey(ErecD.strErection);
		//                     LcomB.LoadCaseKey = SgldK;
		//                     LcomDesign.LcomUlData.Combination.Add(LcomB);
		//                 }
		//             }
		//         }
	}

	if (nStepNo == 0)
	{
		// Get Last StepNo at Current Stage.
		T_STAG_STEP_INFO StageInfo;
		m_pAttrCtrl->GetStagStepInfo(GirderLastStagK, StageInfo);
		int nStepSize = StageInfo.aInfo.GetSize();
		m_pStageInfo->GetStepSerialKey(GirderLastStagK, nStepSize, nStepNo);
	}

	INT_PTR nCombSize = LcomDesign.LcomUlData.Combination.GetSize();
	for (INT_PTR ik = 0; ik < nCombSize; ++ik)
	{
		T_LCOM_BASE &LcomBase = LcomDesign.LcomUlData.Combination[ik];

		if (LcomBase.AnalType == D_LCOM_STAGE)
		{
			T_SGLD_D SgldD; SgldD.Initialize();

			//++++++++++++++++++++++++++++++++++++++++++++++++++
			// 반드시 함수를 호출하는 곳에서 Stage를 설정한 후에 사용해야 한다.
			SgldD.Initialize();
			if (!m_pStageInfo->GetSgldPost(LcomBase.LoadCaseKey, SgldD))	continue;
			//++++++++++++++++++++++++++++++++++++++++++++++++++

			if (nType != 0)
			{
				if (IsBeforeLoadSgld(SgldD.LoadCaseName, StctD) == FALSE) continue;
			}

			T_SGLD_K SgldK = m_pAttrCtrl->GetSgldKey(SgldD.LoadCaseName);

			if ( bUnfactored )
			{
				LcomBase.Factor = 1.0;
			}
            _DGN_FORC_CRC ForcMax, ForcMin;
            if(!Get_CompositeForceBySgld(ElemK, SgldK, GirderLastStagK, nStepNo, LcomBase.Factor, ForcMax, ForcMin))	continue;
            ForceCS += ForcMax;
        }

	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_GirderForce4CStage(T_STCT_D &StctD, ElemPairK ElemK, T_STAG_K GirderLastStagK, int nStepNo, T_CSLF_CPT &CslFac, _DGN_FORC_CRC& ForceCS)
{
	ForceCS.Initialize();

	CString strSgldName = _LS(IDS_DB_SGLD_DL);	// DL.
	T_SGLD_K SgldK = m_pAttrCtrl->GetSgldKey(strSgldName);

	_DGN_FORC_CRC ForcMax, ForcMin;
	Get_CompositeForceBySgld(ElemK, SgldK, GirderLastStagK, nStepNo, CslFac.dFacDL, ForcMax, ForcMin);
	ForceCS += ForcMax;

	INT_PTR nErFactorSize = CslFac.aFacEr.GetSize();
	for (INT_PTR i = 0; i < StctD.aErection.GetSize(); ++i)
	{
		double dFacEr = 1.0;
		if (i < nErFactorSize) dFacEr = CslFac.aFacEr[i].dFactor;
		T_STCT_EREC &ErecD = StctD.aErection[i];
		if (ErecD.nNumStctCase > 0)
		{
			if (CDBLib::IsStldDL(ErecD.LoadCaseType))
			{
				SgldK = m_pAttrCtrl->GetSgldKey(ErecD.strErection);
				Get_CompositeForceBySgld(ElemK, SgldK, GirderLastStagK, nStepNo, dFacEr, ForcMax, ForcMin);
				ForceCS += ForcMax;
			}
		}
	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_CSGirderForce4CompoBefore(ElemPairK ElemK, _DGN_FORC_CRC &ForD)
{

	CArray<T_STAG_K, T_STAG_K> aStagK;
	m_pStageInfo->GetResultSavedStagKeyList(aStagK);
	int nStageSize = aStagK.GetSize();
	if (nStageSize == 0)	return FALSE;

	ForD.Initialize();

	T_STAG_K GirderLastStagK = 0;
	BOOL bBeforeForce = FALSE;
	for (int ik = 0; ik < nStageSize; ++ik)
	{
		T_STAG_K StagK = aStagK.GetAt(ik);

		// 0:오류 또는 시공 합성 단면 아님
		// 1:시공 합성 단면 : 합성 전 (Active Stage 이전)
		// 2:시공 합성 단면 : 합성 중 (Active되고 모든 Part가 합성되기 전)
		// 3:시공 합성 단면 : 합성 후 (모든 Part가 합성된 후)
		T_CSCS_D CscsD; CscsD.Initialize();
		g_num_mutex1.lock();
		int nCompositeType = m_pAttrCtrl->GetElemSectCompositeInfo(ElemK.first, StagK, CscsD);
		g_num_mutex1.unlock();
		if (nCompositeType == 0) continue;
		if (nCompositeType > 1)
		{
			if (nCompositeType == 3) break;
			GirderLastStagK = StagK;
		}
	}

	int nFinalStepNo = 0;
	// Get Last StepNo at Current Stage.
	T_STAG_STEP_INFO StageInfo;
	m_pAttrCtrl->GetStagStepInfo(GirderLastStagK, StageInfo);
	int nStep = StageInfo.aInfo.GetSize();
	m_pStageInfo->GetStepSerialKey(GirderLastStagK, nStep, nFinalStepNo);


	CString strSgldName = _LS(IDS_DB_SGLD_DL);	// DL.
	T_SGLD_K SgldK = m_pAttrCtrl->GetSgldKey(strSgldName);

	double dFactor = 1.0;
	_DGN_FORC_CRC ForcMinTemp;
	Get_CompositeForceBySgld(ElemK, SgldK, GirderLastStagK, nFinalStepNo, dFactor, ForD, ForcMinTemp);

	return TRUE;
}

BOOL CCRCForceCtrl::Get_SfcpExist(int nLcomType, int nOrgLcomK, bool& bExistCrp, bool& bExistShr, bool& bExistBST)
{
	bExistCrp = bExistShr = bExistBST = false;

	T_LCOM_D LcomD;
	if (!m_pAttrCtrl->GetLcom(nLcomType, nOrgLcomK, LcomD))
	{
		return FALSE;
	}
	else
	{
		for (int nLoadCase = 0; nLoadCase < LcomD.aCombination.GetSize(); ++nLoadCase)
		{
			const T_LCOM_BASE& LcomBaseD = LcomD.aCombination[nLoadCase];

			T_SGLD_D LoadCaseD;
			T_STLD_D StldCaseD;
			bool bExistCS = (LcomBaseD.AnalType == D_LCOM_STAGE && m_pAttrCtrl->GetSgld(LcomBaseD.LoadCaseKey, LoadCaseD));
			bool bExistST = (LcomBaseD.AnalType == D_LCOM_STATIC && m_pAttrCtrl->GetStld(LcomBaseD.LoadCaseKey, StldCaseD));
			if (!bExistCS && !bExistST) continue;

			// Erection에 포함된 IDS_DB_SGLD_CS 하중을 이름으로 찾기 보다는 고정된  Key로 찾도록 변경
			if(LoadCaseD.LoadCaseType.CompareNoCase(_T("CS")) == 0 &&
				LcomBaseD.LoadCaseKey == D_SGLD_CS_CVL) {bExistCrp = true;}
				//LoadCaseD.LoadCaseName.CompareNoCase(_LS(IDS_DB_SGLD_CS)) == 0){bExistCrp = true;}

			if(LoadCaseD.LoadCaseType.CompareNoCase(_T("CS")) == 0 &&
				LcomBaseD.LoadCaseKey == D_SGLD_SS_CVL) {bExistShr = true;}
				//LoadCaseD.LoadCaseName.CompareNoCase(_LS(IDS_DB_SGLD_SS)) == 0){bExistShr = true;}

			if (StldCaseD.LoadCaseType.CompareNoCase(_T("T")) == 0 ||
				StldCaseD.LoadCaseType.CompareNoCase(_T("TPG")) == 0)
			{
				bExistBST = true;
			}
		}
	}

	return TRUE;
}

BOOL CCRCForceCtrl::GetCSGirderMembForce(T_SGLD_K SgldK, T_STAG_K StagK, int iStepNo, ArrElemPairKey& aElemList, T_STRB_D* pDataMax)
{
	int iLcaseType = D_LOADCASE_STAGE;
	// Get Force Data by Load Case.
	T_LCOM_D LcasD;
	LcasD.Initialize();
	if (!m_pPostCtrl->MakeLoadComb(D_LOADCASE_STAGE, SgldK, LcasD)) { return FALSE; }
	if (iStepNo > 0)	m_pPostCtrl->SelectLoadCombNew(LcasD, iStepNo, 2);	// 0=Nonlinear, 1=Pushover, 2=Construction.
	else			m_pPostCtrl->SelectLoadCombNew(LcasD);
	//
	ArrElemPairKey aElemCS;
	aElemCS.Copy(aElemList);
	int nElemCS = aElemCS.GetSize();
	int nPartId = 1;
	CArray<T_STRB_D, T_STRB_D&> aStrbMemb;
	aStrbMemb.SetSize(nElemCS);
	for (int i = 0; i < aElemCS.GetSize(); ++i)
	{
		if (!m_pPostCtrl->GetStrbNew(aElemCS[i].first, &aStrbMemb[i], 0, 0, FALSE, NULL, aElemCS[i].second))
		{
			aElemCS.RemoveAt(i);
			aStrbMemb.RemoveAt(i);
		}
	}

	DGN_MY_MAX_B MyMaxB;
	GetMembForce(aElemCS, aStrbMemb, pDataMax, MyMaxB);


	return TRUE;
}

BOOL CCRCForceCtrl::Get_GirderMembForce4CSLoadOfLCOM(BOOL bIsRating, T_STCT_D &StctD, ElemPairK ElemK, T_STAG_K GirderLastStagK, int nStepNo, int nDgnLcomKey, int nType, ArrElemPairKey& aElemList, T_STRB_D* pMembF, double dFactorDL)
{
	_DGN_LCOM LcomDesign;
	if (!Get_DgnLcomData(nDgnLcomKey, LcomDesign)) return FALSE;

	if (nStepNo == 0)
	{
		// Get Last StepNo at Current Stage.
		T_STAG_STEP_INFO StageInfo;
		m_pAttrCtrl->GetStagStepInfo(GirderLastStagK, StageInfo);
		int nStepSize = StageInfo.aInfo.GetSize();
		m_pStageInfo->GetStepSerialKey(GirderLastStagK, nStepSize, nStepNo);
	}

	if (bIsRating)
	{
		CString strSgldName = _LS(IDS_DB_SGLD_DL);	// DL.
		T_SGLD_K SgldK = m_pAttrCtrl->GetSgldKey(strSgldName);

		T_LCOM_BASE LcomB; LcomB.Initialize();
		LcomB.AnalType = D_LCOM_STAGE;
		LcomB.Factor = dFactorDL;
		LcomB.LoadCaseKey = SgldK;

		if (LcomDesign.LcomUlData.Combination.GetSize() > 0)
		{
			LcomDesign.LcomUlData.Combination.InsertAt(0, LcomB);
		}
		else
		{
			LcomDesign.LcomUlData.Combination.Add(LcomB);
		}

		//         for ( INT_PTR i=0; i<StctD.aErection.GetSize(); ++i )
		//         {
		//             T_STCT_EREC &ErecD = StctD.aErection[i];
		//             if ( ErecD.nNumStctCase>0 )
		//             {
		//                 if ( CDBLib::IsStldDL(ErecD.LoadCaseType) )
		//                 {
		//                     SgldK = m_pAttrCtrl->GetSgldKey(ErecD.strErection);
		//                     LcomB.LoadCaseKey = SgldK;
		//                     LcomDesign.LcomUlData.Combination.Add(LcomB);
		//                 }
		//             }
		//         }
	}

	BOOL bBeforeLoad = TRUE;
	INT_PTR nCombSize = LcomDesign.LcomUlData.Combination.GetSize();
	for (INT_PTR ik = 0; ik < nCombSize; ++ik)
	{
		T_LCOM_BASE &LcomBase = LcomDesign.LcomUlData.Combination[ik];

		if (LcomBase.AnalType == D_LCOM_STAGE)
		{
			T_SGLD_D SgldD; SgldD.Initialize();

			//++++++++++++++++++++++++++++++++++++++++++++++++++
			// 반드시 함수를 호출하는 곳에서 Stage를 설정한 후에 사용해야 한다.
			SgldD.Initialize();
			if (!m_pStageInfo->GetSgldPost(LcomBase.LoadCaseKey, SgldD))	continue;
			//++++++++++++++++++++++++++++++++++++++++++++++++++

			if (nType != 0)
			{
				if (IsBeforeLoadSgld(SgldD.LoadCaseName, StctD) == FALSE) continue;
			}

			T_SGLD_K SgldK = m_pAttrCtrl->GetSgldKey(SgldD.LoadCaseName);

			T_STRB_D StrbFor; StrbFor.Initialize();
			GetCSGirderMembForce(SgldK, GirderLastStagK, nStepNo, aElemList, &StrbFor);
			StrbFor.Mult(LcomBase.Factor);
			if (StrbFor.nDOFType == 2)
			{
				pMembF->nDOFType = StrbFor.nDOFType;
			}
			pMembF->Add(StrbFor);
		}
	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_GirderMembForce4CStage(T_STCT_D &StctD, T_STAG_K GirderLastStagK, int nStepNo, T_CSLF_CPT &CslFac, ArrElemPairKey& aElemList, T_STRB_D* pDataMax)
{
	CString strSgldName = _LS(IDS_DB_SGLD_DL);	// DL.
	T_SGLD_K SgldK = m_pAttrCtrl->GetSgldKey(strSgldName);

	T_STRB_D StrbFor; StrbFor.Initialize();
	GetCSGirderMembForce(SgldK, GirderLastStagK, nStepNo, aElemList, &StrbFor);
	StrbFor.Mult(CslFac.dFacDL);
	pDataMax->nDOFType = StrbFor.nDOFType;
	pDataMax->Add(StrbFor);

	for (INT_PTR i = 0; i < StctD.aErection.GetSize(); ++i)
	{
		const T_STCT_EREC &ErecD = StctD.aErection[i];
		if (ErecD.nNumStctCase > 0) // 혹시라도 strErName에 erection이 아닌 load case인데 strErection과 이름이 같을 수 있기 때문에 
		{
			StrbFor.Initialize();
			strSgldName = ErecD.strErection;	// EL.
			SgldK = m_pAttrCtrl->GetSgldKey(strSgldName);
			GetCSGirderMembForce(SgldK, GirderLastStagK, nStepNo, aElemList, &StrbFor);
			double dFactor = 1.0;
			if (CslFac.aFacEr.GetSize() > i) dFactor = CslFac.aFacEr[i].dFactor;
			StrbFor.Mult(dFactor);
			pDataMax->Add(StrbFor);
		}
	}
	return TRUE;
}

BOOL CCRCForceCtrl::GetGirderLastStageKey(ElemPairK ElemK, T_STAG_K &rLastStagK, int &nLastStepNo)
{
	CArray<T_STAG_K, T_STAG_K> aStagK;
	m_pStageInfo->GetResultSavedStagKeyList(aStagK);
	int nStageSize = aStagK.GetSize();
	if (nStageSize == 0)	return FALSE;

	rLastStagK = 0;
	for (int ik = 0; ik < nStageSize; ++ik)
	{
		T_STAG_K StagK = aStagK.GetAt(ik);

		// 0:오류 또는 시공 합성 단면 아님
		// 1:시공 합성 단면 : 합성 전 (Active Stage 이전)
		// 2:시공 합성 단면 : 합성 중 (Active되고 모든 Part가 합성되기 전)
		// 3:시공 합성 단면 : 합성 후 (모든 Part가 합성된 후)
		T_CSCS_D CscsD; CscsD.Initialize();
		g_num_mutex1.lock();
		int nCompositeType = m_pAttrCtrl->GetElemSectCompositeInfo(ElemK.first, StagK, CscsD);
		g_num_mutex1.unlock();
		if (nCompositeType == 0) continue;
		if (nCompositeType > 1)
		{
			if (nCompositeType == 3) break;
			rLastStagK = StagK;
		}
	}

	m_pDataCtrl->Get_LastStepInCurStage(rLastStagK, nLastStepNo);

	return TRUE;
}

BOOL CCRCForceCtrl::Get_CompoForceBySgld_EX(ElemPairK ElemK, T_SGLD_K SgldK, T_STAG_K StagK, int iStepNo,
	_DGN_FORC_CRC_EX& ForcMax, _DGN_FORC_CRC_EX& ForcMin, BOOL bCompo)
{

	int iLcaseType = D_LOADCASE_STAGE;
	// Normal
	T_STRB_D StrMaxData; StrMaxData.Initialize();
	T_STRB_D StrMinData; StrMinData.Initialize();
	// Get Force Data by Load Case.
	T_LCOM_D LcasD;
	LcasD.Initialize();
	if (!m_pPostCtrl->MakeLoadComb(D_LOADCASE_STAGE, SgldK, LcasD)) { ASSERT(0); return FALSE; }
	if (iStepNo > 0)	m_pPostCtrl->SelectLoadCombNew(LcasD, iStepNo, 2);	// 0=Nonlinear, 1=Pushover, 2=Construction.
	else			m_pPostCtrl->SelectLoadCombNew(LcasD);
	//
	int nPartId = 1;
	if (bCompo)
		m_pPostCtrl->GetStrbPartNew(ElemK.first, nPartId, &StrMaxData, &StrMinData, NULL);
	else
		m_pPostCtrl->GetStrbNew(ElemK.first, &StrMaxData, &StrMinData, NULL, FALSE, NULL, ElemK.second);

	// Get Load Case Name (SUM).
	// Set Force.
	for (int i = 0; i < cPOSI_CRC_EX; ++i)
	{
		int iPart = (i < cPOSI_CRC_EX - 1 ? i : i - 1);
		int iKind = (i < cPOSI_CRC_EX - 1 ? 0 : 6);
		double dMymax = ForcMax.dMuy[i];
		double dMymin = ForcMin.dMuy[i];

		if (dMymax < StrMaxData.dblForce[iPart][iKind + 4])
		{
			ForcMax.iRefNo[i] = StagK;
			ForcMax.dFxx[i] = StrMaxData.dblForce[iPart][iKind + 0];
			ForcMax.dFzz[i] = StrMaxData.dblForce[iPart][iKind + 1];
			ForcMax.dFyy[i] = StrMaxData.dblForce[iPart][iKind + 2];
			ForcMax.dMux[i] = StrMaxData.dblForce[iPart][iKind + 3];
			ForcMax.dMuy[i] = StrMaxData.dblForce[iPart][iKind + 4];
			ForcMax.dMuz[i] = StrMaxData.dblForce[iPart][iKind + 5];
			ForcMax.dMbi[i] = StrMaxData.dblForce[iPart][Mbi_Id + i]; // Bi-moment
			ForcMax.dTst[i] = StrMaxData.dblForce[iPart][Mst_Id + i]; // Pure torsion
			ForcMax.dTwp[i] = StrMaxData.dblForce[iPart][Mwp_Id + i]; // Warping torsion
		}
		if (dMymin > StrMinData.dblForce[iPart][iKind + 4])
		{
			ForcMin.iRefNo[i] = StagK;
			ForcMin.dFxx[i] = StrMinData.dblForce[iPart][iKind + 0];
			ForcMin.dFzz[i] = StrMinData.dblForce[iPart][iKind + 1];
			ForcMin.dFyy[i] = StrMinData.dblForce[iPart][iKind + 2];
			ForcMin.dMux[i] = StrMinData.dblForce[iPart][iKind + 3];
			ForcMin.dMuy[i] = StrMinData.dblForce[iPart][iKind + 4];
			ForcMin.dMuz[i] = StrMinData.dblForce[iPart][iKind + 5];
			ForcMin.dMbi[i] = StrMinData.dblForce[iPart][Mbi_Id + i]; // Bi-moment
			ForcMin.dTst[i] = StrMinData.dblForce[iPart][Mst_Id + i]; // Pure torsion
			ForcMin.dTwp[i] = StrMinData.dblForce[iPart][Mwp_Id + i]; // Warping torsion
		}
	}
	return TRUE;
}

BOOL CCRCForceCtrl::Get_ForceBySgld_EX(ElemPairK ElemK, T_SGLD_K SgldK, T_STAG_K StagK, int iStepNo,
	_DGN_FORC_CRC_EX& ForcMax, _DGN_FORC_CRC_EX& ForcMin)
{
	BOOL bCompo = FALSE;
	return Get_CompoForceBySgld_EX(ElemK, SgldK, StagK, iStepNo, ForcMax, ForcMin, bCompo);
}

