BOOL CCRCForceCtrl::Get_GirderForce4CSLoadOfLCOM_EX(ElemPairK ElemK, int nDgnLcomKey, _DGN_FORC_CRC_EX& ForceCS)
{

	CArray<T_STAG_K, T_STAG_K> aStagK;
	m_pStageInfo->GetResultSavedStagKeyList(aStagK);
	int nStageSize = aStagK.GetSize();
	if (nStageSize == 0)	return FALSE;

	ForceCS.Initialize();

	T_STAG_K GirderLastStagK = 0;
	BOOL bBeforeForce = FALSE;
	for (int ik = 0; ik < nStageSize; ++ik)
	{
		T_STAG_K StagK = aStagK.GetAt(ik);

		// 0:오류 또는 시공 합성 단면 아님
		// 1:시공 합성 단면 : 합성 전 (Active Stage 이전)
		// 2:시공 합성 단면 : 합성 중 (Active되고 모든 Part가 합성되기 전)
		// 3:시공 합성 단면 : 합성 후 (모든 Part가 합성된 후)
		T_CSCS_D CscsD; CscsD.Initialize();
		g_num_mutex1.lock();
		int nCompositeType = m_pAttrCtrl->GetElemSectCompositeInfo(ElemK.first, StagK, CscsD);
		g_num_mutex1.unlock();
		if (nCompositeType == 0) continue;
		if (nCompositeType > 1)
		{
			if (nCompositeType == 3) break;
			GirderLastStagK = StagK;
		}
	}

	_DGN_LCOM LcomDesign;
	if (!Get_DgnLcomData(nDgnLcomKey, LcomDesign)) return FALSE;

	int nCombSize = LcomDesign.LcomUlData.Combination.GetSize();
	for (int ik = 0; ik < nCombSize; ++ik)
	{
		T_LCOM_BASE &LcomBase = LcomDesign.LcomUlData.Combination[ik];
		if (LcomBase.AnalType == D_LCOM_STAGE)
		{
			T_SGLD_D SgldD; SgldD.Initialize();

			//++++++++++++++++++++++++++++++++++++++++++++++++++
			// 반드시 함수를 호출하는 곳에서 Stage를 설정한 후에 사용해야 한다.
			SgldD.Initialize();
			if (!m_pStageInfo->GetSgldPost(LcomBase.LoadCaseKey, SgldD))	continue;
			//++++++++++++++++++++++++++++++++++++++++++++++++++

			int iFinalStepNo = 0;
			// Get Last StepNo at Current Stage.
			T_STAG_STEP_INFO StageInfo;
			m_pAttrCtrl->GetStagStepInfo(GirderLastStagK, StageInfo);
			int iStep = StageInfo.aInfo.GetSize();
			m_pStageInfo->GetStepSerialKey(GirderLastStagK, iStep, iFinalStepNo);
			//CString strSgldName = _LS(IDS_DB_SGLD_SUM);	
			T_SGLD_K SgldK = m_pAttrCtrl->GetSgldKey(SgldD.LoadCaseName);

			_DGN_FORC_CRC_EX ForcMax, ForcMin;
			//if(!Get_CompositeForceBySgld_EX(ElemK, SgldK, GirderLastStagK, iFinalStepNo, ForcMax, ForcMin))	continue;
			ForcMax *= LcomBase.Factor;
			ForceCS += ForcMax;
		}

	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_GirderForce4CSLoadOfLCOM_EX(BOOL bIsRating, T_STCT_D &StctD, ElemPairK ElemK, T_STAG_K GirderLastStagK, int nStepNo, int nDgnLcomKey, int nType, _DGN_FORC_CRC_EX& ForceCS, double dFactorDL)
{
	ForceCS.Initialize();

	_DGN_LCOM LcomDesign;
	if (!Get_DgnLcomData(nDgnLcomKey, LcomDesign)) return FALSE;

	if (bIsRating)
	{
		CString strSgldName = _LS(IDS_DB_SGLD_DL);	// DL.
		T_SGLD_K SgldK = m_pAttrCtrl->GetSgldKey(strSgldName);

		T_LCOM_BASE LcomB; LcomB.Initialize();
		LcomB.AnalType = D_LCOM_STAGE;
		LcomB.Factor = dFactorDL;
		LcomB.LoadCaseKey = SgldK;

		if (LcomDesign.LcomUlData.Combination.GetSize() > 0)
		{
			LcomDesign.LcomUlData.Combination.InsertAt(0, LcomB);
		}
		else
		{
			LcomDesign.LcomUlData.Combination.Add(LcomB);
		}

	}

	if (nStepNo == 0)
	{
		// Get Last StepNo at Current Stage.
		T_STAG_STEP_INFO StageInfo;
		m_pAttrCtrl->GetStagStepInfo(GirderLastStagK, StageInfo);
		int nStepSize = StageInfo.aInfo.GetSize();
		m_pStageInfo->GetStepSerialKey(GirderLastStagK, nStepSize, nStepNo);
	}

	INT_PTR nCombSize = LcomDesign.LcomUlData.Combination.GetSize();
	for (INT_PTR ik = 0; ik < nCombSize; ++ik)
	{
		T_LCOM_BASE &LcomBase = LcomDesign.LcomUlData.Combination[ik];

		if (LcomBase.AnalType == D_LCOM_STAGE)
		{
			T_SGLD_D SgldD; SgldD.Initialize();

			//++++++++++++++++++++++++++++++++++++++++++++++++++
			// 반드시 함수를 호출하는 곳에서 Stage를 설정한 후에 사용해야 한다.
			SgldD.Initialize();
			if (!m_pStageInfo->GetSgldPost(LcomBase.LoadCaseKey, SgldD))	continue;
			//++++++++++++++++++++++++++++++++++++++++++++++++++

			if (nType != 0)
			{
				if (IsBeforeLoadSgld(SgldD.LoadCaseName, StctD) == FALSE) continue;
			}

			T_SGLD_K SgldK = m_pAttrCtrl->GetSgldKey(SgldD.LoadCaseName);

			_DGN_FORC_CRC_EX ForcMax, ForcMin;
			if (!Get_CompositeForceBySgld_EX(ElemK, SgldK, GirderLastStagK, nStepNo, LcomBase.Factor, ForcMax, ForcMin))	continue;
			ForceCS += ForcMax;
		}

	}

	return TRUE;
}

BOOL CCRCForceCtrl::GetMembForce(ArrElemPairKey& aElemList, CArray<T_STRB_D, T_STRB_D&> &aDataMax, T_STRB_D* pDataMax, DGN_MY_MAX_B& MyMaxD)
{
	pDataMax->Initialize();
	MyMaxD.Initialize();
	INT_PTR nElemSize = aElemList.GetSize();
	INT_PTR nStrbSize = aDataMax.GetSize();

	if (nElemSize == 0) return FALSE;
	if (nStrbSize == 0) return FALSE;
	if (nElemSize != nStrbSize) return FALSE;

	double dLen = 0.0;	// Member Length.
	ArrElemPairKey aPartElemList;
	BOOL bStaInc = FALSE;
	for (int nEIdx = 0; nEIdx < aElemList.GetSize(); nEIdx++)
	{
		ElemPairK PartElemK = aElemList.GetAt(nEIdx);
		if (PartElemK.second == EN_EL_BEAM)
		{
			dLen += m_pDoc->calcLAVElem(PartElemK.first);
		}
		else if (PartElemK.second == EN_EL_VBEAM)
		{
			dLen += m_pDoc->calcLenthVbem(PartElemK.first);
		}
		else ASSERT(0);
	}

	//
	double dLenR[5] = { 0.0, 0.25, 0.50, 0.75, 1.0 };

	double dTotL[5] = { 0.,0.,0.,0.,0. };
	for (int n = 0; n < 5; n++)	dTotL[n] = dLenR[n] * dLen;
	double dSumLi = 0.0, dSumLj = 0.0;
	double dCurLi = 0.0, dCurLj = 0.0;

	// To Search Max/Min Moment between 1/4 and 3/4.
	double dMmaxUpMID = 0.0, dMmaxDnMID = 0.0;
	double dMminUpMID = 0.0, dMminDnMID = 0.0;
	
	double dMyMaxAbs = 0.0;
	T_ELEM_K MyMaxElemK = 0;
	int nMyElemSub = 0;
	int nMyMaxPos = 0;

	BOOL   bMUpSet = FALSE;
	BOOL   bMDnSet = FALSE;
	int nPos7Dof = 6;
	int i = 0;
	for (INT_PTR j = 0; j < nElemSize; j++)
	{
		ElemPairK ElemPairCur = aElemList.GetAt(j);
		T_ELEM_K ElemKeyCur = ElemPairCur.first;
		// Get Member Force by Element.
		T_STRB_D &StrMaxData = aDataMax[j];
		if (StrMaxData.nDOFType == 2)
		{
			pDataMax->nDOFType = StrMaxData.nDOFType;
		}
		double dL = 0.0;
		if (ElemPairCur.second == EN_EL_BEAM)
		{
			dL = m_pDoc->calcLAVElem(ElemKeyCur);
		}
		else if (ElemPairCur.second == EN_EL_VBEAM)
		{
			dL = m_pDoc->calcLenthVbem(ElemPairCur.first);
		}
		else ASSERT(0);

		double dCompL[4][2] = { {0.0*dL / 4.0, 1.0*dL / 4.0},
		{1.0*dL / 4.0, 2.0*dL / 4.0},
		{2.0*dL / 4.0, 3.0*dL / 4.0},
		{3.0*dL / 4.0, 4.0*dL / 4.0} };
		if (i >= 5)	break;
		for (int k = 0; k < 4; k++)
		{
			BOOL bPreElemJ_Skip = FALSE;
			dCurLi = dCompL[k][0] + dSumLi - m_dZero;
			dCurLj = dCompL[k][1] + dSumLj + m_dZero;
			if (j > 0 && k == 0 && i > 0 && (dTotL[i - 1] - dCurLi) > 0.0 && (dCurLj - dTotL[i]) < 0.0)
			{
				i -= 1;
				bPreElemJ_Skip = TRUE;
			}

			if (dTotL[i] > dCurLi && dTotL[i] < dCurLj)
			{
				for (int m = 0; m < 9; m++)
				{
					double dLenRat = (dTotL[i] - dCurLi) / (dCurLj - dCurLi);
					//////////////////////
					// Maximum Forces.
					double dMaxForI = 0.0;
					double dMaxForJ = 0.0;
					int nMbI = m * 2;
					int nMbJ = m * 2 + 1;
					if (m < 6)
					{
						dMaxForI = StrMaxData.dblForce[k][m];
						dMaxForJ = StrMaxData.dblForce[k][m + 6];
					}
					else
					{
						dMaxForI = StrMaxData.dblForce[k][nMbI];
						dMaxForJ = StrMaxData.dblForce[k][nMbJ];
					}
					// Calculate Force at Position.
					double dMaxForce = dMaxForI + dLenRat * (dMaxForJ - dMaxForI);
					if (m == 4) // My
					{
						if (AbsMT(dMaxForce, dMyMaxAbs))
						{
							dMyMaxAbs = fabs(dMaxForce);
							MyMaxElemK = ElemKeyCur;
							nMyElemSub = k;
							nMyMaxPos = i < 4 ? 0 : 1;
						}
					}
					//////////////////////
					// Save Calculated Forces.
					if (i < 4)
					{
						if (!bPreElemJ_Skip)
						{
							if (m < 6)
							{
								pDataMax->dblForce[i][m] = dMaxForce;
							}
							else
							{
								pDataMax->dblForce[i][nMbI] = dMaxForce;
							}

						}
					}
					if (i > 0)	// Not I.
					{
						if (m < 6)
						{
							pDataMax->dblForce[i - 1][m + 6] = dMaxForce;
						}
						else
						{
							pDataMax->dblForce[i - 1][nMbJ] = dMaxForce;
						}

					}
				}
				i++;
			}
		}
		if (j == aElemList.GetSize() - 1)	// If Last Element.
		{
			for (int m = 0; m < 9; m++)
			{
				if (m < 6)
				{
					double dMyEnd = StrMaxData.dblForce[3][m + 6];
					pDataMax->dblForce[3][m + 6] = dMyEnd;
					if (m == 4)
					{						
						if (AbsMT(dMyEnd, dMyMaxAbs))
						{
							dMyMaxAbs = dMyEnd;
							MyMaxElemK = ElemKeyCur;
							nMyElemSub = 3; // Elem sub - 4
							nMyMaxPos = 1;
						}
					}
				}
				else
				{
					int nMbJ = m * 2 + 1;
					pDataMax->dblForce[3][nMbJ] = StrMaxData.dblForce[3][nMbJ];
				}
			}
		}
		dSumLi += dL;
		dSumLj += dL;
	}

	T_ELEM_D MyElemD; MyElemD.Initialize();
	m_pDoc->m_pPostCtrl->GetElemPost(MyMaxElemK, MyElemD);

	MyMaxD.dMyMax   = dMyMaxAbs;
	MyMaxD.ElemK    = MyMaxElemK;
	MyMaxD.SectK    = MyElemD.elpro;
	MyMaxD.nElemSub = nMyElemSub;
	MyMaxD.nPosSub  = nMyMaxPos;
	MyMaxD.nPos5    = nMyElemSub < 3 ? nMyElemSub : (nMyMaxPos==0 ? 3 : 4);
	MyMaxD.nPosIJ   = nMyElemSub <= 1 ? 0 : 1;

	return TRUE;
}

double CCRCForceCtrl::GetMaxMyByMembForce(T_STRB_D* pMembForD)
{
	double dMmax = 0.0;
	for (int k = 0; k < 4; k++)
	{
		double dMmax_elem = max(fabs(pMembForD->dblForce[k][4]), fabs(pMembForD->dblForce[k][10]));
		if (dMmax < dMmax_elem)
		{
			dMmax = dMmax_elem;
		}
	}
	return dMmax;
}

void CCRCForceCtrl::ConvertDgnForceToStrb(_DGN_FORC_CRC_EX &For, T_STRB_D &rData)
{
	for (int i = 0; i < 4; ++i)
	{
		int Ie = i;
		int Je = i + 1;
		rData.dblForce[i][0] = For.dFxx[Ie];
		rData.dblForce[i][1] = For.dFyy[Ie];
		rData.dblForce[i][2] = For.dFzz[Ie];
		rData.dblForce[i][3] = For.dMux[Ie];
		rData.dblForce[i][4] = For.dMuy[Ie];
		rData.dblForce[i][5] = For.dMuz[Ie];
		rData.dblForce[i][6] = For.dFxx[Je];
		rData.dblForce[i][7] = For.dFyy[Je];
		rData.dblForce[i][8] = For.dFzz[Je];
		rData.dblForce[i][9] = For.dMux[Je];
		rData.dblForce[i][10] = For.dMuy[Je];
		rData.dblForce[i][11] = For.dMuz[Je];
		//
		rData.dblForce[i][12] = For.dMbi[Ie];
		rData.dblForce[i][14] = For.dTst[Ie];
		rData.dblForce[i][16] = For.dTwp[Ie];
		rData.dblForce[i][13] = For.dMbi[Je];
		rData.dblForce[i][15] = For.dTst[Je];
		rData.dblForce[i][17] = For.dTwp[Je];
	}
}


BOOL CCRCForceCtrl::Is_StldLL(CString strLcaseType, UINT nDgnCode)
{
	// BOOL CDBLib::IsStldLL(CString strLcaseType)
	// DBLib.cpp에 있는 함수인데 Static load 중 Live load로 판단 하는 경우가 기준별로 다를 때 사용하기 위해..
	// CDBLib::IsStldLL 에 통합하는 것이 좋은데. 지금은 Civil PSC 용으로만 사용.   

	BOOL bLL = FALSE;

	switch (nDgnCode)
	{
	case AASHTO_LRFD08:
	case AASHTO_LRFD12:
	case AASHTO_LRFD14:
	case AASHTO_LRFD16:
	case AASHTO_LRFD17:
	case AASHTO_LRFD20:
	case AASHTO_LRFD24:
	case CSA_S6_10:
	case CSA_S6_14:
	case CSA_S6_19:
	case AREMA_23:
		if (strLcaseType == _T("L"))  bLL = TRUE;
		else if (strLcaseType == _T("IL"))	 bLL = TRUE;
		else if (strLcaseType == _T("LP"))	 bLL = TRUE;
		else if (strLcaseType == _T("ILP"))	 bLL = TRUE;
		else if (strLcaseType == _T("BRK"))	 bLL = TRUE;
		else if (strLcaseType == _T("BK"))	 bLL = TRUE;
		else if (strLcaseType == _T("T"))	 bLL = TRUE;
		else if (strLcaseType == _T("CR"))	 bLL = TRUE;
		else if (strLcaseType == _T("CT"))	 bLL = TRUE;
		else if (strLcaseType == _T("CV"))	 bLL = TRUE;
		else if (strLcaseType == _T("E"))	 bLL = TRUE;
		else if (strLcaseType == _T("FR"))	 bLL = TRUE;
		else if (strLcaseType == _T("IP"))	 bLL = TRUE;
		else if (strLcaseType == _T("W"))	 bLL = TRUE;
		else if (strLcaseType == _T("WL"))	 bLL = TRUE;
		else if (strLcaseType == _T("STL"))	 bLL = TRUE;

		break;
	default:
		ASSERT(0);
	}
	return bLL;
}

