double CCRCForceCtrl::AdjustCJJLoadCaseFactor(unsigned int iAnalType, _DGN_LCOM &LcomDesign, double dFactor, T_CHRP_D &chrpd, T_PSCD_D &pscd)
{
	if ((iAnalType == D_LCOM_STATIC || iAnalType == D_LCOM_STAGE || iAnalType == D_LCOM_MOVING) && Is_LcomForStrn(LcomDesign.DesignLcomKey))
	{

		if (m_iDgnCode == RC_CJJ_11_2011)
		{
			if (chrpd.bExistSpecialLoad)
			{
				if (fabs(dFactor - 1.4) < 1.0e-6)
					dFactor = 1.1;
				if (chrpd.iSafeType == 1)
					dFactor = dFactor * 1.02;
				else if (chrpd.iSafeType == 2)
					dFactor = dFactor * 1.03;
				else
					dFactor = dFactor * 1.0;
			}
		}
		else if (m_iDgnCode == CJJ_11_2011)
		{
			if (pscd.bExistSpecialLoad)
			{
				if (fabs(dFactor - 1.4) < 1.0e-6)
					dFactor = 1.1;

				if (pscd.iSafeType == 1)
					dFactor = dFactor * 1.02;
				else if (pscd.iSafeType == 2)
					dFactor = dFactor * 1.03;
				else
					dFactor = dFactor * 1.0;
			}
		}
	}
	else if (iAnalType == D_LCOM_MOVING && Is_LcomForServ(LcomDesign.DesignLcomKey) && !Is_LongTerm(LcomDesign.DesignLcomKey))
	{
		if (m_iDgnCode == RC_CJJ_11_2011)
		{
			if (chrpd.bExistSpecialLoad)
			{
				dFactor = 0.7;
			}
		}
		else if (m_iDgnCode == CJJ_11_2011)
		{
			if (pscd.bExistSpecialLoad)
			{
				dFactor = 0.7;
			}
		}
	}
	else if (iAnalType == D_LCOM_MOVING && Is_LcomForServ(LcomDesign.DesignLcomKey) && Is_LongTerm(LcomDesign.DesignLcomKey))
	{
		if (m_iDgnCode == RC_CJJ_11_2011)
		{
			if (chrpd.bExistSpecialLoad)
			{
				dFactor = 0.4;
			}
		}
		else if (m_iDgnCode == CJJ_11_2011)
		{
			if (pscd.bExistSpecialLoad)
			{
				dFactor = 0.4;
			}
		}
	}
	return dFactor;
}

