BOOL CCRCForceCtrl::IsMVLcaseConcurrentForce(T_MVLD_K MvldK)
{

	BOOL bIsConcForce = TRUE;

	T_MVCD_D MvcdD;
	if (!m_pAttrCtrl->GetMvcd(MvcdD)) return FALSE;

	if (MvcdD.nCodeType == D_MOVE_CODE_EURO_BS)
	{
		T_MVLD_D MvldD;
		if (!m_pAttrCtrl->GetMvld(MvldK, MvldD)) return FALSE;

		if (MvldD.nLoadModel == 2 || MvldD.nLoadModel == 3) bIsConcForce = FALSE;
	}

	return bIsConcForce;
}

CString CCRCForceCtrl::GetConCurrForceType(int nId)
{
	CString strForceType = _T("");
	switch (nId)
	{
	case -1: strForceType = _T("-"); break;
	case  0: strForceType = _T("FX-MAX"); break;
	case  1: strForceType = _T("FX-MIN"); break;
	case  2: strForceType = _T("FY-MAX"); break;
	case  3: strForceType = _T("FY-MIN"); break;
	case  4: strForceType = _T("FZ-MAX"); break;
	case  5: strForceType = _T("FZ-MIN"); break;
	case  6: strForceType = _T("MX-MAX"); break;
	case  7: strForceType = _T("MX-MIN"); break;
	case  8: strForceType = _T("MY-MAX"); break;
	case  9: strForceType = _T("MY-MIN"); break;
	case 10: strForceType = _T("MZ-MAX"); break;
	case 11: strForceType = _T("MZ-MIN"); break;
	case 12: strForceType = _T("MB-MAX"); break;
	case 13: strForceType = _T("MB-MIN"); break;
	case 14: strForceType = _T("MP-MAX"); break;
	case 15: strForceType = _T("MP-MIN"); break;
	case 16: strForceType = _T("MW-MAX"); break;
	case 17: strForceType = _T("MW-MIN"); break;
	default: ASSERT(0); break;
	}
	return strForceType;
}

