	pdW[6] = PropB.Stiff.dw7;
	pdW[7] = PropB.Stiff.dw8;
	pdW[8] = PropB.Stiff.dw9;
	pdW[9] = PropB.Stiff.dw10;

	pdXYsh[0] = PropB.Stiff.Stiffness.dxy1;
	pdXYsh[1] = PropB.Stiff.Stiffness.dxy2;
	pdXYsh[2] = PropB.Stiff.Stiffness.dxy3;
	pdXYsh[3] = PropB.Stiff.Stiffness.dxy4;
	pdXYsh[4] = PropB.Stiff.dxy5;
	pdXYsh[5] = PropB.Stiff.dxy6;
	pdXYsh[6] = PropB.Stiff.dxy7;
	pdXYsh[7] = PropB.Stiff.dxy8;
	pdXYsh[8] = PropB.Stiff.dxy9;
