// PMS.5862 BS BD21 Assessment
void CCRCForceCtrl::Set_RatingCaseDataForBD21()
{
	m_arStldK.RemoveAll();
	m_arSplcK.RemoveAll();
	m_arEspcK.RemoveAll();
	m_arMvldK.RemoveAll();
	m_arThisK.RemoveAll();
	m_arSmlcK.RemoveAll();
	m_arSgldK.RemoveAll();
	m_arGilcK.RemoveAll();
	m_arStepK.RemoveAll();

	// Save Total Load Combination Name by Serial Number(No LcomKey).
	CArray<T_ALCS_K, T_ALCS_K> arAlcsKey; // T_ALCS_D
	arAlcsKey.RemoveAll();
	m_pAttrCtrl2->GetAlcsKeyList(arAlcsKey);
	int nAlcs = arAlcsKey.GetSize();
	int iRklcSerNum = 0;
	int iRklcCount = 0;
	for (int i = 0; i < nAlcs; ++i)
	{
		T_ALCS_D AlcsData;
		AlcsData.Initialize();
		m_pAttrCtrl2->GetAlcs(arAlcsKey[i], AlcsData);
		if (AlcsData.nLimitState == 1)	iRklcSerNum++;
		// Static
		unsigned int iAnalType = 0;
		unsigned int iLcaseKey = 0;
		int iLoadCaseNum = AlcsData.arLoadComb.GetSize();
		if (iLoadCaseNum == 0) continue;

		T_LCOM_D_UL	LcomUlData; // 시공단계 거더 부재력을 위해
		LcomUlData.Initialize();
		LcomUlData.Combination.SetSize(iLoadCaseNum);
		if (AlcsData.nLimitState == 0)
		{
			LcomUlData.nActive = 1;
		}
		else if (AlcsData.nLimitState == 1)
		{
			LcomUlData.nActive = 2;
		}

		for (int k = 0; k < iLoadCaseNum; ++k)
		{
			T_LCOM_BASE &AlcsBase = AlcsData.arLoadComb[k];
			iAnalType = AlcsBase.AnalType;
			iLcaseKey = AlcsBase.LoadCaseKey;

			switch (iAnalType)
			{
			case D_LCOM_STATIC:
				m_arStldK.SetAt(iLcaseKey, iLcaseKey);
				break;
			case D_LCOM_SPECTRUM:
				m_arSplcK.SetAt(iLcaseKey, iLcaseKey);
				break;
			case D_LCOM_ECCENSPEC:
				m_arEspcK.SetAt(iLcaseKey, iLcaseKey);
				break;
			case D_LCOM_MOVING:
				m_arMvldK.SetAt(iLcaseKey, iLcaseKey);
				break;
			case D_LCOM_HISTORY:
				m_arThisK.SetAt(iLcaseKey, iLcaseKey);
				break;
			case D_LCOM_SETTLEMENT:
				m_arSmlcK.SetAt(iLcaseKey, iLcaseKey);
				break;
			case D_LCOM_STAGE:
				m_arSgldK.SetAt(iLcaseKey, iLcaseKey);
				break;
			case D_LCOM_GRIDMODEL:
				m_arGilcK.SetAt(iLcaseKey, iLcaseKey);
				break;
			default:
				ASSERT(0);
				break;
			}
			LcomUlData.Combination.SetAt(k, AlcsBase); // 
		}

		if (m_iCivilCode == STL_NR_GN_CIV_025_06)
		{
			iAnalType = AlcsData.CombinedMVCase.AnalType;
			iLcaseKey = AlcsData.CombinedMVCase.LoadCaseKey;
			if (iAnalType == D_LCOM_MOVING) m_arMvldK.SetAt(iLcaseKey, iLcaseKey);
			else ASSERT(0);

			iAnalType = AlcsData.SpecialMVCase.AnalType;
			iLcaseKey = AlcsData.SpecialMVCase.LoadCaseKey;
			if (iAnalType == D_LCOM_MOVING) m_arMvldK.SetAt(iLcaseKey, iLcaseKey);
			else ASSERT(0);
		}
		else
		{
			// CIVIL-1063 / CIVIL-1103 CS454 Assessment 검토용 Moving 부재력 분리
			if (AlcsData.nMovType == 1) //Special 인 경우
			{
				iAnalType = AlcsData.SpecialMVCase.AnalType;
				iLcaseKey = AlcsData.SpecialMVCase.LoadCaseKey;
				if (iAnalType == D_LCOM_MOVING) m_arMvldK.SetAt(iLcaseKey, iLcaseKey);
				else                         ASSERT(0);
			}
			else //Combined
			{
				iAnalType = AlcsData.CombinedMVCase.AnalType;
				iLcaseKey = AlcsData.CombinedMVCase.LoadCaseKey;
				if (iAnalType == D_LCOM_MOVING) m_arMvldK.SetAt(iLcaseKey, iLcaseKey);
				else                         ASSERT(0);
			}
		}

		// Add [5/29/2013 joahn]
		BOOL b7Dof = FALSE;
		if (m_iDgnCode == STL_CS454_20)
		{
			b7Dof = TRUE;
		}
		int  nCCurrForce = GetConCurrForceNum(b7Dof);

		//++++++++++++++++++++++++++++++++++++++++++++++++++
		// Check Max/Min Lcom (Mvld, Smlc).
		int iRcaseTypeDL = 0;
		int iRcaseTypeLL = 0;
		BOOL bMaxMin = CDBLib::IsConcurrType4RatingBD21(b7Dof, AlcsData, iRcaseTypeDL, iRcaseTypeLL);

		_DGN_LCOM LcomDesign;
		LcomDesign.Initialize();
		int iIterLcom = (bMaxMin ? nCCurrForce : 1);

		for (int j = 0; j < iIterLcom; ++j)
		{
			BOOL bMaxLcom = (j % 2 == 0 ? TRUE : FALSE);
			iRklcCount++;
			LcomDesign.DesignLcomNa = _T("");
			LcomDesign.DesignLcomKey = iRklcCount;
			LcomDesign.bMaxLcom = bMaxLcom;
			LcomDesign.iDgnLcomType = (iRcaseTypeDL == nCCurrForce ? j + 1 : 0);	// 1=FX-MAX,2=FX-MIN,...12=MZ-MIN. Rating case 중 DL 하중에 해당하는 하중조합.. type
			LcomDesign.iMoveLcaseType = (iRcaseTypeLL == nCCurrForce ? j + 1 : 0);	// 1=FX-MAX,2=FX-MIN,...12=MZ-MIN. Rating case 중 LL 하중에 해당하는 하중조합.. type
			LcomDesign.OriginalLcomKey = arAlcsKey[i];
			LcomDesign.iRatingCase = AlcsData.nLimitState;
			LcomDesign.LcomUlData = LcomUlData;
			// Save Lcom Data for Design.
			m_arLcomData.SetAt(LcomDesign.DesignLcomKey, LcomDesign);
			// For write binary
			m_arSerialLcomK.SetAt(iRklcCount, iRklcCount);
			// Set LcomNum For Strength, Stress.
			if (AlcsData.nLimitState == 0)	m_iLcomNoStrn++;
			if (AlcsData.nLimitState == 1)	m_iLcomNoStrs++;
		}
	}


	// Static
	m_arMapStldK.InitHashTable(max(1, m_arStldK.GetCount()));
	UINT iCount = 0;
	T_STLD_K StldK, StldGetK;
	POSITION PosStld = m_arStldK.GetStartPosition();
	while (PosStld)
	{
		m_arStldK.GetNextAssoc(PosStld, StldK, StldGetK);
		m_arMapStldK.SetAt(StldGetK, iCount);
		iCount++;
	}
	// Sepctrum
	m_arMapSplcK.InitHashTable(max(1, m_arSplcK.GetCount()));
	iCount = 0;
	T_SPLC_K SplcK, SplcGetK;
	POSITION PosSplc = m_arSplcK.GetStartPosition();
	while (PosSplc)
	{
		m_arSplcK.GetNextAssoc(PosSplc, SplcK, SplcGetK);
		m_arMapSplcK.SetAt(SplcGetK, iCount);
		iCount++;
	}
	// Eccentric Sepctrum
	m_arMapEspcK.InitHashTable(max(1, m_arEspcK.GetCount()));
	iCount = 0;
	T_ESPC_K EspcK, EspcGetK;
	POSITION PosEspc = m_arEspcK.GetStartPosition();
	while (PosEspc)
	{
		m_arEspcK.GetNextAssoc(PosEspc, EspcK, EspcGetK);
		m_arMapEspcK.SetAt(EspcGetK, iCount);
		iCount++;
	}
	// Time History
	m_arMapThisK.InitHashTable(max(1, m_arThisK.GetCount()));
	iCount = 0;
	T_THIS_K ThisK, ThisGetK;
	POSITION PosThis = m_arThisK.GetStartPosition();
	while (PosThis)
	{
		m_arThisK.GetNextAssoc(PosThis, ThisK, ThisGetK);
		m_arMapThisK.SetAt(ThisGetK, iCount);
		iCount++;
	}
	// Moving Load
	m_arMapMvldK.InitHashTable(max(1, m_arMvldK.GetCount()));
	iCount = 0;
	T_MVLD_K MvldK, MvldGetK;
	POSITION PosMvld = m_arMvldK.GetStartPosition();
	while (PosMvld)
	{
		m_arMvldK.GetNextAssoc(PosMvld, MvldK, MvldGetK);
		m_arMapMvldK.SetAt(MvldGetK, iCount);
		iCount++;
	}
	// Settlement
	m_arMapSmlcK.InitHashTable(max(1, m_arSmlcK.GetCount()));
	iCount = 0;
	T_SMLC_K SmlcK, SmlcGetK;
	POSITION PosSmlc = m_arSmlcK.GetStartPosition();
	while (PosSmlc)
	{
		m_arSmlcK.GetNextAssoc(PosSmlc, SmlcK, SmlcGetK);
		m_arMapSmlcK.SetAt(SmlcGetK, iCount);
		iCount++;
	}
	// Sgld
	m_arMapSgldK.InitHashTable(max(1, m_arSgldK.GetCount()));
	iCount = 0;
	T_SGLD_K SgldK, SgldGetK;
	POSITION PosSgld = m_arSgldK.GetStartPosition();
	while (PosSgld)
	{
		m_arSgldK.GetNextAssoc(PosSgld, SgldK, SgldGetK);
		m_arMapSgldK.SetAt(SgldGetK, iCount);
		iCount++;
	}
	// Step
	T_STEP_K StepK, StepGetK;
	m_arMapStepK.InitHashTable(max(1, m_arStepK.GetCount()));
	iCount = 0;
	POSITION PosStep = m_arStepK.GetStartPosition();
	while (PosStep)
	{
		m_arStepK.GetNextAssoc(PosStep, StepK, StepGetK);
		m_arMapStepK.SetAt(StepGetK, iCount);
		iCount++;
	}
	// Grid
	m_arMapGilcStrbK.InitHashTable(max(1, m_arGilcK.GetCount()));
	m_arMapGilcSbcfK.InitHashTable(max(1, m_arGilcK.GetCount()));
	UINT iCountStrb = 0;
	UINT iCountSbcf = 0;
	T_GILC_K GilcK, GilcGetK;
	POSITION PosGilc = m_arGilcK.GetStartPosition();
	while (PosGilc)
	{
		m_arGilcK.GetNextAssoc(PosGilc, GilcK, GilcGetK);
		T_GILC_D GilcD;
		GilcD.Initialize();
		if (!m_pAttrCtrl->GetGilc(GilcK, GilcD))	continue;
		int iLcaseType = GilcD.nLoadCaseType;
		if (iLcaseType == 0 || iLcaseType == 1)
		{
			m_arMapGilcStrbK.SetAt(GilcGetK, iCountStrb);
			iCountStrb++;
		}
		else if (iLcaseType == 2 || iLcaseType == 3 || iLcaseType == 4)
		{
			m_arMapGilcSbcfK.SetAt(GilcGetK, iCountSbcf);
			iCountSbcf++;
		}
		else ASSERT(0);
	}
}

BOOL CCRCForceCtrl::Get_ForceStressDataForRatingBD21(ElemPairK ElemK,
	CArray<FORCE_RCASE_BD, FORCE_RCASE_BD>& arForceRCase,
	CArray<STRESS_RCASE_BD, STRESS_RCASE_BD>& arStressRCase,
	CArray<STRESS_RCASE_BD, STRESS_RCASE_BD>& arSlabStressRCase,
	FORCE_RCASE_PRECOMP_ELEM &ForcePreComElem)
{
	arForceRCase.RemoveAll();
	arStressRCase.RemoveAll();
	ForcePreComElem.Initialize();

	// Reset DimType.
	m_iDimType = 2;	// Set 3D.
	// Consider No Effect Zone.
	Set_RatNoEffectZone(ElemK);

	m_StrsPost.Initialize();
	m_pSectInfo->Get_StrsPscd(FALSE, ElemK.first, m_StrsPost);

	int iLcomNum = m_arLcomData.GetCount();
	if (iLcomNum == 0)	return FALSE;

	// Check Existing Reciprocal Stress.
	T_LCRS_D LcrsD;
	LcrsD.Initialize();
	BOOL bReciInput = m_pAttrCtrl->GetLcrs(LcrsD);

	BOOL bIncludeTP = TRUE;

	T_ELEM_D ElemD;
	ElemD.Initialize();
	T_SECT_D SectD;   SectD.Initialize();

	if (ElemK.second == EN_EL_BEAM)
	{
		if (!m_pPostCtrl->GetElemPost(ElemK.first, ElemD))	return FALSE;
		if (!m_pPostCtrl->GetSectPost(ElemD.elpro, SectD))	return FALSE;
	}
	else if (ElemK.second == EN_EL_VBEAM)
	{
		T_VBEM_D VbemD;
		if (!m_pAttrCtrl2->GetVbem(ElemK.first, VbemD)) return FALSE;

		T_SECV_D SecvD; SecvD.Initialize();
		m_pAttrCtrl2->GetSecv(ElemK.first, SecvD); // T_SECV_K = T_VBEM_K
		SecvD.ConvertToSect(SectD);
	}
	else ASSERT(0);


	BOOL bIsCptPSC = m_pDataCtrl->IsComPSCSect(SectD.nStype, SectD.SectBefore.nStype);
	BOOL bIsCsgSect = m_pDataCtrl->IsCsgSect(SectD.nStype, SectD.SectBefore.nStype);
	// Composite 경우 Part force/stress를 위해..
	int nForType = (bIsCptPSC == TRUE || bIsCsgSect == TRUE) ? 1 : 0;

	for (int i = 0; i < iLcomNum; ++i)
	{
		// Initialize Forces.
		Set_ForceIni();

		_DGN_LCOM LcomDesign;
		LcomDesign.Initialize();
		if (!m_arLcomData.Lookup(i + 1, LcomDesign))	continue;

		T_ALCS_D AlcsD;
		AlcsD.Initialize();
		T_ALCS_K AlcsKey = LcomDesign.OriginalLcomKey;
		m_pAttrCtrl2->GetAlcs(AlcsKey, AlcsD);

		CArray<T_LCOM_BASE, T_LCOM_BASE&> aLcom;
		aLcom.RemoveAll();
		aLcom.Copy(AlcsD.arLoadComb);

		T_LCOM_BASE* pStdMvCase = &AlcsD.CombinedMVCase;
		T_LCOM_BASE* pSpcMvCase = &AlcsD.SpecialMVCase;
		BOOL bCalcStss = (AlcsD.nLimitState == 1); // SLS

		int iLcaseNum = aLcom.GetSize();
		for (int j = 0; j < iLcaseNum; ++j)
		{
			T_LCOM_BASE &LcomBase = aLcom[j];
			unsigned int iAnalType = LcomBase.AnalType;
			unsigned int iLcaseKey = LcomBase.LoadCaseKey;
			double dFactor = LcomBase.Factor * AlcsD.dGammaF3;
			int iMaxMinType = LcomDesign.iMoveLcaseType;//  LcomDesign.iDgnLcomType; - 확인필요!!
			// Lcase for Reciprocal Stress.
			BOOL bReciLcase = (bReciInput ? Is_Reciprocal(iAnalType, iLcaseKey) : FALSE);
			// LcomUlData.Combination[i].AnalType is...
			// D_LCOM_STATIC       1
			// D_LCOM_SPECTRUM     2
			// D_LCOM_ECCENSPEC   14
			// D_LCOM_HISTORY      3 
			// D_LCOM_STAGE       13
			// D_LCOM_MOVING       4 (Load Combination - Max, Min)
			// D_LCOM_SETTLEMENT   5 (Load Combination - Max, Min)
			// D_LCOM_GRIDMODEL   15 (Load Combination - Max, Min)
			_DGN_FORC_CRC_EX ForceLcase;

			switch (iAnalType)
			{
			case D_LCOM_STATIC:
				Get_Stld_EX(ElemK, iLcaseKey, nForType, bCalcStss, dFactor, bReciLcase);
				break;
			case D_LCOM_SPECTRUM:
				Get_Splc_EX(ElemK, iLcaseKey, nForType, bCalcStss, dFactor);
				break;
			case D_LCOM_ECCENSPEC:
				Get_Espc_EX(ElemK, iLcaseKey, nForType, bCalcStss, dFactor);
				break;
			case D_LCOM_HISTORY:
				Get_This_EX(ElemK, iLcaseKey, nForType, bCalcStss, dFactor);
				break;
			case D_LCOM_STAGE:
				Get_Sgld_EX(ElemK, iLcaseKey, nForType, bCalcStss, dFactor, bReciLcase, bIncludeTP, 0);	// If iStepNo=0, Final Stage.
				break;
			case D_LCOM_MOVING:
				Get_Mvld_EX(ElemK, iLcaseKey, nForType, bCalcStss, dFactor, bReciLcase, iMaxMinType);
				break;
			case D_LCOM_SETTLEMENT:
				Get_Smlc_EX(ElemK, iLcaseKey, nForType, bCalcStss, dFactor, iMaxMinType);
				break;
			case D_LCOM_GRIDMODEL:
				Get_Gilc_EX(ElemK, iLcaseKey, nForType, bCalcStss, dFactor, bReciLcase, iMaxMinType);
				break;
			case D_LCOM_CB_CONCRETE:
			case D_LCOM_CB_STEEL:
			case D_LCOM_CB_STLCOMP:
				Get_Lcom(ElemK, iLcaseKey, nForType, bCalcStss, dFactor, iMaxMinType);  // Add by GAY. MNET:2903. ('07.07.31).
				break;
			default:
				ASSERT(0);
				break;
			}
		}

		// Force.
		_DGN_FORC_CRC_EX ForceLcom;
		_DGN_FORC_CRC_EX ForceTnpr;
		_DGN_FORC_CRC_EX ForceTnsc;
		if (!Get_Force4RatingDL_EX(ForceLcom, ForceTnpr, ForceTnsc))	ASSERT(0);
		ForceLcom.strType = LcomDesign.DesignLcomNa;	// For Design LcomNa (cLCB-DA+1,...).

		// Stress.
		_DGN_STRS_CRC_EX StressLcom;
		if (bIsCptPSC)
		{
			if (!Get_StressPart1_EX(StressLcom)) ASSERT(0);
		}
		else
		{
			if (!Get_Stress4RatingDL_EX(StressLcom)) ASSERT(0);
		}

		StressLcom.strType = LcomDesign.DesignLcomNa;

		_DGN_STRS_CRC_EX SlabStressLcom;
		if (bIsCptPSC) Get_StressPart2_EX(SlabStressLcom);

		// PreCompForce
		_DGN_FORC_CRC_EX PreCompForce;
		_DGN_STRS_CRC_EX PreCompStress;
		Get_PreForceStress4RatingDL_EX(PreCompForce, PreCompStress);

		// Initial force,stress
		Set_ForceIni();

		// Standard Moving case
		_DGN_FORC_CRC_EX ForceStdMove;
		_DGN_STRS_CRC_EX StressStdMove;
		_DGN_STRS_CRC_EX SlabStressStdMove;

		// Special Moving case
		_DGN_FORC_CRC_EX ForceSpcMove;
		_DGN_STRS_CRC_EX StressSpcMove;
		_DGN_STRS_CRC_EX SlabStressSpcMove;

		// CIVIL-1063 / CIVIL-1103 CS454 Assessment 검토용 Moving 부재력 분리
		if (AlcsD.nMovType == 1) //Special 인 경우
		{
			unsigned int iAnalType_Move = pSpcMvCase->AnalType;
			unsigned int iLcaseKey_Move = pSpcMvCase->LoadCaseKey;
			double dFactor_Move = pSpcMvCase->Factor * AlcsD.dGammaF3;
			int iMaxMinType_Move = LcomDesign.iMoveLcaseType;
			BOOL bReciLcase_Move = (bReciInput ? Is_Reciprocal(iAnalType_Move, iLcaseKey_Move) : FALSE);
			if (iAnalType_Move == D_LCOM_MOVING)
			{
				Get_Mvld_EX(ElemK, iLcaseKey_Move, nForType, bCalcStss, dFactor_Move, bReciLcase_Move, iMaxMinType_Move);
				if (!Get_Force4RatingLL_EX(ForceSpcMove)) ASSERT(0);
				if (!Get_Stress4RatingLL_EX(StressSpcMove)) ASSERT(0);
				if (bIsCptPSC == TRUE) Get_StressPart2_EX(SlabStressSpcMove);

				// 혹시 나중에 EX 하중이 필요하면....
				//Get_Mvld_EX(ElemK, iLcaseKey_Move, nForType, bCalcStss, dFactor_Move, bReciLcase_Move, iMaxMinType_Move);
			}
		}
		else // combined
		{
			if (m_iCivilCode == STL_NR_GN_CIV_025_06)
			{
				unsigned int iAnalType_Move = pStdMvCase->AnalType;
				unsigned int iLcaseKey_Move = pStdMvCase->LoadCaseKey;
				double dFactor_Move = pStdMvCase->Factor * AlcsD.dGammaF3;
				int iMaxMinType_Move = LcomDesign.iMoveLcaseType;
				BOOL bReciLcase_Move = (bReciInput ? Is_Reciprocal(iAnalType_Move, iLcaseKey_Move) : FALSE);
				if (iAnalType_Move == D_LCOM_MOVING)
				{
					Get_Mvld_EX(ElemK, iLcaseKey_Move, nForType, bCalcStss, dFactor_Move, bReciLcase_Move, iMaxMinType_Move);
					if (!Get_Force4RatingLL_EX(ForceStdMove)) ASSERT(0);
					if (!Get_Stress4RatingLL_EX(StressStdMove)) ASSERT(0);
					if (bIsCptPSC == TRUE) Get_StressPart2_EX(SlabStressStdMove);
				}

				// Initial force,stress
				Set_ForceIni();
				iAnalType_Move = pSpcMvCase->AnalType;
				iLcaseKey_Move = pSpcMvCase->LoadCaseKey;
				dFactor_Move = pSpcMvCase->Factor * AlcsD.dGammaF3;
				iMaxMinType_Move = LcomDesign.iMoveLcaseType;
				bReciLcase_Move = (bReciInput ? Is_Reciprocal(iAnalType_Move, iLcaseKey_Move) : FALSE);
				if (iAnalType_Move == D_LCOM_MOVING)
				{
					Get_Mvld_EX(ElemK, iLcaseKey_Move, nForType, bCalcStss, dFactor_Move, bReciLcase_Move, iMaxMinType_Move);
					if (!Get_Force4RatingLL_EX(ForceSpcMove)) ASSERT(0);
					if (!Get_Stress4RatingLL_EX(StressSpcMove)) ASSERT(0);
					if (bIsCptPSC == TRUE) Get_StressPart2_EX(SlabStressSpcMove);
				}
			}
			else
			{
				unsigned int iAnalType_Move = pStdMvCase->AnalType;
				unsigned int iLcaseKey_Move = pStdMvCase->LoadCaseKey;
				double dFactor_Move = pStdMvCase->Factor * AlcsD.dGammaF3;
				int iMaxMinType_Move = LcomDesign.iMoveLcaseType;
				BOOL bReciLcase_Move = (bReciInput ? Is_Reciprocal(iAnalType_Move, iLcaseKey_Move) : FALSE);
				if (iAnalType_Move == D_LCOM_MOVING)
				{
					Get_Mvld_EX(ElemK, iLcaseKey_Move, nForType, bCalcStss, dFactor_Move, bReciLcase_Move, iMaxMinType_Move);
					if (!Get_Force4RatingLL_EX(ForceStdMove)) ASSERT(0);
					if (!Get_Stress4RatingLL_EX(StressStdMove)) ASSERT(0);
					if (bIsCptPSC == TRUE) Get_StressPart2_EX(SlabStressStdMove);

					// Initial force,stress
					Set_ForceIni();

					Get_Mvld_EX(ElemK, iLcaseKey_Move, nForType, bCalcStss, dFactor_Move, bReciLcase_Move, iMaxMinType_Move, TRUE);
					if (!Get_Force4RatingLL_EX(ForceSpcMove)) ASSERT(0);
					if (!Get_Stress4RatingLL_EX(StressSpcMove)) ASSERT(0);
					if (bIsCptPSC == TRUE) Get_StressPart2_EX(SlabStressSpcMove);

					ForceStdMove -= ForceSpcMove;
					StressStdMove -= StressSpcMove;
					SlabStressStdMove -= SlabStressSpcMove;

					// 혹시 나중에 EX 하중이 필요하면....
					//Get_Mvld_EX(ElemK, iLcaseKey_Move, nForType, bCalcStss, dFactor_Move, bReciLcase_Move, iMaxMinType_Move, TRUE);
				}
			}
		}

		// Force
		FORCE_RCASE_BD ForceRcase;
		ForceRcase.Initialize();
		ForceRcase.ForceSd = ForceLcom;
		ForceRcase.ForceSst = ForceStdMove;
		ForceRcase.ForceS = ForceSpcMove;
		ForceRcase.ForceSst.iRefNo[0] = LcomDesign.iMoveLcaseType;
		arForceRCase.Add(ForceRcase);

		if (bCalcStss) // 현재 CRCDataCtrl에서 ULS 에서는 사용안함
		{
			// Stress
			STRESS_RCASE_BD StressRcase;
			StressRcase.Initialize();
			StressRcase.StressSd = StressLcom;
			StressRcase.StressSst = StressStdMove;
			StressRcase.StressS = StressSpcMove;
			StressRcase.StressSst.iRefNo[0] = LcomDesign.iMoveLcaseType;
			arStressRCase.Add(StressRcase);

			// Stress
			STRESS_RCASE_BD SlabStressRcase;
			SlabStressRcase.Initialize();
			SlabStressRcase.StressSd = SlabStressLcom;
			SlabStressRcase.StressSst = SlabStressStdMove;
			SlabStressRcase.StressS = SlabStressSpcMove;
			SlabStressRcase.StressSst.iRefNo[0] = LcomDesign.iMoveLcaseType;
			arSlabStressRCase.Add(SlabStressRcase);
		}

	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_LcomData(int iLcom, T_LCOM_IN& paramD, T_LCOM_OUT& outD)
{
	// Initialize Forces.
	outD.Init();

	T_LCOM_FORC forcD;
	forcD.Init();

	_DGN_LCOM& LcomDesign = paramD.LcomDesign;

	// Check Existing Reciprocal Stress.
	T_LCRS_D LcrsD;
	LcrsD.Initialize();
	BOOL bReciInput = m_pAttrCtrl->GetLcrs(LcrsD);

	//////////////////////////
	T_ELEM_K ElemK = paramD.ElemK.first;
	int nForType = paramD.nForType;
	//////////////////////////
	if (LcomDesign.LcomUlData.LoadCombType == 1)
	{
		Get_EnvelopLcom_mt(paramD, forcD, bReciInput);
	}
	else
	{
		int iLcaseNum = LcomDesign.LcomUlData.Combination.GetSize();
		for (int j = 0; j < iLcaseNum; ++j)
		{
			const T_LCOM_BASE &LcomB = LcomDesign.LcomUlData.Combination[j];

			unsigned int iAnalType = LcomB.AnalType;
			paramD.iLcaseK = LcomB.LoadCaseKey;
			paramD.iMaxMinType = LcomDesign.iDgnLcomType;
			// Lcase for Reciprocal Stress.
			paramD.bReciLcase = (bReciInput ? Is_Reciprocal(iAnalType, LcomB.LoadCaseKey) : FALSE);
			paramD.dFactor = AdjustCJJLoadCaseFactor(iAnalType, LcomDesign, LcomB.Factor, m_Chrp, m_Pscd);

			_DGN_FORC_CRC ForceLcase;
			if (iAnalType == D_LCOM_STATIC)				Get_Stld_mt(paramD, forcD);
			else if (iAnalType == D_LCOM_SPECTRUM)		Get_Splc_mt(paramD, forcD);
			else if (iAnalType == D_LCOM_ECCENSPEC)		Get_Espc_mt(paramD, forcD);
			else if (iAnalType == D_LCOM_HISTORY)		Get_This_mt(paramD, forcD);
			else if (iAnalType == D_LCOM_STAGE)			Get_Sgld_mt(paramD, forcD, 0);	// If iStepNo=0, Final Stage.
			else if (iAnalType == D_LCOM_MOVING)		Get_Mvld_mt(paramD, forcD);
			else if (iAnalType == D_LCOM_SETTLEMENT)	Get_Smlc_mt(paramD, forcD);
			else if (iAnalType == D_LCOM_GRIDMODEL)		Get_Gilc_mt(paramD, forcD);
			else if ((m_iDgnCode == RC_JTG_B02_01_2008 || m_iDgnCode == RC_CJJ_166_2011) && iAnalType == D_LCOM_CB_CONCRETE) // Add by SHIN(09.12.21)
			{
				T_LCOM_D LcomD;
				if (m_pAttrCtrl->GetLcom(D_LCOMTYPE_CONCRETE, LcomB.LoadCaseKey, LcomD))
				{
					if (LcomD.LoadCombType == 3)
					{
						Get_Lcom_mt(paramD, forcD, LcomB.LoadCaseKey);
					}
				}
			}
			else if ((CDBLib::IsCSGCode(m_iDgnCode) == TRUE && (iAnalType == D_LCOM_CB_STEEL || iAnalType == D_LCOM_CB_STLCOMP)) || (CDBLib::IsCSGCode(m_iDgnCode) == FALSE && iAnalType == D_LCOM_CB_CONCRETE))
			{
				Get_Lcom_mt(paramD, forcD, LcomB.LoadCaseKey);  // Add by GAY. MNET:2903. ('07.07.31).
			}
			else ASSERT(0);
		}
	}

	if (!Get_Force_mt(forcD, outD))	ASSERT(0);

	outD.ForceLcom.strType = LcomDesign.DesignLcomNa;	// For Design LcomNa (cLCB-DA+1,...).
	if (paramD.bBinary)
	{
		outD.ForceLcomExTp += outD.ForceLcom;
		outD.ForceLcomExTp -= outD.ForceTnpr;
	}

	if (!Get_Stress_mt(forcD, outD)) ASSERT(0);

	int iSerialLcom = iLcom + 1;
	Get_PrincipalStressByLcom(paramD.ElemK, paramD.SectD, paramD.RpscMbar, paramD.RpscSbar, paramD.StrsPropD, iSerialLcom, FALSE, outD.ForceLcom, outD.StssLcom);
	outD.StressLcom.iRefNo[0] = outD.StressLcom.iRefNo[1] = LcomDesign.OriginalLcomKey;
	outD.StressStag.iRefNo[0] = outD.StressStag.iRefNo[1] = LcomDesign.OriginalLcomKey;
	outD.StressTnpr.iRefNo[0] = outD.StressTnpr.iRefNo[1] = LcomDesign.OriginalLcomKey;
	outD.StressTnsc.iRefNo[0] = outD.StressTnsc.iRefNo[1] = LcomDesign.OriginalLcomKey;
	outD.StressLTerm.iRefNo[0] = outD.StressLTerm.iRefNo[1] = LcomDesign.OriginalLcomKey;
	outD.StressDL_TB05.iRefNo[0] = outD.StressDL_TB05.iRefNo[1] = LcomDesign.OriginalLcomKey;
	outD.StressLL_TB05.iRefNo[0] = outD.StressLL_TB05.iRefNo[1] = LcomDesign.OriginalLcomKey;
	outD.StressCSTP_TB05.iRefNo[0] = outD.StressCSTP_TB05.iRefNo[1] = LcomDesign.OriginalLcomKey;

	outD.StressLcom.strType = LcomDesign.DesignLcomNa;
	if (paramD.bBinary)
	{
		if (m_iDgnCode == SNiP_20503_84_CSG || m_iDgnCode == SP_35_13330_11_CSG ||
			m_iDgnCode == EUROCODE4_2_04_CSG)
		{
			outD.StrScfpCr = forcD.StressScfpCr;
			outD.StrScfpSh = forcD.StressScfpSh;
			outD.StrScfpTe = forcD.StressScfpTe;
			outD.StrScfpRe = forcD.StressScfpRe;
			outD.ForceScfpSum = forcD.ForceScfpSum;
			outD.ForceScfpCrp = forcD.ForceScfpCrp;
			outD.ForceScfpShr = forcD.ForceScfpShr;
		}

		if (paramD.nForType == 1 || paramD.nForType == 2)
		{
			outD.ForceLcomPart1 += forcD.ForceRemnP1;
			outD.StressLcomPart1 += forcD.StressRemnP1;
			outD.ForceLcomPart2 += forcD.ForceRemnP2;
			outD.StressLcomPart2 += forcD.StressRemnP2;
			outD.StressLTermPart2 += forcD.StressLTermP2;
			outD.StressSTermPart2 += forcD.StressSTermP2;
			outD.StrTnprPa2 = forcD.StressTnpr2;
			outD.StrTnscPa2 = forcD.StressTnsc2;
		}
	}
	return TRUE;
}

BOOL CCRCForceCtrl::Get_EnvelopLcom_mt(T_LCOM_IN& paramD, T_LCOM_FORC& forcD, BOOL bReciInput)
{
	_DGN_LCOM& LcomDesign = paramD.LcomDesign;
	if (LcomDesign.LcomUlData.LoadCombType != 1) return FALSE;

	int iLcaseNum = LcomDesign.LcomUlData.Combination.GetSize();

	CArray<_DGN_FORC_CRC, _DGN_FORC_CRC&>arForceLcase;
	CArray<_DGN_STRS_ADD, _DGN_STRS_ADD&>arStressAdd;
	CArray<_DGN_STRS_CRC, _DGN_STRS_CRC&>arStressLcase;
	CArray<_DGN_SHRS_ADD, _DGN_SHRS_ADD&>arStssLcase;
	CArray<_DGN_FORC_CRC, _DGN_FORC_CRC&>arForcePart1;
	CArray<_DGN_STRS_CRC, _DGN_STRS_CRC&>arStressPart1;
	CArray<_DGN_FORC_CRC, _DGN_FORC_CRC&>arForcePart2;
	CArray<_DGN_STRS_CRC, _DGN_STRS_CRC&>arStressPart2;

	_DGN_FORC_CRC ForceLcase;
	_DGN_STRS_ADD StressAdd;
	_DGN_STRS_CRC StressLcase;
	_DGN_SHRS_ADD StssLcase;

	_DGN_FORC_CRC ForcePart1;
	_DGN_STRS_CRC StressPart1;
	_DGN_FORC_CRC ForcePart2;
	_DGN_STRS_CRC StressPart2;

	//////////////////////////////////////////////////////////////////////////
	for (int j = 0; j < iLcaseNum; ++j)
	{
		const T_LCOM_BASE &LcomB = LcomDesign.LcomUlData.Combination[j];

		ForceLcase.Initialize();
		StressAdd.Initialize();
		StressLcase.Initialize();
		StssLcase.Initialize();
		ForcePart1.Initialize();
		StressPart1.Initialize();
		ForcePart2.Initialize();
		StressPart2.Initialize();

		unsigned int iAnalType = LcomB.AnalType;
		unsigned int iLcaseKey = LcomB.LoadCaseKey;
		double dFactor = LcomB.Factor;
		int iMaxMinType = LcomDesign.iDgnLcomType;
		BOOL bReciLcase = (bReciInput ? Is_Reciprocal(iAnalType, iLcaseKey) : FALSE);

		dFactor = AdjustCJJLoadCaseFactor(iAnalType, LcomDesign, dFactor, m_Chrp, m_Pscd);

		_DGN_FORC_CRC ForceLcase;
		if ((CDBLib::IsCSGCode(m_iDgnCode) == FALSE && iAnalType == D_LCOM_CB_CONCRETE) || (CDBLib::IsCSGCode(m_iDgnCode) == TRUE && (iAnalType == D_LCOM_CB_STEEL || iAnalType == D_LCOM_CB_STLCOMP)))
		{
			//O≫OEÐiOO×eºIA´½øÐÐ°uAc￡￢EcEo°uAcOÐOÐ¹¤¿o￡￢½¨OeOA≫§½≪¸A¹¤¿oμ￥¶A¶¨OaIªºEOØ×eºIA´´|Ai
			g_num_mutex1.lock();
			Get_Lcom_mt(paramD, iLcaseKey, ForceLcase, StressAdd, StressLcase, StssLcase, ForcePart1, StressPart1, ForcePart2, StressPart2);
			g_num_mutex1.unlock();
		}
		else
		{
			ASSERT(0);
		}

		Set_DimTypeForc(ForceLcase);

		ForceLcase *= dFactor;
		forcD.StressAdd *= dFactor;
		StressLcase *= dFactor;
		StssLcase *= dFactor;
		ForcePart1 *= dFactor;
		ForcePart2 *= dFactor;
		StressPart1 *= dFactor;
		StressPart2 *= dFactor;

		arForceLcase.Add(ForceLcase);//½≪°uAcOÐμAA¿O≫¸o×eºIμAAUA|´æÆðA´
		arStressAdd.Add(forcD.StressAdd);
		arStressLcase.Add(StressLcase);
		arStssLcase.Add(StssLcase);
		arForcePart1.Add(ForcePart1);
		arForcePart2.Add(ForcePart2);
		arStressPart1.Add(StressPart1);
		arStressPart2.Add(StressPart2);
	}
	//////////////////////////////////////////////////////////////////////////  
	//double dFxx[cPOSI_CRC], dFyy[cPOSI_CRC], dFzz[cPOSI_CRC];//18×eAUA|Oμ¶OO|μAOªEØ
	//double dMux[cPOSI_CRC], dMuy[cPOSI_CRC], dMuz[cPOSI_CRC];
	//double dMbi[cPOSI_CRC], dTst[cPOSI_CRC], dTwp[cPOSI_CRC]; 
	int nFlag = 0;//±e¼CAAO≫×eEC×iOμ
	_DGN_FORC_CRC TempForceLaseMax; TempForceLaseMax.Initialize(TRUE);
	_DGN_FORC_CRC TempForceLaseMin; TempForceLaseMin.Initialize(FALSE);

	for (int ii = 0; ii < iLcaseNum; ++ii)//E¡×i²≫Au
	{
		switch (paramD.nCompareType)
		{
		case 0://dFxxMax
			if (arForceLcase.GetAt(ii).dFxx[0] >= TempForceLaseMax.dFxx[0])
			{
				nFlag = ii;
				TempForceLaseMax = arForceLcase.GetAt(ii);
			}
			break;
		case 1://dFxxMin
			if (arForceLcase.GetAt(ii).dFxx[1] <= TempForceLaseMin.dFxx[1])
			{
				nFlag = ii;
				TempForceLaseMin = arForceLcase.GetAt(ii);
			}
			break;
		case 2://dFyyMax
			if (arForceLcase.GetAt(ii).dFyy[0] >= TempForceLaseMax.dFyy[0])
			{
				nFlag = ii;
				TempForceLaseMax = arForceLcase.GetAt(ii);
			}
			break;
		case 3://dFyyMin
			if (arForceLcase.GetAt(ii).dFyy[1] <= TempForceLaseMin.dFyy[1])
			{
				nFlag = ii;
				TempForceLaseMin = arForceLcase.GetAt(ii);
			}
			break;
		case 4://dFzzMax
			if (arForceLcase.GetAt(ii).dFzz[0] >= TempForceLaseMax.dFzz[0])
			{
				nFlag = ii;
				TempForceLaseMax = arForceLcase.GetAt(ii);
			}
			break;
		case 5://dFzzMin
			if (arForceLcase.GetAt(ii).dFzz[1] <= TempForceLaseMin.dFzz[1])
			{
				nFlag = ii;
				TempForceLaseMin = arForceLcase.GetAt(ii);
			}
			break;
		case 6://dMuxMax
			if (arForceLcase.GetAt(ii).dMux[0] >= TempForceLaseMax.dMux[0])
			{
				nFlag = ii;
				TempForceLaseMax = arForceLcase.GetAt(ii);
			}
			break;
		case 7://dMuxMin
			if (arForceLcase.GetAt(ii).dMux[1] <= TempForceLaseMin.dMux[1])
			{
				nFlag = ii;
				TempForceLaseMin = arForceLcase.GetAt(ii);
			}
			break;
		case 8://dMuyMax
			if (arForceLcase.GetAt(ii).dMuy[0] >= TempForceLaseMax.dMuy[0])
			{
				nFlag = ii;
				TempForceLaseMax = arForceLcase.GetAt(ii);
			}
			break;
		case 9://dMuyMin
			if (arForceLcase.GetAt(ii).dMuy[1] <= TempForceLaseMin.dMuy[1])
			{
				nFlag = ii;
				TempForceLaseMin = arForceLcase.GetAt(ii);
			}
			break;
		case 10://dMuzMax
			if (arForceLcase.GetAt(ii).dMuz[0] >= TempForceLaseMax.dMuz[0])
			{
				nFlag = ii;
				TempForceLaseMax = arForceLcase.GetAt(ii);
			}
			break;
		case 11://dMuzMin
			if (arForceLcase.GetAt(ii).dMuz[1] <= TempForceLaseMin.dMuz[1])
			{
				nFlag = ii;
				TempForceLaseMin = arForceLcase.GetAt(ii);
			}
			break;
		case 12://dMbiMax
			if (arForceLcase.GetAt(ii).dMbi[0] >= TempForceLaseMax.dMbi[0])
			{
				nFlag = ii;
				TempForceLaseMax = arForceLcase.GetAt(ii);
			}
			break;
		case 13://dMbiMin
			if (arForceLcase.GetAt(ii).dMbi[1] <= TempForceLaseMin.dMbi[1])
			{
				nFlag = ii;
				TempForceLaseMin = arForceLcase.GetAt(ii);
			}
			break;
		case 14://dTstMax
			if (arForceLcase.GetAt(ii).dTst[0] >= TempForceLaseMax.dTst[0])
			{
				nFlag = ii;
				TempForceLaseMax = arForceLcase.GetAt(ii);
			}
			break;
		case 15://dTstMin
			if (arForceLcase.GetAt(ii).dTst[1] <= TempForceLaseMin.dTst[1])
			{
				nFlag = ii;
				TempForceLaseMin = arForceLcase.GetAt(ii);
			}
			break;
		case 16://dTwpMax
			if (arForceLcase.GetAt(ii).dTwp[0] >= TempForceLaseMax.dTwp[0])
			{
				nFlag = ii;
				TempForceLaseMax = arForceLcase.GetAt(ii);
			}
			break;
		case 17://dTwpMin
			if (arForceLcase.GetAt(ii).dTwp[1] <= TempForceLaseMin.dTwp[1])
			{
				nFlag = ii;
				TempForceLaseMin = arForceLcase.GetAt(ii);
			}
			break;
		default:
			ASSERT(0);
			break;
		}
	}
	//////////////////////////////////////////////////////////////////////////
	forcD.ForceRemn = arForceLcase.GetAt(nFlag);
	forcD.StressAdd = arStressAdd.GetAt(nFlag);
	forcD.StressRemn = arStressLcase.GetAt(nFlag);
	forcD.StressShr = arStssLcase.GetAt(nFlag);

	if (paramD.nForType > 0)
	{
		forcD.ForceRemnP1 = arForcePart1.GetAt(nFlag);
		forcD.ForceRemnP2 = arForcePart2.GetAt(nFlag);
		forcD.StressRemnP1 = arStressPart1.GetAt(nFlag);
		forcD.StressRemnP2 = arStressPart2.GetAt(nFlag);
	}
	//////////////////////////////////////////////////////////////////////////
	return TRUE;
}

BOOL CCRCForceCtrl::Get_Stld_mt(T_LCOM_IN& paramD, T_LCOM_FORC& forcD)
{
	_DGN_FORC_CRC ForceLcase;
	_DGN_STRS_ADD StressAdd;
	_DGN_STRS_CRC StressLcase;
	_DGN_SHRS_ADD StssLcase;

	_DGN_FORC_CRC ForcePart1;
	_DGN_STRS_CRC StressPart1;
	_DGN_FORC_CRC ForcePart2;
	_DGN_STRS_CRC StressPart2;

	if (!Get_Stld_mt(paramD, paramD.iLcaseK, ForceLcase, StressAdd, StressLcase, StssLcase,
		ForcePart1, StressPart1, ForcePart2, StressPart2))	return FALSE;

	double dFactor = paramD.dFactor;
	// Set Forces by DimType.
	Set_DimTypeForc(ForceLcase);
	// Apply Lcase Factor.
	ForceLcase *= dFactor;
	// Stress.
	StressLcase *= dFactor;

	_DGN_SCFP_PART_LCASE ScfpPartLcase;
	T_STLD_K StldScfpK = 0;
	if (m_arStldScfpK.Lookup(paramD.iLcaseK, StldScfpK))
	{
		g_num_mutex1.lock();
		Get_StldScfp(paramD.ElemK, StldScfpK, ScfpPartLcase);
		g_num_mutex1.unlock();

		ScfpPartLcase.ForceP1 *= dFactor;
		ScfpPartLcase.ForceP2 *= dFactor;

		if (CDBLib::IsStldTL(ForceLcase.strType))
		{
			forcD.StressScfpTe.ForceP1 += ScfpPartLcase.ForceP1;
			forcD.StressScfpTe.ForceP2 += ScfpPartLcase.ForceP2;
		}
		else
		{
			forcD.StressScfpRe.ForceP1 += ScfpPartLcase.ForceP1;
			forcD.StressScfpRe.ForceP2 += ScfpPartLcase.ForceP2;
		}
		// 
		forcD.ForceScfpSum += ForceLcase;
	}

	// Add by ZINU.('05.01.03). Consider Stress.
	StressAdd *= dFactor;
	forcD.StressAdd += StressAdd;
	// Principle.
	StssLcase *= dFactor;
	forcD.StressShr += StssLcase;

	if (paramD.nForType > 0)
	{
		ForcePart1 *= dFactor;
		StressPart1 *= dFactor;
		ForcePart2 *= dFactor;
		StressPart2 *= dFactor;

		forcD.ForceRemnP1 += ForcePart1;
		forcD.StressRemnP1 += StressPart1;
		forcD.ForceRemnP2 += ForcePart2;
		forcD.StressRemnP2 += StressPart2;
	}

	T_STLD_K TempK = 0;
	if (m_mapPlcbStldK.Lookup(paramD.iLcaseK, TempK))
	{
		forcD.ForceAddDL += ForceLcase;
		// Stress
		forcD.StressNorDL += StressLcase;
		// JTG
		forcD.StressAddDL += StressLcase;
	}
	else if (CDBLib::IsStldDL(ForceLcase.strType))	// Dead.
	{
		if (paramD.bReciLcase)
			forcD.ForceDrec += ForceLcase;
		else
			forcD.ForceDnon += ForceLcase;

		if (m_bIsPLCB == FALSE)
		{
			forcD.ForceAddDL += ForceLcase;
			// Stress
			forcD.StressNorDL += StressLcase;
			// JTG
			forcD.StressAddDL += StressLcase;
		}
		if (CDBLib::IsStldLTerm(ForceLcase.strType))
		{
			forcD.ForceLTerm += ForceLcase;
			forcD.StressLTerm += StressLcase;
			forcD.StressLTermP2 += StressPart2;
		}
	}
	else if (CDBLib::IsStldLL(ForceLcase.strType))	// Live.
	{
		if (paramD.bReciLcase)
			forcD.ForceLrec += ForceLcase;
		else
			forcD.ForceLnon += ForceLcase;

		// Stress
		forcD.StressNorLL += StressLcase;
		forcD.StressSTermP2 += StressPart2;
	}
	else
	{
		forcD.ForceRemn += ForceLcase;
		// Stress.
		forcD.StressRemn += StressLcase;
	}

	if (Is_JtgStldLL(ForceLcase.strType))
	{
		forcD.ForceLL += ForceLcase;
		// Stress.
		forcD.StressJtgLL += StressLcase;
	}

	// For JTG, Tendon Stress.
	forcD.ForceJtgTndn += ForceLcase;

	// For TB 10002.3-2005, Force Stress
	// DL
	if (m_iDgnCode == TB_10002_3_05 || m_iDgnCode == RC_TB_10002_3_05)
	{
		if (Is_TB05StldDL(ForceLcase.strType))
		{
			forcD.ForceDL_TB05 += ForceLcase;
			forcD.StressDL_TB05 += StressLcase;
		}
		// LL
		if (Is_TB05StldLL(ForceLcase.strType))
		{
			forcD.ForceLL_TB05 += ForceLcase;
			forcD.StressLL_TB05 += StressLcase;
		}
	}
	else if (m_iDgnCode == RC_JTG_B02_01_2008 || m_iDgnCode == RC_CJJ_166_2011)
	{
		if (IsPermanentLoad_JTG_B02(ForceLcase.strType))
		{
			forcD.ForceEQE2_JTG += ForceLcase;
		}
		if (IsSelfWeightLoad_JTG_B02(ForceLcase.strType))
		{
			forcD.ForceWeight_JTG += ForceLcase;
		}
	}

	return TRUE;
}
BOOL CCRCForceCtrl::Get_Splc_mt(T_LCOM_IN& paramD, T_LCOM_FORC& forcD)
{
	//PROFILING(_T("CCRCForceCtrl::Get_Splc"));
	_DGN_FORC_CRC ForceLcase;
	_DGN_STRS_CRC StressLcase;
	_DGN_SHRS_ADD StssLcase;
	//
	_DGN_FORC_CRC ForcePart1;
	_DGN_STRS_CRC StressPart1;
	_DGN_FORC_CRC ForcePart2;
	_DGN_STRS_CRC StressPart2;

	if (!Get_Sepc_mt(paramD, paramD.iLcaseK, D_LOADCASE_SPECTRUM,
		ForceLcase, StressLcase, StssLcase, ForcePart1, StressPart1, ForcePart2, StressPart2))
		return FALSE;

	// Set Forces by DimType.
	Set_DimTypeForc(ForceLcase);

	// Apply Lcase Factor.
	double dFactor = paramD.dFactor;
	ForceLcase *= dFactor;
	forcD.ForceRemn += ForceLcase;
	// Stress
	StressLcase *= dFactor;
	forcD.StressRemn += StressLcase;
	// Principle.
	StssLcase *= dFactor;
	forcD.StressShr += StssLcase;

	// For JTG, Tendon Stress.
	forcD.ForceJtgTndn += ForceLcase;

	if (paramD.nForType > 0)
	{
		ForcePart1 *= dFactor;
		StressPart1 *= dFactor;
		ForcePart2 *= dFactor;
		StressPart2 *= dFactor;

		forcD.ForceRemnP1 += ForcePart1;
		forcD.StressRemnP1 += StressPart1;
		forcD.ForceRemnP2 += ForcePart2;
		forcD.StressRemnP2 += StressPart2;
	}
	return TRUE;
}

