BOOL CCRCForceCtrl::Get_Sepc_mt(T_LCOM_IN& paramD, unsigned int iLcaseKey, int iLcaseType, _DGN_FORC_CRC& ForceLcase, _DGN_STRS_CRC& StressLcase, _DGN_SHRS_ADD& StssLcase,
	_DGN_FORC_CRC& ForcePart1, _DGN_STRS_CRC& StressPart1, _DGN_FORC_CRC& ForcePart2, _DGN_STRS_CRC& StressPart2)
{
	if (!(iLcaseType == D_LOADCASE_SPECTRUM || iLcaseType == D_LOADCASE_ECCENSPEC))	return FALSE;

	_DGN_STRBFORC_LCASE      DgnStrb;
	_DGN_STRBFORC_PART_LCASE DgnStrbPart;
	g_num_mutex1.lock();
	GetStrb4Elem(paramD.ElemK, paramD.nForType, iLcaseType, iLcaseKey, DgnStrb, DgnStrbPart);
	g_num_mutex1.unlock();

	ForceLcase = DgnStrb.Force;
	StressLcase = DgnStrb.Stress;
	if (paramD.bIsCalcStss == TRUE) StssLcase = DgnStrb.Stss;

	if (paramD.nForType > 0)
	{
		ForcePart1 = DgnStrbPart.ForceP1;
		ForcePart2 = DgnStrbPart.ForceP2;
		StressPart1 = DgnStrb.Stress;
		StressPart2 = DgnStrbPart.StressP2;
	}

	// Set Force Type (D,L,W,...).
	if (iLcaseType == D_LOADCASE_SPECTRUM)			ForceLcase.strType = StressLcase.strType = _T("RSP");
	else if (iLcaseType == D_LOADCASE_ECCENSPEC)	ForceLcase.strType = StressLcase.strType = _T("ESP");
	else	ASSERT(0);

	return TRUE;
}
BOOL CCRCForceCtrl::Get_This_mt(T_LCOM_IN& paramD, T_LCOM_FORC& forcD)
{
	//PROFILING(_T("CCRCForceCtrl::Get_This"));

	_DGN_FORC_CRC ForceLcase;
	_DGN_STRS_CRC StressLcase;
	_DGN_SHRS_ADD StssLcase;
	//
	_DGN_FORC_CRC ForcePart1;
	_DGN_STRS_CRC StressPart1;
	_DGN_FORC_CRC ForcePart2;
	_DGN_STRS_CRC StressPart2;

	if (!Get_This_mt(paramD, ForceLcase, StressLcase, StssLcase,
		ForcePart1, StressPart1, ForcePart2, StressPart2))	return FALSE;
	// Set Forces by DimType.
	Set_DimTypeForc(ForceLcase);
	// Apply Lcase Factor.
	double dFactor = paramD.dFactor;
	ForceLcase *= dFactor;
	forcD.ForceRemn += ForceLcase;
	// Stress
	StressLcase *= dFactor;
	forcD.StressRemn += StressLcase;
	// Principle.
	StssLcase *= dFactor;
	forcD.StressShr += StssLcase;

	// For JTG, Tendon Stress.
	forcD.ForceJtgTndn += ForceLcase;

	if (paramD.nForType > 0)
	{
		ForcePart1 *= dFactor;
		StressPart1 *= dFactor;
		ForcePart2 *= dFactor;
		StressPart2 *= dFactor;

		forcD.ForceRemnP1 += ForcePart1;
		forcD.StressRemnP1 += StressPart1;
		forcD.ForceRemnP2 += ForcePart2;
		forcD.StressRemnP2 += StressPart2;
	}

	return TRUE;
}
BOOL CCRCForceCtrl::Get_This_mt(T_LCOM_IN& paramD, _DGN_FORC_CRC& ForceLcase, _DGN_STRS_CRC& StressLcase, _DGN_SHRS_ADD& StssLcase,
	_DGN_FORC_CRC& ForcePart1, _DGN_STRS_CRC& StressPart1, _DGN_FORC_CRC& ForcePart2, _DGN_STRS_CRC& StressPart2)
{
	int nLcaseType = D_LOADCASE_HISTORY;

	_DGN_STRBFORC_LCASE      DgnStrb;
	_DGN_STRBFORC_PART_LCASE DgnStrbPart;
	g_num_mutex1.lock();
	GetStrb4Elem(paramD.ElemK, paramD.nForType, nLcaseType, paramD.iLcaseK, DgnStrb, DgnStrbPart);
	g_num_mutex1.unlock();

	ForceLcase = DgnStrb.Force;
	StressLcase = DgnStrb.Stress;
	if (paramD.bIsCalcStss == TRUE) StssLcase = DgnStrb.Stss;

	if (paramD.nForType > 0)
	{
		ForcePart1 = DgnStrbPart.ForceP1;
		ForcePart2 = DgnStrbPart.ForceP2;
		StressPart1 = DgnStrb.Stress;
		StressPart2 = DgnStrbPart.StressP2;
	}

	// Set Force Type.
	ForceLcase.strType = StressLcase.strType = _T("TH");

	return TRUE;
}
BOOL CCRCForceCtrl::Get_Sgld_mt(T_LCOM_IN& paramD, T_SGLD_K SgldK, T_SGLD_D& SgldD, int iStepNo, _DGN_FORC_CRC& ForceLcase, _DGN_STRS_CRC& StressLcase, _DGN_SHRS_ADD& StssLcase,
	_DGN_FORC_CRC& ForcePart1, _DGN_STRS_CRC& StressPart1, _DGN_FORC_CRC& ForcePart2, _DGN_STRS_CRC& StressPart2, int Lcase/*Default=0*/)
{

	int nLcaseType = D_LOADCASE_STAGE;

	_DGN_STRBFORC_LCASE      DgnStrb;
	_DGN_STRBFORC_PART_LCASE DgnStrbPart;

	g_num_mutex1.lock();
	GetStrb4Elem(paramD.ElemK, paramD.nForType, nLcaseType, SgldK, DgnStrb, DgnStrbPart);
	g_num_mutex1.unlock();

	ForceLcase = DgnStrb.Force;
	StressLcase = DgnStrb.Stress;
	if (paramD.bIsCalcStss == TRUE) StssLcase = DgnStrb.Stss;

	if (paramD.nForType > 0)
	{
		ForcePart1 = DgnStrbPart.ForceP1;
		ForcePart2 = DgnStrbPart.ForceP2;
		StressPart1 = DgnStrb.Stress;
		StressPart2 = DgnStrbPart.StressP2;
	}

	T_STCT_D StctD; StctD.Initialize();
	m_pAttrCtrl->GetStct(StctD);

	if (iStepNo > 0)
	{
		ASSERT(0);
	}

	// Get Load Case Name(DL,LL,EL,TP,TS,CP,CS,SP,SS,SUM).
	if (SgldD.LoadCaseId == 0 && SgldD.LoadCaseName.IsEmpty())
	{
		//++++++++++++++++++++++++++++++++++++++++++++++++++
		// 반드시 함수를 호출하는 곳에서 Stage를 설정한 후에 사용해야 한다.
		SgldD.Initialize();
		if (!m_pStageInfo->GetSgldPost(SgldK, SgldD))	return FALSE;
		//++++++++++++++++++++++++++++++++++++++++++++++++++
	}

	CString strCSLCType = _T("");
	CString strLCSubType = _T("");
	GetStageLoadDgnType(SgldD.LoadCaseName, StctD, strCSLCType, strLCSubType);
	ForceLcase.strType = StressLcase.strType = strCSLCType;
	ForceLcase.strLCSubType = StressLcase.strLCSubType = strLCSubType;

	return TRUE;
}
BOOL CCRCForceCtrl::Get_Stld_mt(T_LCOM_IN& paramD, T_STLD_K StldK, _DGN_FORC_CRC& ForceLcase, _DGN_STRS_ADD& StressAdd, _DGN_STRS_CRC& StressLcase, _DGN_SHRS_ADD& StssLcase,
	_DGN_FORC_CRC& ForcePart1, _DGN_STRS_CRC& StressPart1,
	_DGN_FORC_CRC& ForcePart2, _DGN_STRS_CRC& StressPart2)
{
	//PROFILING(_T("CCRCForceCtrl::Get_Stld"));

	// Get Member Force by Element.
	int nLcaseType = D_LOADCASE_STATIC;

	//
	_DGN_STRBFORC_LCASE      DgnStrb;
	_DGN_STRBFORC_PART_LCASE DgnStrbPart;

	g_num_mutex1.lock();
	GetStld4Elem(paramD.ElemK, paramD.nForType, nLcaseType, StldK, DgnStrb, DgnStrbPart);
	g_num_mutex1.unlock();

	ForceLcase = DgnStrb.Force;
	StressLcase = DgnStrb.Stress;
	if (paramD.bIsCalcStss == TRUE) StssLcase = DgnStrb.Stss;

	if (paramD.nForType > 0)
	{
		ForcePart1 = DgnStrbPart.ForceP1;
		ForcePart2 = DgnStrbPart.ForceP2;
		StressPart1 = DgnStrb.Stress;
		StressPart2 = DgnStrbPart.StressP2;
	}

	// Set Force Type (D,L,W,...).
	T_STLD_D StldD;
	StldD.Initialize();
	if (!m_pPostCtrl->GetStld(StldK, StldD))	return FALSE;
	ForceLcase.strType = StressLcase.strType = StldD.LoadCaseType;
	ForcePart1.strType = StressPart1.strType = StldD.LoadCaseType;
	ForcePart2.strType = StressPart2.strType = StldD.LoadCaseType;

	return TRUE;
}
BOOL CCRCForceCtrl::Get_Lcom_mt(T_LCOM_IN paramD, T_LCOM_K LcomK, _DGN_FORC_CRC& ForceLcase, _DGN_STRS_ADD& StressAdd, _DGN_STRS_CRC& StressLcase, _DGN_SHRS_ADD& StssLcase,
	_DGN_FORC_CRC& ForcePart1, _DGN_STRS_CRC& StressPart1, _DGN_FORC_CRC& ForcePart2, _DGN_STRS_CRC& StressPart2) // Add by GAY. MNET:2903. ('07.07.31).
{
	//PROFILING(_T("CCRCForceCtrl::Get_Lcom"));

	ForceLcase.Initialize();
	StressAdd.Initialize();
	StressLcase.Initialize();
	StssLcase.Initialize();

	// Get Load Combination Data.
	T_LCOM_D LcomD;
	LcomD.Initialize();
	if (CDBLib::IsCSGCode(m_iDgnCode) == TRUE)
	{
		if (m_iDgnCode == EUROCODE4_2_04_CSG || m_iDgnCode == IRC22_08_CSG || m_iDgnCode == IRC22_15_CSG) m_pAttrCtrl->GetLcom(D_LCOMTYPE_STEEL, LcomK, LcomD);
		else                                  m_pAttrCtrl->GetLcom(D_LCOMTYPE_STLCOMP, LcomK, LcomD);
	}
	else                                    m_pAttrCtrl->GetLcom(D_LCOMTYPE_CONCRETE, LcomK, LcomD);

	int iLcaseType = Get_LcaseCombType();
	int iMaxMinType = paramD.LcomDesign.iDgnLcomType;
	// Get Member Force by Element.
	if (!m_pAttrCtrl->IsConCurrentComb12(LcomD))  // Not consider Concurrent Forces.
	{
		_DGN_STRBFORC_LCASE      DgnStrb;
		_DGN_STRBFORC_PART_LCASE DgnStrbPart;
		g_num_mutex1.lock();
		GetLcom4Elem(paramD.ElemK, paramD.nForType, iLcaseType, LcomK, iMaxMinType, DgnStrb, DgnStrbPart);
		g_num_mutex1.unlock();

		ForceLcase = DgnStrb.Force;
		StressLcase = DgnStrb.Stress;
		if (paramD.bIsCalcStss == TRUE) StssLcase = DgnStrb.Stss;

		if (paramD.nForType > 0)
		{
			ForcePart1 = DgnStrbPart.ForceP1;
			ForcePart2 = DgnStrbPart.ForceP2;
			StressPart1 = DgnStrb.Stress;
			StressPart2 = DgnStrbPart.StressP2;
		}
		ForceLcase.strType = StressLcase.strType = LcomD.LoadCombName;
	}
	else // Consider Concurrent Forces.
	{
		_DGN_SBCFFORC_LCASE      DgnSbcf;
		_DGN_SBCFFORC_PART_LCASE DgnSbcfPart;
		g_num_mutex1.lock();
		GetSbcf4Elem(paramD.ElemK, paramD.nForType, iLcaseType, LcomK, DgnSbcf, DgnSbcfPart);
		g_num_mutex1.unlock();

		int i = iMaxMinType - 1;
		ForceLcase = DgnSbcf.Force[i];
		StressLcase = DgnSbcf.Stress[i];
		if (paramD.bIsCalcStss == TRUE) StssLcase = DgnSbcf.Stss[i];
		// Set Force Type.
		ForceLcase.strType = StressLcase.strType = GetConCurrForceType(i);

		if (paramD.nForType > 0)
		{
			StressPart1 = DgnSbcf.Stress[i];
			StressPart2 = DgnSbcfPart.StressP2[i];
		}
	}

	return TRUE;
}
BOOL CCRCForceCtrl::Get_Force_mt(T_LCOM_FORC& forcD, T_LCOM_OUT& outD)
{
	outD.ForceLcom.Initialize();
	outD.ForceStag.Initialize();
	outD.ShrsStage.Initialize();
	outD.ForceTnpr.Initialize();
	outD.ForceTnsc.Initialize();
	outD.StressAdd.Initialize();
	outD.ForceLTerm.Initialize();
	outD.ForceJtgTndn.Initialize();
	outD.ForceDL_TB05.Initialize();
	outD.ForceLL_TB05.Initialize();
	outD.ForceEQE2_JTG.Initialize();
	outD.ForceLL.Initialize();

	outD.ForceLcom += forcD.ForceDnon;
	outD.ForceLcom += forcD.ForceDrec;
	outD.ForceLcom += forcD.ForceLnon;
	outD.ForceLcom += forcD.ForceLrec;
	outD.ForceLcom += forcD.ForceRemn;
	// Forec by All Sgld.
	outD.ForceStag = forcD.ForceStag;
	outD.ShrsStage = forcD.ShrsStage;
	// Force by Tendon Primary.
	outD.ForceTnpr = forcD.ForceTnpr;
	outD.ForceTnsc = forcD.ForceTnsc;
	// Add by ZINU.('05.01.03). Stress by Beam Section Temperature.
	outD.StressAdd = forcD.StressAdd;
	// Add by Jaeoh. ('05.08.16).
	//ForceSgldDL += m_ForceSgldRemn; // For Required Tendon , Mg1  
	//ForceAddDL  += m_ForceAddDL;  // For Add DL , JTG D6204, 
	//ForceLL     += m_ForceLL;     // For 균열검토, JTG D62-04, LL

	switch (m_iDgnCode)
	{
	case SNiP_20503_84_PSC:
	case SP_35_13330_11_PSC:
	case SNiP_20503_84_PSC_MKS:
	case SP_35_13330_11_PSC_MKS:
	case SNiP_20503_84_SOD:
	case SP_35_13330_11_SOD:
		outD.ForceLTerm += forcD.ForceAddDL;
		break;
	case KSCE_LSD15_CSG:
	case AASHTO_LRFD12_CSG:
	case AASHTO_LRFD07_CSG:
	case KDS_24_14_31_2018_CSG:
	case KSSC_2014_CSG:
	case CSA_S6_10_CSG:
	case CSA_S6_14_CSG:
	case CSA_S6_19_CSG:
	case AASHTO_LRFD16_CSG:
	case AASHTO_LRFD17_CSG:
	case AASHTO_LRFD20_CSG:
	case EUROCODE4_2_04_CSG:
	case CS457_R1_CSG:
	case NR_GN_CIV_025_06_CSG:
	case AS5100_6_17_CSG:
		// Beforce force
		if (m_bIsPLCB == TRUE)
		{
			outD.ForceStag = forcD.ForceAddDL;
			outD.ForceLcom += forcD.ForceAddDL;
		}
		// 2014.03.31 이정우 GJ님 요청
		// After force는 Dead(CS), CP(CS), CS(CS), SP(CS), SS(CS) 으로 수정 
		outD.ForceLTerm += forcD.ForceLTerm;
		break;
	case SNiP_20503_84_CSG:
	case SP_35_13330_11_CSG:
		// Beforce force
		if (m_bIsPLCB == TRUE)
		{
			outD.ForceStag = forcD.ForceAddDL;
		}
		// 2014.03.31 이정우 GJ님 요청
		// After force는 Dead(CS), CP(CS), CS(CS), SP(CS), SS(CS) 으로 수정 
		outD.ForceLTerm += forcD.ForceLTerm;
		outD.ForceLTerm += forcD.ForceRemn;
		break;
	case TB_10002_3_05:
	case RC_TB_10002_3_05:
		outD.ForceDL_TB05 += forcD.ForceDL_TB05;
		outD.ForceLL_TB05 += forcD.ForceLL_TB05;
		outD.ForceCSTP_TB05 += forcD.ForceCS_TP_TB05;
		break;
	case RC_JTG_B02_01_2008:
	case RC_CJJ_166_2011:
		outD.ForceEQE2_JTG += forcD.ForceEQE2_JTG;
		outD.ForceWeight_JTG += forcD.ForceWeight_JTG;
		break;
	default:
		// PSC 기준으로 분리 했던 것을 삭제, 
		// Beforce force
		if (m_bIsPLCB == TRUE)
		{
			outD.ForceStag = forcD.ForceAddDL;
			// PSC Composite 경우 완성계의 Force는 해석과 같아야 하기 때문에..
			// Steel Composite과는 다름.
			outD.ForceLcom += forcD.ForceAddDL;
		}
		outD.ForceLTerm += forcD.ForceSgldRe;
		outD.ForceLTerm += forcD.ForceAddDL;
		//ForceLTerm += m_ForceLL;  
		break;
	}
	outD.ForceLL += forcD.ForceLnon;
	outD.ForceLL += forcD.ForceLrec;
	// Add by Jaeoh. ('06.09.18)
	// 시공단계 Load Case를 
	outD.ForceJtgTndn += forcD.ForceJtgTndn;

	return TRUE;
}

BOOL CCRCForceCtrl::Get_Stress_mt(T_LCOM_FORC& forcD, T_LCOM_OUT& outD)
{
	outD.StressLcom.Initialize();
	//StressStag.Initialize();
	//ShrsStage.Initialize();
	outD.StressTnpr.Initialize();
	outD.StressTnsc.Initialize();
	//StressAdd.Initialize();
	outD.StressLTerm.Initialize();
	outD.StressLL.Initialize();
	outD.StressDL_TB05.Initialize();
	outD.StressLL_TB05.Initialize();

	outD.StressLcom += forcD.StressNorDL;
	outD.StressLcom += forcD.StressNorLL;
	outD.StressLcom += forcD.StressRemn;
	// Force by Tendon Primary.
	outD.StressTnpr = forcD.StressTnpr;
	outD.StressTnsc = forcD.StressTnsc;
	// JTG D62-04.

	switch (m_iDgnCode)
	{
	case SNiP_20503_84_PSC:
	case SP_35_13330_11_PSC:
	case SNiP_20503_84_PSC_MKS:
	case SP_35_13330_11_PSC_MKS:
		outD.StressLTerm += forcD.StressTnpr;
		outD.StressLTerm += forcD.StressTnsc;
		outD.StressLTerm += forcD.StressAddDL;
		break;
	case KSCE_LSD15_CSG:
	case KDS_24_14_31_2018_CSG:
	case AASHTO_LRFD20_CSG:
	case AASHTO_LRFD17_CSG:
	case AASHTO_LRFD16_CSG:
	case AASHTO_LRFD12_CSG:
	case AASHTO_LRFD07_CSG:
	case SNiP_20503_84_CSG:
	case SP_35_13330_11_CSG:
	case CSA_S6_10_CSG:
	case CSA_S6_14_CSG:
	case CSA_S6_19_CSG:
	case EUROCODE4_2_04_CSG:
	case CS457_R1_CSG:
	case NR_GN_CIV_025_06_CSG:
	case AS5100_6_17_CSG:
		outD.StressLTerm += forcD.StressLTerm;
		break;
	case TB_10002_3_05:
	case RC_TB_10002_3_05:
		outD.StressDL_TB05 += forcD.StressDL_TB05;
		outD.StressLL_TB05 += forcD.StressLL_TB05;
		outD.StressCSTP_TB05 += forcD.StressCS_TP_TB05;
		break;
	default:
		outD.StressLTerm += forcD.StressSgldRe;
		outD.StressLTerm += forcD.StressAddDL;
		//StressLTerm += m_StressJtgLL;  
		break;
	}

	outD.StressLL += forcD.StressNorLL;

	// Principle.
	//ssStag += m_StssStage;
	outD.StssLcom += forcD.StressShr;

	return TRUE;
}
BOOL CCRCForceCtrl::Get_Lcom_mt(T_LCOM_IN& paramD, T_LCOM_FORC& forcD, T_LCOM_K LcomK)
{
	int iMaxMinType = paramD.LcomDesign.iDgnLcomType;
	if (iMaxMinType < 0 || iMaxMinType > DGN_FORCE_LCOM_SUB_MAX)	return FALSE;

	_DGN_FORC_CRC ForceLcase;
	_DGN_STRS_ADD StressAdd;
	_DGN_STRS_CRC StressLcase;
	_DGN_SHRS_ADD StssLcase;
	//
	_DGN_FORC_CRC ForcePart1;
	_DGN_STRS_CRC StressPart1;
	_DGN_FORC_CRC ForcePart2;
	_DGN_STRS_CRC StressPart2;

	g_num_mutex1.lock();
	if (!Get_Lcom_mt(paramD, LcomK, ForceLcase, StressAdd, StressLcase, StssLcase,
		ForcePart1, StressPart1, ForcePart2, StressPart2))	return FALSE;
	g_num_mutex1.unlock();

	// Set Forces by DimType.
	Set_DimTypeForc(ForceLcase);
	// Apply Lcase Factor.
	double dFactor = paramD.dFactor;
	ForceLcase *= dFactor;
	// Stress.
	StressLcase *= dFactor;
	// Add by ZINU.('05.01.03). Consider Stress.
	StressAdd *= dFactor;
	forcD.StressAdd += StressAdd;
	// Principle.
	StssLcase *= dFactor;
	forcD.StressShr += StssLcase;

	// Force and Stress.
	forcD.ForceRemn += ForceLcase;
	// Stress.
	forcD.StressRemn += StressLcase;

	//remove by maxiao   m_ForceEQE2_JTG is PermanentLoad_JTG_B02， why have this code？
	//	if(m_iDgnCode == RC_JTG_B02_01_2008)
	//	{ m_ForceEQE2_JTG += ForceLcase; }

	if (paramD.nForType > 0)
	{
		ForcePart1 *= dFactor;
		StressPart1 *= dFactor;
		ForcePart2 *= dFactor;
		StressPart2 *= dFactor;

		forcD.ForceRemnP1 += ForcePart1;
		forcD.StressRemnP1 += StressPart1;
		forcD.ForceRemnP2 += ForcePart2;
		forcD.StressRemnP2 += StressPart2;
	}
	return TRUE;
}

BOOL CCRCForceCtrl::Get_Sgld_mt(T_LCOM_IN& paramD, T_LCOM_FORC& forcD, int iStepNo)
{
	//PROFILING(_T("CCRCForceCtrl::Get_Sgld"));

	_DGN_FORC_CRC ForceLcase;
	_DGN_STRS_CRC StressLcase;
	_DGN_SHRS_ADD StssLcase;
	//
	_DGN_FORC_CRC ForcePart1;
	_DGN_STRS_CRC StressPart1;
	_DGN_FORC_CRC ForcePart2;
	_DGN_STRS_CRC StressPart2;

	T_SGLD_K SgldK = paramD.iLcaseK;
	T_SGLD_D SgldD; SgldD.Initialize();
	if (!Get_Sgld_mt(paramD, SgldK, SgldD, iStepNo,
		ForceLcase, StressLcase, StssLcase, ForcePart1, StressPart1, ForcePart2, StressPart2))
		return FALSE;

	// Set Forces by DimType.
	Set_DimTypeForc(ForceLcase);
	// Apply Lcase Factor.	
	double dFactor = paramD.dFactor;
	ForceLcase *= dFactor;
	StressLcase *= dFactor;

	_DGN_SCFP_PART_LCASE ScfpPartLcase;
	T_SGLD_K SgldScfpK = 0;
	BOOL bIsScfp = m_arSgldScfpK.Lookup(SgldK, SgldScfpK);
	if (bIsScfp == TRUE)
	{
		g_num_mutex1.lock();
		Get_SgldScfp(paramD.ElemK, SgldK, ScfpPartLcase);
		g_num_mutex1.unlock();

		ScfpPartLcase.ForceP1 *= dFactor;
		ScfpPartLcase.ForceP2 *= dFactor;

		if (ForceLcase.strType == _T("EL"))
		{
			// m_arSgldScfpK 에서 Erection은 온도만 추가 하고 있음
			// 연관함수 BOOL IsErectionScfp(int nType, T_STCT_D &StctD); 참고
			forcD.StressScfpTe.ForceP1 += ScfpPartLcase.ForceP1;
			forcD.StressScfpTe.ForceP2 += ScfpPartLcase.ForceP2;
		}
		else if (ForceLcase.strType == _T("CS"))
		{
			forcD.StressScfpCr.ForceP1 += ScfpPartLcase.ForceP1;
			forcD.StressScfpCr.ForceP2 += ScfpPartLcase.ForceP2;
			// Creep secondary만 적용한다. [5/26/2015 joahn] 이대근 이사보님, 박창신 사원님 요청
			forcD.ForceScfpCrp += ForceLcase;
			forcD.ForceScfpSum += ForceLcase;
		}
		else if (ForceLcase.strType == _T("SS"))
		{
			forcD.StressScfpSh.ForceP1 += ScfpPartLcase.ForceP1;
			forcD.StressScfpSh.ForceP2 += ScfpPartLcase.ForceP2;
			forcD.ForceScfpShr += ForceLcase;
			forcD.ForceScfpSum += ForceLcase;
		}
		else
		{
			forcD.StressScfpRe.ForceP1 += ScfpPartLcase.ForceP1;
			forcD.StressScfpRe.ForceP2 += ScfpPartLcase.ForceP2;
		}
	}

	// Principle.
	StssLcase *= dFactor;
	forcD.StressShr += StssLcase;

	if (paramD.nForType > 0)
	{
		ForcePart1 *= dFactor;
		StressPart1 *= dFactor;
		ForcePart2 *= dFactor;
		StressPart2 *= dFactor;

		forcD.ForceRemnP1 += ForcePart1;
		forcD.StressRemnP1 += StressPart1;
		forcD.ForceRemnP2 += ForcePart2;
		forcD.StressRemnP2 += StressPart2;
	}

	// Add by ZINU.('05.07.04). Get Force by All Sgld.
	forcD.ForceStag += ForceLcase;
	if (ForceLcase.strType == _T("DL"))	// Dead.
	{
		if (paramD.bReciLcase)	forcD.ForceDrec += ForceLcase;
		else			forcD.ForceDnon += ForceLcase;
		forcD.ForceAddDL += ForceLcase;
		forcD.ForceLTerm += ForceLcase;
		// Stress.
		forcD.StressNorDL += StressLcase;
		forcD.StressAddDL += StressLcase;
		forcD.StressLTerm += StressLcase;
		forcD.StressLTermP2 += StressPart2;
	}
	else if (ForceLcase.strType == _T("LL"))	// Live.
	{
		if (paramD.bReciLcase)	forcD.ForceLrec += ForceLcase;
		else			forcD.ForceLnon += ForceLcase;
		// Stress.
		forcD.StressNorLL += StressLcase;
	}
	else if (ForceLcase.strType == _T("EL"))	// Erection.
	{
		if (CDBLib::IsStldDL(ForceLcase.strLCSubType))
		{
			(paramD.bReciLcase ? forcD.ForceDrec : forcD.ForceDnon) += ForceLcase;
			forcD.ForceAddDL += ForceLcase;
			forcD.ForceLTerm += ForceLcase;
			// Stress.
			forcD.StressNorDL += StressLcase;
			forcD.StressAddDL += StressLcase;
			forcD.StressLTerm += StressLcase;
			forcD.StressLTermP2 += StressPart2;
		}
		else if (CDBLib::IsStldLL(ForceLcase.strLCSubType))
		{
			(paramD.bReciLcase ? m_ForceLrec : forcD.ForceLnon) += ForceLcase;
			forcD.ForceLL += ForceLcase;
			// Stress.
			forcD.StressNorLL += StressLcase;
			forcD.StressJtgLL += StressLcase;
		}
		else
		{
			forcD.ForceRemn += ForceLcase;
			// Stress.
			forcD.StressRemn += StressLcase;
		}
	}
	else if (ForceLcase.strType == _T("TP"))	// Tendon Primary.
	{
		if (paramD.bIncludeTP)
		{
			forcD.ForceRemn += ForceLcase;
			forcD.ForceSgldRe += ForceLcase;
			// Stress.
			forcD.StressRemn += StressLcase;
			forcD.StressSgldRe += StressLcase;
			// Remove by ZINU.('06.06.12). Remove it because of adding two times.
			//m_StressTnpr += StressLcase;
		}
		forcD.ForceTnpr += ForceLcase;
		// Stress.
		forcD.StressTnpr += StressLcase;
		if (paramD.nForType > 0) forcD.StressTnpr2 += StressPart2;
	}
	else if (ForceLcase.strType == _T("TS"))	// Tendon Secondary.
	{
		forcD.ForceRemn += ForceLcase;
		forcD.ForceSgldRe += ForceLcase;
		// Stress.
		forcD.StressRemn += StressLcase;
		forcD.StressSgldRe += StressLcase;
		// Remove by ZINU.('06.06.12). Remove it because of adding two times.
		//m_StressTnsc += StressLcase;
		forcD.ForceTnsc += ForceLcase;
		// Stress.
		forcD.StressTnsc += StressLcase;
		if (paramD.nForType > 0) forcD.StressTnsc2 += StressPart2;
	}
	else
	{
		// Force.
		forcD.ForceRemn += ForceLcase;
		forcD.ForceSgldRe += ForceLcase;
		// Stress.
		forcD.StressRemn += StressLcase;
		forcD.StressSgldRe += StressLcase;

		if (ForceLcase.strType == _T("CP") || ForceLcase.strType == _T("CS") ||
			ForceLcase.strType == _T("SP") || ForceLcase.strType == _T("SS"))
		{
			forcD.ForceLTerm += ForceLcase;
			forcD.StressLTerm += StressLcase;
			forcD.StressLTermP2 += StressPart2;
		}
	}

	// Add, Jaeoh. [11/7/2008], 시공단계 Load Case를 위해.(TB05), 시공단계도 m_ForceDL_TB05 에 더하는 것으로 함(Maxiao 요구)
	// For TB 10002.3-2005, Force, Stress
	// DL
	if (m_iDgnCode == TB_10002_3_05 || m_iDgnCode == RC_TB_10002_3_05)
	{
		if (Is_TB05SgldDL(ForceLcase.strType))
		{
			forcD.ForceDL_TB05 += ForceLcase;
			forcD.StressDL_TB05 += StressLcase;
		}
		// Add, Jaeoh. [12/23/2008], CS(SUM)안에 있는 TP를 넘기기 위해 (Maxiao 요구) 
		if (ForceLcase.strType == _T("SUM"))
		{
			ForceLcase.Initialize();
			StressLcase.Initialize();
			CString str;
			str.Format(_T("%s"), _LS(IDS_DB_SGLD_TP));
			T_SGLD_K SgldTempK = m_pAttrCtrl->GetSgldKey(str);
			T_STEP_K StepK = 0;
			T_LCOM_D LcasD;
			T_STRB_D StrbMax; StrbMax.Initialize();
			g_num_mutex1.lock();
			m_pPostCtrl->MakeLoadComb(D_LOADCASE_STAGE, SgldTempK, LcasD);
			m_pPostCtrl->SelectLoadCombNew(LcasD, StepK, 2);	// 0=Nonlinear, 1=Pushover, 2=Construction.	  
			m_pPostCtrl->GetStrbNew(paramD.ElemK.first, &StrbMax, 0, NULL, FALSE, NULL, paramD.ElemK.second);
			g_num_mutex1.unlock();
			ForceLcase.strType = StressLcase.strType = _T("TP");

			// Set Forces.
			for (int j = 0; j < cPOSI_CRC; ++j)
			{
				int iPart = (j == 0 ? 0 : 3);
				int iKind = (j == 0 ? 0 : 6);
				ForceLcase.dFxx[j] = StrbMax.dblForce[iPart][iKind + 0];
				ForceLcase.dFyy[j] = StrbMax.dblForce[iPart][iKind + 1];
				ForceLcase.dFzz[j] = StrbMax.dblForce[iPart][iKind + 2];
				ForceLcase.dMux[j] = StrbMax.dblForce[iPart][iKind + 3];
				ForceLcase.dMuy[j] = StrbMax.dblForce[iPart][iKind + 4];
				ForceLcase.dMuz[j] = StrbMax.dblForce[iPart][iKind + 5];
				ForceLcase.dMbi[j] = StrbMax.dblForce[iPart][Mbi_Id + j]; // Bi-moment
				ForceLcase.dTst[j] = StrbMax.dblForce[iPart][Mst_Id + j]; // Pure torsion
				ForceLcase.dTwp[j] = StrbMax.dblForce[iPart][Mwp_Id + j]; // Warping torsion
			}

			// Normal Stress
			Get_LoadCaseStress(paramD.ElemK, StrbMax, StressLcase);

			/*
			ForceLcase.Initialize();
			StressLcase.Initialize();
			StssLcase.Initialize();
			if(!Get_Sgld(ElemK, SgldTempK, iStepNo, ForceLcase, StressLcase, StssLcase))	return FALSE;
			*/
			// Set Forces by DimType.
			Set_DimTypeForc(ForceLcase);
			// Apply Lcase Factor.
			ForceLcase *= dFactor;
			StressLcase *= dFactor;
			forcD.ForceCS_TP_TB05 += ForceLcase;
			forcD.StressCS_TP_TB05 += StressLcase;
		}
	}
	if (m_iDgnCode == RC_JTG_B02_01_2008 || m_iDgnCode == RC_CJJ_166_2011)
	{
		//			if(dFactor!=0.0)
		//				m_ForceEQE2_JTG += ForceLcase/dFactor;
		if (IsPermanentLoad_JTG_B02(ForceLcase.strType))
		{
			forcD.ForceEQE2_JTG += ForceLcase;
		}
		if (IsSelfWeightLoad_JTG_B02(ForceLcase.strType))
		{
			forcD.ForceWeight_JTG += ForceLcase;
		}
	}
	return TRUE;
}

BOOL CCRCForceCtrl::Get_LcomDataForDesign_Org(ElemPairK ElemK, int nForType, int iDgnLcomKind, BOOL bIncludeTP, BOOL bAlways3D,
	ADGNFORCE& aForceLcom,
	ADGNFORCE& aForceStag,
	ADGNSHRSADD& aShrsStage,
	ADGNFORCE& aForceTnpr,
	ADGNFORCE& aForceTnsc,
	ADGNSTRSADD& aStressAdd,
	ADGNFORCE& aForceLTerm,
	ADGNFORCE& aForceJtgTndn,
	// Stres
	ADGNSTRESS& aStressLcom,
	ADGNSTRESS& aStressTnpr,
	ADGNSTRESS& aStressTnsc,
	ADGNSTRESS& aStressLTerm,
	// Principle
	ADGNSHRSADD& aStssLcom, BOOL bBinary)
{
	aForceLcom.RemoveAll();
	aForceStag.RemoveAll();
	aShrsStage.RemoveAll();
	aForceTnpr.RemoveAll();
	aForceTnsc.RemoveAll();
	aStressAdd.RemoveAll();
	aForceLTerm.RemoveAll();
	aForceJtgTndn.RemoveAll();
	// Stress.
	aStressLcom.RemoveAll();
	// aStressStag.RemoveAll();  
	aStressTnpr.RemoveAll();
	aStressTnsc.RemoveAll();
	aStressLTerm.RemoveAll();
	// Principle.
	aStssLcom.RemoveAll();

	/*
	//++++++++++++++++++++++++++++++++++++++++++++
	// <Remember> Get Data by Code Units.
	T_UNIT_INDEX CurIndex, CngIndex;
	pDoc->m_pUnitCtrl->GetUnitIndexCurrent(CurIndex);
	CngIndex.nBase_Length = m_CodeUnit.nBase_Length;
	CngIndex.nBase_Force  = m_CodeUnit.nBase_Force;
	pDoc->m_pUnitCtrl->SetUnitIndexCurrent(CngIndex);
	//++++++++++++++++++++++++++++++++++++++++++++
	*/

	m_StrsPost.Initialize();
	m_pSectInfo->Get_StrsPscd(FALSE, ElemK.first, m_StrsPost);

	// Reset DimType.
	if (bAlways3D)	m_iDimType = 2;	// Set 3D.
	// Consider No Effect Zone.
	Set_RatNoEffectZone(ElemK);

	T_ELEM_D ElemD; ElemD.Initialize();
	T_SECT_K SectK = 0;
	T_SECT_K OrgSectK = 0;
	// Get Sect Data.
	T_SECT_D SectD; SectD.Initialize();
	// Get Rbar Data.
	T_RPSC_D RpscMbar, RpscSbar;
	if (ElemK.second == EN_EL_BEAM)
	{
		if (!m_pPostCtrl->GetElemPost(ElemK.first, ElemD))	return FALSE;
		SectK = ElemD.elpro;
		if (!m_pPostCtrl->GetSectPost(SectK, SectD))	return FALSE;
		OrgSectK = m_pPostCtrl->GetOrgSectKeyPost(SectK);

		RpscMbar.Initialize();
		m_pAttrCtrl->GetRpscByConsiderRbar(TRUE, OrgSectK, RpscMbar);
		RpscSbar.Initialize();
		m_pAttrCtrl->GetRpscByConsiderRbar(FALSE, OrgSectK, RpscSbar);
	}
	else if (ElemK.second == EN_EL_VBEAM)
	{
		T_VBEM_D VbemD; VbemD.Initialize();
		if (m_pDoc->m_pAttrCtrl2->GetVbem(ElemK.first, VbemD))
		{
			T_SECV_D SecvD; SecvD.Initialize();
			m_pDoc->m_pAttrCtrl2->GetSecv(ElemK.first, SecvD); // T_SECV_K = T_VBEM_K
			SecvD.ConvertToSect(SectD);
		}
		T_RPSV_SSM_D RpsvSsmD; RpsvSsmD.Initialize();
		m_pAttrCtrl2->GetRpsvSsm(ElemK.first, RpsvSsmD);

		T_RPSC_SSM_D RpscSsmD;
		RpsvSsmD.ConvertToRpscSSM(RpscSsmD);

		m_pAttrCtrl2->ConvertRpscSSMtoRpsc(SectD, RpscSsmD, RpscMbar);
		RpscSbar = RpscMbar;
	}
	else ASSERT(0);		


	BOOL bIs7Dof = SectD.SectBefore.bConsiderWarpingEffect;

	T_STRSPROP_D StrsPropD;
	if (bIs7Dof)
	{
		m_pSectInfo->ReadSectPostProp(ElemK.first, StrsPropD);
	}

	int iLcomNum = m_arLcomData.GetCount();
	if (iLcomNum == 0)	return FALSE;
	int nEnvelopType = -1;//add by gongxing at 2016-05-10

	for (int i = 0; i < iLcomNum; ++i)
	{
		// Initialize Forces.
		Set_ForceIni();

		_DGN_LCOM LcomDesign;
		LcomDesign.Initialize();
		if (!m_arLcomData.Lookup(i + 1, LcomDesign))	continue;
		// Check LcomKind.
		if (iDgnLcomKind > 0 && iDgnLcomKind != LcomDesign.bLongTerm)	continue;

		//BOOL bIsCalcStss = (LcomDesign.nActive==2); // Service 경우만 Stss 계산하기 위해.
		BOOL bIsCalcStss = (LcomDesign.nActive == 2 || LcomDesign.nActive == 7 || LcomDesign.nActive == 8); // modify by juhonghua 20151222.

		// Check Existing Reciprocal Stress.
		T_LCRS_D LcrsD;
		LcrsD.Initialize();
		BOOL bReciInput = m_pAttrCtrl->GetLcrs(LcrsD);

		if (LcomDesign.LcomUlData.LoadCombType == 1)
		{
			//뎠뵐潼莉북槨관쭹珂 add by gongxing at 2016-05-10
			nEnvelopType++;
			int nCompareType = nEnvelopType % cFORC_CON;//덜깊궐싹18莉코제珂뚤壇돨莉냥
			Get_EnvelopLcom(ElemK, nForType, bIsCalcStss, bReciInput, bIncludeTP, LcomDesign, nCompareType);
		}
		else
		{
			int iLcaseNum = LcomDesign.LcomUlData.Combination.GetSize();
			for (int j = 0; j < iLcaseNum; ++j)
			{
				const T_LCOM_BASE &LcomB = LcomDesign.LcomUlData.Combination[j];

				unsigned int iAnalType = LcomB.AnalType;
				unsigned int iLcaseKey = LcomB.LoadCaseKey;
				double dFactor = LcomB.Factor;
				int iMaxMinType = LcomDesign.iDgnLcomType;
				// Lcase for Reciprocal Stress.
				BOOL bReciLcase = (bReciInput ? Is_Reciprocal(iAnalType, iLcaseKey) : FALSE);
				// LcomUlData.Combination[i].AnalType is...
				// D_LCOM_STATIC       1
				// D_LCOM_SPECTRUM     2
				// D_LCOM_ECCENSPEC		14
				// D_LCOM_HISTORY      3 
				// D_LCOM_STAGE       13
				// D_LCOM_MOVING       4 (Load Combination - Max, Min)
				// D_LCOM_SETTLEMENT   5 (Load Combination - Max, Min)
				// D_LCOM_GRIDMODEL   15 (Load Combination - Max, Min)
				///*** Add by juhonghua 2012.03.10
				dFactor = AdjustCJJLoadCaseFactor(iAnalType, LcomDesign, dFactor, m_Chrp, m_Pscd);

				_DGN_FORC_CRC ForceLcase;
				if (iAnalType == D_LCOM_STATIC)					Get_Stld(ElemK, iLcaseKey, nForType, bIsCalcStss, dFactor, bReciLcase);
				else if (iAnalType == D_LCOM_SPECTRUM)		Get_Splc(ElemK, iLcaseKey, nForType, bIsCalcStss, dFactor);
				else if (iAnalType == D_LCOM_ECCENSPEC)	Get_Espc(ElemK, iLcaseKey, nForType, bIsCalcStss, dFactor);
				else if (iAnalType == D_LCOM_HISTORY)		Get_This(ElemK, iLcaseKey, nForType, bIsCalcStss, dFactor);
				else if (iAnalType == D_LCOM_STAGE)			Get_Sgld(ElemK, iLcaseKey, nForType, bIsCalcStss, dFactor, bReciLcase, bIncludeTP, 0);	// If iStepNo=0, Final Stage.
				else if (iAnalType == D_LCOM_MOVING)			Get_Mvld(ElemK, iLcaseKey, nForType, bIsCalcStss, dFactor, bReciLcase, iMaxMinType);
				else if (iAnalType == D_LCOM_SETTLEMENT)	Get_Smlc(ElemK, iLcaseKey, nForType, bIsCalcStss, dFactor, iMaxMinType);
				else if (iAnalType == D_LCOM_GRIDMODEL)	Get_Gilc(ElemK, iLcaseKey, nForType, bIsCalcStss, dFactor, bReciLcase, iMaxMinType);
				else if ((m_iDgnCode == RC_JTG_B02_01_2008 || m_iDgnCode == RC_CJJ_166_2011) && iAnalType == D_LCOM_CB_CONCRETE) // Add by SHIN(09.12.21)
				{
					T_LCOM_D LcomD;
					if (m_pAttrCtrl->GetLcom(D_LCOMTYPE_CONCRETE, iLcaseKey, LcomD))
					{
						if (LcomD.LoadCombType == 3)
						{
							Get_Lcom(ElemK, iLcaseKey, nForType, bIsCalcStss, dFactor, iMaxMinType);
						}
					}
				}
				else if ((CDBLib::IsCSGCode(m_iDgnCode) == TRUE && (iAnalType == D_LCOM_CB_STEEL || iAnalType == D_LCOM_CB_STLCOMP)) || (CDBLib::IsCSGCode(m_iDgnCode) == FALSE && iAnalType == D_LCOM_CB_CONCRETE))
				{
					Get_Lcom(ElemK, iLcaseKey, nForType, bIsCalcStss, dFactor, iMaxMinType);  // Add by GAY. MNET:2903. ('07.07.31).
				}
				else if ((m_iDgnCode == SNiP_20503_84_SOD || m_iDgnCode == SP_35_13330_11_SOD) && iAnalType == D_LCOM_CB_STEEL)
				{
					Get_Lcom(ElemK, iLcaseKey, nForType, bIsCalcStss, dFactor, iMaxMinType);
				}
				else	ASSERT(0);
			}
		}
		_DGN_FORC_CRC ForceLcom;
		_DGN_FORC_CRC ForceLcomExTp;
		_DGN_FORC_CRC ForceStag;
		_DGN_SHRS_ADD ShrsStage;
		_DGN_FORC_CRC ForceTnpr;
		_DGN_FORC_CRC ForceTnsc;
		_DGN_STRS_ADD StressAdd;
		_DGN_FORC_CRC ForceLTerm;
		_DGN_FORC_CRC ForceLL;
		_DGN_FORC_CRC ForceJtgTndn;
		//
		_DGN_FORC_CRC ForceDL_TB05;
		_DGN_FORC_CRC ForceLL_TB05;
		_DGN_FORC_CRC ForceCSTP_TB05;

		_DGN_FORC_CRC ForceEQE2_JTG;
		_DGN_FORC_CRC ForceWeight_JTG;

		if (!Get_Force(ForceLcom, ForceStag, ShrsStage, ForceTnpr, ForceTnsc, StressAdd, ForceLTerm, ForceLL, ForceJtgTndn, ForceDL_TB05, ForceLL_TB05, ForceCSTP_TB05, ForceEQE2_JTG, ForceWeight_JTG))	ASSERT(0);
		ForceLcom.strType = LcomDesign.DesignLcomNa;	// For Design LcomNa (cLCB-DA+1,...).
		if (!bBinary)
		{
			aForceLcom.Add(ForceLcom);
			aForceStag.Add(ForceStag);
			aShrsStage.Add(ShrsStage);
			aForceTnpr.Add(ForceTnpr);
			aForceTnsc.Add(ForceTnsc);
			aStressAdd.Add(StressAdd);
			aForceLTerm.Add(ForceLTerm);
			aForceJtgTndn.Add(ForceJtgTndn);
		}
		else
		{
			ForceLcomExTp += ForceLcom;
			ForceLcomExTp -= ForceTnpr;
		}
		// Add by ZINU.('04.12.01). See JTG D62-04 6.4.3 For C2(Variable).
		// Assumed by ZINU. C2=1.5, Ms(+/-)Mp2=Muy.
		//*/ZINU.		Set_CrackJtg(ElemK, i+1, ForceLcom);

		// Stress.
		_DGN_STRS_CRC StressLcom;
		_DGN_STRS_CRC StressStag;
		_DGN_STRS_CRC StressTnpr;
		_DGN_STRS_CRC StressTnsc;
		_DGN_STRS_CRC StressLTerm;
		_DGN_STRS_CRC StressLL;
		_DGN_SHRS_ADD StssLcom;
		//
		_DGN_STRS_CRC StressDL_TB05;
		_DGN_STRS_CRC StressLL_TB05;
		_DGN_STRS_CRC StressCSTP_TB05;
		if (!Get_Stress(StressLcom, StressTnpr, StressTnsc, StressLTerm, StressLL, StssLcom, StressDL_TB05, StressLL_TB05, StressCSTP_TB05)) ASSERT(0);
		//
		int iSerialLcom = i + 1;
		Get_PrincipalStressByLcom(ElemK, SectD, RpscMbar, RpscSbar, StrsPropD, iSerialLcom, FALSE, ForceLcom, StssLcom);

		StressLcom.iRefNo[0] = StressLcom.iRefNo[1] = LcomDesign.OriginalLcomKey;
		StressStag.iRefNo[0] = StressStag.iRefNo[1] = LcomDesign.OriginalLcomKey;
		StressTnpr.iRefNo[0] = StressTnpr.iRefNo[1] = LcomDesign.OriginalLcomKey;
		StressTnsc.iRefNo[0] = StressTnsc.iRefNo[1] = LcomDesign.OriginalLcomKey;
		StressLTerm.iRefNo[0] = StressLTerm.iRefNo[1] = LcomDesign.OriginalLcomKey;
		StressDL_TB05.iRefNo[0] = StressDL_TB05.iRefNo[1] = LcomDesign.OriginalLcomKey;
		StressLL_TB05.iRefNo[0] = StressLL_TB05.iRefNo[1] = LcomDesign.OriginalLcomKey;
		StressCSTP_TB05.iRefNo[0] = StressCSTP_TB05.iRefNo[1] = LcomDesign.OriginalLcomKey;

		StressLcom.strType = LcomDesign.DesignLcomNa;
		if (!bBinary)
		{
			aStressLcom.Add(StressLcom);
			//aStressStag.Add(StressStag);  
			aStressTnpr.Add(StressTnpr);
			aStressTnsc.Add(StressTnsc);
			aStressLTerm.Add(StressLTerm);
			// Principle.
			aStssLcom.Add(StssLcom);
		}

		if (bBinary)
		{
			//////////////////////////////////////////////////////////////////////////
			// Write Force & Stress
			int iSerialLcom = i + 1;
			WriteForceLcom(ElemK, iSerialLcom, ForceLcom);
			WriteForceLcomExTp(ElemK, iSerialLcom, ForceLcomExTp);
			WriteForceStage(ElemK, iSerialLcom, ForceStag);
			WriteaShrsStage(ElemK, iSerialLcom, ShrsStage);
			WriteForceTnpr(ElemK, iSerialLcom, ForceTnpr);
			WriteForceTnsc(ElemK, iSerialLcom, ForceTnsc);
			WriteStressAdd(ElemK, iSerialLcom, StressAdd);
			WriteForceLTerm(ElemK, iSerialLcom, ForceLTerm);
			WriteForceSTerm(ElemK, iSerialLcom, ForceLL);
			WriteForceJtgTndn(ElemK, iSerialLcom, ForceJtgTndn);
			WriteStressLcom(ElemK, iSerialLcom, StressLcom);
			WriteStressTnpr(ElemK, iSerialLcom, StressTnpr);
			WriteStressTnsc(ElemK, iSerialLcom, StressTnsc);
			WriteStressLTerm(ElemK, iSerialLcom, StressLTerm);
			WriteStressSTerm(ElemK, iSerialLcom, StressLL);
			WriteStssLcom(ElemK, iSerialLcom, StssLcom);

			// SCFP
			if (m_iDgnCode == SNiP_20503_84_CSG || m_iDgnCode == SP_35_13330_11_CSG ||
				m_iDgnCode == EUROCODE4_2_04_CSG)
			{
				_DGN_SCFP_PART_LCASE StrScfpCr;
				_DGN_SCFP_PART_LCASE StrScfpSh;
				_DGN_SCFP_PART_LCASE StrScfpTe;
				_DGN_SCFP_PART_LCASE StrScfpRe;

				Get_StressScfpPart(StrScfpCr, StrScfpSh, StrScfpTe, StrScfpRe);
				WriteStressScfpCrPartLcom(ElemK, iSerialLcom, StrScfpCr);
				WriteStressScfpShPartLcom(ElemK, iSerialLcom, StrScfpSh);
				WriteStressScfpTePartLcom(ElemK, iSerialLcom, StrScfpTe);
				WriteStressScfpRePartLcom(ElemK, iSerialLcom, StrScfpRe);
				WriteForceScfpSum(ElemK, iSerialLcom, m_ForceScfpSum);
				WriteForceScfpCrp(ElemK, iSerialLcom, m_ForceScfpCrp);
				WriteForceScfpShr(ElemK, iSerialLcom, m_ForceScfpShr);
			}

			if (nForType == 1 || nForType == 2)
			{
				_DGN_FORC_CRC ForceLcomPart;
				Get_ForcePart1(ForceLcomPart);

				_DGN_STRS_CRC StressLcomPart;
				Get_StressPart1(StressLcomPart);

				WriteForceLcom_Part1(ElemK, iSerialLcom, ForceLcomPart);
				WriteStressLcom_Part1(ElemK, iSerialLcom, StressLcomPart);

				ForceLcomPart.Initialize();
				Get_ForcePart2(ForceLcomPart);

				StressLcomPart.Initialize();
				Get_StressPart2(StressLcomPart);
				WriteForceLcom_Part2(ElemK, iSerialLcom, ForceLcomPart);
				WriteStressLcom_Part2(ElemK, iSerialLcom, StressLcomPart);

				StressLcomPart.Initialize();
				Get_StressLTermPart2(StressLcomPart);
				WriteStressLTermPart2(ElemK, iSerialLcom, StressLcomPart);

				StressLcomPart.Initialize();
				Get_StressSTermPart2(StressLcomPart);
				WriteStressSTermPart2(ElemK, iSerialLcom, StressLcomPart);

				_DGN_STRS_CRC StrTnprPa2;
				_DGN_STRS_CRC StrTnscPa2;
				Get_StressTendonPart2(StrTnprPa2, StrTnscPa2);
				WriteStressTnpr_Part2(ElemK, iSerialLcom, StrTnprPa2);
				WriteStressTnsc_Part2(ElemK, iSerialLcom, StrTnscPa2);
			}

			//
			if (m_iDgnCode == TB_10002_3_05 || m_iDgnCode == RC_TB_10002_3_05)
			{
				WriteForceDL_TB05(ElemK, iSerialLcom, ForceDL_TB05);
				WriteForceLL_TB05(ElemK, iSerialLcom, ForceLL_TB05);
				WriteStressDL_TB05(ElemK, iSerialLcom, StressDL_TB05);
				WriteStressLL_TB05(ElemK, iSerialLcom, StressLL_TB05);
				WriteForceCSTP_TB05(ElemK, iSerialLcom, ForceCSTP_TB05);
				WriteStressCSTP_TB05(ElemK, iSerialLcom, StressCSTP_TB05);
			}
			else if (m_iDgnCode == RC_JTG_B02_01_2008 || m_iDgnCode == RC_CJJ_166_2011)
			{
				WriteForceEQE2_JTG(ElemK, iSerialLcom, ForceEQE2_JTG);
			}
			/////////////////////////////////////////////////////////////////////////////////
		}
	}
	/*
	//++++++++++++++++++++++++++++++++++++++++++++
	// <Remember> Set Data by Current Units.
	m_pUnitCtrl->SetUnitIndexCurrent(CurIndex);
	//++++++++++++++++++++++++++++++++++++++++++++
	*/
	return TRUE;
}
BOOL CCRCForceCtrl::Get_Mvld_mt(T_LCOM_IN& paramD, T_LCOM_FORC& forcD, BOOL bSpc)
{
	//PROFILING(_T("CCRCForceCtrl::Get_Mvld"));
	int nMaxMinType = paramD.LcomDesign.iDgnLcomType;
	// iMaxMinType (1=FX-MAX, 2=FX-MIN, 3=FY-MAX,..., 11=MZ-MAX, 12=MZ-MIN).
	if (nMaxMinType < 0 || nMaxMinType > cFORC_CON)	return FALSE;

	_DGN_FORC_CRC ForceLcase;
	_DGN_STRS_CRC StressLcase;
	_DGN_SHRS_ADD StssLcase;
	//
	_DGN_FORC_CRC ForcePart1;
	_DGN_STRS_CRC StressPart1;
	_DGN_FORC_CRC ForcePart2;
	_DGN_STRS_CRC StressPart2;

	T_MVLD_K MvldK = paramD.iLcaseK;
	CString strLcaseNa = _T("MV");
	if (!Get_Sbcf_mt(paramD, MvldK, D_LOADCASE_MOVING, ForceLcase, StressLcase, StssLcase, ForcePart1, StressPart1, ForcePart2, StressPart2, bSpc))
		return FALSE;	 // Civil v891 US - BS Assessment - CS454 Special Moving Load Case (CIVIL-1069)

	Set_DimTypeForc(ForceLcase);
	// Apply Lcase Factor.
	double dFactor = paramD.dFactor;
	ForceLcase *= dFactor;
	StressLcase *= dFactor;
	StssLcase *= dFactor;
	// Live.
	if (paramD.bReciLcase)	forcD.ForceLrec += ForceLcase;
	else			forcD.ForceLnon += ForceLcase;

	forcD.ForceLL += ForceLcase;

	// Stress.
	forcD.StressNorLL += StressLcase;
	// JTG
	forcD.StressJtgLL += StressLcase;
	// Principle.
	forcD.StressShr += StssLcase;

	// For JTG, Tendon Stress.
	forcD.ForceJtgTndn += ForceLcase;

	// For TB 10002.3-2005, LL
	if (m_iDgnCode == TB_10002_3_05 || m_iDgnCode == RC_TB_10002_3_05)
	{
		forcD.ForceLL_TB05 += ForceLcase;
		forcD.StressLL_TB05 += StressLcase;
	}

	if (paramD.nForType > 0)
	{
		ForcePart1 *= dFactor;
		StressPart1 *= dFactor;
		ForcePart2 *= dFactor;
		StressPart2 *= dFactor;

		forcD.ForceRemnP1 += ForcePart1;
		forcD.StressRemnP1 += StressPart1;
		forcD.ForceRemnP2 += ForcePart2;
		forcD.StressRemnP2 += StressPart2;
		forcD.StressSTermP2 += StressPart2;
	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_Sbcf_mt(T_LCOM_IN& paramD, unsigned int iLcaseKey, int iLcaseType, _DGN_FORC_CRC& ForceLcase, _DGN_STRS_CRC& StressLcase, _DGN_SHRS_ADD& StssLcase,
	_DGN_FORC_CRC& ForcePart1, _DGN_STRS_CRC& StressPart1, _DGN_FORC_CRC& ForcePart2, _DGN_STRS_CRC& StressPart2, BOOL bSpc)
{
	ForceLcase.Initialize();
	StressLcase.Initialize();
	StssLcase.Initialize();

	if (!(iLcaseType == D_LOADCASE_MOVING || iLcaseType == D_LOADCASE_SETTLE))	return FALSE;

	_DGN_SBCFFORC_LCASE      DgnSbcf;
	_DGN_SBCFFORC_PART_LCASE DgnSbcfPart;

	g_num_mutex1.lock();
	GetSbcf4Elem(paramD.ElemK, paramD.nForType, iLcaseType, iLcaseKey, DgnSbcf, DgnSbcfPart, bSpc);  // Civil v891 US - BS Assessment - CS454 Special Moving Load Case (CIVIL-1069) 
	g_num_mutex1.unlock();

	int i = paramD.LcomDesign.iDgnLcomType - 1;
	ForceLcase = DgnSbcf.Force[i];
	StressLcase = DgnSbcf.Stress[i];
	if (paramD.bIsCalcStss == TRUE) StssLcase = DgnSbcf.Stss[i];
	// Set Force Type.
	ForceLcase.strType = StressLcase.strType = GetConCurrForceType(i);

	if (paramD.nForType > 0)
	{
		StressPart1 = DgnSbcf.Stress[i];
		StressPart2 = DgnSbcfPart.StressP2[i];
	}

	return TRUE;
}

BOOL CCRCForceCtrl::Get_Smlc_mt(T_LCOM_IN& paramD, T_LCOM_FORC& forcD)
{
	//PROFILING(_T("CCRCForceCtrl::Get_Smlc"));

	// iMaxMinType (1=FX-MAX, 2=FX-MIN, 3=FY-MAX,..., 11=MZ-MAX, 12=MZ-MIN).
	int iMaxMinType = paramD.LcomDesign.iDgnLcomType;
	if (iMaxMinType < 0 || iMaxMinType > cFORC_CON)	return FALSE;

	_DGN_FORC_CRC ForceLcase;
	_DGN_STRS_CRC StressLcase;
	_DGN_SHRS_ADD StssLcase;
	//
	_DGN_FORC_CRC ForcePart1;
	_DGN_STRS_CRC StressPart1;
	_DGN_FORC_CRC ForcePart2;
	_DGN_STRS_CRC StressPart2;

	T_SMLC_K SmlcK = paramD.iLcaseK;
	CString strLcaseNa = _T("SET");
	if (!Get_Sbcf_mt(paramD, SmlcK, D_LOADCASE_SETTLE,
		ForceLcase, StressLcase, StssLcase, ForcePart1, StressPart1, ForcePart2, StressPart2))
		return FALSE;

	// Set Forces by DimType.
	Set_DimTypeForc(ForceLcase);
	// Apply Lcase Factor.
	double dFactor = paramD.dFactor;
	ForceLcase *= dFactor;
	StressLcase *= dFactor;
	// Remnant.
	forcD.ForceRemn += ForceLcase;
	// Stress.
	forcD.StressRemn += StressLcase;
	// Principle.
	forcD.StressShr += StssLcase;

	// For JTG, Tendon Stress.
	forcD.ForceJtgTndn += ForceLcase;

	// Add, Jaeoh. [11/17/2008] Req.Maxiao, Settlement도 TB05, Dead Load에 포함.
	// For TB 10002.3-2005, LL
	if (m_iDgnCode == TB_10002_3_05 || m_iDgnCode == RC_TB_10002_3_05)
	{
		forcD.ForceDL_TB05 += ForceLcase;
		forcD.StressDL_TB05 += StressLcase;
	}

	if (paramD.nForType > 0)
	{
		ForcePart1 *= dFactor;
		StressPart1 *= dFactor;
		ForcePart2 *= dFactor;
		StressPart2 *= dFactor;

		forcD.ForceRemnP1 += ForcePart1;
		forcD.StressRemnP1 += StressPart1;
		forcD.ForceRemnP2 += ForcePart2;
		forcD.StressRemnP2 += StressPart2;
	}

	return TRUE;
}
BOOL CCRCForceCtrl::Get_Gilc_mt(T_LCOM_IN& paramD, T_LCOM_FORC& forcD)
{
	//PROFILING(_T("CCRCForceCtrl::Get_Gilc"));

	// iMaxMinType (1=FX-MAX, 2=FX-MIN, 3=FY-MAX,..., 11=MZ-MAX, 12=MZ-MIN).
	int iMaxMinType = paramD.LcomDesign.iDgnLcomType;
	if (iMaxMinType < 0 || iMaxMinType > cFORC_CON)	return FALSE;

	// Get Load Case Type.
	T_GILC_K GilcK = paramD.iLcaseK;
	T_GILC_D GilcD;
	GilcD.Initialize();
	if (!m_pAttrCtrl->GetGilc(GilcK, GilcD))	return FALSE;
	int iLcaseType = GilcD.nLoadCaseType;

	CString strLcaseNa = _T("");
	_DGN_FORC_CRC ForceLcase;
	_DGN_STRS_CRC StressLcase;
	_DGN_SHRS_ADD StssLcase;
	//
	_DGN_FORC_CRC ForcePart1;
	_DGN_STRS_CRC StressPart1;
	_DGN_FORC_CRC ForcePart2;
	_DGN_STRS_CRC StressPart2;

	if (!Get_Gilc_mt(paramD, GilcK, iLcaseType, strLcaseNa, ForceLcase, StressLcase, StssLcase,
		ForcePart1, StressPart1, ForcePart2, StressPart2))	return FALSE;
	BOOL bDL = (iLcaseType == 0 || iLcaseType == 1 ? TRUE : FALSE);
	// Set Forces by DimType.
	Set_DimTypeForc(ForceLcase);
	// Apply Lcase Factor.
	double dFactor = paramD.dFactor;
	ForceLcase *= dFactor;
	StressLcase *= dFactor;
	StssLcase *= dFactor;
	// Principle.
	forcD.StressShr += StssLcase;

	// For JTG, Tendon Stress.
	forcD.ForceJtgTndn += ForceLcase;

	// 0:Dead, 1:Other Dead Load, 
	// 2:Vehicle Live Load, 3:Crowded Line Load, 4:Other Live Load (2,3,4는 일본 버전에만)
	if (iLcaseType == 0)
	{
		(paramD.bReciLcase ? forcD.ForceDrec : forcD.ForceDnon) += ForceLcase;	// Dead Load.
		forcD.ForceAddDL += ForceLcase;

		// Stress.
		forcD.StressNorDL += StressLcase;
		//Jtg
		forcD.StressAddDL += StressLcase;
		if (m_iDgnCode == TB_10002_3_05 || m_iDgnCode == RC_TB_10002_3_05)
		{
			// For TB 10002.3-2005
			forcD.ForceDL_TB05 += ForceLcase;
			forcD.StressDL_TB05 += StressLcase;
		}
	}
	else if (iLcaseType == 1)
	{
		(paramD.bReciLcase ? forcD.ForceDnon : forcD.ForceDnon) += ForceLcase;	// Other Dead Load.
		forcD.ForceAddDL += ForceLcase;

		// Stress.
		forcD.StressNorDL += StressLcase;
		//Jtg
		forcD.StressAddDL += StressLcase;
		// For TB 10002.3-2005
		if (m_iDgnCode == TB_10002_3_05 || m_iDgnCode == RC_TB_10002_3_05)
		{
			forcD.ForceDL_TB05 += ForceLcase;
			forcD.StressDL_TB05 += StressLcase;
		}
	}
	else if (iLcaseType == 2)
	{
		(paramD.bReciLcase ? forcD.ForceLrec : forcD.ForceLnon) += ForceLcase;	// Vehicle Live Load.
		// Stress.
		forcD.StressNorLL += StressLcase;
	}
	else if (iLcaseType == 3)
	{
		(paramD.bReciLcase ? forcD.ForceLrec : forcD.ForceLnon) += ForceLcase;	// Crowded Line Load.
		// Stress.
		forcD.StressNorLL += StressLcase;
	}
	else if (iLcaseType == 4)
	{
		(paramD.bReciLcase ? forcD.ForceLrec : forcD.ForceLnon) += ForceLcase;	// Other Live Load.
		// Stress.
		forcD.StressNorLL += StressLcase;
	}
	else	ASSERT(0);

	if (paramD.nForType > 0)
	{
		ForcePart1 *= dFactor;
		StressPart1 *= dFactor;
		ForcePart2 *= dFactor;
		StressPart2 *= dFactor;

		forcD.ForceRemnP1 += ForcePart1;
		forcD.StressRemnP1 += StressPart1;
		forcD.ForceRemnP2 += ForcePart2;
		forcD.StressRemnP2 += StressPart2;
		forcD.StressSTermP2 += StressPart2;
	}

	return TRUE;
}
BOOL CCRCForceCtrl::Get_Gilc_mt(T_LCOM_IN& paramD, T_GILC_K GilcK, int iLcaseType, CString& strLcaseNa, _DGN_FORC_CRC& ForceLcase, _DGN_STRS_CRC& StressLcase, _DGN_SHRS_ADD& StssLcase,
	_DGN_FORC_CRC& ForcePart1, _DGN_STRS_CRC& StressPart1, _DGN_FORC_CRC& ForcePart2, _DGN_STRS_CRC& StressPart2)
{
	strLcaseNa = _T("");
	ForceLcase.Initialize();
	StressLcase.Initialize();
	StssLcase.Initialize();

	// iLcaseType.
	// 0:Dead, 1:Other Dead Load, 
	// 2:Vehicle Live Load, 3:Crowded Line Load, 4:Other Live Load (2,3,4는 일본 버전에만)  
	BOOL bMaxMin = (iLcaseType == 2 || iLcaseType == 3 || iLcaseType == 4 ? TRUE : FALSE);
	if (!bMaxMin)
	{
		_DGN_STRBFORC_LCASE      DgnStrb;
		_DGN_STRBFORC_PART_LCASE DgnStrbPart;

		g_num_mutex1.lock();
		GetStrb4Elem(paramD.ElemK, paramD.nForType, D_LOADCASE_GRIDMODEL, GilcK, DgnStrb, DgnStrbPart);
		g_num_mutex1.unlock();

		ForceLcase = DgnStrb.Force;
		StressLcase = DgnStrb.Stress;
		if (paramD.bIsCalcStss == TRUE) StssLcase = DgnStrb.Stss;

		if (paramD.nForType > 0)
		{
			ForcePart1 = DgnStrbPart.ForceP1;
			ForcePart2 = DgnStrbPart.ForceP2;
			StressPart1 = DgnStrb.Stress;
			StressPart2 = DgnStrbPart.StressP2;
		}

		// Set Force Type (D,L,W,...).
		if (iLcaseType == 0)		strLcaseNa = _T("GD");	// Dead Load.
		else if (iLcaseType == 1)	strLcaseNa = _T("GOD");	// Other Dead Load.
		else	ASSERT(0);
		ForceLcase.strType = StressLcase.strType = strLcaseNa;

	}
	else
	{
		if (iLcaseType == 2)		strLcaseNa = _T("GVH");	// Vehicle Live Load.
		else if (iLcaseType == 3)	strLcaseNa = _T("GCR");	// Crowded Line Load.
		else if (iLcaseType == 4)	strLcaseNa = _T("GOL");	// Other Live Load.
		else	ASSERT(0);

		_DGN_SBCFFORC_LCASE      DgnSbcf;
		_DGN_SBCFFORC_PART_LCASE DgnSbcfPart;

		g_num_mutex1.lock();
		GetSbcf4Elem(paramD.ElemK, paramD.nForType, D_LOADCASE_GRIDMODEL, GilcK, DgnSbcf, DgnSbcfPart);
		g_num_mutex1.unlock();

		int i = paramD.LcomDesign.iDgnLcomType - 1;
		ForceLcase = DgnSbcf.Force[i];
		StressLcase = DgnSbcf.Stress[i];
		if (paramD.bIsCalcStss == TRUE) StssLcase = DgnSbcf.Stss[i];
		// Set Force Type.
		ForceLcase.strType = StressLcase.strType = GetConCurrForceType(i);

		if (paramD.nForType > 0)
		{
			StressPart1 = DgnSbcf.Stress[i];
			StressPart2 = DgnSbcfPart.StressP2[i];
		}
	}
	return TRUE;
}

BOOL CCRCForceCtrl::Get_LcomDataForDesign_EX_org(ElemPairK ElemK, int nForType, int iDgnLcomKind, BOOL bIncludeTP, BOOL bAlways3D,
	ADGNFORCE_EX &aForceLcom, ADGNFORCE_EX &aForceStag, ADGNSHRSADD_EX &aShrsStage,
	ADGNFORCE_EX &aForceTnpr, ADGNFORCE_EX &aForceTnsc, ADGNSTRSADD_EX &aStressAdd,
	ADGNFORCE_EX &aForceLTerm, ADGNFORCE_EX &aForceJtgTndn, ADGNSTRESS_EX& aStressLcom,
	ADGNSTRESS_EX& aStressTnpr, ADGNSTRESS_EX& aStressTnsc, ADGNSTRESS_EX& aStressLTerm,
	ADGNSHRSADD_EX &aStssLcom, BOOL bBinary)
{
	aForceLcom.RemoveAll();
	aForceStag.RemoveAll();
	aShrsStage.RemoveAll();
	aForceTnpr.RemoveAll();
	aForceTnsc.RemoveAll();
	aStressAdd.RemoveAll();
	aForceLTerm.RemoveAll();
	aForceJtgTndn.RemoveAll();
	// Stress.
	aStressLcom.RemoveAll();
	// aStressStag.RemoveAll();  
	aStressTnpr.RemoveAll();
	aStressTnsc.RemoveAll();
	aStressLTerm.RemoveAll();
	// Principle.
	aStssLcom.RemoveAll();

	/*
	//++++++++++++++++++++++++++++++++++++++++++++
	// <Remember> Get Data by Code Units.
	T_UNIT_INDEX CurIndex, CngIndex;
	pDoc->m_pUnitCtrl->GetUnitIndexCurrent(CurIndex);
	CngIndex.nBase_Length = m_CodeUnit.nBase_Length;
	CngIndex.nBase_Force  = m_CodeUnit.nBase_Force;
	pDoc->m_pUnitCtrl->SetUnitIndexCurrent(CngIndex);
	//++++++++++++++++++++++++++++++++++++++++++++
	*/

	m_StrsPost.Initialize();
	m_pSectInfo->Get_StrsPscd(FALSE, ElemK.first, m_StrsPost);

	// Reset DimType.
	if (bAlways3D)	m_iDimType = 2;	// Set 3D.
	// Consider No Effect Zone.
	Set_RatNoEffectZone(ElemK);

	int iLcomNum = m_arLcomData.GetCount();
	if (iLcomNum == 0)	return FALSE;

	for (int i = 0; i < iLcomNum; ++i)
	{
		// Initialize Forces.
		Set_ForceIni();

		_DGN_LCOM LcomDesign;
		LcomDesign.Initialize();
		if (!m_arLcomData.Lookup(i + 1, LcomDesign))	continue;
		// Check LcomKind.
		if (iDgnLcomKind > 0 && iDgnLcomKind != LcomDesign.bLongTerm)	continue;

		BOOL bIsCalcStss = (LcomDesign.nActive == 2); // Service 경우만 Stss 계산하기 위해.

		// Check Existing Reciprocal Stress.
		T_LCRS_D LcrsD;
		LcrsD.Initialize();
		BOOL bReciInput = m_pAttrCtrl->GetLcrs(LcrsD);

		int iLcaseNum = LcomDesign.LcomUlData.Combination.GetSize();
		for (int j = 0; j < iLcaseNum; ++j)
		{
			const T_LCOM_BASE &LcomB = LcomDesign.LcomUlData.Combination[j];

			unsigned int iAnalType = LcomB.AnalType;
			unsigned int iLcaseKey = LcomB.LoadCaseKey;
			double dFactor = LcomB.Factor;
			int iMaxMinType = LcomDesign.iDgnLcomType;
			// Lcase for Reciprocal Stress.
			BOOL bReciLcase = (bReciInput ? Is_Reciprocal(iAnalType, iLcaseKey) : FALSE);
			// LcomUlData.Combination[i].AnalType is...
			// D_LCOM_STATIC       1
			// D_LCOM_SPECTRUM     2
			// D_LCOM_ECCENSPEC		14
			// D_LCOM_HISTORY      3 
			// D_LCOM_STAGE       13
			// D_LCOM_MOVING       4 (Load Combination - Max, Min)
			// D_LCOM_SETTLEMENT   5 (Load Combination - Max, Min)
			// D_LCOM_GRIDMODEL   15 (Load Combination - Max, Min)
			///*** Add by juhonghua 2012.03.10
			dFactor = AdjustCJJLoadCaseFactor(iAnalType, LcomDesign, dFactor, m_Chrp, m_Pscd);

			//_DGN_FORC_CRC ForceLcase;
			if (iAnalType == D_LCOM_STATIC)			Get_Stld_EX(ElemK, iLcaseKey, nForType, bIsCalcStss, dFactor, bReciLcase);
			else if (iAnalType == D_LCOM_SPECTRUM)	Get_Splc_EX(ElemK, iLcaseKey, nForType, bIsCalcStss, dFactor);
			else if (iAnalType == D_LCOM_ECCENSPEC)	Get_Espc_EX(ElemK, iLcaseKey, nForType, bIsCalcStss, dFactor);
			else if (iAnalType == D_LCOM_HISTORY)	Get_This_EX(ElemK, iLcaseKey, nForType, bIsCalcStss, dFactor);
			else if (iAnalType == D_LCOM_STAGE)		Get_Sgld_EX(ElemK, iLcaseKey, nForType, bIsCalcStss, dFactor, bReciLcase, bIncludeTP, 0);	// If iStepNo=0, Final Stage.
			else if (iAnalType == D_LCOM_MOVING)		Get_Mvld_EX(ElemK, iLcaseKey, nForType, bIsCalcStss, dFactor, bReciLcase, iMaxMinType);
			else if (iAnalType == D_LCOM_SETTLEMENT)	Get_Smlc_EX(ElemK, iLcaseKey, nForType, bIsCalcStss, dFactor, iMaxMinType);
			else if (iAnalType == D_LCOM_GRIDMODEL)	Get_Gilc_EX(ElemK, iLcaseKey, nForType, bIsCalcStss, dFactor, bReciLcase, iMaxMinType);
			else if ((m_iDgnCode == RC_JTG_B02_01_2008 || m_iDgnCode == RC_CJJ_166_2011) && iAnalType == D_LCOM_CB_CONCRETE) // Add by SHIN(09.12.21)
			{
				T_LCOM_D LcomD;
				if (m_pAttrCtrl->GetLcom(D_LCOMTYPE_CONCRETE, iLcaseKey, LcomD))
				{
					if (LcomD.LoadCombType == 3)
					{
						Get_Lcom_EX(ElemK, iLcaseKey, nForType, bIsCalcStss, dFactor, iMaxMinType);
					}
				}
			}
			else if ((CDBLib::IsCSGCode(m_iDgnCode) == TRUE && (iAnalType == D_LCOM_CB_STEEL || iAnalType == D_LCOM_CB_STLCOMP)) || (CDBLib::IsCSGCode(m_iDgnCode) == FALSE && iAnalType == D_LCOM_CB_CONCRETE))
			{
				Get_Lcom_EX(ElemK, iLcaseKey, nForType, bIsCalcStss, dFactor, iMaxMinType);  // Add by GAY. MNET:2903. ('07.07.31).
			}
			else	ASSERT(0);
		}
		_DGN_FORC_CRC_EX ForceLcom;
		_DGN_FORC_CRC_EX ForceLcomExTp;
		_DGN_FORC_CRC_EX ForceStag;
		_DGN_SHRS_ADD_EX ShrsStage;
		_DGN_FORC_CRC_EX ForceTnpr;
		_DGN_FORC_CRC_EX ForceTnsc;
		_DGN_STRS_ADD_EX StressAdd;
		_DGN_FORC_CRC_EX ForceLTerm;
		_DGN_FORC_CRC_EX ForceJtgTndn;
		//
		_DGN_FORC_CRC_EX ForceDL_TB05;
		_DGN_FORC_CRC_EX ForceLL_TB05;
		_DGN_FORC_CRC_EX ForceCSTP_TB05;

		_DGN_FORC_CRC_EX ForceEQE2_JTG;
		_DGN_FORC_CRC_EX ForceWeight_JTG;

		if (!Get_Force_EX(ForceLcom, ForceStag, ShrsStage, ForceTnpr, ForceTnsc, StressAdd, ForceLTerm, ForceJtgTndn, ForceDL_TB05, ForceLL_TB05, ForceCSTP_TB05, ForceEQE2_JTG, ForceWeight_JTG))	ASSERT(0);
		ForceLcom.strType = LcomDesign.DesignLcomNa;	// For Design LcomNa (cLCB-DA+1,...).
		if (!bBinary)
		{
			aForceLcom.Add(ForceLcom);
			aForceStag.Add(ForceStag);
			aShrsStage.Add(ShrsStage);
			aForceTnpr.Add(ForceTnpr);
			aForceTnsc.Add(ForceTnsc);
			aStressAdd.Add(StressAdd);
			aForceLTerm.Add(ForceLTerm);
			aForceJtgTndn.Add(ForceJtgTndn);
		}
		else
		{
			ForceLcomExTp += ForceLcom;
			ForceLcomExTp -= ForceTnpr;
		}
		// Add by ZINU.('04.12.01). See JTG D62-04 6.4.3 For C2(Variable).
		// Assumed by ZINU. C2=1.5, Ms(+/-)Mp2=Muy.
		//*/ZINU.		Set_CrackJtg(ElemK, i+1, ForceLcom);

		// Stress.
		_DGN_STRS_CRC_EX StressLcom;
		_DGN_STRS_CRC_EX StressStag;
		_DGN_STRS_CRC_EX StressTnpr;
		_DGN_STRS_CRC_EX StressTnsc;
		_DGN_STRS_CRC_EX StressLTerm;
		_DGN_SHRS_ADD_EX StssLcom;
		//
		_DGN_STRS_CRC_EX StressDL_TB05;
		_DGN_STRS_CRC_EX StressLL_TB05;
		_DGN_STRS_CRC_EX StressCSTP_TB05;
		if (!Get_Stress_EX(StressLcom, StressTnpr, StressTnsc, StressLTerm, StssLcom, StressDL_TB05, StressLL_TB05, StressCSTP_TB05)) ASSERT(0);

		StressLcom.iRefNo[0] = StressLcom.iRefNo[1] = LcomDesign.OriginalLcomKey;
		StressStag.iRefNo[0] = StressStag.iRefNo[1] = LcomDesign.OriginalLcomKey;
		StressTnpr.iRefNo[0] = StressTnpr.iRefNo[1] = LcomDesign.OriginalLcomKey;
		StressTnsc.iRefNo[0] = StressTnsc.iRefNo[1] = LcomDesign.OriginalLcomKey;
		StressLTerm.iRefNo[0] = StressLTerm.iRefNo[1] = LcomDesign.OriginalLcomKey;
		StressDL_TB05.iRefNo[0] = StressDL_TB05.iRefNo[1] = LcomDesign.OriginalLcomKey;
		StressLL_TB05.iRefNo[0] = StressLL_TB05.iRefNo[1] = LcomDesign.OriginalLcomKey;
		StressCSTP_TB05.iRefNo[0] = StressCSTP_TB05.iRefNo[1] = LcomDesign.OriginalLcomKey;

		StressLcom.strType = LcomDesign.DesignLcomNa;
		if (!bBinary)
		{
			aStressLcom.Add(StressLcom);
			//aStressStag.Add(StressStag);  
			aStressTnpr.Add(StressTnpr);
			aStressTnsc.Add(StressTnsc);
			aStressLTerm.Add(StressLTerm);
			// Principle.
			aStssLcom.Add(StssLcom);
		}

		if (bBinary)
		{
			//////////////////////////////////////////////////////////////////////////
			// Write Force & Stress
			int iSerialLcom = i + 1;
			WriteForceLcom_EX(ElemK, iSerialLcom, ForceLcom);
			WriteForceLcomExTp_EX(ElemK, iSerialLcom, ForceLcomExTp);
			WriteForceStage_EX(ElemK, iSerialLcom, ForceStag);
			WriteaShrsStage_EX(ElemK, iSerialLcom, ShrsStage);
			WriteForceTnpr_EX(ElemK, iSerialLcom, ForceTnpr);
			WriteForceTnsc_EX(ElemK, iSerialLcom, ForceTnsc);
			WriteStressAdd_EX(ElemK, iSerialLcom, StressAdd);
			WriteForceLTerm_EX(ElemK, iSerialLcom, ForceLTerm);
			WriteForceJtgTndn_EX(ElemK, iSerialLcom, ForceJtgTndn);
			WriteStressLcom_EX(ElemK, iSerialLcom, StressLcom);
			WriteStressTnpr_EX(ElemK, iSerialLcom, StressTnpr);
			WriteStressTnsc_EX(ElemK, iSerialLcom, StressTnsc);
			WriteStressLTerm_EX(ElemK, iSerialLcom, StressLTerm);
			WriteStssLcom_EX(ElemK, iSerialLcom, StssLcom);

			// SCFP
			if (m_iDgnCode == SNiP_20503_84_CSG || m_iDgnCode == SP_35_13330_11_CSG ||
				m_iDgnCode == EUROCODE4_2_04_CSG)
			{
				_DGN_SCFP_PART_LCASE_EX StrScfpCr;
				_DGN_SCFP_PART_LCASE_EX StrScfpSh;
				_DGN_SCFP_PART_LCASE_EX StrScfpTe;
				_DGN_SCFP_PART_LCASE_EX StrScfpRe;

				Get_StressScfpPart_EX(StrScfpCr, StrScfpSh, StrScfpTe, StrScfpRe);
				WriteStressScfpCrPartLcom_EX(ElemK, iSerialLcom, StrScfpCr);
				WriteStressScfpShPartLcom_EX(ElemK, iSerialLcom, StrScfpSh);
				WriteStressScfpTePartLcom_EX(ElemK, iSerialLcom, StrScfpTe);
				WriteStressScfpRePartLcom_EX(ElemK, iSerialLcom, StrScfpRe);
				WriteForceScfpSum_EX(ElemK, iSerialLcom, *m_pForceScfpSum_EX);
				WriteForceScfpCrp_EX(ElemK, iSerialLcom, *m_pForceScfpCrp_EX);
				WriteForceScfpShr_EX(ElemK, iSerialLcom, *m_pForceScfpShr_EX);
			}

			if (nForType == 1 || nForType == 2)
			{
				_DGN_FORC_CRC_EX ForceLcomPart;
				Get_ForcePart1_EX(ForceLcomPart);

				_DGN_STRS_CRC_EX StressLcomPart;
				Get_StressPart1_EX(StressLcomPart);

				WriteForceLcom_Part1_EX(ElemK, iSerialLcom, ForceLcomPart);
				WriteStressLcom_Part1_EX(ElemK, iSerialLcom, StressLcomPart);

				ForceLcomPart.Initialize();
				Get_ForcePart2_EX(ForceLcomPart);

				StressLcomPart.Initialize();
				Get_StressPart2_EX(StressLcomPart);
				WriteForceLcom_Part2_EX(ElemK, iSerialLcom, ForceLcomPart);
				WriteStressLcom_Part2_EX(ElemK, iSerialLcom, StressLcomPart);

				_DGN_STRS_CRC_EX StrTnprPa2;
				_DGN_STRS_CRC_EX StrTnscPa2;
				Get_StressTendonPart2_EX(StrTnprPa2, StrTnscPa2);
				WriteStressTnpr_Part2_EX(ElemK, iSerialLcom, StrTnprPa2);
				WriteStressTnsc_Part2_EX(ElemK, iSerialLcom, StrTnscPa2);
			}

			//
			if (m_iDgnCode == TB_10002_3_05 || m_iDgnCode == RC_TB_10002_3_05)
			{
				WriteForceDL_TB05_EX(ElemK, iSerialLcom, ForceDL_TB05);
				WriteForceLL_TB05_EX(ElemK, iSerialLcom, ForceLL_TB05);
				WriteStressDL_TB05_EX(ElemK, iSerialLcom, StressDL_TB05);
				WriteStressLL_TB05_EX(ElemK, iSerialLcom, StressLL_TB05);
				WriteForceCSTP_TB05_EX(ElemK, iSerialLcom, ForceCSTP_TB05);
				WriteStressCSTP_TB05_EX(ElemK, iSerialLcom, StressCSTP_TB05);
			}
			else if (m_iDgnCode == RC_JTG_B02_01_2008 || m_iDgnCode == RC_CJJ_166_2011)
			{
				WriteForceEQE2_JTG_EX(ElemK, iSerialLcom, ForceEQE2_JTG);
			}
			/////////////////////////////////////////////////////////////////////////////////
		}
	}
	/*
	//++++++++++++++++++++++++++++++++++++++++++++
	// <Remember> Set Data by Current Units.
	m_pUnitCtrl->SetUnitIndexCurrent(CurIndex);
	//++++++++++++++++++++++++++++++++++++++++++++
	*/
	return TRUE;
}

BOOL CCRCForceCtrl::Get_Lcom_EX_mt(T_LCOM_IN& paramD, T_LCOM_EX_FORC& forcD)
{
	if (paramD.iMaxMinType < 0 || paramD.iMaxMinType > DGN_FORCE_LCOM_SUB_MAX)	return FALSE;

	_DGN_FORC_CRC_EX ForceLcase;
	_DGN_STRS_ADD_EX StressAdd;
	_DGN_STRS_CRC_EX StressLcase;
	_DGN_SHRS_ADD_EX StssLcase;
	//
	_DGN_FORC_CRC_EX ForcePart1;
	_DGN_STRS_CRC_EX StressPart1;
	_DGN_FORC_CRC_EX ForcePart2;
	_DGN_STRS_CRC_EX StressPart2;

	if (!Get_Lcom_EX(paramD.ElemK, paramD.iLcaseK, paramD.nForType, paramD.bIsCalcStss, ForceLcase, StressAdd, StressLcase, StssLcase,
		ForcePart1, StressPart1, ForcePart2, StressPart2, paramD.iMaxMinType))	return FALSE;
	// Set Forces by DimType.
	Set_DimTypeForc_EX(ForceLcase);
	// Apply Lcase Factor.
	ForceLcase *= paramD.dFactor;
	// Stress.
	StressLcase *= paramD.dFactor;
	// Add by ZINU.('05.01.03). Consider Stress.
	StressAdd *= paramD.dFactor;
	forcD.StressAdd_EX += StressAdd;
	// Principle.
	StssLcase *= paramD.dFactor;
	forcD.StressShr_EX += StssLcase;

	// Force and Stress.
	forcD.ForceRemn_EX += ForceLcase;
	// Stress.
	forcD.StressRemn_EX += StressLcase;

	//remove by maxiao   m_ForceEQE2_JTG is PermanentLoad_JTG_B02， why have this code？
	//	if(m_iDgnCode == RC_JTG_B02_01_2008)
	//	{ m_ForceEQE2_JTG += ForceLcase; }

	if (paramD.nForType > 0)
	{
		ForcePart1 *= paramD.dFactor;
		StressPart1 *= paramD.dFactor;
		ForcePart2 *= paramD.dFactor;
		StressPart2 *= paramD.dFactor;

		forcD.ForceRemnP1_EX += ForcePart1;
		forcD.StressRemnP1_EX += StressPart1;
		forcD.ForceRemnP2_EX += ForcePart2;
		forcD.StressRemnP2_EX += StressPart2;
	}
	return TRUE;
}
BOOL CCRCForceCtrl::Get_Force_EX_mt(T_LCOM_EX_OUT& outD, T_LCOM_EX_FORC& forcD)
{
	outD.ForceLcom.Initialize();
	outD.ForceStag.Initialize();
	outD.ShrsStage.Initialize();
	outD.ForceTnpr.Initialize();
	outD.ForceTnsc.Initialize();
	outD.StressAdd.Initialize();
	outD.ForceLTerm.Initialize();
	outD.ForceJtgTndn.Initialize();
	outD.ForceDL_TB05.Initialize();
	outD.ForceLL_TB05.Initialize();
	outD.ForceEQE2_JTG.Initialize();

	outD.ForceLcom += forcD.ForceDnon_EX;
	outD.ForceLcom += forcD.ForceDrec_EX;
	outD.ForceLcom += forcD.ForceLnon_EX;
	outD.ForceLcom += forcD.ForceLrec_EX;
	outD.ForceLcom += forcD.ForceRemn_EX;
	// Forec by All Sgld.
	outD.ForceStag = forcD.ForceStag_EX;
	outD.ShrsStage = forcD.ShrsStage_EX;
	// Force by Tendon Primary.
	outD.ForceTnpr = forcD.ForceTnpr_EX;
	outD.ForceTnsc = forcD.ForceTnsc_EX;
	// Add by ZINU.('05.01.03). Stress by Beam Section Temperature.
	outD.StressAdd = forcD.StressAdd_EX;
	// Add by Jaeoh. ('05.08.16).
	//ForceSgldDL += m_ForceSgldRemn; // For Required Tendon , Mg1  
	//ForceAddDL  += m_ForceAddDL;  // For Add DL , JTG D6204, 
	//ForceLL     += m_ForceLL;     // For 균열검토, JTG D62-04, LL

	switch (m_iDgnCode)
	{
	case SNiP_20503_84_PSC:
	case SP_35_13330_11_PSC:
	case SNiP_20503_84_PSC_MKS:
	case SP_35_13330_11_PSC_MKS:
	case SNiP_20503_84_SOD:
	case SP_35_13330_11_SOD:
		outD.ForceLTerm += forcD.ForceAddDL_EX;
		break;
	case KSCE_LSD15_CSG:
	case AASHTO_LRFD12_CSG:
	case AASHTO_LRFD07_CSG:
	case KDS_24_14_31_2018_CSG:
	case KSSC_2014_CSG:
	case CSA_S6_10_CSG:
	case CSA_S6_14_CSG:
	case CSA_S6_19_CSG:
	case AASHTO_LRFD16_CSG:
	case AASHTO_LRFD17_CSG:
	case AASHTO_LRFD20_CSG:
	case EUROCODE4_2_04_CSG:
	case CS457_R1_CSG:
	case NR_GN_CIV_025_06_CSG:
	case AS5100_6_17_CSG:
		// Beforce force
		if (m_bIsPLCB == TRUE)
		{
			outD.ForceStag = forcD.ForceAddDL_EX;
		}
		// 2014.03.31 이정우 GJ님 요청
		// After force는 Dead(CS), CP(CS), CS(CS), SP(CS), SS(CS) 으로 수정 
		outD.ForceLTerm += forcD.ForceLTerm_EX;
		break;
	case SNiP_20503_84_CSG:
	case SP_35_13330_11_CSG:
		// Beforce force
		if (m_bIsPLCB == TRUE)
		{
			outD.ForceStag = forcD.ForceAddDL_EX;
		}
		// 2014.03.31 이정우 GJ님 요청
		// After force는 Dead(CS), CP(CS), CS(CS), SP(CS), SS(CS) 으로 수정 
		outD.ForceLTerm += forcD.ForceLTerm_EX;
		outD.ForceLTerm += forcD.ForceRemn_EX;
		break;
	case TB_10002_3_05:
	case RC_TB_10002_3_05:
		outD.ForceDL_TB05 += forcD.ForceDL_TB05_EX;
		outD.ForceLL_TB05 += forcD.ForceLL_TB05_EX;
		outD.ForceCSTP_TB05 += forcD.ForceCS_TP_TB05_EX;
		break;
	case RC_JTG_B02_01_2008:
	case RC_CJJ_166_2011:
		outD.ForceEQE2_JTG += forcD.ForceEQE2_JTG_EX;
		outD.ForceWeight_JTG += forcD.ForceWeight_JTG_EX;
		break;
	default:
		outD.ForceLTerm += forcD.ForceSgldRe_EX;
		outD.ForceLTerm += forcD.ForceAddDL_EX;
		outD.ForceLTerm += forcD.ForceLL_EX;
		break;
	}
	// Add by Jaeoh. ('06.09.18)
	// 시공단계 Load Case를 
	outD.ForceJtgTndn += forcD.ForceJtgTndn_EX;
	return TRUE;
}
BOOL CCRCForceCtrl::Get_Stress_EX_mt(T_LCOM_EX_OUT& outD, T_LCOM_EX_FORC& forcD)
{
	outD.StressLcom.Initialize();
	//outD.StressStag.Initialize();
	//outD.ShrsStage.Initialize();
	outD.StressTnpr.Initialize();
	outD.StressTnsc.Initialize();
	//outD.StressAdd.Initialize();
	outD.StressLTerm.Initialize();
	outD.StressDL_TB05.Initialize();
	outD.StressLL_TB05.Initialize();
	outD.StressLcom += forcD.StressNorDL_EX;
	outD.StressLcom += forcD.StressNorLL_EX;
	outD.StressLcom += forcD.StressRemn_EX;
	// Force by Tendon Primary.
	outD.StressTnpr = forcD.StressTnpr_EX;
	outD.StressTnsc = forcD.StressTnsc_EX;
	// JTG D62-04.
	switch (m_iDgnCode)
	{
	case SNiP_20503_84_PSC:
	case SP_35_13330_11_PSC:
	case SNiP_20503_84_PSC_MKS:
	case SP_35_13330_11_PSC_MKS:
		outD.StressLTerm += forcD.StressTnpr_EX;
		outD.StressLTerm += forcD.StressTnsc_EX;
		outD.StressLTerm += forcD.StressAddDL_EX;
		break;
	case KSCE_LSD15_CSG:
	case AASHTO_LRFD20_CSG:
	case AASHTO_LRFD17_CSG:
	case AASHTO_LRFD16_CSG:
	case AASHTO_LRFD12_CSG:
	case AASHTO_LRFD07_CSG:
	case KDS_24_14_31_2018_CSG:
	case KSSC_2014_CSG:
	case SNiP_20503_84_CSG:
	case SP_35_13330_11_CSG:
	case CSA_S6_10_CSG:
	case CSA_S6_14_CSG:
	case CSA_S6_19_CSG:
	case EUROCODE4_2_04_CSG:
	case CS457_R1_CSG:
	case NR_GN_CIV_025_06_CSG:
	case AS5100_6_17_CSG:
		outD.StressLTerm += forcD.StressLTerm_EX;
		break;
	case TB_10002_3_05:
	case RC_TB_10002_3_05:
		outD.StressDL_TB05 += forcD.StressDL_TB05_EX;
		outD.StressLL_TB05 += forcD.StressLL_TB05_EX;
		outD.StressCSTP_TB05 += forcD.StressCS_TP_TB05_EX;
		break;
	default:
		outD.StressLTerm += forcD.StressSgldRe_EX;
		outD.StressLTerm += forcD.StressAddDL_EX;
		outD.StressLTerm += forcD.StressJtgLL_EX;
		break;
	}
	// Principle.
	outD.StssLcom += forcD.StressShr_EX;
	return TRUE;
}

BOOL CCRCForceCtrl::Get_Stld_EX_mt(T_LCOM_IN& paramD, T_LCOM_EX_FORC& forcD)
{
	_DGN_FORC_CRC_EX ForceLcase;
	_DGN_STRS_ADD_EX StressAdd;
	_DGN_STRS_CRC_EX StressLcase;
	_DGN_SHRS_ADD_EX StssLcase;

	_DGN_FORC_CRC_EX ForcePart1;
	_DGN_STRS_CRC_EX StressPart1;
	_DGN_FORC_CRC_EX ForcePart2;
	_DGN_STRS_CRC_EX StressPart2;

	if (!Get_Stld_EX(paramD.ElemK, paramD.iLcaseK, paramD.nForType, paramD.bIsCalcStss, ForceLcase, StressAdd, StressLcase, StssLcase,
		ForcePart1, StressPart1, ForcePart2, StressPart2))	return FALSE;

	// Set Forces by DimType.
	Set_DimTypeForc_EX(ForceLcase);
	// Apply Lcase Factor.
	ForceLcase *= paramD.dFactor;
	// Stress.
	StressLcase *= paramD.dFactor;

	_DGN_SCFP_PART_LCASE_EX ScfpPartLcase;
	T_STLD_K StldScfpK = 0;
	if (m_arStldScfpK.Lookup(paramD.iLcaseK, StldScfpK))
	{
		Get_StldScfp_EX(paramD.ElemK, StldScfpK, ScfpPartLcase);

		ScfpPartLcase.ForceP1 *= paramD.dFactor;
		ScfpPartLcase.ForceP2 *= paramD.dFactor;

		if (CDBLib::IsStldTL(ForceLcase.strType))
		{
			forcD.StressScfpTe_EX.ForceP1 += ScfpPartLcase.ForceP1;
			forcD.StressScfpTe_EX.ForceP2 += ScfpPartLcase.ForceP2;
		}
		else
		{
			forcD.StressScfpRe_EX.ForceP1 += ScfpPartLcase.ForceP1;
			forcD.StressScfpRe_EX.ForceP2 += ScfpPartLcase.ForceP2;
		}
	}

	// Add by ZINU.('05.01.03). Consider Stress.
	StressAdd *= paramD.dFactor;
	forcD.StressAdd_EX += StressAdd;
	// Principle.
	StssLcase *= paramD.dFactor;
	forcD.StressShr_EX += StssLcase;

	if (paramD.nForType > 0)
	{
		ForcePart1 *= paramD.dFactor;
		StressPart1 *= paramD.dFactor;
		ForcePart2 *= paramD.dFactor;
		StressPart2 *= paramD.dFactor;

		forcD.ForceRemnP1_EX += ForcePart1;
		forcD.StressRemnP1_EX += StressPart1;
		forcD.ForceRemnP2_EX += ForcePart2;
		forcD.StressRemnP2_EX += StressPart2;
	}

	T_STLD_K TempK = 0;
	if (m_mapPlcbStldK.Lookup(paramD.iLcaseK, TempK))
	{
		forcD.ForceAddDL_EX += ForceLcase;
		// Stress
		forcD.StressNorDL_EX += StressLcase;
		// JTG
		forcD.StressAddDL_EX += StressLcase;
	}
	else if (CDBLib::IsStldDL(ForceLcase.strType))	// Dead.
	{
		if (paramD.bReciLcase)
			forcD.ForceDrec_EX += ForceLcase;
		else
			forcD.ForceDnon_EX += ForceLcase;

		if (m_bIsPLCB == FALSE)
		{
			forcD.ForceAddDL_EX += ForceLcase;
			// Stress
			forcD.StressNorDL_EX += StressLcase;
			// JTG
			forcD.StressAddDL_EX += StressLcase;
		}
		if (CDBLib::IsStldLTerm(ForceLcase.strType))
		{
			forcD.ForceLTerm_EX += ForceLcase;
			forcD.StressLTerm_EX += StressLcase;
		}
	}
	else if (CDBLib::IsStldLL(ForceLcase.strType))	// Live.
	{
		if (paramD.bReciLcase)
			forcD.ForceLrec_EX += ForceLcase;
		else
			forcD.ForceLnon_EX += ForceLcase;

		// Stress
		forcD.StressNorLL_EX += StressLcase;
	}
	else
	{
		forcD.ForceRemn_EX += ForceLcase;
		// Stress.
		forcD.StressRemn_EX += StressLcase;
	}

	if (Is_JtgStldLL(ForceLcase.strType))
	{
		forcD.ForceLL_EX += ForceLcase;
		// Stress.
		forcD.StressJtgLL_EX += StressLcase;
	}

	// For JTG, Tendon Stress.
	forcD.ForceJtgTndn_EX += ForceLcase;

	// For TB 10002.3-2005, Force Stress
	// DL
	if (m_iDgnCode == TB_10002_3_05 || m_iDgnCode == RC_TB_10002_3_05)
	{
		if (Is_TB05StldDL(ForceLcase.strType))
		{
			forcD.ForceDL_TB05_EX += ForceLcase;
			forcD.StressDL_TB05_EX += StressLcase;
		}
		// LL
		if (Is_TB05StldLL(ForceLcase.strType))
		{
			forcD.ForceLL_TB05_EX += ForceLcase;
			forcD.StressLL_TB05_EX += StressLcase;
		}
	}
	else if (m_iDgnCode == RC_JTG_B02_01_2008 || m_iDgnCode == RC_CJJ_166_2011)
	{
		if (IsPermanentLoad_JTG_B02(ForceLcase.strType))
		{
			forcD.ForceEQE2_JTG_EX += ForceLcase;
		}
		if (IsSelfWeightLoad_JTG_B02(ForceLcase.strType))
		{
			forcD.ForceWeight_JTG_EX += ForceLcase;
		}
	}
	return TRUE;
}

